def format_number(value: float) -> str:
    rounded = round(float(value), 12)
    if math.isclose(rounded, 0.0, abs_tol=1e-12):
        rounded = 0.0
    text = f"{rounded:.12f}".rstrip("0").rstrip(".")
    return text or "0"


def parse_position(text: str) -> tuple[float, float, float]:
    x_str, y_str, z_str = text.split()
    return float(x_str), float(y_str), float(z_str)


def find_named_element(scenario: ET.Element, tag: str, name: str) -> ET.Element:
    for element in scenario.findall(tag):
        name_element = element.find("name")
        if name_element is not None and name_element.text == name:
            return element
    raise ValueError(f"Could not find {tag} named {name!r} in template.")


def find_driver_by_id(scenario: ET.Element, driver_id: int) -> ET.Element:
    for driver in scenario.findall("Driver"):
        id_element = driver.find("id")
        if id_element is not None and id_element.text == str(driver_id):
            return driver
    raise ValueError(f"Could not find Driver id={driver_id}.")


def get_abscissa(element: ET.Element) -> float:
    road_position = element.find("ObjectPosition/RoadPosition/abscissa")
    if road_position is None or road_position.text is None:
        raise ValueError("Missing abscissa.")
    return float(road_position.text)


def get_lane_gap(element: ET.Element) -> float:
    gap = element.find("ObjectPosition/RoadPosition/gapInItnSystem")
    if gap is None or gap.text is None:
        raise ValueError("Missing gapInItnSystem.")
    return float(gap.text)


def get_heading(element: ET.Element) -> float:
    heading = element.find("ObjectPosition/heading")
    if heading is None or heading.text is None:
        raise ValueError("Missing heading.")
    return float(heading.text)


def get_position_x(element: ET.Element) -> float:
    position = element.find("ObjectPosition/position")
    if position is None or position.text is None:
        raise ValueError("Missing position.")
    x_value, _, _ = parse_position(position.text)
    return x_value


def shorten_name(name: str, *, max_length: int = 14) -> str:
    if len(name) <= max_length:
        return name
    return name[: max_length - 1] + "…"


def shorten_name(name: str, *, max_length: int = 14) -> str:
    if len(name) <= max_length:
        return name
    return name[: max_length - 3] + "..."


def find_rule_blocks(script_text: str) -> list[tuple[int, int]]:
    blocks: list[tuple[int, int]] = []
    search_start = 0
    while True:
        rule_start = script_text.find("TYPEOF RULE", search_start)
        if rule_start < 0:
            return blocks
        brace_start = script_text.find("{", rule_start)
        if brace_start < 0:
            return blocks
        depth = 0
        for index in range(brace_start, len(script_text)):
            if script_text[index] == "{":
                depth += 1
            elif script_text[index] == "}":
                depth -= 1
                if depth == 0:
                    blocks.append((rule_start, index + 1))
                    search_start = index + 1
                    break
        else:
            return blocks


def find_primary_story_script(scenario: ET.Element) -> str:
    for script_element in scenario.findall(".//Step/ScenarioScript/script"):
        script_text = script_element.text or ""
        if "TYPEOF RULE" in script_text:
            return script_text
    return ""


def extract_sound_load_filename(script_text: str) -> str | None:
    for start, end in find_rule_blocks(script_text):
        block = script_text[start:end]
        if "TYPEOF ACTION (SOUND_LOAD)" not in block:
            continue
        match = re.search(
            r'TYPEOF PARAMETER \(MESSAGE\)\s*\{\s*KIND="FILE"\s*VALUE="([^"]+)"',
            block,
            flags=re.DOTALL,
        )
        if match:
            return match.group(1)
    return None


def extract_sound_play_trigger_name(script_text: str) -> str | None:
    for start, end in find_rule_blocks(script_text):
        block = script_text[start:end]
        if "TYPEOF ACTION (SOUND_PLAY)" not in block:
            continue
        match = re.search(
            r'TYPEOF PARAMETER \(TRIGGER_NAME\)\s*\{\s*KIND="TRIGGER"\s*VALUE="([^"]+)"',
            block,
            flags=re.DOTALL,
        )
        if match:
            return match.group(1)
    return None


def replace_audio_configuration(script_text: str, *, audio_file: str, audio_trigger_name: str) -> str:
    updated = script_text
    replaced_load = False
    replaced_play = False

    for start, end in reversed(find_rule_blocks(script_text)):
        block = updated[start:end]
        if "TYPEOF ACTION (SOUND_PLAY)" in block and not replaced_play:
            block = re.sub(
                r'(TYPEOF PARAMETER \(TRIGGER_NAME\)\s*\{\s*KIND="TRIGGER"\s*VALUE=")([^"]+)(")',
                lambda match: match.group(1) + audio_trigger_name + match.group(3),
                block,
                count=1,
                flags=re.DOTALL,
            )
            replaced_play = True
        if "TYPEOF ACTION (SOUND_LOAD)" in block and not replaced_load:
            block = re.sub(
                r'(TYPEOF PARAMETER \(MESSAGE\)\s*\{\s*KIND="FILE"\s*VALUE=")([^"]+)(")',
                lambda match: match.group(1) + audio_file + match.group(3),
                block,
                count=1,
                flags=re.DOTALL,
            )
            replaced_load = True
        updated = updated[:start] + block + updated[end:]

    return updated


def classify_reference_trigger(name: str) -> tuple[str, str, int] | None:
    trigger_families = [
        ("Trigger_L", "Loop Start", "#64748b", 0),
        ("Trigger_1_", "Lane Change Ref", "#7c3aed", 1),
        ("Trigger_2_", "Front Stop Ref", "#dc2626", 2),
        ("Trigger_3_", "Rear Stop Ref", "#ea580c", 3),
        ("Repair_", "Repair Ref", "#0ea5e9", 4),
        ("performance error", "Performance Ref", "#14b8a6", 5),
    ]
    for prefix, label, color, order in trigger_families:
        if name.startswith(prefix):
            return label, color, order
    return None


def load_reference_context(reference_path: Path) -> ReferenceContext:
    if not reference_path.exists():
        return ReferenceContext(vehicles=[], triggers=[], lane_gaps=[])

    tree = ET.parse(reference_path)
    scenario = tree.getroot().find("Scenario")
    if scenario is None:
        return ReferenceContext(vehicles=[], triggers=[], lane_gaps=[])

    ego = find_named_element(scenario, "Vehicle", EGO_NAME)
    ego_abscissa = get_abscissa(ego)

    editable_names = {EGO_NAME, REAR_NAME, FRONT_NAME, LEFT_LANE_NAME}
    vehicles: list[ReferenceVehicle] = []
    lane_gap_values: set[float] = {get_lane_gap(ego)}

    for vehicle in scenario.findall("Vehicle"):
        name = (vehicle.findtext("name") or "").strip()
        if not name or name in editable_names:
            continue
        try:
            relative_distance = get_abscissa(vehicle) - ego_abscissa
            lane_gap = get_lane_gap(vehicle)
        except ValueError:
            continue
        if not (-160.0 <= relative_distance <= 460.0):
            continue
        vehicles.append(
            ReferenceVehicle(
                name=name,
                relative_distance=relative_distance,
                lane_gap=lane_gap,
            )
        )
        lane_gap_values.add(lane_gap)

    vehicles.sort(key=lambda item: (abs(item.relative_distance), item.relative_distance, item.lane_gap))
    vehicles = vehicles[:18]

    grouped_triggers: dict[tuple[int, float, float], ReferenceTrigger] = {}
    for trigger in scenario.findall("Trigger"):
        name = (trigger.findtext("name") or "").strip()
        if not name:
            continue
        classified = classify_reference_trigger(name)
        if classified is None:
            continue
        label, color, order = classified
        try:
            relative_distance = get_abscissa(trigger) - ego_abscissa
            lane_gap = get_lane_gap(trigger)
        except ValueError:
            continue
        lane_gap_values.add(lane_gap)
        key = (order, round(relative_distance, 6), round(lane_gap, 3))
        grouped_triggers[key] = ReferenceTrigger(
            label=label,
            relative_distance=relative_distance,
            lane_gap=lane_gap,
            color=color,
            order=order,
        )

    triggers = sorted(
        grouped_triggers.values(),
        key=lambda item: (item.order, item.relative_distance, item.lane_gap),
    )
    lane_gaps = sorted(lane_gap_values)
    return ReferenceContext(vehicles=vehicles, triggers=triggers, lane_gaps=lane_gaps)


def load_template_defaults(template_path: Path) -> TemplateDefaults:
    tree = ET.parse(template_path)
    scenario = tree.getroot().find("Scenario")
    if scenario is None:
        raise ValueError("Template is missing <Scenario>.")

    ego = find_named_element(scenario, "Vehicle", EGO_NAME)
    rear = find_named_element(scenario, "Vehicle", REAR_NAME)
    front = find_named_element(scenario, "Vehicle", FRONT_NAME)
    left_lane = find_named_element(scenario, "Vehicle", LEFT_LANE_NAME)

    rear_lane_change_trigger = find_named_element(scenario, "Trigger", REAR_LANE_CHANGE_TRIGGER_NAME)
    front_stop_trigger = find_named_element(scenario, "Trigger", FRONT_STOP_TRIGGER_NAME)
    rear_stop_trigger = find_named_element(scenario, "Trigger", REAR_STOP_TRIGGER_NAME)
    start_trigger = find_named_element(scenario, "Trigger", START_TRIGGER_NAME)

    ego_abscissa = get_abscissa(ego)
    ego_x = get_position_x(ego)

    ego_driver = find_driver_by_id(scenario, 0)
    ego_max_speed = ego_driver.find("TrafficDriver/maxSpeed")
    if ego_max_speed is None or ego_max_speed.text is None:
        raise ValueError("Template is missing the ego max speed.")
    timing_ref_speed_kmh = float(ego_max_speed.text) * 3.6
    timing_ref_speed_mps = float(ego_max_speed.text)
    if timing_ref_speed_mps <= 0:
        raise ValueError("Template ego max speed must be positive.")

    rear_lane_change_time_s = (get_abscissa(rear_lane_change_trigger) - ego_abscissa) / timing_ref_speed_mps
    front_stop_time_s = (get_abscissa(front_stop_trigger) - ego_abscissa) / timing_ref_speed_mps
    rear_stop_time_s = (get_abscissa(rear_stop_trigger) - ego_abscissa) / timing_ref_speed_mps

    primary_script = find_primary_story_script(scenario)
    audio_file = extract_sound_load_filename(primary_script) or KNOWN_AUDIO_FILES[0]
    audio_trigger_name = extract_sound_play_trigger_name(primary_script) or FRONT_STOP_TRIGGER_NAME
    try:
        audio_trigger = find_named_element(scenario, "Trigger", audio_trigger_name)
        audio_trigger_time_s = (get_abscissa(audio_trigger) - ego_abscissa) / timing_ref_speed_mps
    except ValueError:
        audio_trigger_time_s = front_stop_time_s

    stop_criteria = scenario.find("ScenarioStopCriteria")
    total_experiment_time_s = max(
        16.0,
        rear_lane_change_time_s,
        front_stop_time_s,
        rear_stop_time_s,
        audio_trigger_time_s,
    ) + 6.0
    if stop_criteria is not None:
        final_time = stop_criteria.findtext("finalTime")
        stop_at_final_time = stop_criteria.findtext("stopAtFinalTime")
        if stop_at_final_time == "1" and final_time is not None:
            try:
                parsed_final_time = float(final_time)
            except ValueError:
                parsed_final_time = total_experiment_time_s
            if parsed_final_time > 0:
                total_experiment_time_s = parsed_final_time

    return TemplateDefaults(
        ego_abscissa=ego_abscissa,
        x_plus_abscissa=ego_x + ego_abscissa,
        right_lane_gap=get_lane_gap(ego),
        left_lane_gap=get_lane_gap(left_lane),
        heading_radians=get_heading(ego),
        front_gap_m=get_abscissa(front) - ego_abscissa,
        rear_gap_m=ego_abscissa - get_abscissa(rear),
        left_lane_vehicle_gap_m=get_abscissa(left_lane) - ego_abscissa,
        timing_ref_speed_kmh=timing_ref_speed_kmh,
        rear_lane_change_time_s=rear_lane_change_time_s,
        front_stop_time_s=front_stop_time_s,
        rear_stop_time_s=rear_stop_time_s,
        total_experiment_time_s=total_experiment_time_s,
        audio_trigger_time_s=audio_trigger_time_s,
        audio_file=audio_file,
        start_trigger_offset_m=get_abscissa(start_trigger) - ego_abscissa,
    )


def set_object_position(
    element: ET.Element,
    *,
    abscissa: float,
    lane_gap: float,
    x_plus_abscissa: float,
    heading_radians: float,
) -> None:
    heading = element.find("ObjectPosition/heading")
    position = element.find("ObjectPosition/position")
    road_position = element.find("ObjectPosition/RoadPosition")

    if heading is None or position is None or road_position is None:
        raise ValueError("Template object is missing ObjectPosition data.")

    road_abscissa = road_position.find("abscissa")
    road_gap = road_position.find("gapInItnSystem")
    if road_abscissa is None or road_gap is None:
        raise ValueError("Template object is missing RoadPosition data.")

    x_position = x_plus_abscissa - abscissa

    heading.text = format_number(heading_radians)
    position.text = f"{format_number(x_position)} {format_number(lane_gap)} 0"
    road_abscissa.text = format_number(abscissa)
    road_gap.text = format_number(lane_gap)


def set_road_position_child_v2(road_position: ET.Element, tag: str, value: object) -> None:
    child = road_position.find(tag)
    if child is None:
        child = ET.SubElement(road_position, tag)
    child.text = str(value)


def set_explicit_object_position_v2(
    element: ET.Element,
    *,
    map_x: float,
    map_y: float,
    map_z: float = 0.0,
    heading_radians: float,
    subnetwork: str,
    track: str,
    road_abscissa: float,
    road_gap: float,
    z_offset: float = 0.0,
) -> None:
    object_position = element.find("ObjectPosition")
    if object_position is None:
        raise ValueError("Object is missing ObjectPosition data.")
    heading = object_position.find("heading")
    position = object_position.find("position")
    road_position = object_position.find("RoadPosition")
    if heading is None or position is None or road_position is None:
        raise ValueError("Object is missing ObjectPosition/RoadPosition data.")

    heading.text = format_number(heading_radians)
    position.text = f"{format_number(map_x)} {format_number(map_y)} {format_number(map_z)}"
    set_road_position_child_v2(road_position, "abscissa", format_number(road_abscissa))
    set_road_position_child_v2(road_position, "gapInItnSystem", format_number(road_gap))
    set_road_position_child_v2(road_position, "relativeHeading", "0")
    set_road_position_child_v2(road_position, "subNetwork", subnetwork)
    set_road_position_child_v2(road_position, "track", track)
    set_road_position_child_v2(road_position, "zOffset", format_number(z_offset))


def set_scenario_ground_name_v2(scenario: ET.Element, terrain_rnd_name: str) -> None:
    ground_name = scenario.find("Ground/name")
    if ground_name is None:
        raise ValueError("Scenario is missing Ground/name.")
    ground_name.text = terrain_rnd_name


def normalize_output_filename(value: str) -> str:
    filename = value.strip()
    if not filename:
        raise ValueError("Output filename is required.")
    if not filename.lower().endswith(".sce"):
        filename += ".sce"
    if Path(filename).name != filename:
        raise ValueError("Use a filename only; the file will be created in the SCANeR workspace scenario folder.")
    return filename


def path_is_relative_to_v2(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
    except ValueError:
        return False
    return True


def prompt_scenario_output_dir_v2(template_path: Path | None = None) -> Path:
    if template_path is not None:
        template_parent = Path(template_path).resolve().parent
        data_sets_root = Path(__file__).resolve().parent / "unbundled" / 'data_sets'
        if path_is_relative_to_v2(template_parent, data_sets_root):
            return template_parent
    return DEFAULT_PROMPT_SCENARIO_OUTPUT_DIR_V2


def normalize_prompt_output_dir_v2(output_dir: str | Path | None, template_path: Path | None = None) -> Path:
    if output_dir is None or not str(output_dir).strip():
        return prompt_scenario_output_dir_v2(template_path)
    path = Path(str(output_dir).strip()).expanduser()
    if not path.is_absolute():
        path = (SCRIPT_DIR.parent / path).resolve()
    return path


def prompt_scenario_output_path_v2(
    output_filename: str,
    template_path: Path | None = None,
    output_dir: str | Path | None = None,
) -> Path:
    return normalize_prompt_output_dir_v2(output_dir, template_path) / normalize_output_filename(output_filename)


def register_prompt_output_dir_for_runner_v2(
    output_dir: str | Path | None,
    template_path: Path | None = None,
) -> bool:
    if output_dir is None or not str(output_dir).strip():
        return False
    try:
        folder = normalize_prompt_output_dir_v2(output_dir, template_path).resolve()
    except OSError:
        folder = normalize_prompt_output_dir_v2(output_dir, template_path).absolute()

    try:
        if DEFAULT_SCANER_RUNNER_SETTINGS_PATH.exists():
            payload = json.loads(DEFAULT_SCANER_RUNNER_SETTINGS_PATH.read_text(encoding="utf-8"))
            if not isinstance(payload, dict):
                payload = {}
        else:
            payload = {}
    except (OSError, json.JSONDecodeError):
        payload = {}

    raw_folders = payload.get("scenario_folders", [])
    if isinstance(raw_folders, str):
        raw_folders = [raw_folders]
    if not isinstance(raw_folders, list):
        raw_folders = []

    folders: list[str] = []
    seen: set[str] = set()
    for value in raw_folders:
        text = str(value).strip()
        if not text:
            continue
        existing_path = Path(text).expanduser()
        try:
            existing_path = existing_path.resolve()
        except OSError:
            existing_path = existing_path.absolute()
        key = str(existing_path).lower()
        if key in seen:
            continue
        seen.add(key)
        folders.append(str(existing_path))

    folder_key = str(folder).lower()
    if folder_key in seen:
        return False

    folders.append(str(folder))
    payload["scenario_folders"] = folders
    try:
        DEFAULT_SCANER_RUNNER_SETTINGS_PATH.parent.mkdir(parents=True, exist_ok=True)
        DEFAULT_SCANER_RUNNER_SETTINGS_PATH.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    except OSError:
        return False
    return True


def extract_prompt_output_filename_v2(prompt_text: str) -> str | None:
    safe_name_pattern = r"[A-Za-z0-9][A-Za-z0-9_. -]{0,96}(?:\.sce)?"
    patterns = (
        rf"(?:^|\n)\s*(?:output(?:\s*file(?:name)?)?|filename|file\s*name|save\s*as|檔名|档名|輸出檔|输出文件)\s*[:=]\s*['\"]?(?P<name>{safe_name_pattern})['\"]?",
        rf"(?:^|\n)\s*(?:命名(?:為|为)?|檔案命名(?:為|为)?|文件命名(?:为)?)\s*[:=]?\s*['\"]?(?P<name>{safe_name_pattern})['\"]?",
    )
    for pattern in patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE)
        if not match:
            continue
        try:
            return normalize_output_filename(match.group("name"))
        except ValueError:
            continue
    return None


def normalize_audio_filename(value: str) -> str:
    filename = value.strip()
    if not filename:
        raise ValueError("Audio file is required.")
    if not filename.lower().endswith(".wav"):
        filename += ".wav"
    if Path(filename).name != filename:
        raise ValueError("Use an audio filename only, for example NormalDriveTest_400.wav.")
    return filename


def upsert_trigger_from_template(
    scenario: ET.Element,
    *,
    trigger_name: str,
    template_trigger: ET.Element,
) -> ET.Element:
    try:
        return find_named_element(scenario, "Trigger", trigger_name)
    except ValueError:
        trigger = copy.deepcopy(template_trigger)
        name_element = trigger.find("name")
        if name_element is None:
            raise ValueError("Template trigger is missing its <name> element.")
        name_element.text = trigger_name
        scenario.append(trigger)
        return trigger


def validate_parameters(params: ScenarioParameters) -> None:
    if params.front_gap_m <= 0:
        raise ValueError("Front gap must be greater than 0 m.")
    if params.rear_gap_m <= 0:
        raise ValueError("Rear gap must be greater than 0 m.")
    if params.left_lane_gap_m <= 0:
        raise ValueError("Left-lane gap must be greater than 0 m.")
    if params.timing_ref_speed_kmh <= 0:
        raise ValueError("Timing reference speed must be greater than 0 km/h.")
    if params.rear_lane_change_time_s < 0:
        raise ValueError("Rear lane-change time cannot be negative.")
    if params.front_stop_time_s < 0:
        raise ValueError("Front stop time cannot be negative.")
    if params.rear_stop_time_s < 0:
        raise ValueError("Rear stop time cannot be negative.")
    if params.total_experiment_time_s <= 0:
        raise ValueError("Total experiment time must be greater than 0 s.")
    if params.audio_trigger_time_s < 0:
        raise ValueError("Audio time cannot be negative.")
    params.audio_file = normalize_audio_filename(params.audio_file)


def replace_script_file_token(script_text: str, scenario_token: str) -> str:
    return re.sub(
        r'FILE="Agent1_Type1/[^"]+_Script_0"',
        f'FILE="Agent1_Type1/{scenario_token}_Script_0"',
        script_text,
    )


def build_description(params: ScenarioParameters) -> str:
    return (
        "Simple human-factor scenario generated from ERTR_LC_Keep_CR.sce; "
        f"front_gap_m={format_number(params.front_gap_m)}, "
        f"rear_gap_m={format_number(params.rear_gap_m)}, "
        f"left_lane_gap_m={format_number(params.left_lane_gap_m)}, "
        f"rear_lane_change_time_s={format_number(params.rear_lane_change_time_s)}, "
        f"front_stop_time_s={format_number(params.front_stop_time_s)}, "
        f"rear_stop_time_s={format_number(params.rear_stop_time_s)}, "
        f"audio_time_s={format_number(params.audio_trigger_time_s)}, "
        f"audio_file={params.audio_file}, "
        f"total_experiment_time_s={format_number(params.total_experiment_time_s)}, "
        f"timing_ref_speed_kmh={format_number(params.timing_ref_speed_kmh)}"
    )


def normalize_written_xml(output_path: Path) -> None:
    xml_text = output_path.read_text(encoding="utf-8")
    lines = xml_text.splitlines()
    if not lines:
        raise ValueError("Generated XML file is empty.")

    lines[0] = '<?xml version="1.0" encoding="UTF-8" standalone="yes" ?>'
    xml_text = "\n".join(lines) + "\n"

    if "xmlns:xsi=" not in xml_text:
        xml_text = re.sub(
            r"<sce\b([^>]*)>",
            r'<sce\1 xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">',
            xml_text,
            count=1,
        )

    output_path.write_text(xml_text, encoding="utf-8")


def generate_scenario(
    *,
    template_path: Path,
    output_path: Path,
    params: ScenarioParameters,
    defaults: TemplateDefaults,
) -> Path:
    validate_parameters(params)

    tree = ET.parse(template_path)
    scenario = tree.getroot().find("Scenario")
    if scenario is None:
        raise ValueError("Template is missing <Scenario>.")

    scenario_token = output_path.stem

    name_element = scenario.find("name")
    original_name = scenario.find("ProjectInfos/originalName")
    description = scenario.find("description")
    if name_element is None or original_name is None or description is None:
        raise ValueError("Template is missing scenario metadata fields.")

    name_element.text = scenario_token
    original_name.text = output_path.name
    description.text = build_description(params)

    for script_element in scenario.findall(".//ScenarioScript/script"):
        script_text = replace_script_file_token(script_element.text or "", scenario_token)
        if "TYPEOF ACTION (SOUND_" in script_text:
            script_text = replace_audio_configuration(
                script_text,
                audio_file=params.audio_file,
                audio_trigger_name=AUDIO_TRIGGER_NAME,
            )
        script_element.text = script_text

    stop_criteria = scenario.find("ScenarioStopCriteria")
    if stop_criteria is None:
        raise ValueError("Template is missing <ScenarioStopCriteria>.")
    final_time = stop_criteria.find("finalTime")
    stop_at_final_time = stop_criteria.find("stopAtFinalTime")
    if final_time is None or stop_at_final_time is None:
        raise ValueError("Template is missing ScenarioStopCriteria/finalTime or stopAtFinalTime.")
    final_time.text = format_number(params.total_experiment_time_s)
    stop_at_final_time.text = "1"

    ego_abscissa = defaults.ego_abscissa
    timing_speed_mps = params.timing_ref_speed_kmh / 3.6

    ego = find_named_element(scenario, "Vehicle", EGO_NAME)
    rear = find_named_element(scenario, "Vehicle", REAR_NAME)
    front = find_named_element(scenario, "Vehicle", FRONT_NAME)
    left_lane = find_named_element(scenario, "Vehicle", LEFT_LANE_NAME)

    set_object_position(
        ego,
        abscissa=ego_abscissa,
        lane_gap=defaults.right_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )
    set_object_position(
        rear,
        abscissa=ego_abscissa - params.rear_gap_m,
        lane_gap=defaults.right_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )
    set_object_position(
        front,
        abscissa=ego_abscissa + params.front_gap_m,
        lane_gap=defaults.right_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )
    set_object_position(
        left_lane,
        abscissa=ego_abscissa + params.left_lane_gap_m,
        lane_gap=defaults.left_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )

    start_trigger = find_named_element(scenario, "Trigger", START_TRIGGER_NAME)
    rear_lane_change_trigger = find_named_element(scenario, "Trigger", REAR_LANE_CHANGE_TRIGGER_NAME)
    front_stop_trigger = find_named_element(scenario, "Trigger", FRONT_STOP_TRIGGER_NAME)
    rear_stop_trigger = find_named_element(scenario, "Trigger", REAR_STOP_TRIGGER_NAME)
    audio_trigger = upsert_trigger_from_template(
        scenario,
        trigger_name=AUDIO_TRIGGER_NAME,
        template_trigger=front_stop_trigger,
    )

    set_object_position(
        start_trigger,
        abscissa=ego_abscissa + defaults.start_trigger_offset_m,
        lane_gap=defaults.right_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )
    set_object_position(
        rear_lane_change_trigger,
        abscissa=ego_abscissa + (params.rear_lane_change_time_s * timing_speed_mps),
        lane_gap=defaults.right_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )
    set_object_position(
        front_stop_trigger,
        abscissa=ego_abscissa + (params.front_stop_time_s * timing_speed_mps),
        lane_gap=defaults.right_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )
    set_object_position(
        rear_stop_trigger,
        abscissa=ego_abscissa + (params.rear_stop_time_s * timing_speed_mps),
        lane_gap=defaults.right_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )
    set_object_position(
        audio_trigger,
        abscissa=ego_abscissa + (params.audio_trigger_time_s * timing_speed_mps),
        lane_gap=defaults.right_lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )

    tree.write(output_path, encoding="utf-8", xml_declaration=True, short_empty_elements=False)
    normalize_written_xml(output_path)
    return output_path


class ScenarioGui(tk.Tk):
    MAP_WIDTH = 640
    MAP_HEIGHT = 470
    TIMELINE_WIDTH = 640
    TIMELINE_HEIGHT = 330

    def __init__(self, template_path: Path) -> None:
        super().__init__()
        self.title("Simple HF Scenario GUI")
        self.resizable(True, True)
        self.minsize(1280, 900)

        self.template_path = template_path
        self.defaults = load_template_defaults(template_path)
        self.reference_context = load_reference_context(REFERENCE_CONTEXT_PATH)
        self._preview_after_id: str | None = None
        self._map_drag_target: str | None = None
        self._timeline_drag_target: str | None = None
        self._map_model: dict[str, object] = {}
        self._timeline_model: dict[str, object] = {}
        self.audio_file_options = tuple(dict.fromkeys((self.defaults.audio_file, *KNOWN_AUDIO_FILES)))

        self.output_filename_var = tk.StringVar(value=DEFAULT_OUTPUT_FILENAME)
        self.front_gap_var = tk.StringVar(value=format_number(self.defaults.front_gap_m))
        self.rear_gap_var = tk.StringVar(value=format_number(self.defaults.rear_gap_m))
        self.left_lane_gap_var = tk.StringVar(value=format_number(self.defaults.left_lane_vehicle_gap_m))
        self.timing_speed_var = tk.StringVar(value=format_number(self.defaults.timing_ref_speed_kmh))
        self.rear_lane_change_time_var = tk.StringVar(value=format_number(self.defaults.rear_lane_change_time_s))
        self.front_stop_time_var = tk.StringVar(value=format_number(self.defaults.front_stop_time_s))
        self.rear_stop_time_var = tk.StringVar(value=format_number(self.defaults.rear_stop_time_s))
        self.total_experiment_time_var = tk.StringVar(value=format_number(self.defaults.total_experiment_time_s))
        self.audio_trigger_time_var = tk.StringVar(value=format_number(self.defaults.audio_trigger_time_s))
        self.audio_file_var = tk.StringVar(value=self.defaults.audio_file)
        self.preview_status_var = tk.StringVar()
        self.preview_summary_var = tk.StringVar()

        self._build_layout()
        self._bind_preview_updates()
        self.after(0, self._refresh_preview)

    def _build_layout(self) -> None:
        container = ttk.Frame(self, padding=18)
        container.grid(row=0, column=0, sticky="nsew")
        container.columnconfigure(0, weight=0)
        container.columnconfigure(1, weight=1)
        container.rowconfigure(0, weight=1)

        controls = ttk.Frame(container)
        controls.grid(row=0, column=0, sticky="nw", padx=(0, 18))
        controls.columnconfigure(0, weight=1)
        preview = ttk.Frame(container)
        preview.grid(row=0, column=1, sticky="nsew")
        preview.columnconfigure(0, weight=1)

        ttk.Label(
            controls,
            text="Human-Factor Scenario Builder",
            font=("TkDefaultFont", 12, "bold"),
        ).grid(row=0, column=0, sticky="w", pady=(0, 6))

        ttk.Label(
            controls,
            text=(
                "Template: ERTR_LC_Keep_CR.sce\n"
                "Left side is grouped by scenario role.\n"
                "Right side stays synced with a cleaner map and a live timeline."
            ),
            justify="left",
        ).grid(row=1, column=0, sticky="w", pady=(0, 12))

        general_section = self._add_section(
            controls,
            row=2,
            title="General",
            description="Output name, timing basis, and when the scenario ends.",
        )
        self._add_entry_row(general_section, row=0, label="Output filename", variable=self.output_filename_var)
        self._add_entry_row(
            general_section,
            row=1,
            label="Total experiment time (s)",
            variable=self.total_experiment_time_var,
        )
        self._add_entry_row(
            general_section,
            row=2,
            label="Timing ref speed (km/h)",
            variable=self.timing_speed_var,
        )

        front_section = self._add_section(
            controls,
            row=3,
            title="Front Vehicle",
            description="Front car spacing and when it stops.",
        )
        self._add_entry_row(front_section, row=0, label="Initial gap (m)", variable=self.front_gap_var)
        self._add_entry_row(front_section, row=1, label="Stop time (s)", variable=self.front_stop_time_var)

        rear_section = self._add_section(
            controls,
            row=4,
            title="Rear Vehicle",
            description="Rear car spacing, lane change, and stop timing.",
        )
        self._add_entry_row(rear_section, row=0, label="Initial gap (m)", variable=self.rear_gap_var)
        self._add_entry_row(
            rear_section,
            row=1,
            label="Lane-change time (s)",
            variable=self.rear_lane_change_time_var,
        )
        self._add_entry_row(rear_section, row=2, label="Stop time (s)", variable=self.rear_stop_time_var)

        left_section = self._add_section(
            controls,
            row=5,
            title="Left Vehicle",
            description="Support vehicle position in the left lane.",
        )
        self._add_entry_row(left_section, row=0, label="Initial gap (m)", variable=self.left_lane_gap_var)

        audio_section = self._add_section(
            controls,
            row=6,
            title="Audio",
            description="Independent audio cue timing and the WAV that should play.",
        )
        self._add_entry_row(audio_section, row=0, label="Audio time (s)", variable=self.audio_trigger_time_var)
        self._add_combobox_row(
            audio_section,
            row=1,
            label="Audio file (.wav)",
            variable=self.audio_file_var,
            values=self.audio_file_options,
        )

        ttk.Label(
            controls,
            text=(
                "Interaction hints:\n"
                "Map drag changes Front / Rear / Left positions.\n"
                "Timeline drag changes LC / Stop / Audio times.\n"
                "ExecutiveCar stays fixed at 0 m."
            ),
            justify="left",
            foreground="#475569",
        ).grid(row=7, column=0, sticky="w", pady=(8, 10))

        button_row = ttk.Frame(controls)
        button_row.grid(row=8, column=0, sticky="e", pady=(2, 0))
        ttk.Button(button_row, text="Reset Defaults", command=self._reset_defaults).grid(row=0, column=0, padx=(0, 8))
        ttk.Button(button_row, text="Generate .sce", command=self._generate).grid(row=0, column=1)

        ttk.Label(preview, text="Live Preview", font=("TkDefaultFont", 12, "bold")).grid(row=0, column=0, sticky="w")
        ttk.Label(
            preview,
            text=(
                "Top: a cleaner road map with editable vehicles and a soft 4-loop reference layer.\n"
                "Bottom: the event timeline with LC, stop, audio, and scenario end timing."
            ),
            justify="left",
        ).grid(row=1, column=0, sticky="w", pady=(4, 10))

        self.preview_status_label = tk.Label(
            preview,
            textvariable=self.preview_status_var,
            anchor="w",
            justify="left",
            bg="#e0f2fe",
            fg="#0f172a",
            padx=10,
            pady=8,
            relief="solid",
            bd=1,
        )
        self.preview_status_label.grid(row=2, column=0, sticky="ew", pady=(0, 10))

        self.map_canvas = tk.Canvas(
            preview,
            width=self.MAP_WIDTH,
            height=self.MAP_HEIGHT,
            bg="#f8fafc",
            highlightthickness=1,
            highlightbackground="#cbd5e1",
        )
        self.map_canvas.grid(row=3, column=0, sticky="ew")

        self.timeline_canvas = tk.Canvas(
            preview,
            width=self.TIMELINE_WIDTH,
            height=self.TIMELINE_HEIGHT,
            bg="#f8fafc",
            highlightthickness=1,
            highlightbackground="#cbd5e1",
        )
        self.timeline_canvas.grid(row=4, column=0, sticky="ew", pady=(12, 0))
        self.map_canvas.bind("<ButtonPress-1>", self._on_map_press)
        self.map_canvas.bind("<B1-Motion>", self._on_map_drag)
        self.map_canvas.bind("<ButtonRelease-1>", self._on_map_release)
        self.timeline_canvas.bind("<ButtonPress-1>", self._on_timeline_press)
        self.timeline_canvas.bind("<B1-Motion>", self._on_timeline_drag)
        self.timeline_canvas.bind("<ButtonRelease-1>", self._on_timeline_release)

        self.preview_summary_label = tk.Label(
            preview,
            textvariable=self.preview_summary_var,
            anchor="w",
            justify="left",
            wraplength=self.TIMELINE_WIDTH - 20,
            bg="#f8fafc",
            fg="#334155",
            padx=2,
            pady=8,
        )
        self.preview_summary_label.grid(row=5, column=0, sticky="ew", pady=(6, 0))

    def _add_section(self, parent: ttk.Frame, *, row: int, title: str, description: str) -> ttk.LabelFrame:
        section = ttk.LabelFrame(parent, text=title, padding=(12, 10))
        section.grid(row=row, column=0, sticky="ew", pady=(0, 10))
        section.columnconfigure(1, weight=1)
        ttk.Label(
            section,
            text=description,
            justify="left",
            foreground="#64748b",
            wraplength=290,
        ).grid(row=0, column=0, columnspan=2, sticky="w", pady=(0, 8))
        return section

    def _add_entry_row(self, parent: ttk.LabelFrame, *, row: int, label: str, variable: tk.StringVar) -> None:
        ttk.Label(parent, text=label).grid(row=row + 1, column=0, sticky="w", padx=(0, 10), pady=4)
        ttk.Entry(parent, textvariable=variable, width=20).grid(row=row + 1, column=1, sticky="ew", pady=4)

    def _add_combobox_row(
        self,
        parent: ttk.LabelFrame,
        *,
        row: int,
        label: str,
        variable: tk.StringVar,
        values: tuple[str, ...],
    ) -> None:
        ttk.Label(parent, text=label).grid(row=row + 1, column=0, sticky="w", padx=(0, 10), pady=4)
        ttk.Combobox(parent, textvariable=variable, values=values, state="normal").grid(
            row=row + 1,
            column=1,
            sticky="ew",
            pady=4,
        )

    def _reset_defaults(self) -> None:
        self.output_filename_var.set(DEFAULT_OUTPUT_FILENAME)
        self.front_gap_var.set(format_number(self.defaults.front_gap_m))
        self.rear_gap_var.set(format_number(self.defaults.rear_gap_m))
        self.left_lane_gap_var.set(format_number(self.defaults.left_lane_vehicle_gap_m))
        self.timing_speed_var.set(format_number(self.defaults.timing_ref_speed_kmh))
        self.rear_lane_change_time_var.set(format_number(self.defaults.rear_lane_change_time_s))
        self.front_stop_time_var.set(format_number(self.defaults.front_stop_time_s))
        self.rear_stop_time_var.set(format_number(self.defaults.rear_stop_time_s))
        self.total_experiment_time_var.set(format_number(self.defaults.total_experiment_time_s))
        self.audio_trigger_time_var.set(format_number(self.defaults.audio_trigger_time_s))
        self.audio_file_var.set(self.defaults.audio_file)
        self._schedule_preview_refresh()

    def _bind_preview_updates(self) -> None:
        variables = [
            self.front_gap_var,
            self.rear_gap_var,
            self.left_lane_gap_var,
            self.timing_speed_var,
            self.rear_lane_change_time_var,
            self.front_stop_time_var,
            self.rear_stop_time_var,
            self.total_experiment_time_var,
            self.audio_trigger_time_var,
            self.audio_file_var,
        ]
        for variable in variables:
            variable.trace_add("write", self._schedule_preview_refresh)

    def _schedule_preview_refresh(self, *_args: object) -> None:
        if self._preview_after_id is not None:
            self.after_cancel(self._preview_after_id)
        self._preview_after_id = self.after(70, self._refresh_preview)

    def _parse_float_field(self, label: str, value: str) -> float:
        text = value.strip()
        if not text:
            raise ValueError(f"{label} is empty.")
        try:
            return float(text)
        except ValueError as exc:
            raise ValueError(f"{label} must be a valid number.") from exc

    def _read_params(self) -> ScenarioParameters:
        return ScenarioParameters(
            output_filename=normalize_output_filename(self.output_filename_var.get()),
            front_gap_m=self._parse_float_field("Front gap", self.front_gap_var.get()),
            rear_gap_m=self._parse_float_field("Rear gap", self.rear_gap_var.get()),
            left_lane_gap_m=self._parse_float_field("Left-lane gap", self.left_lane_gap_var.get()),
            timing_ref_speed_kmh=self._parse_float_field("Timing reference speed", self.timing_speed_var.get()),
            rear_lane_change_time_s=self._parse_float_field("Rear lane-change time", self.rear_lane_change_time_var.get()),
            front_stop_time_s=self._parse_float_field("Front stop time", self.front_stop_time_var.get()),
            rear_stop_time_s=self._parse_float_field("Rear stop time", self.rear_stop_time_var.get()),
            total_experiment_time_s=self._parse_float_field(
                "Total experiment time",
                self.total_experiment_time_var.get(),
            ),
            audio_trigger_time_s=self._parse_float_field("Audio time", self.audio_trigger_time_var.get()),
            audio_file=normalize_audio_filename(self.audio_file_var.get()),
        )

    def _read_preview_params(self) -> tuple[ScenarioParameters | None, str | None]:
        try:
            params = ScenarioParameters(
                output_filename="preview.sce",
                front_gap_m=self._parse_float_field("Front gap", self.front_gap_var.get()),
                rear_gap_m=self._parse_float_field("Rear gap", self.rear_gap_var.get()),
                left_lane_gap_m=self._parse_float_field("Left-lane gap", self.left_lane_gap_var.get()),
                timing_ref_speed_kmh=self._parse_float_field("Timing reference speed", self.timing_speed_var.get()),
                rear_lane_change_time_s=self._parse_float_field(
                    "Rear lane-change time",
                    self.rear_lane_change_time_var.get(),
                ),
                front_stop_time_s=self._parse_float_field("Front stop time", self.front_stop_time_var.get()),
                rear_stop_time_s=self._parse_float_field("Rear stop time", self.rear_stop_time_var.get()),
                total_experiment_time_s=self._parse_float_field(
                    "Total experiment time",
                    self.total_experiment_time_var.get(),
                ),
                audio_trigger_time_s=self._parse_float_field("Audio time", self.audio_trigger_time_var.get()),
                audio_file=normalize_audio_filename(self.audio_file_var.get()),
            )
            validate_parameters(params)
        except ValueError as exc:
            return None, str(exc)

        return params, None

    def _generate(self) -> None:
        try:
            params = self._read_params()
            validate_parameters(params)
            output_path = prompt_scenario_output_path_v2(params.output_filename, self.template_path)
            if output_path.exists():
                should_overwrite = messagebox.askyesno(
                    "Overwrite Existing File",
                    f"{output_path.name} already exists.\nDo you want to overwrite it?",
                )
                if not should_overwrite:
                    return

            generate_scenario(
                template_path=self.template_path,
                output_path=output_path,
                params=params,
                defaults=self.defaults,
            )
        except Exception as exc:  # noqa: BLE001
            messagebox.showerror("Generation Failed", str(exc))
            return

        messagebox.showinfo(
            "Scenario Generated",
            f"Created:\n{output_path}\n\nYou can now open the new .sce in SCANeR.",
        )

    def _refresh_preview(self) -> None:
        self._preview_after_id = None
        params, error = self._read_preview_params()
        if params is None:
            self._set_preview_status(error or "Preview waits for valid numeric inputs.", level="warning")
            self.preview_summary_var.set("Fill every numeric field with a valid value to redraw the map and timeline.")
            self._clear_canvas_with_message(
                self.map_canvas,
                "Lane map will appear here\nonce all numeric values are valid.",
            )
            self._clear_canvas_with_message(
                self.timeline_canvas,
                "Event timeline will appear here\nonce all numeric values are valid.",
            )
            return

        warnings = self._build_preview_warnings(params)
        status_text = (
            "Preview updates live. Drag cars on the map or drag LC / Stop / Audio markers on the timeline."
            if not warnings
            else "Preview updated with timing notes: " + " ".join(warnings)
        )
        self._set_preview_status(status_text, level="warning" if warnings else "info")
        self.preview_summary_var.set(self._build_preview_summary(params))
        self._draw_map(params)
        self._draw_timeline(params)

    def _set_preview_status(self, text: str, *, level: str) -> None:
        palette = {
            "info": {"bg": "#e0f2fe", "fg": "#0f172a"},
            "warning": {"bg": "#fef3c7", "fg": "#78350f"},
        }
        colors = palette[level]
        self.preview_status_var.set(text)
        self.preview_status_label.configure(bg=colors["bg"], fg=colors["fg"])

    def _build_preview_warnings(self, params: ScenarioParameters) -> list[str]:
        warnings: list[str] = []
        if params.rear_stop_time_s < params.rear_lane_change_time_s:
            warnings.append("Rear stop happens before the rear lane-change trigger.")
        if params.front_stop_time_s < params.rear_lane_change_time_s:
            warnings.append("Front stop happens before the rear car changes lane.")
        latest_event_time_s = max(
            params.rear_lane_change_time_s,
            params.front_stop_time_s,
            params.rear_stop_time_s,
            params.audio_trigger_time_s,
        )
        if params.total_experiment_time_s < latest_event_time_s:
            warnings.append("Scenario end is earlier than at least one event.")
        return warnings

    def _build_preview_summary(self, params: ScenarioParameters) -> str:
        timing_speed_mps = params.timing_ref_speed_kmh / 3.6
        rear_lane_change_dist = params.rear_lane_change_time_s * timing_speed_mps
        front_stop_dist = params.front_stop_time_s * timing_speed_mps
        rear_stop_dist = params.rear_stop_time_s * timing_speed_mps
        audio_dist = params.audio_trigger_time_s * timing_speed_mps
        return (
            f"Scenario end: {format_number(params.total_experiment_time_s)} s. "
            f"Relative positions: front {format_number(params.front_gap_m)} m ahead, "
            f"rear {format_number(params.rear_gap_m)} m behind, "
            f"left-lane vehicle {format_number(params.left_lane_gap_m)} m ahead.\n"
            f"Trigger distances from ExecutiveCar at {format_number(params.timing_ref_speed_kmh)} km/h: "
            f"rear lane change +{format_number(rear_lane_change_dist)} m, "
            f"front stop +{format_number(front_stop_dist)} m, "
            f"rear stop +{format_number(rear_stop_dist)} m, "
            f"audio +{format_number(audio_dist)} m ({params.audio_file})."
        )

    def _clear_canvas_with_message(self, canvas: tk.Canvas, message: str) -> None:
        canvas.delete("all")
        width = int(canvas.cget("width"))
        height = int(canvas.cget("height"))
        canvas.create_text(
            width / 2,
            height / 2,
            text=message,
            justify="center",
            fill="#64748b",
            font=("TkDefaultFont", 12, "bold"),
        )

    def _create_badge(
        self,
        canvas: tk.Canvas,
        x: float,
        y: float,
        text: str,
        *,
        anchor: str = "w",
        fill: str = "#ffffff",
        outline: str = "#cbd5e1",
        text_color: str = "#0f172a",
        font: tuple[str, int, str] | tuple[str, int] = ("TkDefaultFont", 9, "bold"),
    ) -> None:
        text_id = canvas.create_text(x, y, text=text, anchor=anchor, fill=text_color, font=font)
        bbox = canvas.bbox(text_id)
        if bbox is None:
            return
        badge_id = canvas.create_rectangle(
            bbox[0] - 5,
            bbox[1] - 3,
            bbox[2] + 5,
            bbox[3] + 3,
            fill=fill,
            outline=outline,
        )
        canvas.tag_lower(badge_id, text_id)

    def _draw_vehicle(
        self,
        canvas: tk.Canvas,
        *,
        lane_x: float,
        y: float,
        fill: str,
        label: str,
        detail: str,
        detail_anchor_x: float,
        detail_anchor: str,
        tags: tuple[str, ...] = (),
    ) -> None:
        half_width = 25
        half_height = 11
        canvas.create_rectangle(
            lane_x - half_width,
            y - half_height,
            lane_x + half_width,
            y + half_height,
            fill=fill,
            outline="#1f2937",
            width=1,
            tags=tags,
        )
        canvas.create_text(
            lane_x,
            y,
            text=label,
            fill="#ffffff",
            font=("TkDefaultFont", 9, "bold"),
            tags=tags,
        )
        self._create_badge(
            canvas,
            detail_anchor_x,
            y,
            detail,
            anchor=detail_anchor,
            fill="#ffffff",
            outline="#cbd5e1",
            text_color="#0f172a",
            font=("TkDefaultFont", 9),
        )

    def _draw_map(self, params: ScenarioParameters) -> None:
        canvas = self.map_canvas
        canvas.delete("all")
        width = int(canvas.cget("width"))
        height = int(canvas.cget("height"))

        canvas.create_rectangle(0, 0, width, height, fill="#ffffff", outline="")
        canvas.create_text(
            16,
            18,
            text="Scenario Map",
            anchor="w",
            fill="#0f172a",
            font=("TkDefaultFont", 11, "bold"),
        )
        canvas.create_text(
            16,
            36,
            text="Editable vehicles are bold. The muted layer shows nearby 4-loop reference traffic and triggers.",
            anchor="w",
            fill="#64748b",
            font=("TkDefaultFont", 8),
        )

        road_left = 82
        road_right = min(420, width - 220)
        road_top = 68
        road_bottom = height - 42
        legend_left = road_right + 24
        timing_speed_mps = params.timing_ref_speed_kmh / 3.6
        current_events = [
            ("Rear LC", params.rear_lane_change_time_s, params.rear_lane_change_time_s * timing_speed_mps, "#7c3aed"),
            ("Front stop", params.front_stop_time_s, params.front_stop_time_s * timing_speed_mps, "#dc2626"),
            ("Rear stop", params.rear_stop_time_s, params.rear_stop_time_s * timing_speed_mps, "#ea580c"),
            ("Audio", params.audio_trigger_time_s, params.audio_trigger_time_s * timing_speed_mps, "#0f766e"),
        ]
        context_distances = [vehicle.relative_distance for vehicle in self.reference_context.vehicles]
        context_distances.extend(trigger.relative_distance for trigger in self.reference_context.triggers)

        min_rel = min(-params.rear_gap_m, 0.0, *(context_distances or [0.0])) - 10.0
        max_rel = max(
            params.front_gap_m,
            params.left_lane_gap_m,
            *(event_distance for _, _, event_distance, _ in current_events),
            *(context_distances or [0.0]),
        ) + 10.0
        span = max(max_rel - min_rel, 80.0)

        lane_gap_values = sorted(
            {
                self.defaults.right_lane_gap,
                self.defaults.left_lane_gap,
                *self.reference_context.lane_gaps,
            }
        )
        if not lane_gap_values:
            lane_gap_values = [self.defaults.left_lane_gap, self.defaults.right_lane_gap]
        gap_min = min(lane_gap_values) - 1.75
        gap_max = max(lane_gap_values) + 1.75
        gap_span = max(gap_max - gap_min, 1.0)

        def rel_to_y(relative_distance: float) -> float:
            return road_top + ((max_rel - relative_distance) / span) * (road_bottom - road_top)

        def gap_to_x(lane_gap: float) -> float:
            return road_left + ((lane_gap - gap_min) / gap_span) * (road_right - road_left)

        canvas.create_rectangle(road_left, road_top, road_right, road_bottom, fill="#f8fafc", outline="#cbd5e1", width=1)
        for lane_gap in lane_gap_values:
            lane_x = gap_to_x(lane_gap)
            is_editable_lane = math.isclose(lane_gap, self.defaults.right_lane_gap, abs_tol=0.01) or math.isclose(
                lane_gap,
                self.defaults.left_lane_gap,
                abs_tol=0.01,
            )
            canvas.create_line(
                lane_x,
                road_top + 10,
                lane_x,
                road_bottom - 10,
                fill="#94a3b8" if is_editable_lane else "#d7dee8",
                dash=() if is_editable_lane else (4, 8),
                width=2 if is_editable_lane else 1,
            )

        canvas.create_text(
            gap_to_x(self.defaults.left_lane_gap),
            road_top - 18,
            text="Left lane",
            fill="#475569",
            font=("TkDefaultFont", 8, "bold"),
        )
        canvas.create_text(
            gap_to_x(self.defaults.right_lane_gap),
            road_top - 18,
            text="Exec lane",
            fill="#475569",
            font=("TkDefaultFont", 8, "bold"),
        )

        tick_step = 5 if span <= 60 else 10 if span <= 140 else 20
        tick = math.floor(min_rel / tick_step) * tick_step
        while tick <= max_rel:
            y = rel_to_y(tick)
            is_zero = math.isclose(tick, 0.0, abs_tol=tick_step / 3)
            canvas.create_line(
                road_left - 6,
                y,
                road_right + 6,
                y,
                fill="#0f172a" if is_zero else "#e2e8f0",
                dash=() if is_zero else (2, 6),
                width=2 if is_zero else 1,
            )
            canvas.create_text(
                road_left - 14,
                y,
                text=f"{int(tick):+d} m",
                anchor="e",
                fill="#64748b",
                font=("TkDefaultFont", 8),
            )
            tick += tick_step

        for vehicle in self.reference_context.vehicles:
            lane_x = gap_to_x(vehicle.lane_gap)
            y = rel_to_y(vehicle.relative_distance)
            canvas.create_rectangle(
                lane_x - 10,
                y - 3,
                lane_x + 10,
                y + 3,
                fill="#d5dbe3",
                outline="",
            )

        for trigger in self.reference_context.triggers:
            y = rel_to_y(trigger.relative_distance)
            canvas.create_line(road_left + 6, y, road_right - 6, y, fill=trigger.color, dash=(2, 10), width=1)

        for event_index, (label, time_s, relative_distance, color) in enumerate(current_events):
            y = rel_to_y(relative_distance)
            canvas.create_line(road_left + 6, y, road_right - 6, y, fill=color, dash=(7, 4), width=2)
            self._create_badge(
                canvas,
                legend_left,
                road_top + 22 + event_index * 28,
                f"{label}  {format_number(time_s)} s",
                anchor="w",
                fill="#ffffff",
                outline=color,
                text_color="#0f172a",
            )

        self._draw_vehicle(
            canvas,
            lane_x=gap_to_x(self.defaults.right_lane_gap),
            y=rel_to_y(params.front_gap_m),
            fill="#16a34a",
            label="Front",
            detail=f"+{format_number(params.front_gap_m)} m",
            detail_anchor_x=legend_left,
            detail_anchor="w",
            tags=("drag_vehicle_front",),
        )
        self._draw_vehicle(
            canvas,
            lane_x=gap_to_x(self.defaults.right_lane_gap),
            y=rel_to_y(0.0),
            fill="#2563eb",
            label="Exec",
            detail="0 m reference",
            detail_anchor_x=legend_left,
            detail_anchor="w",
        )
        self._draw_vehicle(
            canvas,
            lane_x=gap_to_x(self.defaults.right_lane_gap),
            y=rel_to_y(-params.rear_gap_m),
            fill="#f59e0b",
            label="Rear",
            detail=f"-{format_number(params.rear_gap_m)} m",
            detail_anchor_x=legend_left,
            detail_anchor="w",
            tags=("drag_vehicle_rear",),
        )
        self._draw_vehicle(
            canvas,
            lane_x=gap_to_x(self.defaults.left_lane_gap),
            y=rel_to_y(params.left_lane_gap_m),
            fill="#8b5cf6",
            label="Left",
            detail=f"+{format_number(params.left_lane_gap_m)} m",
            detail_anchor_x=legend_left,
            detail_anchor="w",
            tags=("drag_vehicle_left",),
        )

        canvas.create_text(
            legend_left,
            road_top + 146,
            text="4-loop reference",
            anchor="w",
            fill="#334155",
            font=("TkDefaultFont", 9, "bold"),
        )
        self._create_badge(
            canvas,
            legend_left,
            road_top + 168,
            f"{len(self.reference_context.vehicles)} ghost vehicles",
            anchor="w",
            fill="#ffffff",
            outline="#cbd5e1",
            text_color="#334155",
            font=("TkDefaultFont", 8),
        )
        for index, trigger in enumerate(self.reference_context.triggers):
            legend_y = road_top + 196 + index * 22
            canvas.create_line(legend_left, legend_y, legend_left + 16, legend_y, fill=trigger.color, width=2)
            canvas.create_text(
                legend_left + 24,
                legend_y,
                text=trigger.label,
                anchor="w",
                fill="#475569",
                font=("TkDefaultFont", 8),
            )

        canvas.create_text(
            legend_left,
            road_bottom - 8,
            text="Drag Front / Rear / Left vertically",
            anchor="w",
            fill="#475569",
            font=("TkDefaultFont", 8, "bold"),
        )

        self._map_model = {
            "road_top": road_top,
            "road_bottom": road_bottom,
            "min_rel": min_rel,
            "max_rel": max_rel,
        }

    def _draw_timeline(self, params: ScenarioParameters) -> None:
        canvas = self.timeline_canvas
        canvas.delete("all")
        width = int(canvas.cget("width"))
        height = int(canvas.cget("height"))

        canvas.create_rectangle(0, 0, width, height, fill="#ffffff", outline="")
        canvas.create_text(
            16,
            18,
            text="Event Timeline",
            anchor="w",
            fill="#0f172a",
            font=("TkDefaultFont", 11, "bold"),
        )

        timing_speed_mps = params.timing_ref_speed_kmh / 3.6
        reference_trigger_times = [
            max(0.0, trigger.relative_distance / timing_speed_mps)
            for trigger in self.reference_context.triggers
            if timing_speed_mps > 0
        ]

        left = 132
        right = width - 28
        horizon = max(
            12.0,
            params.total_experiment_time_s,
            params.rear_lane_change_time_s,
            params.front_stop_time_s,
            params.rear_stop_time_s,
            params.audio_trigger_time_s,
            *(reference_trigger_times or [0.0]),
        ) + 2.0
        horizon = math.ceil(horizon / 2.0) * 2.0
        top = 56
        bottom = height - 34
        rows = {
            "ExecutiveCar": top + 28,
            "Rear car": top + 88,
            "Front car": top + 148,
            "Audio": top + 208,
            "4-loop refs": top + 268,
        }

        def time_to_x(time_s: float) -> float:
            return left + (time_s / horizon) * (right - left)

        tick_step = 1 if horizon <= 10 else 2 if horizon <= 20 else 5
        current_tick = 0.0
        while current_tick <= horizon + 1e-9:
            x = time_to_x(current_tick)
            canvas.create_line(x, top, x, bottom, fill="#e2e8f0")
            canvas.create_text(x, bottom + 12, text=f"{format_number(current_tick)} s", fill="#64748b", font=("TkDefaultFont", 8))
            current_tick += tick_step

        for row_name, row_y in rows.items():
            canvas.create_text(left - 14, row_y, text=row_name, anchor="e", fill="#334155", font=("TkDefaultFont", 9, "bold"))
            canvas.create_rectangle(left, row_y - 12, right, row_y + 12, fill="#e5e7eb", outline="#cbd5e1")

        canvas.create_rectangle(left, rows["ExecutiveCar"] - 12, right, rows["ExecutiveCar"] + 12, fill="#2563eb", outline="")
        canvas.create_text((left + right) / 2, rows["ExecutiveCar"], text="steady drive", fill="#ffffff", font=("TkDefaultFont", 9, "bold"))

        rear_row = rows["Rear car"]
        front_row = rows["Front car"]
        audio_row = rows["Audio"]
        refs_row = rows["4-loop refs"]
        lane_change_x = time_to_x(min(params.rear_lane_change_time_s, horizon))
        rear_stop_x = time_to_x(min(params.rear_stop_time_s, horizon))
        front_stop_x = time_to_x(min(params.front_stop_time_s, horizon))
        audio_x = time_to_x(min(params.audio_trigger_time_s, horizon))
        lane_change_time = min(params.rear_lane_change_time_s, horizon)
        rear_stop_time = min(params.rear_stop_time_s, horizon)
        front_stop_time = min(params.front_stop_time_s, horizon)
        scenario_end_x = time_to_x(min(params.total_experiment_time_s, horizon))

        if lane_change_time > 0:
            canvas.create_rectangle(left, rear_row - 12, lane_change_x, rear_row + 12, fill="#2563eb", outline="")
        if lane_change_time < rear_stop_time:
            canvas.create_rectangle(lane_change_x, rear_row - 12, rear_stop_x, rear_row + 12, fill="#8b5cf6", outline="")
        if rear_stop_time < horizon:
            canvas.create_rectangle(rear_stop_x, rear_row - 12, right, rear_row + 12, fill="#f59e0b", outline="")
        if lane_change_time >= 1.5:
            canvas.create_text((left + lane_change_x) / 2, rear_row, text="right lane", fill="#ffffff", font=("TkDefaultFont", 8, "bold"))
        if rear_stop_time - lane_change_time >= 1.5:
            canvas.create_text((lane_change_x + rear_stop_x) / 2, rear_row, text="left lane", fill="#ffffff", font=("TkDefaultFont", 8, "bold"))
        if horizon - rear_stop_time >= 1.5:
            canvas.create_text((rear_stop_x + right) / 2, rear_row, text="stopped", fill="#ffffff", font=("TkDefaultFont", 8, "bold"))

        if front_stop_time > 0:
            canvas.create_rectangle(left, front_row - 12, front_stop_x, front_row + 12, fill="#16a34a", outline="")
        if front_stop_time < horizon:
            canvas.create_rectangle(front_stop_x, front_row - 12, right, front_row + 12, fill="#ef4444", outline="")
        if front_stop_time >= 1.5:
            canvas.create_text((left + front_stop_x) / 2, front_row, text="moving", fill="#ffffff", font=("TkDefaultFont", 8, "bold"))
        if horizon - front_stop_time >= 1.5:
            canvas.create_text((front_stop_x + right) / 2, front_row, text="stopped", fill="#ffffff", font=("TkDefaultFont", 8, "bold"))

        canvas.create_text(
            left + 10,
            audio_row,
            text=shorten_name(params.audio_file, max_length=18),
            anchor="w",
            fill="#0f766e",
            font=("TkDefaultFont", 8, "bold"),
        )

        canvas.create_rectangle(left, refs_row - 12, right, refs_row + 12, fill="#f8fafc", outline="")
        canvas.create_text(
            left + 10,
            refs_row,
            text="ghost triggers from the 4-loop reference",
            anchor="w",
            fill="#64748b",
            font=("TkDefaultFont", 8, "bold"),
        )

        for trigger in self.reference_context.triggers:
            trigger_time = max(0.0, trigger.relative_distance / timing_speed_mps) if timing_speed_mps > 0 else 0.0
            x = time_to_x(min(trigger_time, horizon))
            canvas.create_line(x, refs_row - 14, x, refs_row + 14, fill=trigger.color, dash=(3, 4), width=1)
            self._create_badge(
                canvas,
                x,
                refs_row - 22 - (trigger.order % 2) * 16,
                trigger.label,
                anchor="center",
                fill="#ffffff",
                outline=trigger.color,
                text_color="#0f172a",
                font=("TkDefaultFont", 7),
            )

        self._draw_timeline_marker(
            canvas,
            lane_change_x,
            rear_row,
            color="#7c3aed",
            label=f"LC {format_number(params.rear_lane_change_time_s)} s",
            label_y=rear_row - 24,
            tags=("drag_event_rear_lane_change",),
        )
        self._draw_timeline_marker(
            canvas,
            rear_stop_x,
            rear_row,
            color="#ea580c",
            label=f"Stop {format_number(params.rear_stop_time_s)} s",
            label_y=rear_row + 24,
            tags=("drag_event_rear_stop",),
        )
        self._draw_timeline_marker(
            canvas,
            front_stop_x,
            front_row,
            color="#dc2626",
            label=f"Stop {format_number(params.front_stop_time_s)} s",
            label_y=front_row - 24,
            tags=("drag_event_front_stop",),
        )
        self._draw_timeline_marker(
            canvas,
            audio_x,
            audio_row,
            color="#0f766e",
            label=f"Audio {format_number(params.audio_trigger_time_s)} s",
            label_y=audio_row - 24,
            tags=("drag_event_audio",),
        )
        canvas.create_line(scenario_end_x, top - 4, scenario_end_x, bottom + 4, fill="#0f172a", width=2, dash=(4, 3))
        self._create_badge(
            canvas,
            scenario_end_x,
            top - 14,
            f"End {format_number(params.total_experiment_time_s)} s",
            anchor="center",
            fill="#ffffff",
            outline="#0f172a",
            text_color="#0f172a",
            font=("TkDefaultFont", 8, "bold"),
        )
        canvas.create_text(
            right,
            bottom + 26,
            text="Drag LC / Stop / Audio markers horizontally",
            anchor="e",
            fill="#475569",
            font=("TkDefaultFont", 8, "bold"),
        )
        self._timeline_model = {
            "left": left,
            "right": right,
            "horizon": horizon,
        }

    def _draw_timeline_marker(
        self,
        canvas: tk.Canvas,
        x: float,
        row_y: float,
        *,
        color: str,
        label: str,
        label_y: float,
        tags: tuple[str, ...] = (),
    ) -> None:
        canvas.create_line(x, row_y - 16, x, row_y + 16, fill=color, width=2, tags=tags)
        canvas.create_oval(x - 5, row_y - 5, x + 5, row_y + 5, fill=color, outline=color, tags=tags)
        self._create_badge(
            canvas,
            x,
            label_y,
            label,
            anchor="center",
            fill="#ffffff",
            outline=color,
            text_color="#0f172a",
        )

    def _find_drag_tag(self, canvas: tk.Canvas, prefix: str) -> str | None:
        current = canvas.find_withtag("current")
        for item_id in current:
            for tag in canvas.gettags(item_id):
                if tag.startswith(prefix):
                    return tag
        return None

    def _on_map_press(self, _event: tk.Event[tk.Canvas]) -> None:
        tag = self._find_drag_tag(self.map_canvas, "drag_vehicle_")
        self._map_drag_target = tag.removeprefix("drag_vehicle_") if tag else None

    def _on_map_drag(self, event: tk.Event[tk.Canvas]) -> None:
        if self._map_drag_target is None or not self._map_model:
            return
        road_top = float(self._map_model["road_top"])
        road_bottom = float(self._map_model["road_bottom"])
        min_rel = float(self._map_model["min_rel"])
        max_rel = float(self._map_model["max_rel"])
        y = min(max(event.y, road_top), road_bottom)
        ratio = (y - road_top) / max(road_bottom - road_top, 1.0)
        relative_distance = max_rel - (ratio * (max_rel - min_rel))

        if self._map_drag_target == "front":
            self.front_gap_var.set(format_number(max(relative_distance, 0.5)))
        elif self._map_drag_target == "rear":
            self.rear_gap_var.set(format_number(max(-relative_distance, 0.5)))
        elif self._map_drag_target == "left":
            self.left_lane_gap_var.set(format_number(max(relative_distance, 0.5)))

    def _on_map_release(self, _event: tk.Event[tk.Canvas]) -> None:
        self._map_drag_target = None

    def _on_timeline_press(self, _event: tk.Event[tk.Canvas]) -> None:
        tag = self._find_drag_tag(self.timeline_canvas, "drag_event_")
        self._timeline_drag_target = tag.removeprefix("drag_event_") if tag else None

    def _on_timeline_drag(self, event: tk.Event[tk.Canvas]) -> None:
        if self._timeline_drag_target is None or not self._timeline_model:
            return
        left = float(self._timeline_model["left"])
        right = float(self._timeline_model["right"])
        horizon = float(self._timeline_model["horizon"])
        x = min(max(event.x, left), right)
        time_s = ((x - left) / max(right - left, 1.0)) * horizon
        time_text = format_number(max(time_s, 0.0))

        if self._timeline_drag_target == "rear_lane_change":
            self.rear_lane_change_time_var.set(time_text)
        elif self._timeline_drag_target == "rear_stop":
            self.rear_stop_time_var.set(time_text)
        elif self._timeline_drag_target == "front_stop":
            self.front_stop_time_var.set(time_text)
        elif self._timeline_drag_target == "audio":
            self.audio_trigger_time_var.set(time_text)

    def _on_timeline_release(self, _event: tk.Event[tk.Canvas]) -> None:
        self._timeline_drag_target = None

