def blend_hex_colors_v2(background: str, foreground: str, alpha: float) -> str:
    alpha = max(0.0, min(1.0, float(alpha)))

    def channel_pair(value: str) -> tuple[int, int, int]:
        normalized = str(value).strip().lstrip("#")
        if len(normalized) == 3:
            normalized = "".join(ch * 2 for ch in normalized)
        if len(normalized) != 6:
            return (0, 0, 0)
        return (
            int(normalized[0:2], 16),
            int(normalized[2:4], 16),
            int(normalized[4:6], 16),
        )

    bg_r, bg_g, bg_b = channel_pair(background)
    fg_r, fg_g, fg_b = channel_pair(foreground)
    return (
        f"#{round(bg_r * (1.0 - alpha) + fg_r * alpha):02x}"
        f"{round(bg_g * (1.0 - alpha) + fg_g * alpha):02x}"
        f"{round(bg_b * (1.0 - alpha) + fg_b * alpha):02x}"
    )


def point_in_polygon_evenodd_v2(x: float, y: float, polygon: tuple[tuple[float, float], ...]) -> bool:
    inside = False
    if len(polygon) < 3:
        return False
    previous_x, previous_y = polygon[-1]
    for current_x, current_y in polygon:
        crosses_y = (current_y > y) != (previous_y > y)
        if crosses_y:
            slope_x = (previous_x - current_x) * (y - current_y) / ((previous_y - current_y) or 1e-9) + current_x
            if x < slope_x:
                inside = not inside
        previous_x, previous_y = current_x, current_y
    return inside


def point_in_svg_subpaths_evenodd_v2(
    x: float,
    y: float,
    subpaths: tuple[tuple[tuple[float, float], ...], ...],
) -> bool:
    inside = False
    for subpath in subpaths:
        if point_in_polygon_evenodd_v2(x, y, subpath):
            inside = not inside
    return inside


