def parse_svg_path_subpaths_v2(path_data: str, *, curve_steps: int = 12) -> tuple[tuple[tuple[float, float], ...], ...]:
    token_pattern = re.compile(r"[MmLlHhVvCcSsAaQqTtZz]|[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?")
    tokens = token_pattern.findall(path_data)
    index = 0
    command = ""
    x = 0.0
    y = 0.0
    start_x = 0.0
    start_y = 0.0
    last_cubic_control: tuple[float, float] | None = None
    last_quadratic_control: tuple[float, float] | None = None
    current: list[tuple[float, float]] = []
    subpaths: list[tuple[tuple[float, float], ...]] = []

    def is_command(token: str) -> bool:
        return bool(re.fullmatch(r"[A-Za-z]", token))

    def has_number() -> bool:
        return index < len(tokens) and not is_command(tokens[index])

    def has_numbers(count: int) -> bool:
        if index + count > len(tokens):
            return False
        return all(not is_command(tokens[index + offset]) for offset in range(count))

    def read_number() -> float:
        nonlocal index
        value = float(tokens[index])
        index += 1
        return value

    def append_cubic(
        x0: float,
        y0: float,
        x1: float,
        y1: float,
        x2: float,
        y2: float,
        x3: float,
        y3: float,
    ) -> None:
        for step in range(1, curve_steps + 1):
            t = step / curve_steps
            inv = 1.0 - t
            bx = (
                inv * inv * inv * x0
                + 3.0 * inv * inv * t * x1
                + 3.0 * inv * t * t * x2
                + t * t * t * x3
            )
            by = (
                inv * inv * inv * y0
                + 3.0 * inv * inv * t * y1
                + 3.0 * inv * t * t * y2
                + t * t * t * y3
            )
            current.append((bx, by))

    def append_quadratic(x0: float, y0: float, x1: float, y1: float, x2: float, y2: float) -> None:
        for step in range(1, curve_steps + 1):
            t = step / curve_steps
            inv = 1.0 - t
            bx = inv * inv * x0 + 2.0 * inv * t * x1 + t * t * x2
            by = inv * inv * y0 + 2.0 * inv * t * y1 + t * t * y2
            current.append((bx, by))

    def finish_current() -> None:
        nonlocal current
        if len(current) >= 3:
            subpaths.append(tuple(current))
        current = []

    while index < len(tokens):
        if is_command(tokens[index]):
            command = tokens[index]
            index += 1
        if not command:
            break

        relative = command.islower()
        op = command.upper()

        if op == "M":
            first_pair = True
            while has_number() and index + 1 < len(tokens):
                next_x = read_number()
                next_y = read_number()
                if relative:
                    next_x += x
                    next_y += y
                if first_pair:
                    finish_current()
                    current = [(next_x, next_y)]
                    start_x, start_y = next_x, next_y
                    first_pair = False
                else:
                    current.append((next_x, next_y))
                x, y = next_x, next_y
            last_cubic_control = None
            last_quadratic_control = None
            command = "l" if relative else "L"
            continue

        if op == "L":
            while has_number() and index + 1 < len(tokens):
                next_x = read_number()
                next_y = read_number()
                if relative:
                    next_x += x
                    next_y += y
                current.append((next_x, next_y))
                x, y = next_x, next_y
            last_cubic_control = None
            last_quadratic_control = None
            continue

        if op == "H":
            while has_number():
                next_x = read_number()
                if relative:
                    next_x += x
                x = next_x
                current.append((x, y))
            last_cubic_control = None
            last_quadratic_control = None
            continue

        if op == "V":
            while has_number():
                next_y = read_number()
                if relative:
                    next_y += y
                y = next_y
                current.append((x, y))
            last_cubic_control = None
            last_quadratic_control = None
            continue

        if op == "C":
            while has_numbers(6):
                x0, y0 = x, y
                x1 = read_number()
                y1 = read_number()
                x2 = read_number()
                y2 = read_number()
                x3 = read_number()
                y3 = read_number()
                if relative:
                    x1 += x0
                    y1 += y0
                    x2 += x0
                    y2 += y0
                    x3 += x0
                    y3 += y0
                append_cubic(x0, y0, x1, y1, x2, y2, x3, y3)
                last_cubic_control = (x2, y2)
                last_quadratic_control = None
                x, y = x3, y3
            continue

        if op == "S":
            while has_numbers(4):
                x0, y0 = x, y
                if last_cubic_control is None:
                    x1, y1 = x0, y0
                else:
                    x1 = 2.0 * x0 - last_cubic_control[0]
                    y1 = 2.0 * y0 - last_cubic_control[1]
                x2 = read_number()
                y2 = read_number()
                x3 = read_number()
                y3 = read_number()
                if relative:
                    x2 += x0
                    y2 += y0
                    x3 += x0
                    y3 += y0
                append_cubic(x0, y0, x1, y1, x2, y2, x3, y3)
                last_cubic_control = (x2, y2)
                last_quadratic_control = None
                x, y = x3, y3
            continue

        if op == "Q":
            while has_numbers(4):
                x0, y0 = x, y
                x1 = read_number()
                y1 = read_number()
                x2 = read_number()
                y2 = read_number()
                if relative:
                    x1 += x0
                    y1 += y0
                    x2 += x0
                    y2 += y0
                append_quadratic(x0, y0, x1, y1, x2, y2)
                last_quadratic_control = (x1, y1)
                last_cubic_control = None
                x, y = x2, y2
            continue

        if op == "T":
            while has_numbers(2):
                x0, y0 = x, y
                if last_quadratic_control is None:
                    x1, y1 = x0, y0
                else:
                    x1 = 2.0 * x0 - last_quadratic_control[0]
                    y1 = 2.0 * y0 - last_quadratic_control[1]
                x2 = read_number()
                y2 = read_number()
                if relative:
                    x2 += x0
                    y2 += y0
                append_quadratic(x0, y0, x1, y1, x2, y2)
                last_quadratic_control = (x1, y1)
                last_cubic_control = None
                x, y = x2, y2
            continue

        if op == "A":
            while has_numbers(7):
                _rx = read_number()
                _ry = read_number()
                _rotation = read_number()
                _large_arc = read_number()
                _sweep = read_number()
                next_x = read_number()
                next_y = read_number()
                if relative:
                    next_x += x
                    next_y += y
                current.append((next_x, next_y))
                x, y = next_x, next_y
            last_cubic_control = None
            last_quadratic_control = None
            continue

        if op == "Z":
            if current and current[-1] != (start_x, start_y):
                current.append((start_x, start_y))
            finish_current()
            x, y = start_x, start_y
            last_cubic_control = None
            last_quadratic_control = None
            continue

        break

    finish_current()
    return tuple(subpaths)


def normalize_svg_subpaths_v2(
    subpaths: tuple[tuple[tuple[float, float], ...], ...],
) -> tuple[tuple[tuple[float, float], ...], ...]:
    all_points = [point for subpath in subpaths for point in subpath]
    if not all_points:
        return ()
    min_x = min(point[0] for point in all_points)
    max_x = max(point[0] for point in all_points)
    min_y = min(point[1] for point in all_points)
    max_y = max(point[1] for point in all_points)
    center_x = (min_x + max_x) / 2.0
    center_y = (min_y + max_y) / 2.0
    scale = max(max_x - min_x, max_y - min_y, 1.0)
    return tuple(
        tuple(((point_x - center_x) / scale, (point_y - center_y) / scale) for point_x, point_y in subpath)
        for subpath in subpaths
        if len(subpath) >= 3
    )


def load_svg_icon_subpaths_v2(svg_path: Path) -> tuple[tuple[tuple[float, float], ...], ...]:
    if not svg_path.exists():
        return ()
    root = ET.parse(svg_path).getroot()
    candidates: list[tuple[tuple[tuple[float, float], ...], ...]] = []
    for element in root.iter():
        if not str(element.tag).endswith("path"):
            continue
        path_data = (element.attrib.get("d") or "").strip()
        if len(path_data) < 12:
            continue
        subpaths = parse_svg_path_subpaths_v2(path_data)
        if subpaths:
            candidates.append(subpaths)
    if not candidates:
        return ()
    largest = max(candidates, key=lambda item: sum(len(subpath) for subpath in item))
    return normalize_svg_subpaths_v2(largest)


@dataclass
class GapPointV2:
    time_s: float
    gap_m: float


@dataclass
class LaneChangeEventV2:
    time_s: float
    from_lane: str
    target_lane: str
    duration_s: float = DEFAULT_NATIVE_LANE_CHANGE_DURATION_V2


@dataclass
class VehicleConfigV2:
    key: str
    label: str
    name: str
    vehicle_id: int
    initial_offset_m: float
    initial_lane: str
    speed_kmh: float
    lane_change_enabled: bool
    lane_change_time_s: float
    lane_change_target_lane: str
    stop_enabled: bool
    stop_time_s: float
    lane_change_duration_s: float = DEFAULT_NATIVE_LANE_CHANGE_DURATION_V2
    lane_changes: list[LaneChangeEventV2] = field(default_factory=list)
    gap_points: list[GapPointV2] = field(default_factory=list)
    enabled: bool = True


def vehicle_enabled_v2(config: VehicleConfigV2) -> bool:
    return config.key == "ego" or bool(getattr(config, "enabled", True))


def lane_change_events_for_vehicle_v2(config: VehicleConfigV2) -> list[LaneChangeEventV2]:
    explicit_events = getattr(config, "lane_changes", None) or []
    events: list[LaneChangeEventV2] = []
    for event in explicit_events:
        from_lane = event.from_lane if event.from_lane in LANE_NAMES_V2 else config.initial_lane
        target_lane = event.target_lane if event.target_lane in LANE_NAMES_V2 else from_lane
        if target_lane == from_lane:
            continue
        events.append(
            LaneChangeEventV2(
                time_s=max(0.0, float(event.time_s)),
                from_lane=from_lane,
                target_lane=target_lane,
                duration_s=max(0.0, float(event.duration_s)),
            )
        )
    if events:
        return sorted(events, key=lambda item: (item.time_s, item.duration_s, item.from_lane, item.target_lane))
    if config.lane_change_enabled and config.lane_change_target_lane != config.initial_lane:
        return [
            LaneChangeEventV2(
                time_s=max(0.0, float(config.lane_change_time_s)),
                from_lane=config.initial_lane,
                target_lane=config.lane_change_target_lane,
                duration_s=max(0.0, float(config.lane_change_duration_s)),
            )
        ]
    return []


def first_lane_change_event_v2(config: VehicleConfigV2) -> LaneChangeEventV2 | None:
    events = lane_change_events_for_vehicle_v2(config)
    return events[0] if events else None


def last_lane_change_event_v2(config: VehicleConfigV2) -> LaneChangeEventV2 | None:
    events = lane_change_events_for_vehicle_v2(config)
    return events[-1] if events else None


def lane_change_base_time_s_v2(config: VehicleConfigV2) -> float:
    first_event = first_lane_change_event_v2(config)
    return first_event.time_s if first_event is not None else float(getattr(config, "lane_change_time_s", 0.0))


def lane_change_end_time_s_v2(config: VehicleConfigV2) -> float:
    events = lane_change_events_for_vehicle_v2(config)
    if events:
        return max(event.time_s + max(event.duration_s, 0.0) for event in events)
    return float(getattr(config, "lane_change_time_s", 0.0)) + max(
        float(getattr(config, "lane_change_duration_s", 0.0)),
        0.0,
    )


def lane_change_reference_duration_s_v2(config: VehicleConfigV2) -> float:
    last_event = last_lane_change_event_v2(config)
    if last_event is not None:
        return max(float(last_event.duration_s), 0.0)
    return max(float(getattr(config, "lane_change_duration_s", 0.0)), 0.0)


def lane_after_lane_changes_v2(config: VehicleConfigV2) -> str:
    last_event = last_lane_change_event_v2(config)
    return last_event.target_lane if last_event is not None else config.initial_lane


def set_vehicle_lane_changes_v2(config: VehicleConfigV2, events: list[LaneChangeEventV2]) -> None:
    config.lane_changes = sorted(events, key=lambda item: (item.time_s, item.duration_s, item.from_lane, item.target_lane))
    first_event = config.lane_changes[0] if config.lane_changes else None
    if first_event is None:
        config.lane_change_enabled = False
        return
    config.lane_change_enabled = True
    config.lane_change_time_s = first_event.time_s
    config.lane_change_target_lane = first_event.target_lane
    config.lane_change_duration_s = first_event.duration_s


