def kmh_to_mps_v2(speed_kmh: float) -> float:
    return float(speed_kmh) / 3.6


def normalize_audio_filename_v2(value: str) -> str:
    filename = value.strip().replace("\\", "/")
    if not filename:
        raise ValueError("Audio file is required.")
    if not filename.lower().endswith(".wav"):
        filename += ".wav"
    if re.match(r"^[A-Za-z]:", filename) or filename.startswith("/"):
        raise ValueError("Use a relative audio path or filename, not an absolute path.")
    parts = [part for part in filename.split("/") if part not in ("", ".")]
    if not parts or any(part == ".." for part in parts):
        raise ValueError("Audio path cannot traverse parent folders.")
    return "/".join(parts)


def normalize_visual_cue_filename_v2(value: str) -> str:
    filename = value.strip().replace("\\", "/")
    if not filename:
        raise ValueError("Visual cue file is required.")
    if Path(filename).suffix.lower() not in PROMPT_VISUAL_CUE_EXTENSIONS_V2:
        raise ValueError("Use a visual cue file such as .png, .jpg, .svg, .bmp, .gif, or .txt.")
    if re.match(r"^[A-Za-z]:", filename) or filename.startswith("/"):
        raise ValueError("Use a relative visual cue path or filename, not an absolute path.")
    parts = [part for part in filename.split("/") if part not in ("", ".")]
    if not parts or any(part == ".." for part in parts):
        raise ValueError("Visual cue path cannot traverse parent folders.")
    return "/".join(parts)


def ensure_prompt_cue_asset_dirs_v2() -> None:
    PROMPT_AUDITORY_CUE_DIR_V2.mkdir(parents=True, exist_ok=True)
    PROMPT_VISUAL_CUE_DIR_V2.mkdir(parents=True, exist_ok=True)


def normalize_prompt_auditory_cue_filename_v2(value: str) -> str:
    normalized = normalize_audio_filename_v2(value)
    if "/" in normalized:
        raise ValueError(f"Use an audio file directly inside {PROMPT_AUDITORY_CUE_DIR_V2}.")
    ensure_prompt_cue_asset_dirs_v2()
    if not (PROMPT_AUDITORY_CUE_DIR_V2 / normalized).is_file():
        raise ValueError(f"Audio file must exist inside {PROMPT_AUDITORY_CUE_DIR_V2}: {normalized}")
    return normalized


def normalize_prompt_visual_cue_filename_v2(value: str) -> str:
    normalized = normalize_visual_cue_filename_v2(value)
    if "/" in normalized:
        raise ValueError(f"Use a visual file directly inside {PROMPT_VISUAL_CUE_DIR_V2}.")
    ensure_prompt_cue_asset_dirs_v2()
    if not (PROMPT_VISUAL_CUE_DIR_V2 / normalized).is_file():
        raise ValueError(f"Visual cue file must exist inside {PROMPT_VISUAL_CUE_DIR_V2}: {normalized}")
    return normalized


def selected_prompt_auditory_cue_name_v2(path_text: str) -> str:
    ensure_prompt_cue_asset_dirs_v2()
    cue_dir = PROMPT_AUDITORY_CUE_DIR_V2.resolve()
    selected_path = Path(path_text).resolve()
    try:
        relative_path = selected_path.relative_to(cue_dir)
    except ValueError as exc:
        raise ValueError(f"Select a .wav file from {PROMPT_AUDITORY_CUE_DIR_V2}.") from exc
    if relative_path.parent != Path("."):
        raise ValueError(f"Select a .wav file directly inside {PROMPT_AUDITORY_CUE_DIR_V2}.")
    return normalize_prompt_auditory_cue_filename_v2(relative_path.name)


def selected_prompt_visual_cue_name_v2(path_text: str) -> str:
    ensure_prompt_cue_asset_dirs_v2()
    cue_dir = PROMPT_VISUAL_CUE_DIR_V2.resolve()
    selected_path = Path(path_text).resolve()
    try:
        relative_path = selected_path.relative_to(cue_dir)
    except ValueError as exc:
        raise ValueError(f"Select a visual cue file from {PROMPT_VISUAL_CUE_DIR_V2}.") from exc
    if relative_path.parent != Path("."):
        raise ValueError(f"Select a visual cue file directly inside {PROMPT_VISUAL_CUE_DIR_V2}.")
    return normalize_prompt_visual_cue_filename_v2(relative_path.name)


def discover_prompt_auditory_cue_files_v2() -> tuple[str, ...]:
    ensure_prompt_cue_asset_dirs_v2()
    names: set[str] = set()
    try:
        candidates = tuple(PROMPT_AUDITORY_CUE_DIR_V2.iterdir())
    except OSError:
        return ()
    for path in candidates:
        if not path.is_file() or path.suffix.lower() != ".wav":
            continue
        try:
            names.add(normalize_prompt_auditory_cue_filename_v2(path.name))
        except ValueError:
            continue
    return tuple(sorted(names, key=str.lower))


def discover_prompt_visual_cue_files_v2() -> tuple[str, ...]:
    ensure_prompt_cue_asset_dirs_v2()
    names: set[str] = set()
    try:
        candidates = tuple(PROMPT_VISUAL_CUE_DIR_V2.iterdir())
    except OSError:
        return ()
    for path in candidates:
        if not path.is_file() or path.suffix.lower() not in PROMPT_VISUAL_CUE_EXTENSIONS_V2:
            continue
        try:
            names.add(normalize_prompt_visual_cue_filename_v2(path.name))
        except ValueError:
            continue
    return tuple(sorted(names, key=str.lower))


def load_prompt_recent_state_v2() -> dict[str, list[str]]:
    if not PROMPT_RECENT_STATE_PATH_V2.exists():
        return {"prompt_files": [], "outputs": []}
    try:
        data = json.loads(PROMPT_RECENT_STATE_PATH_V2.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {"prompt_files": [], "outputs": []}
    return {
        "prompt_files": list(data.get("prompt_files", []))[:20],
        "outputs": list(data.get("outputs", []))[:40],
    }


def remember_prompt_recent_v2(*, prompt_file: Path | None = None, outputs: list[Path] | None = None) -> None:
    state = load_prompt_recent_state_v2()
    if prompt_file is not None:
        token = str(prompt_file.resolve())
        state["prompt_files"] = [token] + [item for item in state["prompt_files"] if item != token]
        state["prompt_files"] = state["prompt_files"][:20]
    if outputs:
        tokens = [str(path.resolve()) for path in outputs]
        state["outputs"] = tokens + [item for item in state["outputs"] if item not in tokens]
        state["outputs"] = state["outputs"][:40]
    try:
        PROMPT_RECENT_STATE_PATH_V2.write_text(json.dumps(state, indent=2), encoding="utf-8")
    except OSError:
        pass


def shorten_name_v2(name: str, *, max_length: int = 16) -> str:
    if len(name) <= max_length:
        return name
    return name[: max_length - 3] + "..."


def discover_audio_files_v2(base_dir: Path) -> tuple[str, ...]:
    names = set(KNOWN_AUDIO_FILES_V2)
    wav_pattern = re.compile(r'VALUE="([^"]+\.wav)"', flags=re.IGNORECASE)
    for sce_path in base_dir.rglob("*.sce"):
        try:
            text = sce_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        for match in wav_pattern.findall(text):
            try:
                names.add(normalize_audio_filename_v2(match))
            except ValueError:
                continue
    for wav_path in base_dir.rglob("*.wav"):
        try:
            names.add(normalize_audio_filename_v2(wav_path.name))
        except ValueError:
            continue
    if DEFAULT_SOUND_LIBRARY_ROOT_V2.exists():
        for wav_path in DEFAULT_SOUND_LIBRARY_ROOT_V2.rglob("*.wav"):
            try:
                relative_name = wav_path.relative_to(DEFAULT_SOUND_LIBRARY_ROOT_V2).as_posix()
                names.add(normalize_audio_filename_v2(relative_name))
                if wav_path.parent == DEFAULT_SOUND_LIBRARY_ROOT_V2:
                    names.add(normalize_audio_filename_v2(wav_path.name))
            except (ValueError, OSError):
                continue
    return tuple(sorted(names, key=str.lower))


def discover_visual_cue_files_v2(base_dir: Path) -> tuple[str, ...]:
    names = set(KNOWN_VISUAL_CUE_FILES_V2)
    visual_extensions = {".png", ".jpg", ".jpeg", ".svg", ".bmp", ".gif", ".txt"}
    search_roots = [(base_dir, True)]
    downloads_dir = Path(__file__).resolve().parent / "unbundled" / 'Downloads'
    if downloads_dir.exists():
        search_roots.append((downloads_dir, False))
    for root, recursive in search_roots:
        try:
            candidates = list(root.rglob("*") if recursive else root.iterdir())
        except OSError:
            continue
        for path in candidates:
            if not path.is_file() or path.suffix.lower() not in visual_extensions:
                continue
            try:
                if path.is_relative_to(base_dir):
                    names.add(normalize_visual_cue_filename_v2(path.relative_to(base_dir).as_posix()))
                else:
                    names.add(normalize_visual_cue_filename_v2(path.name))
            except (ValueError, OSError):
                continue
    return tuple(sorted(names, key=str.lower))


def lane_name_for_gap_v2(lane_gaps_by_name: dict[str, float], lane_gap: float) -> str:
    return min(lane_gaps_by_name, key=lambda lane_name: abs(lane_gaps_by_name[lane_name] - lane_gap))


def lane_gap_for_name_v2(lane_gaps_by_name: dict[str, float], lane_name: str) -> float:
    return lane_gaps_by_name[lane_name]


def lane_delta_v2(initial_lane: str, target_lane: str) -> int:
    return LANE_ORDER_V2[target_lane] - LANE_ORDER_V2[initial_lane]


def sort_gap_points_v2(gap_points: list[GapPointV2]) -> list[GapPointV2]:
    return sorted(gap_points, key=lambda point: point.time_s)


def compute_segment_speed_kmh_v2(
    *,
    ego_speed_kmh: float,
    start_gap_m: float,
    end_gap_m: float,
    duration_s: float,
) -> float:
    if duration_s <= 0:
        raise ValueError("Gap control durations must be greater than 0 s.")
    return ego_speed_kmh + ((end_gap_m - start_gap_m) / duration_s) * 3.6


def compute_vehicle_speed_segments_v2(
    params: ScenarioParametersV2,
    config: VehicleConfigV2,
) -> list[tuple[float, float | None, float]]:
    ego_speed_kmh = params.vehicles["ego"].speed_kmh
    if config.key == "ego":
        return [(0.0, None, config.speed_kmh)]
    points = sort_gap_points_v2(config.gap_points)
    if not points:
        return [(0.0, None, config.speed_kmh)]

    segments: list[tuple[float, float | None, float]] = []
    previous_time = 0.0
    previous_gap = config.initial_offset_m
    for point in points:
        speed_kmh = compute_segment_speed_kmh_v2(
            ego_speed_kmh=ego_speed_kmh,
            start_gap_m=previous_gap,
            end_gap_m=point.gap_m,
            duration_s=point.time_s - previous_time,
        )
        segments.append((previous_time, point.time_s, speed_kmh))
        previous_time = point.time_s
        previous_gap = point.gap_m
    segments.append((previous_time, None, ego_speed_kmh))
    return segments


def initial_vehicle_speed_kmh_v2(params: ScenarioParametersV2, config: VehicleConfigV2) -> float:
    return compute_vehicle_speed_segments_v2(params, config)[0][2]


def speed_after_gap_point_kmh_v2(
    params: ScenarioParametersV2,
    config: VehicleConfigV2,
    point_index: int,
) -> float:
    segments = compute_vehicle_speed_segments_v2(params, config)
    return segments[point_index + 1][2]


def vehicle_speed_at_time_kmh_v2(
    params: ScenarioParametersV2,
    config: VehicleConfigV2,
    time_s: float,
) -> float:
    for start_time, end_time, speed_kmh in compute_vehicle_speed_segments_v2(params, config):
        if time_s < start_time:
            continue
        if end_time is None or (time_s < end_time and not math.isclose(time_s, end_time, abs_tol=1e-9)):
            return speed_kmh
    return compute_vehicle_speed_segments_v2(params, config)[-1][2]


def find_primary_story_script_v2(scenario: ET.Element) -> str:
    for step in scenario.findall("StoryBoard/Step"):
        if step.findtext("name") != "Step":
            continue
        script_element = step.find("ScenarioScript/script")
        if script_element is not None and script_element.text:
            return script_element.text
    return ""


def extract_initial_speed_map_v2(script_text: str) -> dict[int, float]:
    speed_map: dict[int, float] = {}
    for start, end in find_rule_blocks(script_text):
        block = script_text[start:end]
        if 'VALUE="Trigger"' not in block:
            continue
        pattern = re.compile(
            r'TYPEOF ACTION \(SET_VHL_MAX_SPEED\)\s*\{[\s\S]*?'
            r'TYPEOF PARAMETER \(VHL_NUMBER\)\s*\{[\s\S]*?VALUE="(\d+)"[\s\S]*?'
            r'TYPEOF PARAMETER \(SPEED\)\s*\{[\s\S]*?VALUE="([^"]+)"',
            flags=re.DOTALL,
        )
        for match in pattern.finditer(block):
            speed_map[int(match.group(1))] = float(match.group(2))
        if speed_map:
            return speed_map
    return speed_map


def extract_first_sound_load_v2(script_text: str) -> str | None:
    for start, end in find_rule_blocks(script_text):
        block = script_text[start:end]
        if "TYPEOF ACTION (SOUND_LOAD)" not in block:
            continue
        match = re.search(
            r'TYPEOF PARAMETER \(MESSAGE\)\s*\{[\s\S]*?VALUE="([^"]+\.wav)"',
            block,
            flags=re.DOTALL | re.IGNORECASE,
        )
        if match:
            return match.group(1)
    return None


def extract_first_sound_play_trigger_v2(script_text: str) -> str | None:
    for start, end in find_rule_blocks(script_text):
        block = script_text[start:end]
        if "TYPEOF ACTION (SOUND_PLAY)" not in block:
            continue
        match = re.search(
            r'TYPEOF PARAMETER \(TRIGGER_NAME\)\s*\{[\s\S]*?VALUE="([^"]+)"',
            block,
            flags=re.DOTALL,
        )
        if match:
            return match.group(1)
    return None


def classify_reference_marker_v2(name: str) -> tuple[str, str] | None:
    mapping = (
        ("Trigger_L", ("Loop Start", "#94a3b8")),
        ("Trigger_1_", ("Lane Change", "#7c3aed")),
        ("Trigger_2_", ("Front Stop", "#ef4444")),
        ("Trigger_3_", ("Rear Stop", "#f97316")),
        ("Repair_", ("Repair", "#0ea5e9")),
        ("performance error", ("Performance", "#14b8a6")),
    )
    for prefix, value in mapping:
        if name.startswith(prefix):
            return value
    return None


def load_reference_context_v2(reference_path: Path, lane_gaps_by_name: dict[str, float]) -> ReferenceContextV2:
    if not reference_path.exists():
        return ReferenceContextV2(vehicles=[], markers=[])

    tree = ET.parse(reference_path)
    scenario = tree.getroot().find("Scenario")
    if scenario is None:
        return ReferenceContextV2(vehicles=[], markers=[])

    ego = find_named_element(scenario, "Vehicle", EGO_NAME)
    ego_abscissa = get_abscissa(ego)
    gap_min = min(lane_gaps_by_name.values()) - 0.6
    gap_max = max(lane_gaps_by_name.values()) + 0.6

    vehicles: list[ReferenceVehicleV2] = []
    for vehicle in scenario.findall("Vehicle"):
        name = (vehicle.findtext("name") or "").strip()
        if name in {EGO_NAME, REAR_NAME, FRONT_NAME, LEFT_LANE_NAME}:
            continue
        try:
            relative_distance = get_abscissa(vehicle) - ego_abscissa
            lane_gap = get_lane_gap(vehicle)
        except ValueError:
            continue
        if not (-100.0 <= relative_distance <= 250.0):
            continue
        if not (gap_min <= lane_gap <= gap_max):
            continue
        vehicles.append(
            ReferenceVehicleV2(
                name=name,
                relative_distance=relative_distance,
                lane_gap=lane_gap,
            )
        )
    vehicles.sort(key=lambda item: (abs(item.relative_distance), item.relative_distance))
    vehicles = vehicles[:10]

    grouped_markers: dict[str, ReferenceMarkerV2] = {}
    for trigger in scenario.findall("Trigger"):
        trigger_name = (trigger.findtext("name") or "").strip()
        classified = classify_reference_marker_v2(trigger_name)
        if classified is None:
            continue
        label, color = classified
        try:
            relative_distance = get_abscissa(trigger) - ego_abscissa
        except ValueError:
            continue
        existing = grouped_markers.get(label)
        if existing is None or abs(relative_distance) < abs(existing.relative_distance):
            grouped_markers[label] = ReferenceMarkerV2(
                label=label,
                relative_distance=relative_distance,
                color=color,
            )

    return ReferenceContextV2(
        vehicles=vehicles,
        markers=sorted(grouped_markers.values(), key=lambda item: item.relative_distance),
    )


def default_pedestrian_config_v2(role: str, index: int) -> PedestrianConfigV2:
    meta = PEDESTRIAN_META_V2[role]
    start_side = "Left" if index % 2 else "Right"
    end_side = "Right" if start_side == "Left" else "Left"
    model_name = PEDESTRIAN_MODEL_CHOICES_V2[(index - 1) % len(PEDESTRIAN_MODEL_CHOICES_V2)]
    return PedestrianConfigV2(
        role=role,
        label=str(meta["label"]),
        vehicle_id=int(meta["id"]),
        enabled=False,
        gap_m=18.0 + index * 6.0,
        start_side=start_side,
        end_side=end_side,
        start_time_s=6.0 + index * 2.0,
        duration_s=4.0,
        model_name=model_name,
        world_locked=False,
        lock_time_s=0.0,
    )


def default_obstacle_config_v2(role: str, index: int, total_time_s: float) -> ObstacleConfigV2:
    meta = OBSTACLE_META_V2[role]
    kind = OBSTACLE_KIND_VALUES_V2[(index - 1) % len(OBSTACLE_KIND_VALUES_V2)]
    return ObstacleConfigV2(
        role=role,
        label=str(meta["label"]),
        vehicle_id=int(meta["id"]),
        enabled=False,
        kind=kind,
        lane=LANE_NAMES_V2[(index - 1) % len(LANE_NAMES_V2)],
        gap_m=24.0 + index * 8.0,
        lateral_offset_m=0.0,
        start_time_s=0.0,
        end_time_s=max(total_time_s, 1.0),
        model_name=OBSTACLE_MODEL_BY_KIND_V2[kind],
        world_locked=False,
        lock_time_s=0.0,
    )


def build_default_params_v2(
    *,
    ego_abscissa: float,
    lane_gaps_by_name: dict[str, float],
    script_text: str,
    scenario: ET.Element,
    audio_choices: tuple[str, ...],
) -> ScenarioParametersV2:
    speed_map = extract_initial_speed_map_v2(script_text)

    ego_vehicle = find_named_element(scenario, "Vehicle", EGO_NAME)
    rear_vehicle = find_named_element(scenario, "Vehicle", REAR_NAME)
    front_vehicle = find_named_element(scenario, "Vehicle", FRONT_NAME)
    left_vehicle = find_named_element(scenario, "Vehicle", LEFT_LANE_NAME)
    ego_driver = find_driver_by_id(scenario, 0)
    ego_speed_kmh = float(ego_driver.findtext("TrafficDriver/maxSpeed") or "27.7777777778") * 3.6
    ego_speed_mps = max(kmh_to_mps_v2(ego_speed_kmh), 0.1)

    rear_lane_change_trigger = find_named_element(scenario, "Trigger", "Trigger 1")
    front_stop_trigger = find_named_element(scenario, "Trigger", "Trigger 2")
    rear_stop_trigger = find_named_element(scenario, "Trigger", "Trigger 3")
    rear_lane_change_time = (get_abscissa(rear_lane_change_trigger) - ego_abscissa) / ego_speed_mps
    front_stop_time = (get_abscissa(front_stop_trigger) - ego_abscissa) / ego_speed_mps
    rear_stop_time = (get_abscissa(rear_stop_trigger) - ego_abscissa) / ego_speed_mps

    middle_lane = lane_name_for_gap_v2(lane_gaps_by_name, get_lane_gap(ego_vehicle))
    left_lane = lane_name_for_gap_v2(lane_gaps_by_name, get_lane_gap(left_vehicle))
    audio_file = extract_first_sound_load_v2(script_text) or (
        audio_choices[0] if audio_choices else KNOWN_AUDIO_FILES_V2[0]
    )
    audio_trigger_name = extract_first_sound_play_trigger_v2(script_text) or "Trigger 2"
    try:
        audio_trigger = find_named_element(scenario, "Trigger", audio_trigger_name)
        audio_time = (get_abscissa(audio_trigger) - ego_abscissa) / ego_speed_mps
    except ValueError:
        audio_time = front_stop_time

    stop_criteria = scenario.find("ScenarioStopCriteria")
    total_time = max(18.0, rear_lane_change_time, front_stop_time, rear_stop_time, audio_time) + 6.0
    if stop_criteria is not None and stop_criteria.findtext("stopAtFinalTime") == "1":
        try:
            total_time = float(stop_criteria.findtext("finalTime") or total_time)
        except ValueError:
            pass

    vehicles = {
        "ego": VehicleConfigV2(
            key="ego",
            label=VEHICLE_META_V2["ego"]["label"],
            name=VEHICLE_META_V2["ego"]["name"],
            vehicle_id=VEHICLE_META_V2["ego"]["id"],
            initial_offset_m=0.0,
            initial_lane=middle_lane,
            speed_kmh=ego_speed_kmh,
            lane_change_enabled=False,
            lane_change_time_s=5.0,
            lane_change_target_lane=middle_lane,
            stop_enabled=False,
            stop_time_s=max(12.0, total_time - 4.0),
            gap_points=[],
        ),
        "front": VehicleConfigV2(
            key="front",
            label=VEHICLE_META_V2["front"]["label"],
            name=VEHICLE_META_V2["front"]["name"],
            vehicle_id=VEHICLE_META_V2["front"]["id"],
            initial_offset_m=get_abscissa(front_vehicle) - ego_abscissa,
            initial_lane=lane_name_for_gap_v2(lane_gaps_by_name, get_lane_gap(front_vehicle)),
            speed_kmh=speed_map.get(2, 60.0),
            lane_change_enabled=False,
            lane_change_time_s=8.0,
            lane_change_target_lane=lane_name_for_gap_v2(lane_gaps_by_name, get_lane_gap(front_vehicle)),
            stop_enabled=True,
            stop_time_s=front_stop_time,
            gap_points=[],
        ),
        "rear": VehicleConfigV2(
            key="rear",
            label=VEHICLE_META_V2["rear"]["label"],
            name=VEHICLE_META_V2["rear"]["name"],
            vehicle_id=VEHICLE_META_V2["rear"]["id"],
            initial_offset_m=get_abscissa(rear_vehicle) - ego_abscissa,
            initial_lane=lane_name_for_gap_v2(lane_gaps_by_name, get_lane_gap(rear_vehicle)),
            speed_kmh=speed_map.get(1, 120.0),
            lane_change_enabled=True,
            lane_change_time_s=rear_lane_change_time,
            lane_change_target_lane="Left" if LANE_ORDER_V2[middle_lane] > 0 else middle_lane,
            stop_enabled=True,
            stop_time_s=rear_stop_time,
            gap_points=[],
        ),
        "left": VehicleConfigV2(
            key="left",
            label=VEHICLE_META_V2["left"]["label"],
            name=VEHICLE_META_V2["left"]["name"],
            vehicle_id=VEHICLE_META_V2["left"]["id"],
            initial_offset_m=get_abscissa(left_vehicle) - ego_abscissa,
            initial_lane=left_lane,
            speed_kmh=speed_map.get(3, 60.0),
            lane_change_enabled=False,
            lane_change_time_s=7.0,
            lane_change_target_lane=left_lane,
            stop_enabled=False,
            stop_time_s=12.0,
            gap_points=[],
        ),
    }

    return ScenarioParametersV2(
        output_filename=DEFAULT_OUTPUT_FILENAME,
        total_experiment_time_s=total_time,
        vehicles=vehicles,
        audio_events=[AudioEventV2(time_s=audio_time, file_name=audio_file)],
        pedestrians={
            role: default_pedestrian_config_v2(role, index)
            for index, role in enumerate(PEDESTRIAN_ROLE_ORDER_V2, start=1)
        },
        obstacles={
            role: default_obstacle_config_v2(role, index, total_time)
            for index, role in enumerate(OBSTACLE_ROLE_ORDER_V2, start=1)
        },
    )


_TEMPLATE_DEFAULTS_CACHE_V2: dict[tuple[str, int, int], TemplateDefaultsV2] = {}


def load_template_defaults_v2(template_path: Path) -> TemplateDefaultsV2:
    resolved_path = Path(template_path).resolve()
    stat = resolved_path.stat()
    cache_key = (str(resolved_path).lower(), int(stat.st_mtime_ns), int(stat.st_size))
    cached = _TEMPLATE_DEFAULTS_CACHE_V2.get(cache_key)
    if cached is not None:
        return cached

    for key in list(_TEMPLATE_DEFAULTS_CACHE_V2):
        if key[0] == cache_key[0]:
            _TEMPLATE_DEFAULTS_CACHE_V2.pop(key, None)

    tree = ET.parse(resolved_path)
    scenario = tree.getroot().find("Scenario")
    if scenario is None:
        raise ValueError("Template is missing <Scenario>.")

    ego = find_named_element(scenario, "Vehicle", EGO_NAME)
    left_vehicle = find_named_element(scenario, "Vehicle", LEFT_LANE_NAME)
    ego_abscissa = get_abscissa(ego)
    ego_x = get_position_x(ego)
    heading_radians = get_heading(ego)
    heading_degrees = (math.degrees(heading_radians) + 360.0) % 360.0
    middle_gap = get_lane_gap(ego)
    left_gap = get_lane_gap(left_vehicle)
    lane_step = abs(middle_gap - left_gap) or 3.5
    if left_gap < middle_gap:
        lane_gaps_by_name = {"Left": left_gap, "Middle": middle_gap, "Right": middle_gap + lane_step}
    else:
        lane_gaps_by_name = {"Left": middle_gap - lane_step, "Middle": middle_gap, "Right": left_gap}

    script_text = find_primary_story_script_v2(scenario)
    audio_choices = discover_audio_files_v2(SCRIPT_DIR)
    default_params = build_default_params_v2(
        ego_abscissa=ego_abscissa,
        lane_gaps_by_name=lane_gaps_by_name,
        script_text=script_text,
        scenario=scenario,
        audio_choices=audio_choices,
    )
    defaults = TemplateDefaultsV2(
        ego_abscissa=ego_abscissa,
        x_plus_abscissa=ego_x + ego_abscissa,
        heading_radians=heading_radians,
        heading_degrees=heading_degrees,
        lane_gaps_by_name=lane_gaps_by_name,
        default_params=default_params,
        audio_choices=audio_choices,
    )
    _TEMPLATE_DEFAULTS_CACHE_V2[cache_key] = defaults
    return defaults


def clone_params_v2(params: ScenarioParametersV2) -> ScenarioParametersV2:
    return copy.deepcopy(params)


def default_n_key_intervention_config_v2(params: ScenarioParametersV2) -> NKeyInterventionConfigV2:
    return NKeyInterventionConfigV2(
        enabled=True,
        key_name=N_KEY_INTERVENTION_KEY_NAME_V2,
        lane_change_vehicle_key="front",
        reference_vehicle_key="front",
        merge_vehicle_key="front",
        window_start_offset_s=N_KEY_INTERVENTION_WINDOW_START_OFFSET_S_V2,
        window_end_offset_s=N_KEY_INTERVENTION_WINDOW_END_OFFSET_S_V2,
        ego_speed_delta_mph=N_KEY_INTERVENTION_EGO_SLOW_DELTA_MPH_V2,
        delayed_merge_offset_s=N_KEY_INTERVENTION_DELAYED_MERGE_OFFSET_S_V2,
        merge_target_lane="Middle",
        merge_speed_delta_mph=N_KEY_INTERVENTION_MERGE_ACCEL_DELTA_MPH_V2,
        restore_ego_speed_kmh=0.0,
    )


def enable_default_n_key_intervention_v2(params: ScenarioParametersV2) -> None:
    params.n_key_intervention = default_n_key_intervention_config_v2(params)


def apply_cut_in_ttc14_preset_v2(params: ScenarioParametersV2) -> ScenarioParametersV2:
    params.output_filename = CUT_IN_TTC14_OUTPUT_FILENAME_V2
    params.total_experiment_time_s = CUT_IN_TTC14_TOTAL_TIME_S_V2
    params.audio_events = []
    params.merge = MergeConfigV2(enabled=False)

    ego = params.vehicles["ego"]
    ego.enabled = True
    ego.initial_offset_m = 0.0
    ego.initial_lane = "Left"
    ego.speed_kmh = CUT_IN_TTC14_EGO_SPEED_KMH_V2
    ego.lane_change_enabled = False
    ego.lane_change_time_s = 0.0
    ego.lane_change_duration_s = DEFAULT_NATIVE_LANE_CHANGE_DURATION_V2
    ego.lane_change_target_lane = "Left"
    ego.stop_enabled = False
    ego.stop_time_s = CUT_IN_TTC14_TOTAL_TIME_S_V2
    ego.gap_points = []

    cut_in = params.vehicles["front"]
    cut_in.enabled = True
    cut_in.initial_offset_m = CUT_IN_TTC14_INITIAL_GAP_M_V2
    cut_in.initial_lane = "Middle"
    cut_in.speed_kmh = CUT_IN_TTC14_EGO_SPEED_KMH_V2
    cut_in.lane_change_enabled = True
    cut_in.lane_change_time_s = CUT_IN_TTC14_LANE_CHANGE_TIME_S_V2
    cut_in.lane_change_duration_s = CUT_IN_TTC14_LANE_CHANGE_DURATION_S_V2
    cut_in.lane_change_target_lane = "Left"
    cut_in.stop_enabled = False
    cut_in.stop_time_s = CUT_IN_TTC14_TOTAL_TIME_S_V2
    cut_in.gap_points = [
        GapPointV2(time_s=CUT_IN_TTC14_DECEL_TIME_S_V2, gap_m=CUT_IN_TTC14_INITIAL_GAP_M_V2),
        GapPointV2(time_s=CUT_IN_TTC14_RECOVERY_TIME_S_V2, gap_m=CUT_IN_TTC14_CLOSED_GAP_M_V2),
    ]

    for key in ("rear", "left"):
        vehicle = params.vehicles[key]
        vehicle.enabled = False
        vehicle.lane_change_enabled = False
        vehicle.stop_enabled = False
        vehicle.gap_points = []

    for pedestrian in params.pedestrians.values():
        pedestrian.enabled = False
    for obstacle in params.obstacles.values():
        obstacle.enabled = False
    enable_default_n_key_intervention_v2(params)
    return params


def validate_vehicle_config_v2(config: VehicleConfigV2) -> None:
    if config.initial_lane not in LANE_NAMES_V2:
        raise ValueError(f"{config.label}: invalid initial lane.")
    if config.speed_kmh < 0:
        raise ValueError(f"{config.label}: initial speed cannot be negative.")
    sorted_points = sort_gap_points_v2(config.gap_points)
    previous_time = 0.0
    for index, point in enumerate(sorted_points, start=1):
        if point.time_s <= 0:
            raise ValueError(f"{config.label}: gap point {index} time must be greater than 0 s.")
        if point.time_s <= previous_time:
            raise ValueError(f"{config.label}: gap point times must be strictly increasing.")
        previous_time = point.time_s
    config.gap_points = sorted_points
    lane_change_events = lane_change_events_for_vehicle_v2(config)
    previous_lane_change_time = -1.0
    for index, event in enumerate(lane_change_events, start=1):
        if event.time_s < 0:
            raise ValueError(f"{config.label}: lane-change {index} time cannot be negative.")
        if event.duration_s < 0:
            raise ValueError(f"{config.label}: lane-change {index} duration cannot be negative.")
        if event.from_lane not in LANE_NAMES_V2:
            raise ValueError(f"{config.label}: lane-change {index} has invalid start lane.")
        if event.target_lane not in LANE_NAMES_V2:
            raise ValueError(f"{config.label}: lane-change {index} has invalid target lane.")
        if event.target_lane == event.from_lane:
            raise ValueError(f"{config.label}: lane-change {index} target equals start lane.")
        if event.time_s < previous_lane_change_time:
            raise ValueError(f"{config.label}: lane-change times must be increasing.")
        previous_lane_change_time = event.time_s
    if getattr(config, "lane_changes", None):
        set_vehicle_lane_changes_v2(config, lane_change_events)
    elif config.lane_change_enabled:
        if config.lane_change_time_s < 0:
            raise ValueError(f"{config.label}: lane-change time cannot be negative.")
        if config.lane_change_duration_s < 0:
            raise ValueError(f"{config.label}: lane-change duration cannot be negative.")
        if config.lane_change_target_lane not in LANE_NAMES_V2:
            raise ValueError(f"{config.label}: invalid lane-change target.")
    if config.stop_enabled and config.stop_time_s < 0:
        raise ValueError(f"{config.label}: stop time cannot be negative.")


def validate_pedestrian_config_v2(config: PedestrianConfigV2, *, total_time_s: float) -> None:
    if not config.enabled:
        return
    if config.start_side not in PEDESTRIAN_SIDE_VALUES_V2:
        raise ValueError(f"{config.label}: start side must be Left or Right.")
    if config.end_side not in PEDESTRIAN_SIDE_VALUES_V2:
        raise ValueError(f"{config.label}: end side must be Left or Right.")
    if config.duration_s <= 0:
        raise ValueError(f"{config.label}: crossing duration must be greater than 0 s.")
    if config.start_time_s < 0:
        raise ValueError(f"{config.label}: start time cannot be negative.")
    if config.start_time_s + config.duration_s > total_time_s:
        raise ValueError(f"{config.label}: crossing finishes after scenario end.")
    if config.lock_time_s < 0 or config.lock_time_s > total_time_s:
        raise ValueError(f"{config.label}: lock time must be inside the scenario duration.")
    if not config.model_name.strip():
        raise ValueError(f"{config.label}: model name is required.")


def validate_obstacle_config_v2(config: ObstacleConfigV2, *, total_time_s: float) -> None:
    if not config.enabled:
        return
    if config.kind not in OBSTACLE_KIND_VALUES_V2:
        raise ValueError(f"{config.label}: invalid obstacle kind.")
    if config.lane not in LANE_NAMES_V2:
        raise ValueError(f"{config.label}: invalid lane.")
    if config.start_time_s < 0:
        raise ValueError(f"{config.label}: start time cannot be negative.")
    if config.end_time_s <= config.start_time_s:
        raise ValueError(f"{config.label}: end time must be greater than start time.")
    if config.end_time_s > total_time_s:
        raise ValueError(f"{config.label}: end time exceeds scenario duration.")
    if config.lock_time_s < 0 or config.lock_time_s > total_time_s:
        raise ValueError(f"{config.label}: lock time must be inside the scenario duration.")
    if not config.model_name.strip():
        config.model_name = OBSTACLE_MODEL_BY_KIND_V2.get(config.kind, "Citroen_C3_Red")


def n_key_intervention_enabled_v2(params: ScenarioParametersV2) -> bool:
    config = getattr(params, "n_key_intervention", None)
    return bool(config is not None and getattr(config, "enabled", False))


def extra_vehicles_v2(params: ScenarioParametersV2) -> list[VehicleConfigV2]:
    return list(getattr(params, "extra_vehicles", []) or [])


def extra_obstacles_v2(params: ScenarioParametersV2) -> list[ObstacleConfigV2]:
    return list(getattr(params, "extra_obstacles", []) or [])


def iter_obstacle_configs_v2(params: ScenarioParametersV2) -> list[ObstacleConfigV2]:
    configs = [params.obstacles[role] for role in OBSTACLE_ROLE_ORDER_V2 if role in params.obstacles]
    configs.extend(extra_obstacles_v2(params))
    return configs


def iter_script_vehicle_configs_v2(params: ScenarioParametersV2) -> list[VehicleConfigV2]:
    configs = [params.vehicles[key] for key in VEHICLE_ORDER_V2 if key in params.vehicles]
    configs.extend(extra_vehicles_v2(params))
    return configs


def validate_n_key_intervention_v2(params: ScenarioParametersV2) -> None:
    config = getattr(params, "n_key_intervention", None)
    if config is None:
        params.n_key_intervention = NKeyInterventionConfigV2()
        return
    if not config.enabled:
        return
    for key_name in (
        config.lane_change_vehicle_key,
        config.reference_vehicle_key,
        config.merge_vehicle_key,
        "ego",
    ):
        if key_name not in params.vehicles:
            raise ValueError(f"N-key intervention references unknown vehicle key: {key_name}.")
        if not vehicle_enabled_v2(params.vehicles[key_name]):
            raise ValueError(f"N-key intervention vehicle '{key_name}' must be enabled.")
    lane_change_vehicle = params.vehicles[config.lane_change_vehicle_key]
    merge_vehicle = params.vehicles[config.merge_vehicle_key]
    if first_lane_change_event_v2(lane_change_vehicle) is None:
        raise ValueError("N-key intervention requires the reference lane-change vehicle to have lane change enabled.")
    if config.window_start_offset_s < 0 or config.window_end_offset_s < 0:
        raise ValueError("N-key intervention window offsets cannot be negative.")
    if config.window_end_offset_s <= config.window_start_offset_s:
        raise ValueError("N-key intervention end offset must be after the start offset.")
    if config.ego_speed_delta_mph < 0:
        raise ValueError("N-key intervention speed delta cannot be negative.")
    if config.delayed_merge_offset_s < 0:
        raise ValueError("N-key intervention delayed merge offset cannot be negative.")
    if config.merge_speed_delta_mph < 0:
        raise ValueError("N-key intervention merge speed delta cannot be negative.")
    if config.merge_target_lane not in LANE_NAMES_V2:
        raise ValueError("N-key intervention merge target lane must be Left, Middle, or Right.")
    if not config.key_name.strip():
        config.key_name = N_KEY_INTERVENTION_KEY_NAME_V2
    if config.restore_ego_speed_kmh <= 0:
        config.restore_ego_speed_kmh = params.vehicles["ego"].speed_kmh
    return_duration_s = max(
        lane_change_reference_duration_s_v2(merge_vehicle),
        N_KEY_INTERVENTION_DEFAULT_RETURN_LC_DURATION_S_V2,
    )
    latest_restore_s = (
        lane_change_base_time_s_v2(lane_change_vehicle)
        + config.window_end_offset_s
        + config.delayed_merge_offset_s
        + return_duration_s
    )
    params.total_experiment_time_s = max(params.total_experiment_time_s, latest_restore_s + 0.5)


def validate_parameters_v2(params: ScenarioParametersV2) -> None:
    params.output_filename = normalize_output_filename(params.output_filename)
    if params.total_experiment_time_s <= 0:
        raise ValueError("Total experiment time must be greater than 0 s.")
    prepare_merge_mode_params_v2(params)
    if merge_enabled_v2(params):
        if params.merge.merge_speed_kmh < 0:
            raise ValueError("Merge speed cannot be negative.")
        if params.merge.commit_time_s < 0 or params.merge.end_time_s < 0:
            raise ValueError("Merge trigger times cannot be negative.")
        if params.merge.end_time_s <= params.merge.commit_time_s:
            raise ValueError("Merge end time must be after merge commit time.")
        ensure_merge_terrain_assets_v2(params.merge)
        load_merge_metadata_v2(params.merge)
    for config in params.vehicles.values():
        if vehicle_enabled_v2(config):
            validate_vehicle_config_v2(config)
    seen_vehicle_ids: set[int] = set()
    for config in iter_script_vehicle_configs_v2(params):
        if not vehicle_enabled_v2(config):
            continue
        if config.vehicle_id in seen_vehicle_ids:
            raise ValueError(f"Duplicate vehicle id in generated scene: {config.vehicle_id}.")
        seen_vehicle_ids.add(config.vehicle_id)
        if config.key not in params.vehicles:
            validate_vehicle_config_v2(config)
    validate_n_key_intervention_v2(params)
    for role in PEDESTRIAN_ROLE_ORDER_V2:
        if role not in params.pedestrians:
            params.pedestrians[role] = default_pedestrian_config_v2(role, PEDESTRIAN_ROLE_ORDER_V2.index(role) + 1)
        validate_pedestrian_config_v2(params.pedestrians[role], total_time_s=params.total_experiment_time_s)
    for role in OBSTACLE_ROLE_ORDER_V2:
        if role not in params.obstacles:
            params.obstacles[role] = default_obstacle_config_v2(
                role,
                OBSTACLE_ROLE_ORDER_V2.index(role) + 1,
                params.total_experiment_time_s,
            )
        validate_obstacle_config_v2(params.obstacles[role], total_time_s=params.total_experiment_time_s)
    seen_actor_ids: set[int] = {
        int(PEDESTRIAN_META_V2[role]["id"]) for role in PEDESTRIAN_ROLE_ORDER_V2
    } | {int(OBSTACLE_META_V2[role]["id"]) for role in OBSTACLE_ROLE_ORDER_V2}
    for obstacle in extra_obstacles_v2(params):
        if not obstacle.enabled:
            continue
        if obstacle.vehicle_id in seen_actor_ids or obstacle.vehicle_id in seen_vehicle_ids:
            raise ValueError(f"Duplicate actor/vehicle id in generated scene: {obstacle.vehicle_id}.")
        seen_actor_ids.add(obstacle.vehicle_id)
        validate_obstacle_config_v2(obstacle, total_time_s=params.total_experiment_time_s)
    for event in params.audio_events:
        if event.time_s < 0:
            raise ValueError("Audio time cannot be negative.")
        event.file_name = normalize_audio_filename_v2(event.file_name)
    if params.vehicles["ego"].speed_kmh < 0:
        raise ValueError("Ego initial speed cannot be negative.")
    for config in iter_script_vehicle_configs_v2(params):
        key = config.key
        if key == "ego":
            continue
        if not vehicle_enabled_v2(config):
            continue
        for index, segment in enumerate(compute_vehicle_speed_segments_v2(params, config), start=1):
            speed_kmh = segment[2]
            if speed_kmh < 0:
                raise PromptClarificationError(
                    f"{config.label}: the requested front/back gap target would require reversing. "
                    "Gap seconds are converted from ego speed automatically; please use a longer time or a closer target gap."
                )


def project_vehicle_abscissa_v2(
    params: ScenarioParametersV2,
    defaults: TemplateDefaultsV2,
    config: VehicleConfigV2,
    time_s: float,
) -> float:
    initial_abscissa = defaults.ego_abscissa + config.initial_offset_m
    effective_time = max(time_s, 0.0)
    if config.stop_enabled:
        effective_time = min(effective_time, config.stop_time_s)
    travelled_distance = 0.0
    for start_time, end_time, speed_kmh in compute_vehicle_speed_segments_v2(params, config):
        if effective_time <= start_time:
            break
        segment_end = effective_time if end_time is None else min(effective_time, end_time)
        if segment_end > start_time:
            travelled_distance += kmh_to_mps_v2(speed_kmh) * (segment_end - start_time)
        if end_time is None or effective_time <= end_time:
            break
    return initial_abscissa + travelled_distance


def side_gap_v2(lane_gaps_by_name: dict[str, float], side: str) -> float:
    lane_values = tuple(lane_gaps_by_name.values())
    lane_step = abs(lane_gaps_by_name["Middle"] - lane_gaps_by_name["Left"]) or 3.5
    if side == "Left":
        return min(lane_values) - lane_step
    return max(lane_values) + lane_step


def ego_abscissa_at_time_v2(params: ScenarioParametersV2, defaults: TemplateDefaultsV2, time_s: float) -> float:
    return project_vehicle_abscissa_v2(params, defaults, params.vehicles["ego"], time_s)


def actor_world_abscissa_v2(
    params: ScenarioParametersV2,
    defaults: TemplateDefaultsV2,
    gap_m: float,
    *,
    world_locked: bool,
    lock_time_s: float,
    time_s: float,
) -> float:
    anchor_time = lock_time_s if world_locked else time_s
    return ego_abscissa_at_time_v2(params, defaults, anchor_time) + gap_m


def actor_relative_gap_v2(
    params: ScenarioParametersV2,
    defaults: TemplateDefaultsV2,
    gap_m: float,
    *,
    world_locked: bool,
    lock_time_s: float,
    time_s: float,
) -> float:
    if not world_locked:
        return gap_m
    return actor_world_abscissa_v2(
        params,
        defaults,
        gap_m,
        world_locked=True,
        lock_time_s=lock_time_s,
        time_s=time_s,
    ) - ego_abscissa_at_time_v2(params, defaults, time_s)


def merge_enabled_v2(params: ScenarioParametersV2) -> bool:
    return bool(getattr(params.merge, "enabled", False))


def merge_events_for_config_v2(merge: MergeConfigV2) -> list[MergeEventConfigV2]:
    events = list(getattr(merge, "merge_events", []) or [])
    if not events:
        events = [
            MergeEventConfigV2(
                merge_index=int(getattr(merge, "merge_index", 1) or 1),
                commit_time_s=float(getattr(merge, "commit_time_s", 5.5) or 5.5),
                end_time_s=float(getattr(merge, "end_time_s", 9.0) or 9.0),
                behavior=str(getattr(merge, "behavior", "force_merge") or "force_merge"),
                direction="in",
                side="right",
            )
        ]
    return events


def parse_merge_schedule_v2(
    raw_value: object,
    *,
    merge_count: int,
    default_commit_time_s: float,
    default_end_time_s: float,
    default_behavior: str,
) -> list[MergeEventConfigV2]:
    raw_text = str(raw_value or "").strip()
    if not raw_text:
        return []
    events: list[MergeEventConfigV2] = []
    default_duration_s = max(0.1, float(default_end_time_s) - float(default_commit_time_s))
    for sequence_index, token in enumerate(re.split(r"[,;\n]+", raw_text), start=1):
        entry = token.strip()
        if not entry:
            continue
        behavior = default_behavior
        direction = "in"
        side = "right"
        if "|" in entry:
            entry, behavior_text = entry.rsplit("|", 1)
            behavior = behavior_text.strip() or default_behavior
        if behavior not in MERGE_BEHAVIOR_VALUES_V2:
            raise ValueError(f"Merge schedule '{token.strip()}': behavior must be one of {', '.join(MERGE_BEHAVIOR_VALUES_V2)}.")
        if ":" in entry:
            entry, flow_text = entry.rsplit(":", 1)
            flow_parts = [part.strip().lower() for part in re.split(r"[-/]", flow_text.strip()) if part.strip()]
            for part in flow_parts:
                if part in {"in", "mergein", "merge_in", "entry"}:
                    direction = "in"
                elif part in {"out", "mergeout", "merge_out", "exit"}:
                    direction = "out"
                elif part in {"left", "right"}:
                    side = part
                else:
                    raise ValueError(
                        f"Merge schedule '{token.strip()}': flow must use in/out and optional left/right, such as ':in' or ':out'."
                    )
        if side == "left":
            raise ValueError(
                f"Merge schedule '{token.strip()}': left-side merge needs a mirrored left-ramp terrain, which this V2 builder does not generate yet."
            )
        if "@" in entry:
            index_text, time_text = entry.split("@", 1)
            merge_index = int(float(index_text.strip()))
        else:
            merge_index = sequence_index
            time_text = entry
        if "-" in time_text:
            commit_text, end_text = time_text.split("-", 1)
            commit_time_s = float(commit_text.strip())
            end_time_s = float(end_text.strip())
        elif "+" in time_text:
            commit_text, duration_text = time_text.split("+", 1)
            commit_time_s = float(commit_text.strip())
            end_time_s = commit_time_s + max(0.1, float(duration_text.strip()))
        else:
            commit_time_s = float(time_text.strip())
            end_time_s = commit_time_s + default_duration_s
        if merge_index < 1 or merge_index > merge_count:
            raise ValueError(f"Merge schedule '{token.strip()}': merge index must be between 1 and {merge_count}.")
        if commit_time_s < 0 or end_time_s < 0:
            raise ValueError(f"Merge schedule '{token.strip()}': times cannot be negative.")
        if end_time_s <= commit_time_s:
            raise ValueError(f"Merge schedule '{token.strip()}': end time must be after commit time.")
        events.append(
            MergeEventConfigV2(
                merge_index=merge_index,
                commit_time_s=commit_time_s,
                end_time_s=end_time_s,
                behavior=behavior,
                direction=direction,
                side=side,
            )
        )
    return sorted(events, key=lambda event: (event.commit_time_s, event.merge_index))


def merge_metadata_for_index_v2(metadata: dict[str, Any], merge_index: int) -> dict[str, Any]:
    merge_payloads = metadata.get("merges") or []
    if not merge_payloads:
        return metadata
    selected_index = max(1, min(int(merge_index or 1), len(merge_payloads)))
    payload = dict(metadata)
    payload["merge"] = merge_payloads[selected_index - 1]
    payload["active_merge_index"] = selected_index
    return payload


def load_merge_metadata_v2(config: MergeConfigV2) -> dict[str, Any]:
    path = Path(config.metadata_path)
    if not path.exists():
        raise FileNotFoundError(
            f"Merge V2 metadata not found: {path}. "
            "Run SCANER_tool\\scaner_module_terrain_builder_merge_v2.py --no-gui --run-terrain-generator first."
        )
    payload = json.loads(path.read_text(encoding="utf-8"))
    if payload.get("schema") != "scaner_highway_merge_v2_metadata":
        raise ValueError(f"Unexpected Merge V2 metadata schema in {path}.")
    merge_payloads = payload.get("merges") or []
    if merge_payloads:
        merge_count = len(merge_payloads)
        selected_index = max(1, min(int(getattr(config, "merge_index", 1) or 1), merge_count))
        config.merge_index = selected_index
        config.merge_count = merge_count
        try:
            config.road_segment_count = int(payload.get("road_segment_count", config.road_segment_count) or config.road_segment_count)
            config.merge_slots = tuple(int(slot) for slot in (payload.get("merge_slots") or config.merge_slots))
        except (TypeError, ValueError):
            pass
        payload = dict(payload)
        payload["merge"] = merge_payloads[selected_index - 1]
        payload["active_merge_index"] = selected_index
    return payload


def ensure_merge_terrain_assets_v2(config: MergeConfigV2) -> None:
    if not config.enabled:
        return
    road_segments = max(2, int(getattr(config, "road_segment_count", 2) or 2))
    merge_slots = tuple(getattr(config, "merge_slots", ()) or ())
    if not merge_slots:
        merge_count = max(1, int(getattr(config, "merge_count", 1) or 1))
        road_segments, merge_slots = _scaner_merge_layout_for_mode_v2(
            SCANER_SCENARIO_MODE_MERGE_CORRIDOR_V2 if merge_count > 1 else SCANER_SCENARIO_MODE_MERGE_V2,
            requested_count=merge_count,
        )
    else:
        merge_slots = _scaner_parse_merge_slots_v2(",".join(str(slot) for slot in merge_slots), road_segments)
    merge_count = len(merge_slots)
    terrain_name = _scaner_merge_terrain_for_layout_v2(road_segments, merge_slots)
    metadata_path = _scaner_merge_metadata_for_layout_v2(road_segments, merge_slots)
    rnd_path = DEFAULT_TERRAIN_DIR / terrain_name
    config.terrain_name = terrain_name
    config.metadata_path = str(metadata_path)
    config.road_segment_count = road_segments
    config.merge_slots = merge_slots
    config.merge_count = merge_count

    needs_rebuild = not rnd_path.exists() or not metadata_path.exists()
    if not needs_rebuild:
        try:
            existing_metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            needs_rebuild = (
                int(existing_metadata.get("road_segment_count", 0) or 0) != road_segments
                or tuple(int(slot) for slot in existing_metadata.get("merge_slots", [])) != merge_slots
                or int(existing_metadata.get("merge_count", 1) or 1) != merge_count
            )
        except (OSError, json.JSONDecodeError, TypeError, ValueError):
            needs_rebuild = True

    if needs_rebuild:
        try:
            import scaner_module_terrain_builder_inkspace as terrain_base  # noqa: PLC0415
            import scaner_module_terrain_builder_merge_v2 as merge_builder  # noqa: PLC0415

            merge_builder.install_merge_v2()
            modules = merge_builder.merge_v2_slot_plan_modules(
                road_segment_count=road_segments,
                merge_after_segments=merge_slots,
            )
            terrain_base.compose_scaner_rnd(rnd_path.stem, modules, rnd_path)
        except Exception as exc:  # noqa: BLE001
            raise RuntimeError(f"Could not auto-generate merge corridor terrain '{terrain_name}': {exc}") from exc

    ive_path = rnd_path.with_suffix(".ive")
    sol_path = rnd_path.with_suffix(".sol")
    if not ive_path.exists() or not sol_path.exists():
        try:
            import scaner_module_terrain_builder_inkspace as terrain_base  # noqa: PLC0415

            terrain_base.run_scaner_terrain_generator(rnd_path)
        except Exception as exc:  # noqa: BLE001
            raise RuntimeError(f"Could not generate SCANeR assets for '{terrain_name}': {exc}") from exc


def merge_metadata_boundary_v2(metadata: dict[str, Any], key: str) -> dict[str, float]:
    boundary = (((metadata.get("merge") or {}).get("boundaries_world") or {}).get(key) or {})
    try:
        return {
            "x": float(boundary["x"]),
            "y": float(boundary["y"]),
            "z": float(boundary.get("z", 0.0)),
            "outward_heading_rad": float(boundary.get("outward_heading_rad", 0.0)),
        }
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError(f"Merge V2 metadata is missing boundary '{key}'.") from exc


def merge_clamp_ratio_v2(value: float) -> float:
    return max(0.0, min(1.0, float(value)))


def merge_lerp_v2(start: float, end: float, ratio: float) -> float:
    return float(start) + (float(end) - float(start)) * ratio


def offset_point_by_gap_v2(x: float, y: float, heading_radians: float, gap_m: float) -> tuple[float, float]:
    return (
        x - math.sin(heading_radians) * gap_m,
        y + math.cos(heading_radians) * gap_m,
    )


def merge_pose_payload_v2(
    *,
    map_x: float,
    map_y: float,
    map_z: float,
    heading_radians: float,
    subnetwork: str,
    track: str,
    road_abscissa: float,
    road_gap: float,
) -> dict[str, float | str]:
    return {
        "map_x": map_x,
        "map_y": map_y,
        "map_z": map_z,
        "heading_radians": heading_radians,
        "subnetwork": subnetwork,
        "track": track,
        "road_abscissa": road_abscissa,
        "road_gap": road_gap,
    }


def merge_track_for_ratio_v2(
    merge_data: dict[str, Any],
    section_key: str,
    ratio: float,
    default_track: str,
) -> str:
    section = merge_data.get(section_key) or {}
    ratio = merge_clamp_ratio_v2(ratio)
    for ratio_break in section.get("ratio_breaks") or []:
        try:
            start_ratio = float(ratio_break.get("start", 0.0))
            end_ratio = float(ratio_break.get("end", 1.0))
        except (TypeError, ValueError):
            continue
        if start_ratio <= ratio <= end_ratio:
            track_name = str(ratio_break.get("track", "")).strip()
            if track_name:
                return track_name

    track_sequence = [str(track).strip() for track in section.get("track_sequence") or [] if str(track).strip()]
    if len(track_sequence) == 1:
        return track_sequence[0]
    if track_sequence:
        index = min(len(track_sequence) - 1, max(0, int(ratio * len(track_sequence))))
        return track_sequence[index]

    for field_name in ("through_track", "entry_track", "exit_track", "merge_track"):
        track_name = str(section.get(field_name, "")).strip()
        if track_name:
            return track_name
    return default_track


def merge_mainline_pose_v2(metadata: dict[str, Any], s_m: float, lane_gap: float) -> dict[str, float | str]:
    merge_data = metadata.get("merge") or {}
    estimated = merge_data.get("estimated_s_m") or {}
    approach_end = float(estimated.get("mainline_approach_end", 650.0))
    s_m = max(0.0, float(s_m))
    mainline_in = merge_metadata_boundary_v2(metadata, "mainline_in")
    mainline_out = merge_metadata_boundary_v2(metadata, "mainline_out")
    dx = mainline_out["x"] - mainline_in["x"]
    dy = mainline_out["y"] - mainline_in["y"]
    length = max(math.hypot(dx, dy), 1.0)
    heading = math.atan2(dy, dx)

    if s_m <= approach_end:
        distance_before = approach_end - s_m
        center_x = mainline_in["x"] - math.cos(heading) * distance_before
        center_y = mainline_in["y"] - math.sin(heading) * distance_before
        map_x, map_y = offset_point_by_gap_v2(center_x, center_y, heading, lane_gap)
        return merge_pose_payload_v2(
            map_x=map_x,
            map_y=map_y,
            map_z=mainline_in["z"],
            heading_radians=heading,
            subnetwork=str(merge_data.get("approach_subnetwork") or "Merge V2 Mainline Approach"),
            track="Track",
            road_abscissa=max(0.0, s_m),
            road_gap=lane_gap,
        )

    route_distance = s_m - approach_end
    ratio = merge_clamp_ratio_v2(route_distance / length)
    if route_distance > length:
        extra_distance = route_distance - length
        center_x = mainline_out["x"] + math.cos(heading) * extra_distance
        center_y = mainline_out["y"] + math.sin(heading) * extra_distance
        map_z = mainline_out["z"]
        subnetwork = str(merge_data.get("departure_subnetwork") or merge_data.get("module_name") or "Merge V2 Departure")
        track_name = "Track"
        road_abscissa = extra_distance
    else:
        center_x = merge_lerp_v2(mainline_in["x"], mainline_out["x"], ratio)
        center_y = merge_lerp_v2(mainline_in["y"], mainline_out["y"], ratio)
        map_z = merge_lerp_v2(mainline_in["z"], mainline_out["z"], ratio)
        subnetwork = str(merge_data.get("module_name") or "Merge V2 Ramp Gore")
        track_name = merge_track_for_ratio_v2(merge_data, "mainline", ratio, "Track")
        road_abscissa = max(0.0, route_distance)
    map_x, map_y = offset_point_by_gap_v2(center_x, center_y, heading, lane_gap)
    return merge_pose_payload_v2(
        map_x=map_x,
        map_y=map_y,
        map_z=map_z,
        heading_radians=heading,
        subnetwork=subnetwork,
        track=track_name,
        road_abscissa=road_abscissa,
        road_gap=lane_gap,
    )


def merge_ramp_pose_v2(metadata: dict[str, Any], ratio: float, lateral_gap: float = 0.0) -> dict[str, float | str]:
    merge_data = metadata.get("merge") or {}
    ramp_in = merge_metadata_boundary_v2(metadata, "ramp_in")
    ramp_out = merge_metadata_boundary_v2(metadata, "ramp_out")
    ratio = merge_clamp_ratio_v2(ratio)
    dx = ramp_out["x"] - ramp_in["x"]
    dy = ramp_out["y"] - ramp_in["y"]
    heading = math.atan2(dy, dx)
    center_x = merge_lerp_v2(ramp_in["x"], ramp_out["x"], ratio)
    center_y = merge_lerp_v2(ramp_in["y"], ramp_out["y"], ratio)
    map_x, map_y = offset_point_by_gap_v2(center_x, center_y, heading, lateral_gap)
    ramp_length = max(math.hypot(dx, dy), 1.0)
    return merge_pose_payload_v2(
        map_x=map_x,
        map_y=map_y,
        map_z=merge_lerp_v2(ramp_in["z"], ramp_out["z"], ratio),
        heading_radians=heading,
        subnetwork=str(merge_data.get("module_name") or "Merge V2 Ramp Gore"),
        track=merge_track_for_ratio_v2(merge_data, "ramp", ratio, "Exit Ramp"),
        road_abscissa=ramp_length * ratio,
        road_gap=lateral_gap,
    )


def apply_pose_to_object_v2(element: ET.Element, pose: dict[str, float | str]) -> None:
    set_explicit_object_position_v2(
        element,
        map_x=float(pose["map_x"]),
        map_y=float(pose["map_y"]),
        map_z=float(pose.get("map_z", 0.0)),
        heading_radians=float(pose["heading_radians"]),
        subnetwork=str(pose["subnetwork"]),
        track=str(pose["track"]),
        road_abscissa=float(pose["road_abscissa"]),
        road_gap=float(pose["road_gap"]),
        z_offset=float(pose.get("map_z", 0.0)),
    )


def merge_ego_s_at_time_v2(params: ScenarioParametersV2, time_s: float) -> float:
    return params.merge.ego_start_s_m + kmh_to_mps_v2(params.vehicles["ego"].speed_kmh) * max(0.0, time_s)


def merge_actor_s_at_time_v2(
    params: ScenarioParametersV2,
    gap_m: float,
    *,
    world_locked: bool,
    lock_time_s: float,
    time_s: float,
) -> float:
    anchor_time = lock_time_s if world_locked else time_s
    return merge_ego_s_at_time_v2(params, anchor_time) + gap_m


def merge_pose_for_vehicle_v2(
    metadata: dict[str, Any],
    params: ScenarioParametersV2,
    defaults: TemplateDefaultsV2,
    config: VehicleConfigV2,
    *,
    time_s: float = 0.0,
) -> dict[str, float | str]:
    if config.key == params.merge.merge_vehicle_key:
        first_event = merge_events_for_config_v2(params.merge)[0]
        if first_event.direction == "out":
            s_m = merge_ego_s_at_time_v2(params, time_s) + config.initial_offset_m
            return merge_mainline_pose_v2(
                metadata,
                s_m,
                lane_gap_for_name_v2(defaults.lane_gaps_by_name, "Right"),
            )
        return merge_ramp_pose_v2(metadata, params.merge.ramp_start_ratio)
    s_m = merge_ego_s_at_time_v2(params, time_s) + config.initial_offset_m
    lane_gap = lane_gap_for_name_v2(defaults.lane_gaps_by_name, config.initial_lane)
    return merge_mainline_pose_v2(metadata, s_m, lane_gap)


def merge_pose_for_ego_trigger_v2(
    metadata: dict[str, Any],
    params: ScenarioParametersV2,
    defaults: TemplateDefaultsV2,
    time_s: float,
) -> dict[str, float | str]:
    if params.merge.merge_vehicle_key == "ego":
        commit_time = max(params.merge.commit_time_s, 0.1)
        end_time = max(params.merge.end_time_s, commit_time + 0.1)
        if time_s <= commit_time:
            ratio = max(0.0, min(1.0, time_s / commit_time))
            alpha = params.merge.ramp_start_ratio + (
                (params.merge.ramp_commit_ratio - params.merge.ramp_start_ratio) * ratio
            )
            return merge_ramp_pose_v2(metadata, alpha)
        if params.merge.behavior == "abort_merge":
            ratio = max(0.0, min(1.0, (time_s - commit_time) / (end_time - commit_time)))
            return merge_ramp_pose_v2(metadata, params.merge.ramp_commit_ratio + ((0.94 - params.merge.ramp_commit_ratio) * ratio))
        end_s = merge_ego_s_at_time_v2(params, params.merge.end_time_s) + params.merge.end_gap_to_ego_m
        if time_s >= params.merge.end_time_s:
            return merge_mainline_pose_v2(
                metadata,
                end_s,
                lane_gap_for_name_v2(defaults.lane_gaps_by_name, "Right"),
            )
        return merge_ramp_pose_v2(metadata, params.merge.ramp_commit_ratio)
    ego_lane_gap = lane_gap_for_name_v2(defaults.lane_gaps_by_name, params.vehicles["ego"].initial_lane)
    return merge_mainline_pose_v2(metadata, merge_ego_s_at_time_v2(params, time_s), ego_lane_gap)


def build_action_set_vhl_position_from_pose_v2(vehicle_id: int, pose: dict[str, float | str]) -> str:
    return build_action_set_vhl_position_v2(
        vehicle_id,
        map_x=float(pose["map_x"]),
        map_y=float(pose["map_y"]),
        heading_degrees=math.degrees(float(pose["heading_radians"])),
    )


def prepare_merge_mode_params_v2(params: ScenarioParametersV2) -> None:
    if not merge_enabled_v2(params):
        return
    merge = params.merge
    if merge.behavior not in MERGE_BEHAVIOR_VALUES_V2:
        merge.behavior = "force_merge"
    merge.commit_time_s = max(0.0, merge.commit_time_s)
    merge.end_time_s = max(merge.commit_time_s + 0.1, merge.end_time_s)
    merge.road_segment_count = max(2, int(getattr(merge, "road_segment_count", 2) or 2))
    merge.merge_slots = _scaner_parse_merge_slots_v2(
        ",".join(str(slot) for slot in (getattr(merge, "merge_slots", ()) or ())),
        merge.road_segment_count,
    )
    merge.merge_count = len(merge.merge_slots)
    merge.merge_index = max(1, min(int(getattr(merge, "merge_index", 1) or 1), merge.merge_count))
    merge.ramp_start_ratio = merge_clamp_ratio_v2(merge.ramp_start_ratio)
    merge.ramp_commit_ratio = merge_clamp_ratio_v2(merge.ramp_commit_ratio)
    normalized_events: list[MergeEventConfigV2] = []
    for event in merge_events_for_config_v2(merge):
        behavior = event.behavior or merge.behavior
        if behavior not in MERGE_BEHAVIOR_VALUES_V2:
            behavior = merge.behavior
        event_index = max(1, min(int(event.merge_index or 1), merge.merge_count))
        commit_time_s = max(0.0, float(event.commit_time_s))
        end_time_s = max(commit_time_s + 0.1, float(event.end_time_s))
        normalized_events.append(
            MergeEventConfigV2(
                merge_index=event_index,
                commit_time_s=commit_time_s,
                end_time_s=end_time_s,
                behavior=behavior,
                direction="out" if str(getattr(event, "direction", "in")).lower() == "out" else "in",
                side=str(getattr(event, "side", "right") or "right").lower(),
            )
        )
    normalized_events.sort(key=lambda event: (event.commit_time_s, event.merge_index))
    merge.merge_events = normalized_events
    if normalized_events:
        merge.merge_index = normalized_events[0].merge_index
        merge.commit_time_s = normalized_events[0].commit_time_s
        merge.end_time_s = normalized_events[0].end_time_s
        for event in normalized_events:
            if event.side == "left":
                raise ValueError("Left-side merge needs a mirrored left-ramp terrain; V2 currently supports right-side ramps.")
        params.total_experiment_time_s = max(params.total_experiment_time_s, max(event.end_time_s for event in normalized_events) + 7.0)
    else:
        params.total_experiment_time_s = max(params.total_experiment_time_s, merge.end_time_s + 7.0)

    for vehicle in params.vehicles.values():
        vehicle.lane_change_enabled = False
        vehicle.stop_enabled = False
        vehicle.gap_points = []

    merge_vehicle = params.vehicles.get(merge.merge_vehicle_key)
    if merge_vehicle is not None and vehicle_enabled_v2(merge_vehicle):
        if merge_vehicle.key != "ego":
            merge_vehicle.label = "Merge Vehicle"
        first_event = merge_events_for_config_v2(merge)[0]
        merge_vehicle.initial_lane = "Right"
        merge_vehicle.lane_change_target_lane = "Right"
        merge_vehicle.initial_offset_m = 0.0 if first_event.direction == "in" else merge.end_gap_to_ego_m
        merge_vehicle.speed_kmh = merge.merge_speed_kmh
        merge_vehicle.lane_change_enabled = False
        merge_vehicle.stop_enabled = False
        merge_vehicle.gap_points = []


def obstacle_uses_vehicle_v2(obstacle: ObstacleConfigV2) -> bool:
    return obstacle.kind == "Disabled Vehicle"


def visual_path_for_obstacle_v2(model_name: str) -> str:
    model = model_name.strip() or "orange_white_cone"
    if "/" in model or "\\" in model:
        return model.replace("\\", "/")
    return OBSTACLE_VISUAL_PATH_BY_MODEL_V2.get(
        model,
        f"terrain/3DObjects/road_infrastructure/{model}.ive",
    )


def remove_elements_by_name_prefix_v2(scenario: ET.Element, tag: str, prefix: str) -> None:
    for element in list(scenario.findall(tag)):
        if (element.findtext("name") or "").startswith(prefix):
            scenario.remove(element)


def find_main_script_element_v2(scenario: ET.Element) -> ET.Element:
    for step in scenario.findall("StoryBoard/Step"):
        if step.findtext("name") == "Step":
            script_element = step.find("ScenarioScript/script")
            if script_element is not None:
                return script_element
    raise ValueError("Could not find the main ScenarioScript/script element.")


def find_main_step_v2(scenario: ET.Element) -> ET.Element:
    for step in scenario.findall("StoryBoard/Step"):
        if step.findtext("name") == "Step":
            return step
    raise ValueError("Could not find the main StoryBoard Step.")


def virtual_key_code_for_key_name_v2(key_name: str) -> int:
    key = key_name.strip().upper()
    if len(key) == 1 and ("A" <= key <= "Z" or "0" <= key <= "9"):
        return ord(key)
    special_keys = {
        "SPACE": 0x20,
        "ENTER": 0x0D,
        "RETURN": 0x0D,
        "TAB": 0x09,
    }
    return special_keys.get(key, ord(N_KEY_INTERVENTION_KEY_NAME_V2))


def standalone_python_script_dir_for_output_v2(output_path: Path) -> Path:
    for parent in output_path.resolve().parents:
        if parent.name.lower() == "scenario":
            return parent.parent / "script" / "python" / "standalone"
    return DEFAULT_AGENT_SCENARIO_DIR.parents[1] / "script" / "python" / "standalone"


def safe_python_script_token_v2(raw_token: str) -> str:
    token = re.sub(r"[^A-Za-z0-9_]+", "_", raw_token).strip("_")
    return token[:80] or "scenario"


def lane_change_direction_between_lanes_v2(initial_lane: str, target_lane: str) -> str:
    delta = lane_delta_v2(initial_lane, target_lane)
    if delta > 0:
        return "right"
    if delta < 0:
        return "left"
    return "straight"


def sync_standalone_python_script_element_v2(scenario: ET.Element, script_name: str | None) -> None:
    main_step = find_main_step_v2(scenario)
    for script_element in list(main_step.findall("ScenarioScript")):
        language = script_element.findtext("scriptLanguage") or ""
        existing_script_name = script_element.findtext("scriptName") or ""
        if language == "standalone_python" and existing_script_name.startswith(N_KEY_INTERVENTION_SCRIPT_PREFIX_V2):
            main_step.remove(script_element)
    if not script_name:
        return
    scenario_script = ET.Element("ScenarioScript")
    ET.SubElement(scenario_script, "isScriptActive").text = "1"
    ET.SubElement(scenario_script, "script").text = ""
    ET.SubElement(scenario_script, "scriptLanguage").text = "standalone_python"
    ET.SubElement(scenario_script, "scriptName").text = script_name
    main_step.append(scenario_script)


def build_n_key_intervention_script_v2(params: ScenarioParametersV2) -> str:
    config = params.n_key_intervention
    ego = params.vehicles["ego"]
    lane_change_vehicle = params.vehicles[config.lane_change_vehicle_key]
    reference_vehicle = params.vehicles[config.reference_vehicle_key]
    merge_vehicle = params.vehicles[config.merge_vehicle_key]
    completed_lane = (
        lane_after_lane_changes_v2(merge_vehicle)
    )
    return_direction = lane_change_direction_between_lanes_v2(completed_lane, config.merge_target_lane)
    return_duration_s = max(
        lane_change_reference_duration_s_v2(merge_vehicle),
        N_KEY_INTERVENTION_DEFAULT_RETURN_LC_DURATION_S_V2,
    )
    restore_speed_kmh = config.restore_ego_speed_kmh if config.restore_ego_speed_kmh > 0 else ego.speed_kmh
    base_time_s = lane_change_base_time_s_v2(lane_change_vehicle)
    window_start_s = base_time_s + config.window_start_offset_s
    window_end_s = base_time_s + config.window_end_offset_s
    key_name = config.key_name.strip().upper() or N_KEY_INTERVENTION_KEY_NAME_V2
    key_vk = virtual_key_code_for_key_name_v2(key_name)
    speed_delta_mps = config.ego_speed_delta_mph * N_KEY_INTERVENTION_MPH_TO_MPS_V2
    merge_speed_delta_mps = config.merge_speed_delta_mph * N_KEY_INTERVENTION_MPH_TO_MPS_V2
    return (
        "# Auto-generated by simple_hf_scenario_gui.py. Do not edit by hand.\n"
        "import ctypes\n\n"
        "import scaner.sim\n\n\n"
        f"KEY_NAME = {key_name!r}\n"
        f"KEY_VK = {key_vk}\n"
        f"EGO_NAME = {ego.name!r}\n"
        f"EGO_ID = {int(ego.vehicle_id)}\n"
        f"REFERENCE_NAME = {reference_vehicle.name!r}\n"
        f"REFERENCE_ID = {int(reference_vehicle.vehicle_id)}\n"
        f"MERGE_NAME = {merge_vehicle.name!r}\n"
        f"MERGE_ID = {int(merge_vehicle.vehicle_id)}\n"
        f"WINDOW_START_S = {format_number(window_start_s)}\n"
        f"WINDOW_END_S = {format_number(window_end_s)}\n"
        f"SPEED_DELTA_MPS = {format_number(speed_delta_mps)}\n"
        f"DELAYED_MERGE_OFFSET_S = {format_number(config.delayed_merge_offset_s)}\n"
        f"RETURN_DIRECTION = {return_direction!r}\n"
        f"RETURN_LANE_CHANGE_DURATION_S = {format_number(return_duration_s)}\n"
        f"RESTORE_EGO_SPEED_MPS = {format_number(kmh_to_mps_v2(restore_speed_kmh))}\n"
        f"MERGE_MIN_SPEED_MPS = {format_number(kmh_to_mps_v2(restore_speed_kmh))}\n"
        f"MERGE_SPEED_DELTA_MPS = {format_number(merge_speed_delta_mps)}\n"
        "SPEED_SMOOTHING_S = 1.2\n"
        "LOG_PREFIX = '[HF N-key]'\n\n\n"
        "def _safe_call(function, *args):\n"
        "    try:\n"
        "        function(*args)\n"
        "        return True\n"
        "    except Exception:\n"
        "        return False\n\n\n"
        "class Script:\n"
        "    def __init__(self):\n"
        "        self._last_key_down = False\n"
        "        self._triggered = False\n"
        "        self._press_time_s = None\n"
        "        self._ego_slow_target_mps = None\n"
        "        self._return_started = False\n"
        "        self._return_start_time_s = None\n"
        "        self._ego_restored = False\n"
        "        self.ego_vehicle = None\n"
        "        self.reference_vehicle = None\n"
        "        self.merge_vehicle = None\n"
        "        self.ego_driver = None\n"
        "        self.merge_driver = None\n"
        "        self._refresh_handles()\n"
        "        print(f'{LOG_PREFIX} ready: press {KEY_NAME} from {WINDOW_START_S:.2f}s to {WINDOW_END_S:.2f}s.')\n\n"
        "    def _find_vehicle(self, name, entity_id):\n"
        "        try:\n"
        "            vehicles = scaner.sim.get_vehicles()\n"
        "        except Exception:\n"
        "            return None\n"
        "        if name in vehicles:\n"
        "            return vehicles[name]\n"
        "        for vehicle in vehicles.values():\n"
        "            try:\n"
        "                if int(vehicle.get_entity_id()) == int(entity_id):\n"
        "                    return vehicle\n"
        "            except Exception:\n"
        "                pass\n"
        "            try:\n"
        "                if vehicle.get_name() == name:\n"
        "                    return vehicle\n"
        "            except Exception:\n"
        "                pass\n"
        "        return None\n\n"
        "    def _refresh_handles(self):\n"
        "        if self.ego_vehicle is None:\n"
        "            self.ego_vehicle = self._find_vehicle(EGO_NAME, EGO_ID)\n"
        "        if self.reference_vehicle is None:\n"
        "            self.reference_vehicle = self._find_vehicle(REFERENCE_NAME, REFERENCE_ID)\n"
        "        if self.merge_vehicle is None:\n"
        "            self.merge_vehicle = self._find_vehicle(MERGE_NAME, MERGE_ID)\n"
        "        if self.ego_driver is None and self.ego_vehicle is not None:\n"
        "            try:\n"
        "                self.ego_driver = self.ego_vehicle.get_driver()\n"
        "            except Exception:\n"
        "                self.ego_driver = None\n"
        "        if self.merge_driver is None and self.merge_vehicle is not None:\n"
        "            try:\n"
        "                self.merge_driver = self.merge_vehicle.get_driver()\n"
        "            except Exception:\n"
        "                self.merge_driver = None\n\n"
        "    def _key_down(self):\n"
        "        try:\n"
        "            return bool(ctypes.windll.user32.GetAsyncKeyState(KEY_VK) & 0x8000)\n"
        "        except Exception:\n"
        "            return False\n\n"
        "    def _vehicle_speed(self, vehicle, fallback):\n"
        "        if vehicle is None:\n"
        "            return fallback\n"
        "        try:\n"
        "            return float(vehicle.get_speed())\n"
        "        except Exception:\n"
        "            pass\n"
        "        try:\n"
        "            return float(vehicle.get_output().speed.get_origin().get_norm())\n"
        "        except Exception:\n"
        "            return fallback\n\n"
        "    def _set_driver_speed(self, driver, speed_mps, obligatory):\n"
        "        if driver is None:\n"
        "            return\n"
        "        _safe_call(driver.set_maximum_speed, speed_mps)\n"
        "        _safe_call(driver.set_target_speed, speed_mps, scaner.sim.ETargetSpeedState.forced)\n"
        "        _safe_call(driver.set_speed_obligatory, speed_mps, bool(obligatory), SPEED_SMOOTHING_S)\n\n"
        "    def _apply_ego_slowdown(self, now_s):\n"
        "        reference_speed = self._vehicle_speed(self.reference_vehicle, RESTORE_EGO_SPEED_MPS)\n"
        "        self._ego_slow_target_mps = max(0.0, reference_speed - SPEED_DELTA_MPS)\n"
        "        self._set_driver_speed(self.ego_driver, self._ego_slow_target_mps, True)\n"
        "        print(\n"
        "            f'{LOG_PREFIX} accepted {KEY_NAME} at {now_s:.2f}s; '\n"
        "            f'ego target {self._ego_slow_target_mps * 3.6:.2f} km/h.'\n"
        "        )\n\n"
        "    def _start_return_merge(self, now_s):\n"
        "        current_speed = self._vehicle_speed(self.merge_vehicle, MERGE_MIN_SPEED_MPS)\n"
        "        target_speed = max(MERGE_MIN_SPEED_MPS, current_speed + MERGE_SPEED_DELTA_MPS)\n"
        "        self._set_driver_speed(self.merge_driver, target_speed, False)\n"
        "        _safe_call(self.merge_driver.set_acceleration, 1.5) if self.merge_driver is not None else None\n"
        "        if self.merge_driver is not None:\n"
        "            if RETURN_DIRECTION == 'right':\n"
        "                if not _safe_call(self.merge_driver.go_to_right_lane, 100.0, RETURN_LANE_CHANGE_DURATION_S):\n"
        "                    _safe_call(self.merge_driver.go_to_right_lane_obligatory)\n"
        "            elif RETURN_DIRECTION == 'left':\n"
        "                if not _safe_call(self.merge_driver.go_to_left_lane, 100.0, RETURN_LANE_CHANGE_DURATION_S):\n"
        "                    _safe_call(self.merge_driver.go_to_left_lane_obligatory)\n"
        "            else:\n"
        "                _safe_call(self.merge_driver.go_straight)\n"
        "        self._return_started = True\n"
        "        self._return_start_time_s = now_s\n"
        "        print(f'{LOG_PREFIX} return merge started at {now_s:.2f}s; vehicle target {target_speed * 3.6:.2f} km/h.')\n\n"
        "    def _restore_ego(self, now_s):\n"
        "        self._set_driver_speed(self.ego_driver, RESTORE_EGO_SPEED_MPS, False)\n"
        "        self._ego_restored = True\n"
        "        print(f'{LOG_PREFIX} ego restored to {RESTORE_EGO_SPEED_MPS * 3.6:.2f} km/h at {now_s:.2f}s.')\n\n"
        "    def run(self):\n"
        "        self._refresh_handles()\n"
        "        try:\n"
        "            now_s = float(scaner.sim.get_time())\n"
        "        except Exception:\n"
        "            return\n"
        "        key_down = self._key_down()\n"
        "        pressed = key_down and not self._last_key_down\n"
        "        self._last_key_down = key_down\n"
        "        if pressed and not self._triggered:\n"
        "            if WINDOW_START_S <= now_s <= WINDOW_END_S:\n"
        "                self._triggered = True\n"
        "                self._press_time_s = now_s\n"
        "                self._apply_ego_slowdown(now_s)\n"
        "            else:\n"
        "                print(\n"
        "                    f'{LOG_PREFIX} ignored {KEY_NAME} at {now_s:.2f}s; '\n"
        "                    f'valid window is {WINDOW_START_S:.2f}-{WINDOW_END_S:.2f}s.'\n"
        "                )\n"
        "        if self._triggered and not self._ego_restored and self._ego_slow_target_mps is not None:\n"
        "            self._set_driver_speed(self.ego_driver, self._ego_slow_target_mps, True)\n"
        "        if (\n"
        "            self._triggered\n"
        "            and not self._return_started\n"
        "            and self._press_time_s is not None\n"
        "            and now_s >= self._press_time_s + DELAYED_MERGE_OFFSET_S\n"
        "        ):\n"
        "            self._start_return_merge(now_s)\n"
        "        if (\n"
        "            self._return_started\n"
        "            and not self._ego_restored\n"
        "            and self._return_start_time_s is not None\n"
        "            and now_s >= self._return_start_time_s + RETURN_LANE_CHANGE_DURATION_S\n"
        "        ):\n"
        "            self._restore_ego(now_s)\n"
    )


def write_n_key_intervention_script_v2(output_path: Path, params: ScenarioParametersV2) -> str:
    script_name = (
        f"{N_KEY_INTERVENTION_SCRIPT_PREFIX_V2}_"
        f"{safe_python_script_token_v2(output_path.stem)}.py"
    )
    script_dir = standalone_python_script_dir_for_output_v2(output_path)
    script_dir.mkdir(parents=True, exist_ok=True)
    script_path = script_dir / script_name
    script_path.write_text(build_n_key_intervention_script_v2(params), encoding="utf-8")
    return script_name


def create_hf_trigger_v2(
    scenario: ET.Element,
    *,
    name: str,
    template_trigger: ET.Element,
    abscissa: float,
    lane_gap: float,
    defaults: TemplateDefaultsV2,
) -> None:
    trigger = copy.deepcopy(template_trigger)
    name_element = trigger.find("name")
    if name_element is None:
        raise ValueError("Template trigger is missing its <name> element.")
    name_element.text = name
    set_object_position(
        trigger,
        abscissa=abscissa,
        lane_gap=lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians,
    )
    scenario.append(trigger)
    return trigger


def remove_hf_actor_elements_v2(scenario: ET.Element) -> None:
    actor_ids = {
        int(PEDESTRIAN_META_V2[role]["id"]) for role in PEDESTRIAN_ROLE_ORDER_V2
    } | {int(OBSTACLE_META_V2[role]["id"]) for role in OBSTACLE_ROLE_ORDER_V2}
    for vehicle in list(scenario.findall("Vehicle")):
        name = vehicle.findtext("name") or ""
        try:
            vehicle_id = int(vehicle.findtext("id") or "-1")
        except ValueError:
            vehicle_id = -1
        if name.startswith(HF_ACTOR_PREFIX) or vehicle_id in actor_ids:
            scenario.remove(vehicle)
    for driver in list(scenario.findall("Driver")):
        driver_name = driver.findtext("driverName") or ""
        try:
            driver_id = int(driver.findtext("id") or "-1")
        except ValueError:
            driver_id = -1
        if driver_name.startswith(HF_ACTOR_PREFIX) or driver_id in actor_ids:
            scenario.remove(driver)
    for infrastructure in list(scenario.findall("Infrastructure")):
        name = infrastructure.findtext("name") or ""
        if name.startswith(HF_ACTOR_PREFIX):
            scenario.remove(infrastructure)


def set_child_text_v2(parent: ET.Element, path: str, value: object) -> None:
    child = parent.find(path)
    if child is not None:
        child.text = str(value)


def set_actor_position_v2(
    element: ET.Element,
    *,
    abscissa: float,
    lane_gap: float,
    defaults: TemplateDefaultsV2,
    heading_radians: float | None = None,
    z_offset: float = 0.0,
) -> None:
    set_object_position(
        element,
        abscissa=abscissa,
        lane_gap=lane_gap,
        x_plus_abscissa=defaults.x_plus_abscissa,
        heading_radians=defaults.heading_radians if heading_radians is None else heading_radians,
    )
    position = element.find("ObjectPosition/position")
    if position is not None:
        x = defaults.x_plus_abscissa - abscissa
        position.text = f"{format_number(x)} {format_number(lane_gap)} {format_number(z_offset)}"
    z_element = element.find("ObjectPosition/RoadPosition/zOffset")
    if z_element is not None:
        z_element.text = format_number(z_offset)


def clone_actor_driver_v2(
    scenario: ET.Element,
    *,
    template_driver: ET.Element,
    actor_id: int,
    name: str,
    max_speed_mps: float,
    pedestrian: bool,
) -> ET.Element:
    driver = copy.deepcopy(template_driver)
    set_child_text_v2(driver, "driverName", name)
    set_child_text_v2(driver, "driverType", "TrafficDriver")
    set_child_text_v2(driver, "id", actor_id)
    set_child_text_v2(driver, "process", "")
    set_child_text_v2(driver, "TrafficDriver/maxSpeed", format_number(max_speed_mps))
    set_child_text_v2(driver, "TrafficDriver/norm", "NormalDriver_Pedestrian" if pedestrian else "NormalDriver")
    set_child_text_v2(driver, "TrafficDriver/stayOnLane", "0" if pedestrian else "1")
    set_child_text_v2(driver, "TrafficDriver/safetyTime", "0.5" if pedestrian else "2.5")
    scenario.append(driver)
    return driver


def clone_actor_vehicle_v2(
    scenario: ET.Element,
    *,
    template_vehicle: ET.Element,
    actor_id: int,
    name: str,
    model_name: str,
    process: str,
    abscissa: float,
    lane_gap: float,
    defaults: TemplateDefaultsV2,
    heading_radians: float | None = None,
    z_offset: float = 0.0,
    initial_speed_mps: float = 0.0,
) -> ET.Element:
    vehicle = copy.deepcopy(template_vehicle)
    set_child_text_v2(vehicle, "driverId", actor_id)
    set_child_text_v2(vehicle, "id", actor_id)
    set_child_text_v2(vehicle, "initialSpeed", format_number(initial_speed_mps))
    set_child_text_v2(vehicle, "modelName", model_name)
    set_child_text_v2(vehicle, "name", name)
    set_child_text_v2(vehicle, "process", process)
    set_child_text_v2(vehicle, "state", "0")
    set_child_text_v2(vehicle, "StopCriteria/stopStandstill", "0")
    set_actor_position_v2(
        vehicle,
        abscissa=abscissa,
        lane_gap=lane_gap,
        defaults=defaults,
        heading_radians=heading_radians,
        z_offset=z_offset,
    )
    scenario.append(vehicle)
    return vehicle


def create_actor_infrastructure_v2(
    scenario: ET.Element,
    *,
    name: str,
    model_name: str,
    abscissa: float,
    lane_gap: float,
    defaults: TemplateDefaultsV2,
    heading_radians: float | None = None,
    z_offset: float = 0.0,
) -> ET.Element:
    infrastructure = ET.Element("Infrastructure")
    for tag, value in (
        ("detectionState", "1"),
        ("isSound", "0"),
        ("isStatic", "1"),
        ("mass", "0"),
        ("modelName", model_name),
        ("name", name),
        ("state", "0"),
        ("visualPath", visual_path_for_obstacle_v2(model_name)),
        ("volume", "0"),
    ):
        child = ET.SubElement(infrastructure, tag)
        child.text = value
    object_position = ET.SubElement(infrastructure, "ObjectPosition")
    ET.SubElement(object_position, "heading").text = format_number(
        defaults.heading_radians if heading_radians is None else heading_radians
    )
    ET.SubElement(object_position, "position").text = "0 0 0"
    road_position = ET.SubElement(object_position, "RoadPosition")
    ET.SubElement(road_position, "abscissa").text = "0"
    ET.SubElement(road_position, "gapInItnSystem").text = "0"
    ET.SubElement(road_position, "relativeHeading").text = "0"
    ET.SubElement(road_position, "subNetwork").text = "Sub Network"
    ET.SubElement(road_position, "track").text = "Track"
    ET.SubElement(road_position, "zOffset").text = "0"
    set_actor_position_v2(
        infrastructure,
        abscissa=abscissa,
        lane_gap=lane_gap,
        defaults=defaults,
        heading_radians=heading_radians,
        z_offset=z_offset,
    )
    scenario.append(infrastructure)
    return infrastructure


def build_description_v2(params: ScenarioParametersV2) -> str:
    parts = [f"total_experiment_time_s={format_number(params.total_experiment_time_s)}"]
    for key in VEHICLE_ORDER_V2:
        config = params.vehicles[key]
        if key != "ego" and not vehicle_enabled_v2(config):
            continue
        gap_schedule = (
            ",".join(f"{format_number(point.time_s)}s:{format_number(point.gap_m)}m" for point in config.gap_points)
            or "none"
        )
        lane_change_schedule = (
            ",".join(
                f"{format_number(event.time_s)}s+{format_number(event.duration_s)}s:{event.from_lane}->{event.target_lane}"
                for event in lane_change_events_for_vehicle_v2(config)
            )
            or "none"
        )
        parts.append(
            f"{key}_offset_m={format_number(config.initial_offset_m)} "
            f"{key}_lane={config.initial_lane} "
            f"{key}_speed_kmh={format_number(config.speed_kmh)} "
            f"{key}_gap_points={gap_schedule} "
            f"{key}_lc={lane_change_schedule} "
            f"{key}_stop={int(config.stop_enabled)}@{format_number(config.stop_time_s)}"
        )
    for config in extra_vehicles_v2(params):
        if not vehicle_enabled_v2(config):
            continue
        gap_schedule = (
            ",".join(f"{format_number(point.time_s)}s:{format_number(point.gap_m)}m" for point in config.gap_points)
            or "none"
        )
        lane_change_schedule = (
            ",".join(
                f"{format_number(event.time_s)}s+{format_number(event.duration_s)}s:{event.from_lane}->{event.target_lane}"
                for event in lane_change_events_for_vehicle_v2(config)
            )
            or "none"
        )
        parts.append(
            f"{config.key}_offset_m={format_number(config.initial_offset_m)} "
            f"{config.key}_lane={config.initial_lane} "
            f"{config.key}_speed_kmh={format_number(config.speed_kmh)} "
            f"{config.key}_gap_points={gap_schedule} "
            f"{config.key}_lc={lane_change_schedule} "
            f"{config.key}_stop={int(config.stop_enabled)}@{format_number(config.stop_time_s)}"
        )
    if params.audio_events:
        parts.append(
            "audio=" + "; ".join(f"{format_number(event.time_s)}s:{event.file_name}" for event in params.audio_events)
        )
    if params.rain_level is not None:
        parts.append(f"rain_level={format_number(params.rain_level)}")
    for note in params.scene_notes:
        parts.append(f"note={note}")
    active_pedestrians = [ped for ped in params.pedestrians.values() if ped.enabled]
    if active_pedestrians:
        parts.append(
            "pedestrians="
            + "; ".join(
                f"{ped.label}:{ped.start_side}->{ped.end_side}@{format_number(ped.gap_m)}m "
                f"{format_number(ped.start_time_s)}-{format_number(ped.start_time_s + ped.duration_s)}s"
                for ped in active_pedestrians
            )
        )
    active_obstacles = [obstacle for obstacle in iter_obstacle_configs_v2(params) if obstacle.enabled]
    if active_obstacles:
        parts.append(
            "obstacles="
            + "; ".join(
                f"{obstacle.label}:{obstacle.kind} {obstacle.lane}@{format_number(obstacle.gap_m)}m "
                f"{format_number(obstacle.start_time_s)}-{format_number(obstacle.end_time_s)}s"
                for obstacle in active_obstacles
            )
        )
    if merge_enabled_v2(params):
        merge_events = merge_events_for_config_v2(params.merge)
        merge_event_text = ",".join(
            f"{event.merge_index}@{format_number(event.commit_time_s)}-{format_number(event.end_time_s)}"
            + (f":{event.direction}" if event.direction != "in" or event.side != "right" else "")
            + (f"-{event.side}" if event.side != "right" else "")
            + (f"|{event.behavior}" if event.behavior and event.behavior != params.merge.behavior else "")
            for event in merge_events
        )
        parts.append(
            "merge_v2="
            f"{params.merge.behavior} terrain={params.merge.terrain_name} "
            f"segments={format_number(params.merge.road_segment_count)} "
            f"after={','.join(str(slot) for slot in params.merge.merge_slots)} "
            f"events={merge_event_text} "
            f"commit={format_number(params.merge.commit_time_s)}s "
            f"end={format_number(params.merge.end_time_s)}s "
            f"merge_speed={format_number(params.merge.merge_speed_kmh)}kmh"
        )
    if n_key_intervention_enabled_v2(params):
        n_key = params.n_key_intervention
        lane_change_vehicle = params.vehicles[n_key.lane_change_vehicle_key]
        base_time_s = lane_change_base_time_s_v2(lane_change_vehicle)
        parts.append(
            "n_key_intervention="
            f"key={n_key.key_name} "
            f"window={format_number(base_time_s + n_key.window_start_offset_s)}-"
            f"{format_number(base_time_s + n_key.window_end_offset_s)}s "
            f"ego_slow={format_number(n_key.ego_speed_delta_mph)}mph_below_{n_key.reference_vehicle_key} "
            f"return={n_key.merge_vehicle_key}->{n_key.merge_target_lane}@press+"
            f"{format_number(n_key.delayed_merge_offset_s)}s "
            f"restore_ego={format_number(n_key.restore_ego_speed_kmh or params.vehicles['ego'].speed_kmh)}kmh"
        )
    return "HF scene builder: " + " | ".join(parts)


def imported_scene_float_v2(value: str, default: float = 0.0) -> float:
    match = re.search(r"-?\d+(?:\.\d+)?", str(value))
    if not match:
        return default
    try:
        return float(match.group(0))
    except ValueError:
        return default


def imported_scene_lane_v2(value: str, default: str = "Middle") -> str:
    token = str(value or "").strip().lower()
    if token.startswith("left"):
        return "Left"
    if token.startswith("right"):
        return "Right"
    if token.startswith("middle") or token.startswith("center") or token.startswith("centre"):
        return "Middle"
    return default if default in LANE_NAMES_V2 else "Middle"


def imported_scene_vehicle_label_v2(key: str, fallback_index: int) -> str:
    match = re.search(r"(\d+)$", key)
    if match:
        return f"Vehicle {int(match.group(1))}"
    return " ".join(part.capitalize() for part in key.split("_") if part) or f"Vehicle {fallback_index}"


def imported_scene_next_vehicle_id_v2(params: ScenarioParametersV2) -> int:
    vehicle_ids = [config.vehicle_id for config in params.vehicles.values()]
    vehicle_ids.extend(config.vehicle_id for config in extra_vehicles_v2(params))
    vehicle_ids.extend(obstacle.vehicle_id for obstacle in iter_obstacle_configs_v2(params))
    return max(vehicle_ids or [10]) + 1


def imported_scene_vehicle_config_v2(params: ScenarioParametersV2, key: str) -> VehicleConfigV2:
    if key in params.vehicles:
        return params.vehicles[key]
    for config in params.extra_vehicles:
        if config.key == key:
            return config
    fallback_index = len(params.extra_vehicles) + 1
    config = VehicleConfigV2(
        key=key,
        label=imported_scene_vehicle_label_v2(key, fallback_index),
        name=FRONT_NAME,
        vehicle_id=imported_scene_next_vehicle_id_v2(params),
        initial_offset_m=0.0,
        initial_lane="Middle",
        speed_kmh=params.vehicles.get("ego", params.vehicles["front"]).speed_kmh,
        lane_change_enabled=False,
        lane_change_time_s=0.0,
        lane_change_target_lane="Middle",
        lane_change_duration_s=DEFAULT_NATIVE_LANE_CHANGE_DURATION_V2,
        stop_enabled=False,
        stop_time_s=0.0,
        enabled=True,
    )
    params.extra_vehicles.append(config)
    return config


def parse_imported_gap_points_v2(value: str) -> list[GapPointV2]:
    if not value or value == "none":
        return []
    points: list[GapPointV2] = []
    for token in value.split(","):
        match = re.fullmatch(
            r"\s*(?P<time>-?\d+(?:\.\d+)?)s\s*:\s*(?P<gap>-?\d+(?:\.\d+)?)m\s*",
            token,
            flags=re.IGNORECASE,
        )
        if match:
            points.append(GapPointV2(time_s=float(match.group("time")), gap_m=float(match.group("gap"))))
    return points


def parse_imported_lane_changes_v2(value: str, initial_lane: str) -> list[LaneChangeEventV2]:
    if not value or value == "none":
        return []
    events: list[LaneChangeEventV2] = []
    for token in value.split(","):
        token = token.strip()
        match = re.fullmatch(
            r"(?P<time>-?\d+(?:\.\d+)?)s\+(?P<duration>-?\d+(?:\.\d+)?)s:(?P<from>[A-Za-z]+)->(?P<to>[A-Za-z]+)",
            token,
            flags=re.IGNORECASE,
        )
        if match:
            from_lane = imported_scene_lane_v2(match.group("from"), initial_lane)
            target_lane = imported_scene_lane_v2(match.group("to"), from_lane)
            if target_lane != from_lane:
                events.append(
                    LaneChangeEventV2(
                        time_s=float(match.group("time")),
                        from_lane=from_lane,
                        target_lane=target_lane,
                        duration_s=max(0.0, float(match.group("duration"))),
                    )
                )
            continue
        legacy_match = re.fullmatch(
            r"(?P<enabled>[01])@(?P<time>-?\d+(?:\.\d+)?)\+(?P<duration>-?\d+(?:\.\d+)?)s?->(?P<to>[A-Za-z]+)",
            token,
            flags=re.IGNORECASE,
        )
        if legacy_match and legacy_match.group("enabled") == "1":
            target_lane = imported_scene_lane_v2(legacy_match.group("to"), initial_lane)
            if target_lane != initial_lane:
                events.append(
                    LaneChangeEventV2(
                        time_s=float(legacy_match.group("time")),
                        from_lane=initial_lane,
                        target_lane=target_lane,
                        duration_s=max(0.0, float(legacy_match.group("duration"))),
                    )
                )
    return sorted(events, key=lambda item: (item.time_s, item.duration_s, item.from_lane, item.target_lane))


def parse_imported_stop_v2(value: str) -> tuple[bool, float]:
    match = re.fullmatch(r"\s*(?P<enabled>[01])@(?P<time>-?\d+(?:\.\d+)?)\s*", str(value))
    if not match:
        return False, 0.0
    return match.group("enabled") == "1", float(match.group("time"))


def reset_params_for_sce_import_v2(base_params: ScenarioParametersV2, source_path: Path) -> ScenarioParametersV2:
    params = clone_params_v2(base_params)
    params.output_filename = normalize_output_filename(source_path.name)
    params.audio_events = []
    params.extra_vehicles = []
    params.extra_obstacles = []
    params.scene_notes = []
    params.rain_level = None
    params.terrain_override_name = ""
    params.merge = MergeConfigV2(enabled=False)
    params.n_key_intervention = NKeyInterventionConfigV2(enabled=False)
    for key, config in params.vehicles.items():
        config.enabled = key == "ego"
        config.gap_points = []
        config.lane_changes = []
        config.lane_change_enabled = False
        config.lane_change_duration_s = DEFAULT_NATIVE_LANE_CHANGE_DURATION_V2
        config.stop_enabled = False
    for pedestrian in params.pedestrians.values():
        pedestrian.enabled = False
    for obstacle in params.obstacles.values():
        obstacle.enabled = False
    return params


def apply_imported_vehicle_metadata_v2(params: ScenarioParametersV2, part: str) -> bool:
    match = re.fullmatch(
        r"(?P<key>.+?)_offset_m=(?P<offset>\S+)\s+"
        r"(?P=key)_lane=(?P<lane>\S+)\s+"
        r"(?P=key)_speed_kmh=(?P<speed>\S+)\s+"
        r"(?P=key)_gap_points=(?P<gap_points>\S+)\s+"
        r"(?P=key)_lc=(?P<lane_changes>\S+)\s+"
        r"(?P=key)_stop=(?P<stop>\S+)",
        part,
    )
    if not match:
        return False
    key = match.group("key")
    config = imported_scene_vehicle_config_v2(params, key)
    config.enabled = True
    config.initial_offset_m = imported_scene_float_v2(match.group("offset"), config.initial_offset_m)
    config.initial_lane = imported_scene_lane_v2(match.group("lane"), config.initial_lane)
    config.speed_kmh = imported_scene_float_v2(match.group("speed"), config.speed_kmh)
    config.gap_points = parse_imported_gap_points_v2(match.group("gap_points"))
    lane_events = parse_imported_lane_changes_v2(match.group("lane_changes"), config.initial_lane)
    set_vehicle_lane_changes_v2(config, lane_events)
    config.lane_change_target_lane = config.lane_change_target_lane or config.initial_lane
    stop_enabled, stop_time_s = parse_imported_stop_v2(match.group("stop"))
    config.stop_enabled = stop_enabled
    config.stop_time_s = stop_time_s
    return True


def apply_imported_audio_metadata_v2(params: ScenarioParametersV2, payload: str) -> None:
    events: list[AudioEventV2] = []
    for token in payload.split(";"):
        match = re.fullmatch(r"\s*(?P<time>-?\d+(?:\.\d+)?)s\s*:\s*(?P<file>.+?)\s*", token)
        if match:
            events.append(AudioEventV2(time_s=float(match.group("time")), file_name=match.group("file").strip()))
    params.audio_events = sorted(events, key=lambda item: (item.time_s, item.file_name))


def apply_imported_pedestrian_metadata_v2(params: ScenarioParametersV2, payload: str) -> None:
    role_iter = iter(PEDESTRIAN_ROLE_ORDER_V2)
    for token in payload.split(";"):
        match = re.fullmatch(
            r"\s*(?P<label>[^:]+):(?P<start>[A-Za-z]+)->(?P<end>[A-Za-z]+)@(?P<gap>-?\d+(?:\.\d+)?)m\s+"
            r"(?P<start_time>-?\d+(?:\.\d+)?)-(?P<end_time>-?\d+(?:\.\d+)?)s\s*",
            token,
            flags=re.IGNORECASE,
        )
        if not match:
            continue
        try:
            role = next(role_iter)
        except StopIteration:
            break
        pedestrian = params.pedestrians.get(role) or default_pedestrian_config_v2(role, len(params.pedestrians) + 1)
        start_time = float(match.group("start_time"))
        end_time = float(match.group("end_time"))
        pedestrian.enabled = True
        pedestrian.label = match.group("label").strip() or pedestrian.label
        pedestrian.start_side = imported_scene_lane_v2(match.group("start"), pedestrian.start_side)
        pedestrian.end_side = imported_scene_lane_v2(match.group("end"), pedestrian.end_side)
        pedestrian.gap_m = float(match.group("gap"))
        pedestrian.start_time_s = start_time
        pedestrian.duration_s = max(0.0, end_time - start_time)
        params.pedestrians[role] = pedestrian


def apply_imported_obstacle_metadata_v2(params: ScenarioParametersV2, payload: str) -> None:
    role_iter = iter(OBSTACLE_ROLE_ORDER_V2)
    for token in payload.split(";"):
        match = re.fullmatch(
            r"\s*(?P<label>[^:]+):(?P<kind>\S+)\s+(?P<lane>[A-Za-z]+)@(?P<gap>-?\d+(?:\.\d+)?)m\s+"
            r"(?P<start_time>-?\d+(?:\.\d+)?)-(?P<end_time>-?\d+(?:\.\d+)?)s\s*",
            token,
            flags=re.IGNORECASE,
        )
        if not match:
            continue
        kind = match.group("kind").strip().lower()
        if kind not in OBSTACLE_MODEL_BY_KIND_V2:
            kind = "barrier"
        try:
            role = next(role_iter)
            obstacle = params.obstacles.get(role) or default_obstacle_config_v2(role, len(params.obstacles) + 1, params.total_experiment_time_s)
            params.obstacles[role] = obstacle
        except StopIteration:
            extra_index = len(params.extra_obstacles) + 1
            obstacle = ObstacleConfigV2(
                role=f"imported_obstacle_{extra_index}",
                label=f"Obstacle {extra_index}",
                vehicle_id=imported_scene_next_vehicle_id_v2(params) + extra_index,
                enabled=False,
                kind="barrier",
                lane="Middle",
                gap_m=40.0,
                lateral_offset_m=0.0,
                start_time_s=0.0,
                end_time_s=params.total_experiment_time_s,
                model_name=OBSTACLE_MODEL_BY_KIND_V2["barrier"],
            )
            params.extra_obstacles.append(obstacle)
        obstacle.enabled = True
        obstacle.label = match.group("label").strip() or obstacle.label
        obstacle.kind = kind
        obstacle.model_name = OBSTACLE_MODEL_BY_KIND_V2[kind]
        obstacle.lane = imported_scene_lane_v2(match.group("lane"), obstacle.lane)
        obstacle.gap_m = float(match.group("gap"))
        obstacle.start_time_s = float(match.group("start_time"))
        obstacle.end_time_s = float(match.group("end_time"))


def apply_imported_n_key_metadata_v2(params: ScenarioParametersV2, payload: str) -> None:
    n_key = default_n_key_intervention_config_v2(params)
    n_key.enabled = True
    key_match = re.search(r"\bkey=(\S+)", payload)
    if key_match:
        n_key.key_name = key_match.group(1)
    return_match = re.search(r"\breturn=(?P<vehicle>[A-Za-z0-9_]+)->(?P<lane>[A-Za-z]+)@press\+(?P<delay>-?\d+(?:\.\d+)?)s", payload)
    if return_match:
        vehicle_key = return_match.group("vehicle")
        if vehicle_key in params.vehicles:
            n_key.lane_change_vehicle_key = vehicle_key
            n_key.reference_vehicle_key = vehicle_key
            n_key.merge_vehicle_key = vehicle_key
        n_key.merge_target_lane = imported_scene_lane_v2(return_match.group("lane"), n_key.merge_target_lane)
        n_key.delayed_merge_offset_s = float(return_match.group("delay"))
    slow_match = re.search(r"\bego_slow=(?P<delta>-?\d+(?:\.\d+)?)mph", payload)
    if slow_match:
        n_key.ego_speed_delta_mph = float(slow_match.group("delta"))
    restore_match = re.search(r"\brestore_ego=(?P<speed>-?\d+(?:\.\d+)?)kmh", payload)
    if restore_match:
        n_key.restore_ego_speed_kmh = float(restore_match.group("speed"))
    window_match = re.search(r"\bwindow=(?P<start>-?\d+(?:\.\d+)?)-(?P<end>-?\d+(?:\.\d+)?)s", payload)
    lane_vehicle = params.vehicles.get(n_key.lane_change_vehicle_key)
    base_time_s = lane_change_base_time_s_v2(lane_vehicle) if lane_vehicle is not None else 0.0
    if window_match:
        n_key.window_start_offset_s = float(window_match.group("start")) - base_time_s
        n_key.window_end_offset_s = float(window_match.group("end")) - base_time_s
    params.n_key_intervention = n_key


def params_from_scene_builder_description_v2(
    description: str,
    *,
    source_path: Path,
    base_params: ScenarioParametersV2,
) -> ScenarioParametersV2:
    prefix = "HF scene builder:"
    if prefix not in description:
        raise ValueError("Scenario does not contain HF scene builder metadata.")
    params = reset_params_for_sce_import_v2(base_params, source_path)
    body = description.split(prefix, 1)[1].strip()
    for part in [item.strip() for item in body.split(" | ") if item.strip()]:
        if part.startswith("total_experiment_time_s="):
            params.total_experiment_time_s = max(1.0, imported_scene_float_v2(part, params.total_experiment_time_s))
        elif part.startswith("audio="):
            apply_imported_audio_metadata_v2(params, part.removeprefix("audio=").strip())
        elif part.startswith("rain_level="):
            params.rain_level = imported_scene_float_v2(part, 0.0)
        elif part.startswith("note="):
            params.scene_notes.append(part.removeprefix("note=").strip())
        elif part.startswith("pedestrians="):
            apply_imported_pedestrian_metadata_v2(params, part.removeprefix("pedestrians=").strip())
        elif part.startswith("obstacles="):
            apply_imported_obstacle_metadata_v2(params, part.removeprefix("obstacles=").strip())
        elif part.startswith("n_key_intervention="):
            apply_imported_n_key_metadata_v2(params, part.removeprefix("n_key_intervention=").strip())
        elif part.startswith("merge_v2="):
            params.scene_notes.append(part)
        else:
            apply_imported_vehicle_metadata_v2(params, part)
    return params


def scenario_metadata_from_sce_v2(sce_path: Path) -> tuple[ET.Element, str, str, str]:
    tree = ET.parse(sce_path)
    scenario = tree.getroot().find("Scenario")
    if scenario is None:
        raise ValueError("The selected .sce file is missing <Scenario>.")
    description = scenario.findtext("description", default="") or ""
    scenario_name = scenario.findtext("name", default=sce_path.stem) or sce_path.stem
    terrain_name = scenario.findtext("Ground/name", default="") or ""
    return scenario, description, scenario_name, terrain_name


def imported_sce_audio_source_candidates_v2(sce_path: Path, file_name: str) -> list[Path]:
    source_token = Path(file_name)
    candidates: list[Path] = []
    if source_token.is_absolute():
        candidates.append(source_token)
    bare_name = source_token.name
    search_roots = [sce_path.parent, *list(sce_path.parents)[:5]]
    for root in search_roots:
        candidates.extend(
            (
                root / bare_name,
                root / "audio" / bare_name,
                root / "sound" / bare_name,
            )
        )
    candidates.append(Path(__file__).resolve().parent / "unbundled" / 'sound' / bare_name)
    candidates.append(Path(__file__).resolve().parent / "unbundled" / 'sound' / bare_name)
    unique: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate).lower()
        if key in seen:
            continue
        seen.add(key)
        unique.append(candidate)
    return unique


def copy_imported_sce_audio_assets_v2(sce_path: Path, params: ScenarioParametersV2) -> list[Path]:
    copied: list[Path] = []
    for event in params.audio_events:
        file_name = Path(event.file_name).name
        if not file_name:
            continue
        event.file_name = file_name
        target = PROMPT_AUDITORY_CUE_DIR_V2 / file_name
        if target.is_file():
            continue
        for candidate in imported_sce_audio_source_candidates_v2(sce_path, event.file_name):
            if not candidate.is_file():
                continue
            PROMPT_AUDITORY_CUE_DIR_V2.mkdir(parents=True, exist_ok=True)
            shutil.copy2(candidate, target)
            copied.append(target)
            break
    return copied


def prompt_text_from_sce_v2(sce_path: Path, template_path: Path | None = None) -> str:
    source_path = Path(sce_path).resolve()
    _scenario, description, _scenario_name, terrain_name = scenario_metadata_from_sce_v2(source_path)
    if "HF scene builder:" in description:
        defaults = load_template_defaults_v2(template_path or DEFAULT_TEMPLATE_PATH)
        params = params_from_scene_builder_description_v2(
            description,
            source_path=source_path,
            base_params=defaults.default_params,
        )
    else:
        defaults = load_template_defaults_v2(source_path)
        params = clone_params_v2(defaults.default_params)
        params.output_filename = normalize_output_filename(source_path.name)

    if terrain_name:
        try:
            template_terrain = scenario_metadata_from_sce_v2(Path(template_path or DEFAULT_TEMPLATE_PATH))[3]
        except Exception:  # noqa: BLE001
            template_terrain = ""
        if terrain_name != template_terrain:
            params.terrain_override_name = terrain_name
    copy_imported_sce_audio_assets_v2(source_path, params)
    return build_timeline_sorted_prompt_v2("sce_import", [params])

