def build_rule_v2(rule_index: int, condition_text: str, actions: list[str]) -> str:
    return (
        f'\tTYPEOF RULE ({rule_index})\n'
        '\t{\n'
        '\t\tIS_EXPANDED="1"\n'
        '\t\tLABEL="Rule"\n\n'
        f"{condition_text}\n"
        + "\n".join(actions)
        + '\t}\n'
    )


def lane_change_target_pose_v2(
    params: ScenarioParametersV2,
    defaults: TemplateDefaultsV2,
    config: VehicleConfigV2,
    *,
    time_s: float,
    target_lane_name: str,
    merge_metadata: dict[str, Any] | None,
) -> tuple[float, float, float]:
    target_abscissa = project_vehicle_abscissa_v2(params, defaults, config, time_s)
    target_lane_gap = lane_gap_for_name_v2(defaults.lane_gaps_by_name, target_lane_name)
    if merge_metadata is not None:
        target_pose = merge_mainline_pose_v2(
            merge_metadata,
            params.merge.ego_start_s_m + (target_abscissa - defaults.ego_abscissa),
            target_lane_gap,
        )
        return (
            float(target_pose["map_x"]),
            float(target_pose["map_y"]),
            math.degrees(float(target_pose["heading_radians"])),
        )
    return (
        defaults.x_plus_abscissa - target_abscissa,
        target_lane_gap,
        defaults.heading_degrees,
    )


def staged_lane_change_pose_v2(
    params: ScenarioParametersV2,
    defaults: TemplateDefaultsV2,
    config: VehicleConfigV2,
    *,
    time_s: float,
    fraction: float,
    merge_metadata: dict[str, Any] | None,
    source_lane_name: str | None = None,
    target_lane_name: str | None = None,
) -> tuple[float, float, float]:
    start_lane_gap = lane_gap_for_name_v2(defaults.lane_gaps_by_name, source_lane_name or config.initial_lane)
    target_lane_gap = lane_gap_for_name_v2(defaults.lane_gaps_by_name, target_lane_name or config.lane_change_target_lane)
    staged_lane_gap = start_lane_gap + ((target_lane_gap - start_lane_gap) * max(0.0, min(1.0, fraction)))
    target_abscissa = project_vehicle_abscissa_v2(params, defaults, config, time_s)
    if merge_metadata is not None:
        target_pose = merge_mainline_pose_v2(
            merge_metadata,
            params.merge.ego_start_s_m + (target_abscissa - defaults.ego_abscissa),
            staged_lane_gap,
        )
        return (
            float(target_pose["map_x"]),
            float(target_pose["map_y"]),
            math.degrees(float(target_pose["heading_radians"])),
        )
    return (
        defaults.x_plus_abscissa - target_abscissa,
        staged_lane_gap,
        defaults.heading_degrees,
    )


def lane_change_trigger_key_v2(vehicle_key: str, event_index: int) -> str:
    return f"{vehicle_key}_lane_change" if event_index == 0 else f"{vehicle_key}_lane_change_{event_index + 1}"


def lane_change_end_trigger_key_v2(vehicle_key: str, event_index: int) -> str:
    return f"{vehicle_key}_lane_change_end" if event_index == 0 else f"{vehicle_key}_lane_change_{event_index + 1}_end"


def lane_change_step_trigger_key_v2(vehicle_key: str, event_index: int, step_index: int) -> str:
    return (
        f"{vehicle_key}_lane_change_step_{step_index}"
        if event_index == 0
        else f"{vehicle_key}_lane_change_{event_index + 1}_step_{step_index}"
    )


def build_mice_script_v2(
    scenario_token: str,
    defaults: TemplateDefaultsV2,
    params: ScenarioParametersV2,
    trigger_name_map: dict[str, str],
) -> str:
    rules: list[str] = []
    rule_index = 0
    merge_metadata = load_merge_metadata_v2(params.merge) if merge_enabled_v2(params) else None

    unique_audio_files: list[str] = []
    for event in params.audio_events:
        if event.file_name not in unique_audio_files:
            unique_audio_files.append(event.file_name)
    sound_slot_map = {file_name: index + 1 for index, file_name in enumerate(unique_audio_files)}

    if unique_audio_files:
        rules.append(
            build_rule_v2(
                rule_index,
                build_condition_is_scenario_beginning_v2(),
                [build_action_sound_load_v2(file_name, sound_slot_map[file_name]) for file_name in unique_audio_files],
            )
        )
        rule_index += 1

    speed_actions: list[str] = []
    for config in iter_script_vehicle_configs_v2(params):
        if not vehicle_enabled_v2(config):
            continue
        initial_speed_kmh = initial_vehicle_speed_kmh_v2(params, config)
        speed_actions.append(build_action_set_vhl_max_speed_v2(config.vehicle_id, initial_speed_kmh))
        speed_actions.append(build_action_set_speed_target_v2(config.vehicle_id, initial_speed_kmh))
    rules.append(build_rule_v2(rule_index, build_condition_is_scenario_beginning_v2(), speed_actions))
    rule_index += 1

    for config in iter_script_vehicle_configs_v2(params):
        key = config.key
        if not vehicle_enabled_v2(config):
            continue
        for point_index, gap_point in enumerate(config.gap_points):
            trigger_name = trigger_name_map[f"{key}_gap_{point_index}"]
            next_speed_kmh = speed_after_gap_point_kmh_v2(params, config, point_index)
            rules.append(
                build_rule_v2(
                    rule_index,
                    build_condition_is_triggered_v2(trigger_name),
                    [
                        build_action_set_vhl_max_speed_v2(config.vehicle_id, next_speed_kmh),
                        build_action_set_speed_target_v2(config.vehicle_id, next_speed_kmh),
                    ],
                )
            )
            rule_index += 1

        for lane_event_index, lane_event in enumerate(lane_change_events_for_vehicle_v2(config)):
            trigger_name = trigger_name_map[lane_change_trigger_key_v2(key, lane_event_index)]
            delta = lane_delta_v2(lane_event.from_lane, lane_event.target_lane)
            use_native_adjacent_lane_change = abs(delta) == 1 and lane_event.duration_s > 0
            use_staged_lane_change = abs(delta) > 1 and lane_event.duration_s > 0
            actions: list[str]
            if use_native_adjacent_lane_change:
                lane_change_speed_kmh = vehicle_speed_at_time_kmh_v2(params, config, lane_event.time_s)
                actions = [
                    build_action_set_vhl_max_speed_v2(config.vehicle_id, lane_change_speed_kmh),
                    build_action_set_speed_target_v2(config.vehicle_id, lane_change_speed_kmh),
                    build_action_go_to_adjacent_lane_v2(
                        config.vehicle_id,
                        direction="left" if delta < 0 else "right",
                        duration_s=lane_event.duration_s,
                    ),
                ]
            elif use_staged_lane_change:
                lane_change_speed_kmh = vehicle_speed_at_time_kmh_v2(params, config, lane_event.time_s)
                actions = [
                    build_action_set_vhl_max_speed_v2(config.vehicle_id, lane_change_speed_kmh),
                    build_action_set_speed_target_v2(config.vehicle_id, lane_change_speed_kmh),
                ]
            else:
                target_x, target_y, target_heading_degrees = lane_change_target_pose_v2(
                    params,
                    defaults,
                    config,
                    time_s=lane_event.time_s,
                    target_lane_name=lane_event.target_lane,
                    merge_metadata=merge_metadata,
                )
                lane_change_speed_kmh = vehicle_speed_at_time_kmh_v2(params, config, lane_event.time_s)
                actions = [
                    build_action_set_vhl_position_v2(
                        config.vehicle_id,
                        map_x=target_x,
                        map_y=target_y,
                        heading_degrees=target_heading_degrees,
                    ),
                    build_action_set_vhl_max_speed_v2(config.vehicle_id, lane_change_speed_kmh),
                    build_action_set_speed_target_v2(config.vehicle_id, lane_change_speed_kmh),
                ]
            rules.append(
                build_rule_v2(
                    rule_index,
                    build_condition_is_triggered_v2(trigger_name),
                    actions,
                )
            )
            rule_index += 1

            if use_staged_lane_change:
                for step_index in range(1, CUT_IN_TTC14_STAGED_LANE_CHANGE_STEPS_V2 + 1):
                    if step_index < CUT_IN_TTC14_STAGED_LANE_CHANGE_STEPS_V2:
                        stage_trigger_name = trigger_name_map.get(lane_change_step_trigger_key_v2(key, lane_event_index, step_index))
                    else:
                        stage_trigger_name = trigger_name_map.get(lane_change_end_trigger_key_v2(key, lane_event_index))
                    if not stage_trigger_name:
                        continue
                    stage_fraction = step_index / CUT_IN_TTC14_STAGED_LANE_CHANGE_STEPS_V2
                    stage_time_s = lane_event.time_s + (lane_event.duration_s * stage_fraction)
                    target_x, target_y, target_heading_degrees = staged_lane_change_pose_v2(
                        params,
                        defaults,
                        config,
                        time_s=stage_time_s,
                        fraction=stage_fraction,
                        merge_metadata=merge_metadata,
                        source_lane_name=lane_event.from_lane,
                        target_lane_name=lane_event.target_lane,
                    )
                    stage_speed_kmh = vehicle_speed_at_time_kmh_v2(params, config, stage_time_s)
                    rules.append(
                        build_rule_v2(
                            rule_index,
                            build_condition_is_triggered_v2(stage_trigger_name),
                            [
                                build_action_set_vhl_position_v2(
                                    config.vehicle_id,
                                    map_x=target_x,
                                    map_y=target_y,
                                    heading_degrees=target_heading_degrees,
                                ),
                                build_action_set_vhl_max_speed_v2(config.vehicle_id, stage_speed_kmh),
                                build_action_set_speed_target_v2(config.vehicle_id, stage_speed_kmh),
                            ],
                        )
                    )
                    rule_index += 1
            elif not use_native_adjacent_lane_change:
                end_trigger_name = trigger_name_map.get(lane_change_end_trigger_key_v2(key, lane_event_index))
                if end_trigger_name:
                    lane_change_end_time_s = lane_event.time_s + max(lane_event.duration_s, 0.0)
                    target_x, target_y, target_heading_degrees = lane_change_target_pose_v2(
                        params,
                        defaults,
                        config,
                        time_s=lane_change_end_time_s,
                        target_lane_name=lane_event.target_lane,
                        merge_metadata=merge_metadata,
                    )
                    lane_change_end_speed_kmh = vehicle_speed_at_time_kmh_v2(params, config, lane_change_end_time_s)
                    rules.append(
                        build_rule_v2(
                            rule_index,
                            build_condition_is_triggered_v2(end_trigger_name),
                            [
                                build_action_set_vhl_position_v2(
                                    config.vehicle_id,
                                    map_x=target_x,
                                    map_y=target_y,
                                    heading_degrees=target_heading_degrees,
                                ),
                                build_action_set_vhl_max_speed_v2(config.vehicle_id, lane_change_end_speed_kmh),
                                build_action_set_speed_target_v2(config.vehicle_id, lane_change_end_speed_kmh),
                            ],
                        )
                    )
                    rule_index += 1
            else:
                end_trigger_name = trigger_name_map.get(lane_change_end_trigger_key_v2(key, lane_event_index))
                if end_trigger_name:
                    lane_change_end_time_s = lane_event.time_s + max(lane_event.duration_s, 0.0)
                    lane_change_end_speed_kmh = vehicle_speed_at_time_kmh_v2(params, config, lane_change_end_time_s)
                    rules.append(
                        build_rule_v2(
                            rule_index,
                            build_condition_is_triggered_v2(end_trigger_name),
                            [
                                build_action_set_vhl_max_speed_v2(config.vehicle_id, lane_change_end_speed_kmh),
                                build_action_set_speed_target_v2(config.vehicle_id, lane_change_end_speed_kmh),
                            ],
                        )
                    )
                    rule_index += 1

        if config.stop_enabled:
            trigger_name = trigger_name_map[f"{key}_stop"]
            rules.append(
                build_rule_v2(
                    rule_index,
                    build_condition_is_triggered_v2(trigger_name),
                    [
                        build_action_set_vhl_acceleration_v2(config.vehicle_id, DEFAULT_STOP_DECELERATION_MPS2_V2),
                        build_action_set_vhl_max_speed_v2(config.vehicle_id, 0.0),
                        build_action_set_speed_target_v2(config.vehicle_id, 0.0),
                    ],
                )
            )
            rule_index += 1

    if merge_metadata is not None:
        merge_vehicle = params.vehicles.get(params.merge.merge_vehicle_key)
        if merge_vehicle is not None and vehicle_enabled_v2(merge_vehicle):
            for event_number, event in enumerate(merge_events_for_config_v2(params.merge), start=1):
                commit_trigger = trigger_name_map.get(f"merge_{event_number}_commit")
                end_trigger = trigger_name_map.get(f"merge_{event_number}_end")
                if not commit_trigger or not end_trigger:
                    continue
                event_metadata = merge_metadata_for_index_v2(merge_metadata, event.merge_index)
                event_behavior = event.behavior or params.merge.behavior
                merge_speed = params.merge.merge_speed_kmh
                if event_behavior == "yield_merge":
                    merge_speed = max(0.0, min(merge_speed, params.vehicles["ego"].speed_kmh - 12.0))
                if event.direction == "out":
                    commit_s = merge_ego_s_at_time_v2(params, event.commit_time_s) + params.merge.end_gap_to_ego_m
                    commit_pose = merge_mainline_pose_v2(
                        event_metadata,
                        commit_s,
                        lane_gap_for_name_v2(defaults.lane_gaps_by_name, "Right"),
                    )
                    end_pose = merge_ramp_pose_v2(event_metadata, 0.94)
                else:
                    commit_pose = merge_ramp_pose_v2(event_metadata, params.merge.ramp_commit_ratio)
                    if event_behavior == "abort_merge":
                        end_pose = merge_ramp_pose_v2(event_metadata, 0.94)
                    else:
                        end_s = merge_ego_s_at_time_v2(params, event.end_time_s) + params.merge.end_gap_to_ego_m
                        end_pose = merge_mainline_pose_v2(
                            event_metadata,
                            end_s,
                            lane_gap_for_name_v2(defaults.lane_gaps_by_name, "Right"),
                        )
                rules.append(
                    build_rule_v2(
                        rule_index,
                        build_condition_is_triggered_v2(commit_trigger),
                        [
                            build_action_set_vhl_position_from_pose_v2(merge_vehicle.vehicle_id, commit_pose),
                            build_action_set_vhl_max_speed_v2(merge_vehicle.vehicle_id, merge_speed),
                            build_action_set_speed_target_v2(merge_vehicle.vehicle_id, merge_speed),
                        ],
                    )
                )
                rule_index += 1
                rules.append(
                    build_rule_v2(
                        rule_index,
                        build_condition_is_triggered_v2(end_trigger),
                        [
                            build_action_set_vhl_position_from_pose_v2(merge_vehicle.vehicle_id, end_pose),
                            build_action_set_vhl_max_speed_v2(merge_vehicle.vehicle_id, merge_speed),
                            build_action_set_speed_target_v2(merge_vehicle.vehicle_id, merge_speed),
                        ],
                    )
                )
                rule_index += 1

    offroad_lane_gap = side_gap_v2(defaults.lane_gaps_by_name, "Right") + 80.0
    offroad_abscissa = defaults.ego_abscissa - 500.0

    for role in PEDESTRIAN_ROLE_ORDER_V2:
        pedestrian = params.pedestrians.get(role)
        if pedestrian is None or not pedestrian.enabled:
            continue
        start_trigger = trigger_name_map.get(f"{role}_start")
        end_trigger = trigger_name_map.get(f"{role}_end")
        if start_trigger is None or end_trigger is None:
            continue
        start_abscissa = actor_world_abscissa_v2(
            params,
            defaults,
            pedestrian.gap_m,
            world_locked=pedestrian.world_locked,
            lock_time_s=pedestrian.lock_time_s,
            time_s=pedestrian.start_time_s,
        )
        end_abscissa = actor_world_abscissa_v2(
            params,
            defaults,
            pedestrian.gap_m,
            world_locked=pedestrian.world_locked,
            lock_time_s=pedestrian.lock_time_s,
            time_s=pedestrian.start_time_s + pedestrian.duration_s,
        )
        start_gap = side_gap_v2(defaults.lane_gaps_by_name, pedestrian.start_side)
        end_gap = side_gap_v2(defaults.lane_gaps_by_name, pedestrian.end_side)
        heading_degrees = 90.0 if end_gap > start_gap else 270.0
        crossing_speed_kmh = abs(end_gap - start_gap) / max(pedestrian.duration_s, 0.1) * 3.6
        if merge_metadata is not None:
            start_pose = merge_mainline_pose_v2(
                merge_metadata,
                merge_actor_s_at_time_v2(
                    params,
                    pedestrian.gap_m,
                    world_locked=pedestrian.world_locked,
                    lock_time_s=pedestrian.lock_time_s,
                    time_s=pedestrian.start_time_s,
                ),
                start_gap,
            )
            end_pose = merge_mainline_pose_v2(
                merge_metadata,
                merge_actor_s_at_time_v2(
                    params,
                    pedestrian.gap_m,
                    world_locked=pedestrian.world_locked,
                    lock_time_s=pedestrian.lock_time_s,
                    time_s=pedestrian.start_time_s + pedestrian.duration_s,
                ),
                end_gap,
            )
            start_map_x = float(start_pose["map_x"])
            start_map_y = float(start_pose["map_y"])
            end_map_x = float(end_pose["map_x"])
            end_map_y = float(end_pose["map_y"])
        else:
            start_map_x = defaults.x_plus_abscissa - start_abscissa
            start_map_y = start_gap
            end_map_x = defaults.x_plus_abscissa - end_abscissa
            end_map_y = end_gap
        rules.append(
            build_rule_v2(
                rule_index,
                build_condition_is_triggered_v2(start_trigger),
                [
                    build_action_set_vhl_position_v2(
                        pedestrian.vehicle_id,
                        map_x=start_map_x,
                        map_y=start_map_y,
                        heading_degrees=heading_degrees,
                    ),
                    build_action_set_vhl_max_speed_v2(pedestrian.vehicle_id, crossing_speed_kmh),
                    build_action_set_speed_target_v2(pedestrian.vehicle_id, crossing_speed_kmh),
                ],
            )
        )
        rule_index += 1
        rules.append(
            build_rule_v2(
                rule_index,
                build_condition_is_triggered_v2(end_trigger),
                [
                    build_action_set_vhl_position_v2(
                        pedestrian.vehicle_id,
                        map_x=end_map_x,
                        map_y=end_map_y,
                        heading_degrees=heading_degrees,
                    ),
                    build_action_set_vhl_max_speed_v2(pedestrian.vehicle_id, 0.0),
                    build_action_set_speed_target_v2(pedestrian.vehicle_id, 0.0),
                ],
            )
        )
        rule_index += 1

    for obstacle in iter_obstacle_configs_v2(params):
        role = obstacle.role
        if not obstacle.enabled:
            continue
        start_trigger = trigger_name_map.get(f"{role}_start")
        end_trigger = trigger_name_map.get(f"{role}_end")
        if start_trigger is None or end_trigger is None:
            continue
        start_abscissa = actor_world_abscissa_v2(
            params,
            defaults,
            obstacle.gap_m,
            world_locked=obstacle.world_locked,
            lock_time_s=obstacle.lock_time_s,
            time_s=obstacle.start_time_s,
        )
        lane_gap = lane_gap_for_name_v2(defaults.lane_gaps_by_name, obstacle.lane) + obstacle.lateral_offset_m
        actor_name = f"{HF_ACTOR_PREFIX}{obstacle.role.upper()}"
        if merge_metadata is not None:
            start_pose = merge_mainline_pose_v2(
                merge_metadata,
                merge_actor_s_at_time_v2(
                    params,
                    obstacle.gap_m,
                    world_locked=obstacle.world_locked,
                    lock_time_s=obstacle.lock_time_s,
                    time_s=obstacle.start_time_s,
                ),
                lane_gap,
            )
            end_pose = merge_mainline_pose_v2(
                merge_metadata,
                max(0.0, params.merge.ego_start_s_m - 360.0),
                offroad_lane_gap,
            )
            start_map_x = float(start_pose["map_x"])
            start_map_y = float(start_pose["map_y"])
            start_heading_deg = math.degrees(float(start_pose["heading_radians"]))
            end_map_x = float(end_pose["map_x"])
            end_map_y = float(end_pose["map_y"])
            end_heading_deg = math.degrees(float(end_pose["heading_radians"]))
            start_heading_rad = float(start_pose["heading_radians"])
            end_heading_rad = float(end_pose["heading_radians"])
        else:
            start_map_x = defaults.x_plus_abscissa - start_abscissa
            start_map_y = lane_gap
            start_heading_deg = defaults.heading_degrees
            end_map_x = defaults.x_plus_abscissa - offroad_abscissa
            end_map_y = offroad_lane_gap
            end_heading_deg = defaults.heading_degrees
            start_heading_rad = defaults.heading_radians
            end_heading_rad = defaults.heading_radians
        if obstacle_uses_vehicle_v2(obstacle):
            start_actions = [
                build_action_set_vhl_position_v2(
                    obstacle.vehicle_id,
                    map_x=start_map_x,
                    map_y=start_map_y,
                    heading_degrees=start_heading_deg,
                ),
                build_action_set_vhl_max_speed_v2(obstacle.vehicle_id, 0.0),
                build_action_set_speed_target_v2(obstacle.vehicle_id, 0.0),
            ]
            end_actions = [
                build_action_set_vhl_position_v2(
                    obstacle.vehicle_id,
                    map_x=end_map_x,
                    map_y=end_map_y,
                    heading_degrees=end_heading_deg,
                ),
                build_action_set_vhl_max_speed_v2(obstacle.vehicle_id, 0.0),
                build_action_set_speed_target_v2(obstacle.vehicle_id, 0.0),
            ]
        else:
            start_actions = [
                build_action_set_object_position_v2(
                    actor_name,
                    map_x=start_map_x,
                    map_y=start_map_y,
                    map_z=0.0,
                    heading_radians=start_heading_rad,
                )
            ]
            end_actions = [
                build_action_set_object_position_v2(
                    actor_name,
                    map_x=end_map_x,
                    map_y=end_map_y,
                    map_z=0.0,
                    heading_radians=end_heading_rad,
                )
            ]
        rules.append(
            build_rule_v2(
                rule_index,
                build_condition_is_triggered_v2(start_trigger),
                start_actions,
            )
        )
        rule_index += 1
        rules.append(
            build_rule_v2(
                rule_index,
                build_condition_is_triggered_v2(end_trigger),
                end_actions,
            )
        )
        rule_index += 1

    for audio_index, event in enumerate(params.audio_events):
        trigger_name = trigger_name_map[f"audio_{audio_index}"]
        rules.append(
            build_rule_v2(
                rule_index,
                build_condition_is_triggered_v2(trigger_name),
                [build_action_sound_play_v2(sound_slot_map[event.file_name])],
            )
        )
        rule_index += 1

    return (
        "TYPEOF SCENARIO (0)\n"
        "{\n"
        '\tIS_EXPANDED="1"\n'
        '\tLABEL="Script_0"\n'
        f'\tFILE="Agent1_Type1/{scenario_token}_Script_0"\n'
        '\tTASK_KIND="0"\n\n'
        + "\n".join(rules)
        + "}\n"
    )


def count_generated_vehicle_action_v2(scenario_text: str, action_name: str, vehicle_id: int) -> int:
    action_pattern = re.compile(
        rf"TYPEOF ACTION \({re.escape(action_name)}\)(?P<body>.*?)(?=\n\tTYPEOF ACTION|\n\tTYPEOF RULE|\nTYPEOF SCENARIO|\Z)",
        flags=re.DOTALL,
    )
    vehicle_pattern = re.compile(rf'KIND="VEHICLE"\s+VALUE="{vehicle_id}"')
    return sum(
        1
        for match in action_pattern.finditer(scenario_text)
        if vehicle_pattern.search(match.group("body")) is not None
    )


def expected_lane_change_trigger_names_v2(params: ScenarioParametersV2) -> list[str]:
    trigger_names: list[str] = []
    for config in iter_script_vehicle_configs_v2(params):
        if not vehicle_enabled_v2(config):
            continue
        for lane_event_index, _lane_event in enumerate(lane_change_events_for_vehicle_v2(config)):
            event_suffix = "LANE_CHANGE" if lane_event_index == 0 else f"LANE_CHANGE_{lane_event_index + 1}"
            trigger_names.append(f"{HF_TRIGGER_PREFIX}{config.key.upper()}_{event_suffix}")
    return trigger_names


def expected_native_lane_change_actions_v2(params: ScenarioParametersV2) -> dict[tuple[int, str], int]:
    expected: dict[tuple[int, str], int] = {}
    for config in iter_script_vehicle_configs_v2(params):
        if not vehicle_enabled_v2(config):
            continue
        for lane_event in lane_change_events_for_vehicle_v2(config):
            delta = lane_delta_v2(lane_event.from_lane, lane_event.target_lane)
            if abs(delta) != 1 or lane_event.duration_s <= 0:
                continue
            action_name = "GO_TO_LEFT_LANE" if delta < 0 else "GO_TO_RIGHT_LANE"
            key = (config.vehicle_id, action_name)
            expected[key] = expected.get(key, 0) + 1
    return expected


def assert_generated_lane_change_actions_v2(output_path: Path, params: ScenarioParametersV2) -> None:
    if params_lane_change_event_count_v2(params) <= 0:
        return
    scenario_text = output_path.read_text(encoding="utf-8", errors="ignore")
    missing_triggers = [
        trigger_name
        for trigger_name in expected_lane_change_trigger_names_v2(params)
        if trigger_name not in scenario_text
    ]
    missing_actions: list[str] = []
    for (vehicle_id, action_name), expected_count in expected_native_lane_change_actions_v2(params).items():
        actual_count = count_generated_vehicle_action_v2(scenario_text, action_name, vehicle_id)
        if actual_count < expected_count:
            missing_actions.append(
                f"{action_name} for vehicle {vehicle_id}: expected {expected_count}, found {actual_count}"
            )
    if not missing_triggers and not missing_actions:
        return
    details = []
    if missing_triggers:
        details.append("missing lane-change triggers: " + ", ".join(missing_triggers))
    if missing_actions:
        details.append("missing native lane-change actions: " + "; ".join(missing_actions))
    raise RuntimeError("Lane-change generation check failed; " + " | ".join(details))


def generate_scenario_v2(
    *,
    template_path: Path,
    output_path: Path,
    params: ScenarioParametersV2,
    defaults: TemplateDefaultsV2,
) -> Path:
    validate_parameters_v2(params)
    merge_metadata = load_merge_metadata_v2(params.merge) if merge_enabled_v2(params) else None

    tree = ET.parse(template_path)
    scenario = tree.getroot().find("Scenario")
    if scenario is None:
        raise ValueError("Template is missing <Scenario>.")

    scenario_token = output_path.stem
    name_element = scenario.find("name")
    original_name = scenario.find("ProjectInfos/originalName")
    description = scenario.find("description")
    stop_criteria = scenario.find("ScenarioStopCriteria")
    if name_element is None or original_name is None or description is None or stop_criteria is None:
        raise ValueError("Template is missing scenario metadata fields.")

    final_time = stop_criteria.find("finalTime")
    stop_at_final_time = stop_criteria.find("stopAtFinalTime")
    if final_time is None or stop_at_final_time is None:
        raise ValueError("Template is missing ScenarioStopCriteria fields.")

    name_element.text = scenario_token
    original_name.text = output_path.name
    description.text = build_description_v2(params)
    final_time.text = format_number(params.total_experiment_time_s)
    stop_at_final_time.text = "1"
    if params.rain_level is not None:
        rain_level = scenario.find("Environment/Weather/rainLevel")
        if rain_level is not None:
            rain_level.text = format_number(params.rain_level)
        clouds_level = scenario.find("Environment/Weather/cloudsLevel")
        if clouds_level is not None:
            clouds_level.text = format_number(max(float(clouds_level.text or "0"), 0.75))
    if params.terrain_override_name:
        set_scenario_ground_name_v2(scenario, params.terrain_override_name)
    elif merge_metadata is not None:
        set_scenario_ground_name_v2(scenario, params.merge.terrain_name)

    for script_element in scenario.findall(".//ScenarioScript/script"):
        script_element.text = replace_script_file_token(script_element.text or "", scenario_token)

    disabled_lane_gap = side_gap_v2(defaults.lane_gaps_by_name, "Right") + 80.0
    for vehicle_index, key in enumerate(VEHICLE_ORDER_V2):
        config = params.vehicles[key]
        vehicle = find_named_element(scenario, "Vehicle", config.name)
        driver = find_driver_by_id(scenario, config.vehicle_id)
        is_active_vehicle = vehicle_enabled_v2(config)
        initial_speed_kmh = initial_vehicle_speed_kmh_v2(params, config) if is_active_vehicle else 0.0
        if merge_metadata is not None:
            if is_active_vehicle:
                apply_pose_to_object_v2(vehicle, merge_pose_for_vehicle_v2(merge_metadata, params, defaults, config))
            else:
                disabled_s = params.merge.ego_start_s_m - 520.0 - (vehicle_index * 24.0)
                apply_pose_to_object_v2(
                    vehicle,
                    merge_mainline_pose_v2(merge_metadata, disabled_s, disabled_lane_gap),
                )
        else:
            set_object_position(
                vehicle,
                abscissa=(
                    defaults.ego_abscissa + config.initial_offset_m
                    if is_active_vehicle
                    else defaults.ego_abscissa - 520.0 - (vehicle_index * 24.0)
                ),
                lane_gap=(
                    lane_gap_for_name_v2(defaults.lane_gaps_by_name, config.initial_lane)
                    if is_active_vehicle
                    else disabled_lane_gap
                ),
                x_plus_abscissa=defaults.x_plus_abscissa,
                heading_radians=defaults.heading_radians,
            )
        initial_speed = vehicle.find("initialSpeed")
        if initial_speed is not None:
            initial_speed.text = format_number(kmh_to_mps_v2(initial_speed_kmh))
        driver_max_speed = driver.find("TrafficDriver/maxSpeed")
        if driver_max_speed is not None:
            driver_max_speed.text = format_number(kmh_to_mps_v2(initial_speed_kmh))

    ego_vehicle = find_named_element(scenario, "Vehicle", EGO_NAME)
    set_child_text_v2(ego_vehicle, "modelName", LAUNCHER_EGO_MODEL_NAME)

    remove_hf_actor_elements_v2(scenario)
    actor_vehicle_template = find_named_element(scenario, "Vehicle", LEFT_LANE_NAME)
    actor_driver_template = find_driver_by_id(scenario, int(VEHICLE_META_V2["left"]["id"]))
    offroad_abscissa = defaults.ego_abscissa - 500.0
    offroad_lane_gap = side_gap_v2(defaults.lane_gaps_by_name, "Right") + 80.0

    for index, config in enumerate(extra_vehicles_v2(params), start=1):
        if not vehicle_enabled_v2(config):
            continue
        initial_speed_kmh = initial_vehicle_speed_kmh_v2(params, config)
        initial_abscissa = defaults.ego_abscissa + config.initial_offset_m
        initial_lane_gap = lane_gap_for_name_v2(defaults.lane_gaps_by_name, config.initial_lane)
        actor_name = config.name or f"{HF_ACTOR_PREFIX}{config.key.upper()}"
        extra_vehicle = clone_actor_vehicle_v2(
            scenario,
            template_vehicle=actor_vehicle_template,
            actor_id=config.vehicle_id,
            name=actor_name,
            model_name=actor_vehicle_template.findtext("modelName") or LEFT_LANE_NAME,
            process="${TRAFFIC}",
            abscissa=initial_abscissa,
            lane_gap=initial_lane_gap,
            defaults=defaults,
            heading_radians=defaults.heading_radians,
            z_offset=0.0,
            initial_speed_mps=kmh_to_mps_v2(initial_speed_kmh),
        )
        if merge_metadata is not None:
            apply_pose_to_object_v2(
                extra_vehicle,
                merge_pose_for_vehicle_v2(merge_metadata, params, defaults, config),
            )
        clone_actor_driver_v2(
            scenario,
            template_driver=actor_driver_template,
            actor_id=config.vehicle_id,
            name=actor_name,
            max_speed_mps=kmh_to_mps_v2(initial_speed_kmh),
            pedestrian=False,
        )

    for role in PEDESTRIAN_ROLE_ORDER_V2:
        pedestrian = params.pedestrians[role]
        if not pedestrian.enabled:
            continue
        initial_is_active = pedestrian.start_time_s <= 1e-6
        initial_abscissa = (
            actor_world_abscissa_v2(
                params,
                defaults,
                pedestrian.gap_m,
                world_locked=pedestrian.world_locked,
                lock_time_s=pedestrian.lock_time_s,
                time_s=pedestrian.start_time_s,
            )
            if initial_is_active
            else offroad_abscissa
        )
        initial_lane_gap = (
            side_gap_v2(defaults.lane_gaps_by_name, pedestrian.start_side)
            if initial_is_active
            else offroad_lane_gap
        )
        crossing_gap_span = abs(
            side_gap_v2(defaults.lane_gaps_by_name, pedestrian.end_side)
            - side_gap_v2(defaults.lane_gaps_by_name, pedestrian.start_side)
        )
        crossing_speed_mps = crossing_gap_span / max(pedestrian.duration_s, 0.1)
        actor_name = f"{HF_ACTOR_PREFIX}{pedestrian.role.upper()}"
        pedestrian_vehicle = clone_actor_vehicle_v2(
            scenario,
            template_vehicle=actor_vehicle_template,
            actor_id=pedestrian.vehicle_id,
            name=actor_name,
            model_name=pedestrian.model_name,
            process="${WALKERTRAFFIC}",
            abscissa=initial_abscissa,
            lane_gap=initial_lane_gap,
            defaults=defaults,
            heading_radians=math.radians(90 if pedestrian.end_side == "Right" else 270),
            z_offset=0.15,
            initial_speed_mps=0.0,
        )
        if merge_metadata is not None:
            pose_s = (
                merge_actor_s_at_time_v2(
                    params,
                    pedestrian.gap_m,
                    world_locked=pedestrian.world_locked,
                    lock_time_s=pedestrian.lock_time_s,
                    time_s=pedestrian.start_time_s,
                )
                if initial_is_active
                else params.merge.ego_start_s_m - 360.0
            )
            apply_pose_to_object_v2(
                pedestrian_vehicle,
                merge_mainline_pose_v2(merge_metadata, pose_s, initial_lane_gap),
            )
        clone_actor_driver_v2(
            scenario,
            template_driver=actor_driver_template,
            actor_id=pedestrian.vehicle_id,
            name=actor_name,
            max_speed_mps=crossing_speed_mps,
            pedestrian=True,
        )

    for obstacle in iter_obstacle_configs_v2(params):
        if not obstacle.enabled:
            continue
        initial_is_active = obstacle.start_time_s <= 1e-6
        initial_abscissa = (
            actor_world_abscissa_v2(
                params,
                defaults,
                obstacle.gap_m,
                world_locked=obstacle.world_locked,
                lock_time_s=obstacle.lock_time_s,
                time_s=obstacle.start_time_s,
            )
            if initial_is_active
            else offroad_abscissa
        )
        initial_lane_gap = (
            lane_gap_for_name_v2(defaults.lane_gaps_by_name, obstacle.lane) + obstacle.lateral_offset_m
            if initial_is_active
            else offroad_lane_gap
        )
        actor_name = f"{HF_ACTOR_PREFIX}{obstacle.role.upper()}"
        if obstacle_uses_vehicle_v2(obstacle):
            obstacle_vehicle = clone_actor_vehicle_v2(
                scenario,
                template_vehicle=actor_vehicle_template,
                actor_id=obstacle.vehicle_id,
                name=actor_name,
                model_name=obstacle.model_name,
                process="${TRAFFIC}",
                abscissa=initial_abscissa,
                lane_gap=initial_lane_gap,
                defaults=defaults,
                heading_radians=defaults.heading_radians,
                z_offset=0.0,
                initial_speed_mps=0.0,
            )
            if merge_metadata is not None:
                pose_s = (
                    merge_actor_s_at_time_v2(
                        params,
                        obstacle.gap_m,
                        world_locked=obstacle.world_locked,
                        lock_time_s=obstacle.lock_time_s,
                        time_s=obstacle.start_time_s,
                    )
                    if initial_is_active
                    else params.merge.ego_start_s_m - 360.0
                )
                apply_pose_to_object_v2(
                    obstacle_vehicle,
                    merge_mainline_pose_v2(merge_metadata, pose_s, initial_lane_gap),
                )
            clone_actor_driver_v2(
                scenario,
                template_driver=actor_driver_template,
                actor_id=obstacle.vehicle_id,
                name=actor_name,
                max_speed_mps=0.0,
                pedestrian=False,
            )
        else:
            obstacle_infrastructure = create_actor_infrastructure_v2(
                scenario,
                name=actor_name,
                model_name=obstacle.model_name,
                abscissa=initial_abscissa,
                lane_gap=initial_lane_gap,
                defaults=defaults,
                heading_radians=defaults.heading_radians,
                z_offset=0.0,
            )
            if merge_metadata is not None:
                pose_s = (
                    merge_actor_s_at_time_v2(
                        params,
                        obstacle.gap_m,
                        world_locked=obstacle.world_locked,
                        lock_time_s=obstacle.lock_time_s,
                        time_s=obstacle.start_time_s,
                    )
                    if initial_is_active
                    else params.merge.ego_start_s_m - 360.0
                )
                apply_pose_to_object_v2(
                    obstacle_infrastructure,
                    merge_mainline_pose_v2(merge_metadata, pose_s, initial_lane_gap),
                )

    remove_elements_by_name_prefix_v2(scenario, "Trigger", HF_TRIGGER_PREFIX)
    trigger_template = find_named_element(scenario, "Trigger", "Trigger 2")
    ego_lane_gap = lane_gap_for_name_v2(defaults.lane_gaps_by_name, params.vehicles["ego"].initial_lane)
    trigger_name_map: dict[str, str] = {}

    def create_timed_trigger(
        trigger_name: str,
        time_s: float,
        *,
        trigger_merge_metadata: dict[str, Any] | None = None,
    ) -> None:
        if merge_metadata is None:
            create_hf_trigger_v2(
                scenario,
                name=trigger_name,
                template_trigger=trigger_template,
                abscissa=project_vehicle_abscissa_v2(params, defaults, params.vehicles["ego"], time_s),
                lane_gap=ego_lane_gap,
                defaults=defaults,
            )
            return
        trigger = create_hf_trigger_v2(
            scenario,
            name=trigger_name,
            template_trigger=trigger_template,
            abscissa=defaults.ego_abscissa,
            lane_gap=ego_lane_gap,
            defaults=defaults,
        )
        apply_pose_to_object_v2(
            trigger,
            merge_pose_for_ego_trigger_v2(trigger_merge_metadata or merge_metadata, params, defaults, time_s),
        )

    for config in iter_script_vehicle_configs_v2(params):
        key = config.key
        if not vehicle_enabled_v2(config):
            continue
        for point_index, gap_point in enumerate(config.gap_points):
            trigger_name = f"{HF_TRIGGER_PREFIX}{key.upper()}_GAP_{point_index + 1}"
            trigger_name_map[f"{key}_gap_{point_index}"] = trigger_name
            create_timed_trigger(trigger_name, gap_point.time_s)
        for lane_event_index, lane_event in enumerate(lane_change_events_for_vehicle_v2(config)):
            event_suffix = "LANE_CHANGE" if lane_event_index == 0 else f"LANE_CHANGE_{lane_event_index + 1}"
            trigger_name = f"{HF_TRIGGER_PREFIX}{key.upper()}_{event_suffix}"
            trigger_name_map[lane_change_trigger_key_v2(key, lane_event_index)] = trigger_name
            create_timed_trigger(trigger_name, lane_event.time_s)
            if lane_event.duration_s > 0:
                if abs(lane_delta_v2(lane_event.from_lane, lane_event.target_lane)) > 1:
                    for step_index in range(1, CUT_IN_TTC14_STAGED_LANE_CHANGE_STEPS_V2):
                        trigger_name = f"{HF_TRIGGER_PREFIX}{key.upper()}_{event_suffix}_STEP_{step_index}"
                        trigger_name_map[lane_change_step_trigger_key_v2(key, lane_event_index, step_index)] = trigger_name
                        step_fraction = step_index / CUT_IN_TTC14_STAGED_LANE_CHANGE_STEPS_V2
                        create_timed_trigger(
                            trigger_name,
                            lane_event.time_s + (lane_event.duration_s * step_fraction),
                        )
                trigger_name = f"{HF_TRIGGER_PREFIX}{key.upper()}_{event_suffix}_END"
                trigger_name_map[lane_change_end_trigger_key_v2(key, lane_event_index)] = trigger_name
                create_timed_trigger(trigger_name, lane_event.time_s + lane_event.duration_s)
        if config.stop_enabled:
            trigger_name = f"{HF_TRIGGER_PREFIX}{key.upper()}_STOP"
            trigger_name_map[f"{key}_stop"] = trigger_name
            create_timed_trigger(trigger_name, config.stop_time_s)

    for role in PEDESTRIAN_ROLE_ORDER_V2:
        pedestrian = params.pedestrians[role]
        if not pedestrian.enabled:
            continue
        for suffix, time_s in (
            ("START", pedestrian.start_time_s),
            ("END", pedestrian.start_time_s + pedestrian.duration_s),
        ):
            trigger_name = f"{HF_TRIGGER_PREFIX}{role.upper()}_{suffix}"
            trigger_name_map[f"{role}_{suffix.lower()}"] = trigger_name
            create_timed_trigger(trigger_name, time_s)

    for obstacle in iter_obstacle_configs_v2(params):
        role = obstacle.role
        if not obstacle.enabled:
            continue
        for suffix, time_s in (("START", obstacle.start_time_s), ("END", obstacle.end_time_s)):
            trigger_name = f"{HF_TRIGGER_PREFIX}{role.upper()}_{suffix}"
            trigger_name_map[f"{role}_{suffix.lower()}"] = trigger_name
            create_timed_trigger(trigger_name, time_s)

    for audio_index, event in enumerate(params.audio_events):
        trigger_name = f"{HF_TRIGGER_PREFIX}AUDIO_{audio_index + 1}"
        trigger_name_map[f"audio_{audio_index}"] = trigger_name
        create_timed_trigger(trigger_name, event.time_s)

    if merge_metadata is not None:
        for event_number, event in enumerate(merge_events_for_config_v2(params.merge), start=1):
            event_metadata = merge_metadata_for_index_v2(merge_metadata, event.merge_index)
            commit_key = f"merge_{event_number}_commit"
            end_key = f"merge_{event_number}_end"
            trigger_name_map[commit_key] = f"{MERGE_TRIGGER_PREFIX_V2}{event_number}_COMMIT"
            trigger_name_map[end_key] = f"{MERGE_TRIGGER_PREFIX_V2}{event_number}_END"
            if event_number == 1:
                trigger_name_map["merge_commit"] = trigger_name_map[commit_key]
                trigger_name_map["merge_end"] = trigger_name_map[end_key]
            create_timed_trigger(trigger_name_map[commit_key], event.commit_time_s, trigger_merge_metadata=event_metadata)
            create_timed_trigger(trigger_name_map[end_key], event.end_time_s, trigger_merge_metadata=event_metadata)

    main_script_element = find_main_script_element_v2(scenario)
    main_script_element.text = build_mice_script_v2(scenario_token, defaults, params, trigger_name_map)
    n_key_script_name = write_n_key_intervention_script_v2(output_path, params) if n_key_intervention_enabled_v2(params) else None
    sync_standalone_python_script_element_v2(scenario, n_key_script_name)

    output_path.parent.mkdir(parents=True, exist_ok=True)
    tree.write(output_path, encoding="utf-8", xml_declaration=True, short_empty_elements=False)
    normalize_written_xml(output_path)
    assert_generated_lane_change_actions_v2(output_path, params)
    return output_path

# === HF GUI V2 UI START ===

class ScenarioGui(tk.Tk):
    MAP_WIDTH = 820
    MAP_HEIGHT = 430
    TIMELINE_WIDTH = 820
    TIMELINE_HEIGHT = 360

    def __init__(self, template_path: Path, *, insight_rail_width: int = 360) -> None:
        super().__init__()
        self.template_path = template_path.resolve()
        self.defaults = load_template_defaults_v2(self.template_path)
        self.reference_context = load_reference_context_v2(
            REFERENCE_CONTEXT_PATH,
            self.defaults.lane_gaps_by_name,
        )
        self._insight_rail_width = max(320, int(insight_rail_width))
        self._insight_rail_collapsed = False
        self._insight_toggle_button: ttk.Button | None = None
        self.workspace_paned: tk.PanedWindow | None = None
        self._preview_after_id: str | None = None
        self._map_drag_target: str | None = None
        self._timeline_drag_target: str | None = None
        self._map_model: dict[str, object] = {}
        self._timeline_model: dict[str, object] = {}
        self._audio_rows: list[dict[str, object]] = []
        self._gap_rows: dict[str, list[dict[str, object]]] = {key: [] for key in VEHICLE_ORDER_V2}
        self._gap_containers: dict[str, tk.Frame] = {}
        self._vehicle_vars: dict[str, dict[str, object]] = {}
        self._vehicle_widgets: dict[str, dict[str, ttk.Widget]] = {}
        self._pedestrian_vars: dict[str, dict[str, object]] = {}
        self._obstacle_vars: dict[str, dict[str, object]] = {}
        self._inkspace_dark = False
        self._theme_toggle_button: tk.Button | None = None
        self._inkspace_left_rail_footer: tk.Frame | None = None
        self._last_generated_path: Path | None = None

        self.output_filename_var = tk.StringVar(value=self.defaults.default_params.output_filename)
        self.total_experiment_time_var = tk.StringVar(
            value=format_number(self.defaults.default_params.total_experiment_time_s)
        )
        self._status_var = tk.StringVar(
            value="Insight Rail ready. Timeline stays central; map is contextual on the right."
        )
        self.timeline_readout_var = tk.StringVar(value="SCANeR")
        self.config_path_var = tk.StringVar(value=str(DEFAULT_STUDIO_CONFIG_PATH))
        self.theme_toggle_var = tk.StringVar(value="Lights Off")
        self.preview_status_var = tk.StringVar()
        self.preview_summary_var = tk.StringVar()
        self.map_zoom_var = tk.DoubleVar(value=1.0)
        self.show_reference_var = tk.BooleanVar(value=True)
        self.n_key_intervention_var = tk.BooleanVar(
            value=self.defaults.default_params.n_key_intervention.enabled
        )
        self.workspace_section_var = tk.StringVar(value="Scenario setup")
        self.workspace_helper_var = tk.StringVar(
            value="Shape map, runtime target, active support vehicles, pedestrians, and obstacles."
        )

        self._configure_window_v2()
        self._configure_styles_v2()
        self._build_vehicle_vars_v2()
        self._build_actor_vars_v2()
        self._build_layout_v2()
        self._load_defaults_into_form_v2()
        self._bind_preview_updates_v2()
        self.after(120, self._apply_insight_rail_layout_v2)
        self.after(360, self._apply_insight_rail_layout_v2)
        self.after(0, self._refresh_preview_v2)

    def _configure_window_v2(self) -> None:
        self._update_inkspace_title_v2()
        self.minsize(1280, 820)
        self.geometry("1660x980")
        self.configure(bg=APP_COLORS_V2["app_bg"])

    def _update_inkspace_title_v2(self) -> None:
        suffix = "Dark Workspace" if self._inkspace_dark else "Light Workspace"
        self.title(f"SCANeR HF Scenario Studio Actors - Inkspace Insight Rail {suffix}")

    def _update_theme_toggle_label_v2(self) -> None:
        label = "Lights On" if self._inkspace_dark else "Lights Off"
        self.theme_toggle_var.set(label)
        if self._theme_toggle_button is not None:
            try:
                self._theme_toggle_button.configure(text=label)
            except tk.TclError:
                pass

    def _configure_styles_v2(self) -> None:
        self.option_add("*Font", f"{{{BODY_FONT_FAMILY}}} 10")
        self.option_add("*TCombobox*Listbox*Font", f"{{{BODY_FONT_FAMILY}}} 9")
        style = ttk.Style(self)
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass
        style.configure(".", background=APP_COLORS_V2["app_bg"], foreground=APP_COLORS_V2["text"])
        style.configure("Card.TFrame", background=APP_COLORS_V2["surface"])
        style.configure("Surface.TFrame", background=APP_COLORS_V2["surface"])
        style.configure(
            "CardTitle.TLabel",
            background=APP_COLORS_V2["surface"],
            foreground=APP_COLORS_V2["text"],
            font="{Segoe UI} 12 bold",
        )
        style.configure(
            "CardBody.TLabel",
            background=APP_COLORS_V2["surface"],
            foreground=APP_COLORS_V2["muted"],
            font="{Segoe UI} 9",
        )
        style.configure(
            "Soft.TButton",
            padding=(12, 8),
            background=APP_COLORS_V2["surface"],
            foreground=APP_COLORS_V2["text"],
            bordercolor=APP_COLORS_V2["border"],
            lightcolor=APP_COLORS_V2["surface"],
            darkcolor=APP_COLORS_V2["surface"],
            font=(BODY_FONT_FAMILY, 9, "bold"),
        )
        style.map(
            "Soft.TButton",
            background=[
                ("active", APP_COLORS_V2["surface_subtle"]),
                ("pressed", APP_COLORS_V2["surface_subtle"]),
            ],
            bordercolor=[("focus", APP_COLORS_V2["accent"]), ("active", APP_COLORS_V2["line_strong"])],
            foreground=[("disabled", APP_COLORS_V2["quiet"])],
        )
        style.configure(
            "Primary.TButton",
            padding=(14, 9),
            background=APP_COLORS_V2["accent"],
            foreground="#ffffff",
            bordercolor=APP_COLORS_V2["accent"],
            lightcolor=APP_COLORS_V2["accent"],
            darkcolor=APP_COLORS_V2["accent"],
        )
        style.map(
            "Primary.TButton",
            background=[("active", APP_COLORS_V2["accent_hover"]), ("pressed", APP_COLORS_V2["accent_hover"])],
        )
        style.configure(
            "Card.TLabelframe",
            background=APP_COLORS_V2["surface"],
            bordercolor=APP_COLORS_V2["border"],
            relief="solid",
        )
        style.configure(
            "Card.TLabelframe.Label",
            background=APP_COLORS_V2["surface"],
            foreground=APP_COLORS_V2["text"],
            font="{Segoe UI} 11 bold",
        )
        style.configure(
            "Muted.TCheckbutton",
            background=APP_COLORS_V2["surface"],
            foreground=APP_COLORS_V2["text"],
        )
        style.configure(
            "Inline.TCombobox",
            arrowsize=14,
            fieldbackground="#ffffff",
            background="#ffffff",
        )

    def _build_vehicle_vars_v2(self) -> None:
        self._vehicle_vars = {}
        for key in VEHICLE_ORDER_V2:
            config = self.defaults.default_params.vehicles[key]
            self._vehicle_vars[key] = {
                "offset": tk.StringVar(value=format_number(config.initial_offset_m)),
                "lane": tk.StringVar(value=config.initial_lane),
                "speed": tk.StringVar(value=format_number(config.speed_kmh)),
                "lc_enabled": tk.BooleanVar(value=config.lane_change_enabled),
                "lc_time": tk.StringVar(value=format_number(config.lane_change_time_s)),
                "lc_target": tk.StringVar(value=config.lane_change_target_lane),
                "stop_enabled": tk.BooleanVar(value=config.stop_enabled),
                "stop_time": tk.StringVar(value=format_number(config.stop_time_s)),
            }

    def _build_actor_vars_v2(self) -> None:
        self._pedestrian_vars = {}
        for role in PEDESTRIAN_ROLE_ORDER_V2:
            config = self.defaults.default_params.pedestrians[role]
            self._pedestrian_vars[role] = {
                "enabled": tk.BooleanVar(value=config.enabled),
                "gap": tk.StringVar(value=format_number(config.gap_m)),
                "start_side": tk.StringVar(value=config.start_side),
                "end_side": tk.StringVar(value=config.end_side),
                "start_time": tk.StringVar(value=format_number(config.start_time_s)),
                "duration": tk.StringVar(value=format_number(config.duration_s)),
                "model": tk.StringVar(value=config.model_name),
                "world_locked": tk.BooleanVar(value=config.world_locked),
                "lock_time": tk.StringVar(value=format_number(config.lock_time_s)),
            }
        self._obstacle_vars = {}
        for role in OBSTACLE_ROLE_ORDER_V2:
            config = self.defaults.default_params.obstacles[role]
            self._obstacle_vars[role] = {
                "enabled": tk.BooleanVar(value=config.enabled),
                "kind": tk.StringVar(value=config.kind),
                "lane": tk.StringVar(value=config.lane),
                "gap": tk.StringVar(value=format_number(config.gap_m)),
                "lateral": tk.StringVar(value=format_number(config.lateral_offset_m)),
                "start_time": tk.StringVar(value=format_number(config.start_time_s)),
                "end_time": tk.StringVar(value=format_number(config.end_time_s)),
                "model": tk.StringVar(value=config.model_name),
                "world_locked": tk.BooleanVar(value=config.world_locked),
                "lock_time": tk.StringVar(value=format_number(config.lock_time_s)),
            }

    def _make_inkspace_button_v2(
        self,
        parent: tk.Misc,
        text: str,
        command,
        *,
        primary: bool = False,
        selected: bool = False,
        compact: bool = False,
    ) -> tk.Button:
        colors = APP_COLORS_V2
        if primary:
            background = colors["accent"]
            foreground = colors["selection_fg"]
            border = colors["accent"]
            active_background = colors["accent_hover"]
        elif selected:
            background = colors["accent_soft"]
            foreground = colors["accent"]
            border = colors["border"]
            active_background = colors["surface_subtle"]
        else:
            background = colors["surface"]
            foreground = colors["text"]
            border = colors["border"]
            active_background = colors["surface_subtle"]
        return tk.Button(
            parent,
            text=text,
            command=command,
            bg=background,
            fg=foreground,
            activebackground=active_background,
            activeforeground=foreground,
            relief="flat",
            bd=0,
            highlightthickness=1,
            highlightbackground=border,
            highlightcolor=border,
            padx=12 if compact else 16,
            pady=7 if compact else 10,
            font=(BODY_FONT_FAMILY, 9, "bold"),
            cursor="hand2",
        )

    def _build_layout_v2(self) -> None:
        colors = APP_COLORS_V2
        self.columnconfigure(0, weight=1)
        self.rowconfigure(0, weight=1)

        root = tk.Frame(self, bg=colors["app_bg"], padx=20, pady=20)
        root.grid(row=0, column=0, sticky="nsew")
        root.columnconfigure(0, weight=1)
        root.rowconfigure(0, weight=1)

        app_shell = tk.Frame(
            root,
            bg=colors["surface"],
            highlightthickness=1,
            highlightbackground=colors["border"],
            highlightcolor=colors["border"],
        )
        app_shell.grid(row=0, column=0, sticky="nsew")
        app_shell.columnconfigure(0, weight=0)
        app_shell.columnconfigure(1, weight=1)
        app_shell.rowconfigure(0, weight=1)

        left_shell = tk.Frame(app_shell, bg=colors["surface_alt"], padx=18, pady=18)
        self.left_shell = left_shell
        left_shell.grid(row=0, column=0, sticky="nsw")
        left_shell.configure(width=340)
        left_shell.grid_propagate(False)
        left_shell.columnconfigure(0, weight=1)
        left_shell.rowconfigure(2, weight=1)
        left_shell.rowconfigure(3, weight=0)

        rail_header = tk.Frame(left_shell, bg=colors["surface_alt"])
        rail_header.grid(row=0, column=0, sticky="ew")
        rail_header.columnconfigure(0, weight=1)
        tk.Label(
            rail_header,
            text="AUTHORING RAIL",
            bg=colors["surface_alt"],
            fg=colors["accent"],
            font=(MONO_FONT_FAMILY, 10, "bold"),
            anchor="w",
        ).grid(row=0, column=0, sticky="w")
        tk.Label(
            rail_header,
            textvariable=self.workspace_section_var,
            bg=colors["surface_alt"],
            fg=colors["text"],
            font=(DISPLAY_FONT_FAMILY, 18, "bold"),
            anchor="w",
        ).grid(row=1, column=0, sticky="w", pady=(6, 0))
        tk.Label(
            rail_header,
            textvariable=self.workspace_helper_var,
            bg=colors["surface_alt"],
            fg=colors["muted"],
            font=(BODY_FONT_FAMILY, 11),
            justify="left",
            anchor="w",
            wraplength=300,
        ).grid(row=2, column=0, sticky="ew", pady=(6, 0))

        rail_rule = tk.Frame(left_shell, bg=colors["border"], height=1)
        rail_rule.grid(row=1, column=0, sticky="ew", pady=(16, 12))

        body_shell = tk.Frame(left_shell, bg=colors["surface_alt"], highlightthickness=0)
        body_shell.grid(row=2, column=0, sticky="nsew")
        body_shell.columnconfigure(0, weight=1)
        body_shell.rowconfigure(0, weight=1)

        self.controls_canvas = tk.Canvas(body_shell, bg=colors["surface_alt"], highlightthickness=0, bd=0)
        controls_scrollbar = ttk.Scrollbar(body_shell, orient="vertical", command=self.controls_canvas.yview)
        self.controls_canvas.configure(yscrollcommand=controls_scrollbar.set)
        self.controls_canvas.grid(row=0, column=0, sticky="nsew")
        controls_scrollbar.grid(row=0, column=1, sticky="ns", padx=(8, 0))

        self.controls_body = tk.Frame(self.controls_canvas, bg=colors["surface_alt"])
        self.controls_body.grid_columnconfigure(0, weight=1)
        self.controls_window_id = self.controls_canvas.create_window((0, 0), window=self.controls_body, anchor="nw")
        self.controls_body.bind("<Configure>", self._on_controls_body_configure_v2)
        self.controls_canvas.bind("<Configure>", self._on_controls_canvas_configure_v2)
        self.controls_canvas.bind("<MouseWheel>", self._on_controls_mousewheel_v2)

        self._build_general_card_v2(self.controls_body).grid(row=0, column=0, sticky="ew", pady=(0, 12))
