    def _create_preview_card_v2(self, parent: tk.Widget, *, row: int, title: str) -> tk.Frame:
        colors = APP_COLORS_V2
        is_insight_rail = title == "Scenario Map"
        if title == "Event Timeline":
            title_text = "Timeline"
            subtitle_text = "Primary work surface"
            meta_text = "SEQUENCE EDITOR"
            title_font = "{Segoe UI} 20 bold"
            card_bg = colors["surface"]
        elif is_insight_rail:
            title_text = "Insight Rail"
            subtitle_text = "Map + placement context"
            meta_text = "CONTEXT RAIL"
            title_font = "{Segoe UI} 13 bold"
            card_bg = self._rail_bg_v2()
        else:
            title_text = title
            subtitle_text = "Workspace"
            meta_text = "WORKSPACE"
            title_font = "{Segoe UI} 16 bold"
            card_bg = colors["surface"]

        card = tk.Frame(
            parent,
            bg=card_bg,
            highlightthickness=1,
            highlightbackground=colors["line"],
            highlightcolor=colors["line"],
        )
        card.grid(row=row, column=0, sticky="nsew", pady=(0, 12))
        card.columnconfigure(0, weight=1)
        card.rowconfigure(2, weight=1)
        header = tk.Frame(card, bg=card_bg)
        header.grid(row=0, column=0, sticky="ew")
        header.columnconfigure(1, weight=1)
        title_stack = tk.Frame(header, bg=card_bg)
        title_stack.grid(row=0, column=0, sticky="w", padx=14, pady=8 if is_insight_rail else 12)
        tk.Label(
            title_stack,
            text=meta_text,
            bg=card_bg,
            fg=colors["muted"] if is_insight_rail else colors["accent_secondary"],
            font="{Consolas} 8 bold",
            anchor="w",
        ).pack(anchor="w")
        tk.Label(
            title_stack,
            text=title_text,
            bg=card_bg,
            fg=colors["text"],
            font=title_font,
            anchor="w",
        ).pack(anchor="w", pady=(4, 0))
        tk.Label(
            header,
            text=subtitle_text,
            bg=card_bg,
            fg=colors["muted"],
            font="{Segoe UI} 9",
            padx=14,
            pady=8 if is_insight_rail else 12,
            anchor="e",
        ).grid(row=0, column=1, sticky="e")
        if is_insight_rail:
            self._insight_toggle_button = ttk.Button(
                header,
                text="Hide",
                style="Soft.TButton",
                command=self._toggle_insight_rail_v2,
                width=6,
            )
            self._insight_toggle_button.grid(row=0, column=2, sticky="e", padx=(0, 12), pady=6)
        tk.Frame(header, bg=colors["line"], height=1).grid(row=1, column=0, columnspan=3, sticky="ew")
        return card

    def _rail_bg_v2(self) -> str:
        return APP_COLORS_V2["surface_alt"]

    def _sync_insight_toggle_label_v2(self) -> None:
        if self._insight_toggle_button is None:
            return
        try:
            self._insight_toggle_button.configure(text="Show" if self._insight_rail_collapsed else "Hide")
        except tk.TclError:
            pass

    def _toggle_insight_rail_v2(self) -> None:
        self._insight_rail_collapsed = not self._insight_rail_collapsed
        self._sync_insight_toggle_label_v2()
        if self._insight_rail_collapsed:
            self._collapse_insight_rail_v2()
            self.preview_status_var.set("Insight Rail hidden. Timeline has the full SCANeR timing workspace.")
        else:
            self._apply_insight_rail_layout_v2()
            self.preview_status_var.set("Insight Rail restored. Map context is back on the right.")

    def _collapse_insight_rail_v2(self) -> None:
        if self.workspace_paned is None:
            return
        try:
            self.update_idletasks()
            panes = list(self.workspace_paned.panes())
            if len(panes) >= 2:
                self.workspace_paned.paneconfigure(panes[1], minsize=0)
            total_width = self.workspace_paned.winfo_width()
            if total_width <= 1:
                self.after(80, self._collapse_insight_rail_v2)
                return
            self.workspace_paned.sash_place(0, max(360, total_width - 12), 1)
            self._schedule_preview_refresh_v2()
        except tk.TclError:
            return

    def _set_workspace_paned_sash_v2(self) -> None:
        if self.workspace_paned is None:
            return
        try:
            total_width = self.workspace_paned.winfo_width()
            if total_width <= 1:
                self.after(80, self._set_workspace_paned_sash_v2)
                return
            if self._insight_rail_collapsed:
                self._collapse_insight_rail_v2()
                return

            minimum_timeline_width = 560
            minimum_rail_width = 320
            if total_width < minimum_timeline_width + minimum_rail_width:
                rail_width = max(300, total_width // 3)
                clamped_x = max(360, total_width - rail_width)
            else:
                maximum_rail_width = max(minimum_rail_width, total_width - minimum_timeline_width)
                rail_width = min(self._insight_rail_width, maximum_rail_width)
                rail_width = max(minimum_rail_width, rail_width)
                clamped_x = total_width - rail_width
            self.workspace_paned.sash_place(0, int(clamped_x), 1)
        except tk.TclError:
            return

    def _apply_insight_rail_layout_v2(self) -> None:
        try:
            self.update_idletasks()
            self._set_workspace_paned_sash_v2()
            self._sync_insight_toggle_label_v2()
            if self.map_canvas is not None:
                self.map_canvas.configure(height=max(520, self.map_canvas.winfo_height()))
            if self.timeline_canvas is not None:
                self.timeline_canvas.configure(height=max(420, self.timeline_canvas.winfo_height()))
            self._schedule_preview_refresh_v2()
        except tk.TclError:
            return

    def _create_card_v2(self, parent: tk.Widget, *, title: str, description: str) -> ttk.Frame:
        card = ttk.LabelFrame(parent, text=title, style="Card.TLabelframe", padding=(14, 12))
        card.grid_columnconfigure(0, weight=1)
        card.grid_columnconfigure(2, weight=1)
        ttk.Label(card, text=description, style="CardBody.TLabel", wraplength=360, justify="left").grid(
            row=0,
            column=0,
            columnspan=4,
            sticky="w",
            pady=(0, 10),
        )
        return card

    def _build_general_card_v2(self, parent: tk.Widget) -> ttk.Frame:
        card = self._create_card_v2(
            parent,
            title="General",
            description="Output file, total experiment time, and ego cruise speed. Other vehicles use gap targets instead of manual speed fields.",
        )
        self._add_labeled_entry_v2(card, row=1, column=0, label="Output filename", variable=self.output_filename_var, width=26)
        self._add_labeled_entry_v2(
            card,
            row=1,
            column=2,
            label="Total time (s)",
            variable=self.total_experiment_time_var,
            width=10,
        )
        self._add_labeled_entry_v2(
            card,
            row=2,
            column=0,
            label="Ego speed (km/h)",
            variable=self._vehicle_vars["ego"]["speed"],
            width=10,
        )
        ttk.Checkbutton(
            card,
            text="Enable N-key intervention",
            variable=self.n_key_intervention_var,
            style="Muted.TCheckbutton",
            command=self._schedule_preview_refresh_v2,
        ).grid(row=2, column=2, columnspan=2, sticky="w", pady=(18, 8))
        return card

    def _build_vehicle_card_v2(self, parent: tk.Widget, key: str) -> ttk.Frame:
        meta = VEHICLE_META_V2[key]
        card = self._create_card_v2(
            parent,
            title=meta["label"],
            description=(
                "Ego uses the general speed setting. Other vehicles use initial gap plus optional gap keyframes "
                "to define how far they should be from ego over time."
            ),
        )
        vars_for_vehicle = self._vehicle_vars[key]
        widgets: dict[str, ttk.Widget] = {}

        row_index = 1
        if key != "ego":
            widgets["offset"] = self._add_labeled_entry_v2(
                card,
                row=row_index,
                column=0,
                label="Initial gap to ego (m)",
                variable=vars_for_vehicle["offset"],
                width=10,
            )
            widgets["lane"] = self._add_labeled_combo_v2(
                card,
                row=row_index,
                column=2,
                label="Initial lane",
                variable=vars_for_vehicle["lane"],
                values=LANE_NAMES_V2,
            )
            row_index += 1

            gap_header = tk.Frame(card, bg=APP_COLORS_V2["surface"])
            gap_header.grid(row=row_index, column=0, columnspan=4, sticky="ew", pady=(2, 6))
            gap_header.columnconfigure(0, weight=1)
            tk.Label(
                gap_header,
                text="Gap Keyframes To Ego",
                bg=APP_COLORS_V2["surface"],
                fg=APP_COLORS_V2["text"],
                font="{Segoe UI} 10 bold",
            ).grid(row=0, column=0, sticky="w")
            ttk.Button(
                gap_header,
                text="Add Gap Point",
                style="Soft.TButton",
                command=lambda current_key=key: self._add_gap_row_v2(current_key),
            ).grid(row=0, column=1, sticky="e")
            row_index += 1

            gap_hint = tk.Label(
                card,
                text="Example: at 3 s keep +20 m, at 6 s keep +10 m. Rear vehicles can use negative gaps.",
                bg=APP_COLORS_V2["surface"],
                fg=APP_COLORS_V2["muted"],
                font="{Segoe UI} 8",
            )
            gap_hint.grid(row=row_index, column=0, columnspan=4, sticky="w", pady=(0, 6))
            row_index += 1

            gap_container = tk.Frame(card, bg=APP_COLORS_V2["surface"])
            gap_container.grid(row=row_index, column=0, columnspan=4, sticky="ew", pady=(0, 8))
            gap_container.columnconfigure(0, weight=1)
            self._gap_containers[key] = gap_container
            row_index += 1
        else:
            widgets["lane"] = self._add_labeled_combo_v2(
                card,
                row=row_index,
                column=0,
                label="Initial lane",
                variable=vars_for_vehicle["lane"],
                values=LANE_NAMES_V2,
            )
            tk.Label(
                card,
                text="Ego acts as the distance reference for the other vehicles.",
                bg=APP_COLORS_V2["surface"],
                fg=APP_COLORS_V2["muted"],
                font="{Segoe UI} 8",
            ).grid(row=row_index, column=2, columnspan=2, sticky="w", pady=(18, 8))
            row_index += 1

        ttk.Checkbutton(
            card,
            text="Enable lane change",
            variable=vars_for_vehicle["lc_enabled"],
            style="Muted.TCheckbutton",
            command=lambda current_key=key: self._sync_vehicle_control_state_v2(current_key),
        ).grid(row=row_index, column=0, sticky="w", pady=(4, 0))
        row_index += 1
        widgets["lc_time"] = self._add_labeled_entry_v2(
            card,
            row=row_index,
            column=0,
            label="Lane-change time (s)",
            variable=vars_for_vehicle["lc_time"],
            width=10,
        )
        widgets["lc_target"] = self._add_labeled_combo_v2(
            card,
            row=row_index,
            column=2,
            label="Target lane",
            variable=vars_for_vehicle["lc_target"],
            values=LANE_NAMES_V2,
        )
        row_index += 1

        ttk.Checkbutton(
            card,
            text="Enable stop",
            variable=vars_for_vehicle["stop_enabled"],
            style="Muted.TCheckbutton",
            command=lambda current_key=key: self._sync_vehicle_control_state_v2(current_key),
        ).grid(row=row_index, column=0, sticky="w", pady=(6, 0))
        row_index += 1
        widgets["stop_time"] = self._add_labeled_entry_v2(
            card,
            row=row_index,
            column=0,
            label="Stop time (s)",
            variable=vars_for_vehicle["stop_time"],
            width=10,
        )
        self._vehicle_widgets[key] = widgets
        self._sync_vehicle_control_state_v2(key)
        return card

