def extract_prompt_n_key_merge_speed_delta_mph_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:加速|accelerate|speed\s*up)[^.;\n。；]{{0,8}}?{{n}}{{u}}{PROMPT_MPH_UNIT_PATTERN_V2}",
        ),
    )


def extract_prompt_n_key_merge_target_lane_v2(prompt_text: str, default_lane: str) -> str:
    lane_pattern = lane_word_pattern_v2()
    patterns = (
        rf"(?:按鍵|按键|press|successful|成功|原本|merge)[^.;\n。；]{{0,160}}?"
        rf"(?:向|到|至|回到|變到|变到|變回|变回|to|into)\s*(?:the\s+)?(?P<lane>{lane_pattern})"
        rf"[^.;\n。；]{{0,48}}?(?:變道|变道|換道|换道|merge|lane)",
        rf"(?:vehicle\s*1|vehicle1|front\s+vehicle|lead\s+vehicle|前車|前车)[^.;\n。；]{{0,160}}?"
        rf"(?:向|到|至|回到|變到|变到|變回|变回|to|into)\s*(?:the\s+)?(?P<lane>{lane_pattern})",
    )
    for pattern in patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL)
        if match:
            lane = lane_from_prompt_fragment_v2(match.group("lane"))
            if lane:
                return lane
    return default_lane


def extract_prompt_restore_ego_speed_kmh_v2(prompt_text: str) -> float | None:
    mph_value = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:恢復|恢复|restore|recover)[^.;\n。；]{{0,80}}?"
            rf"(?:速度|speed|driving\s+speed)?[^.;\n。；]{{0,32}}?{{n}}{{u}}{PROMPT_MPH_UNIT_PATTERN_V2}",
        ),
    )
    if mph_value is not None:
        return mph_value * MPH_TO_KMH_V2
    kmh_value = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:恢復|恢复|restore|recover)[^.;\n。；]{{0,80}}?"
            rf"(?:速度|speed|driving\s+speed)?[^.;\n。；]{{0,32}}?{{n}}{{u}}{PROMPT_KMH_UNIT_PATTERN_V2}",
        ),
    )
    return kmh_value


def prompt_text_without_cue_filenames_v2(prompt_text: str) -> str:
    return re.sub(
        r"\b[^\s;:,]+\.(?:wav|mp3|ogg|flac|png|jpg|jpeg|svg|bmp|gif|txt)\b",
        "",
        prompt_text,
        flags=re.IGNORECASE,
    )


def prompt_has_deceleration_intent_v2(prompt_text: str) -> bool:
    text = prompt_text_without_cue_filenames_v2(prompt_text)
    return re.search(PROMPT_DECELERATION_PATTERN_V2, text, flags=re.IGNORECASE) is not None


def extract_prompt_deceleration_start_time_s_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:at|after|around|from|starting(?:\s+at)?|starts?\s+at|開始於|开始于|開始在|开始在|從|从)\s*{{n}}(?:{{u}}{PROMPT_TIME_UNIT_PATTERN_V2})?[^.;\n。；]{{0,90}}?{PROMPT_DECELERATION_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}\s*(?:後|后|時|时|的時候|的时候|開始|开始|into|after|from|mark|,)[^.;\n。；]{{0,70}}?{PROMPT_DECELERATION_PATTERN_V2}",
            rf"{PROMPT_DECELERATION_PATTERN_V2}[^.;\n。；]{{0,50}}?(?:at|after|around|from|starting(?:\s+at)?|starts?\s+at|開始於|开始于|開始在|开始在|從|从)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
        ),
    )


def extract_prompt_deceleration_target_gap_time_s_v2(prompt_text: str) -> float | None:
    gap_words = r"(?:time\s*gap|gap|headway|spacing|following\s+distance|follow\s+distance|間距|间距|距離|距离|車距|车距|跟車|跟车)"
    target_words = r"(?:to|down\s+to|close(?:s|d)?\s+to|reduce(?:s|d)?\s+to|decrease(?:s|d)?\s+to|becomes?|target(?:s|ed)?|拉近到|縮短到|缩短到|降到|變成|变成|到)"
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"{gap_words}[^.;\n。；]{{0,44}}?{target_words}[^.;\n。；]{{0,16}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{target_words}[^.;\n。；]{{0,16}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,44}}?{gap_words}",
        ),
    )


def extract_prompt_deceleration_target_speed_kmh_v2(prompt_text: str) -> float | None:
    mph_value = search_prompt_number_v2(
        prompt_text,
        (
            rf"{PROMPT_DECELERATION_PATTERN_V2}[^.;\n。；]{{0,40}}?(?:to|down\s+to|target(?:s|ed)?|降到|減到|减到|到)\s*{{n}}{{u}}(?:mph|miles?\s*(?:per|an)?\s*hour|miles?/h|miles?|mi/h|英里)",
        ),
    )
    if mph_value is not None:
        return mph_value * MPH_TO_KMH_V2

    kmh_value = search_prompt_number_v2(
        prompt_text,
        (
            rf"{PROMPT_DECELERATION_PATTERN_V2}[^.;\n。；]{{0,40}}?(?:to|down\s+to|target(?:s|ed)?|降到|減到|减到|到)\s*{{n}}{{u}}(?:km/h|kmh|kph|kilometers?\s*per\s*hour|kilometres?\s*per\s*hour|公里/小時|公里每小時|公里/小时|公里每小时)",
        ),
    )
    return kmh_value


def extract_prompt_deceleration_end_time_s_v2(prompt_text: str, start_time_s: float | None) -> float | None:
    absolute_time = search_last_prompt_number_v2(
        prompt_text,
        (
            rf"(?:by|until|ending\s+at|ends?\s+at|finish(?:es)?\s+at|達到|达到|到|直到)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,80}}?(?:{PROMPT_DECELERATION_PATTERN_V2}|gap|headway|車距|车距|恢復|恢复|restore)",
            rf"(?:{PROMPT_DECELERATION_PATTERN_V2}|gap|headway|車距|车距)[^.;\n。；]{{0,80}}?(?:by|until|ending\s+at|ends?\s+at|finish(?:es)?\s+at|達到|达到|到|直到)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:到|直到)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}(?:時|时|的時候|的时候)?(?:$|[.;\n。；])",
        ),
    )
    if absolute_time is not None:
        return absolute_time

    duration_s = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:over|for|within|in|持續|持续|花|花費|花费)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,80}}?(?:{PROMPT_DECELERATION_PATTERN_V2}|gap|headway|車距|车距)",
            rf"(?:{PROMPT_DECELERATION_PATTERN_V2}|gap|headway|車距|车距)[^.;\n。；]{{0,80}}?(?:over|for|within|in|持續|持续|花|花費|花费)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
        ),
    )
    if duration_s is not None and start_time_s is not None:
        return start_time_s + duration_s
    return None


def build_deceleration_clarification_message_v2(missing_items: list[str], *, initial_gap_time_s: float | None) -> str:
    initial_gap_label = format_number(initial_gap_time_s) if initial_gap_time_s is not None else "目前"
    missing_text = ", ".join(missing_items)
    return (
        "Prompt needs more detail before generating the scenario.\n"
        f"I detected a deceleration request, but these details are missing or ambiguous: {missing_text}.\n"
        "Please add one clear sentence, for example:\n"
        f"- vehicle one starts slowing at five seconds and the gap closes from {initial_gap_label} seconds to three seconds by twelve seconds\n"
        "- vehicle one starts slowing at five seconds down to forty mph by twelve seconds\n"
        "After the target time, this CLI keeps the new gap by restoring Vehicle 1 to the ego speed."
    )


def apply_deceleration_prompt_v2(
    params: ScenarioParametersV2,
    vehicle_config: VehicleConfigV2,
    prompt_text: str,
    *,
    ego_speed_kmh: float,
    initial_gap_m: float,
    initial_gap_time_s: float | None,
) -> None:
    if not prompt_has_deceleration_intent_v2(prompt_text):
        return

    start_time_s = extract_prompt_deceleration_start_time_s_v2(prompt_text)
    target_gap_time_s = extract_prompt_deceleration_target_gap_time_s_v2(prompt_text)
    target_speed_kmh = extract_prompt_deceleration_target_speed_kmh_v2(prompt_text)
    end_time_s = extract_prompt_deceleration_end_time_s_v2(prompt_text, start_time_s)
    first_lane_event = first_lane_change_event_v2(vehicle_config)
    inferred_from_lane_change = (
        first_lane_event is not None
        and first_lane_event.duration_s > 0
        and prompt_has_lane_change_deceleration_inference_v2(prompt_text)
    )
    completion_gap_time_s = extract_prompt_lane_change_completion_gap_time_s_v2(prompt_text) if inferred_from_lane_change else None
    if inferred_from_lane_change and first_lane_event is not None:
        lane_change_end_s = first_lane_event.time_s + first_lane_event.duration_s
        if completion_gap_time_s is not None:
            start_time_s = first_lane_event.time_s
            end_time_s = lane_change_end_s
            target_gap_time_s = completion_gap_time_s
        elif start_time_s is None:
            start_time_s = first_lane_event.time_s
            if end_time_s is None:
                end_time_s = lane_change_end_s
        if target_gap_time_s is None and target_speed_kmh is None:
            target_gap_time_s = initial_gap_time_s

    missing_items: list[str] = []
    if start_time_s is None:
        missing_items.append("deceleration start time")
    if target_gap_time_s is None and target_speed_kmh is None:
        missing_items.append("target gap seconds or target speed")
    if end_time_s is None:
        missing_items.append("time when the target gap/speed is reached")
    if missing_items:
        raise PromptClarificationError(
            build_deceleration_clarification_message_v2(
                missing_items,
                initial_gap_time_s=initial_gap_time_s,
            )
        )
    if end_time_s <= start_time_s:
        raise PromptClarificationError("Deceleration target time must be later than the deceleration start time.")

    if target_gap_time_s is not None:
        if (
            initial_gap_time_s is not None
            and target_gap_time_s > initial_gap_time_s
            and not math.isclose(target_gap_time_s, initial_gap_time_s, abs_tol=0.001)
        ):
            raise PromptClarificationError(
                "A deceleration request should close the gap. "
                f"Use a target gap smaller than the initial {format_number(initial_gap_time_s)} seconds."
            )
        target_gap_m = kmh_to_mps_v2(ego_speed_kmh) * target_gap_time_s
    else:
        if target_speed_kmh >= ego_speed_kmh:
            raise PromptClarificationError(
                "A deceleration target speed must be lower than the ego speed "
                f"({format_number(ego_speed_kmh)} km/h)."
            )
        target_gap_m = initial_gap_m + ((target_speed_kmh - ego_speed_kmh) / 3.6) * (end_time_s - start_time_s)
        if target_gap_m <= 0:
            raise PromptClarificationError(
                "The requested deceleration closes the gap to zero or less before the target time. "
                "Use a shorter duration, a higher target speed, or a larger initial gap."
            )

    if (
        inferred_from_lane_change
        and target_speed_kmh is None
        and initial_gap_time_s is not None
        and target_gap_time_s is not None
        and math.isclose(target_gap_time_s, initial_gap_time_s, abs_tol=0.001)
        and end_time_s > start_time_s
    ):
        mid_time_s = start_time_s + ((end_time_s - start_time_s) / 2.0)
        default_decel_delta_mps = N_KEY_INTERVENTION_MERGE_ACCEL_DELTA_MPH_V2 * N_KEY_INTERVENTION_MPH_TO_MPS_V2
        mid_gap_m = max(target_gap_m * 0.2, initial_gap_m - (default_decel_delta_mps * (mid_time_s - start_time_s)))
        vehicle_config.gap_points = [
            GapPointV2(time_s=start_time_s, gap_m=initial_gap_m),
            GapPointV2(time_s=mid_time_s, gap_m=mid_gap_m),
            GapPointV2(time_s=end_time_s, gap_m=target_gap_m),
        ]
        return

    vehicle_config.gap_points = [
        GapPointV2(time_s=start_time_s, gap_m=initial_gap_m),
        GapPointV2(time_s=end_time_s, gap_m=target_gap_m),
    ]


def apply_n_key_intervention_prompt_v2(
    params: ScenarioParametersV2,
    prompt_text: str,
    *,
    ego_speed_kmh: float,
) -> None:
    if not prompt_has_n_key_intervention_intent_v2(prompt_text):
        return
    vehicle1 = params.vehicles["front"]
    if first_lane_change_event_v2(vehicle1) is None:
        raise PromptClarificationError(
            "N-key intervention requires vehicle 1 to have a lane change. "
            "Please say when and where vehicle 1 changes lanes."
        )

    config = default_n_key_intervention_config_v2(params)
    window_offsets = extract_prompt_n_key_window_offsets_v2(prompt_text)
    if window_offsets is not None:
        config.window_start_offset_s, config.window_end_offset_s = window_offsets
    speed_delta_mph = extract_prompt_n_key_speed_delta_mph_v2(prompt_text)
    if speed_delta_mph is not None:
        config.ego_speed_delta_mph = speed_delta_mph
    delayed_merge_s = extract_prompt_n_key_delay_s_v2(prompt_text)
    if delayed_merge_s is not None:
        config.delayed_merge_offset_s = delayed_merge_s
    config.merge_target_lane = extract_prompt_n_key_merge_target_lane_v2(prompt_text, config.merge_target_lane)
    merge_speed_delta_mph = extract_prompt_n_key_merge_speed_delta_mph_v2(prompt_text)
    if merge_speed_delta_mph is not None:
        config.merge_speed_delta_mph = merge_speed_delta_mph
    config.restore_ego_speed_kmh = extract_prompt_restore_ego_speed_kmh_v2(prompt_text) or ego_speed_kmh
    params.n_key_intervention = config


def append_scene_note_v2(params: ScenarioParametersV2, note: str) -> None:
    compact_note = re.sub(r"\s+", " ", str(note).strip())
    if compact_note and compact_note not in params.scene_notes:
        params.scene_notes.append(compact_note)


def prompt_has_review_pattern_v2(prompt_text: str, pattern: str) -> bool:
    return re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL) is not None


def extract_review_duration_s_v2(prompt_text: str, subject_pattern: str) -> float | None:
    minute_value = search_prompt_number_v2(
        prompt_text,
        (
            rf"{subject_pattern}[^.;\n。；]{{0,96}}?{{n}}{{u}}{PROMPT_MINUTE_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_MINUTE_UNIT_PATTERN_V2}[^.;\n。；]{{0,96}}?{subject_pattern}",
        ),
    )
    if minute_value is not None:
        return minute_value * 60.0
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"{subject_pattern}[^.;\n。；]{{0,96}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,96}}?{subject_pattern}",
        ),
    )


def extract_review_prompt_cue_time_s_v2(params: ScenarioParametersV2, prompt_text: str) -> float:
    explicit_time_s = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:tor|takeover\s+request|alert|warning|notification|chime|cue|警示|警報|提示|接管)"
            rf"[^.;\n。；]{{0,48}}?(?:at|after|around|time|issued|triggered|發出|发出|啟動|启动|在|於|于)"
            rf"[^.;\n。；]{{0,20}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:at|after|around|在|於|于)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}"
            rf"[^.;\n。；]{{0,80}}?(?:tor|takeover\s+request|alert|warning|notification|chime|cue|警示|警報|提示|接管)",
        ),
    )
    if explicit_time_s is not None:
        return explicit_time_s
    if params.audio_events:
        return params.audio_events[0].time_s
    front_vehicle = params.vehicles.get("front")
    if front_vehicle and first_lane_change_event_v2(front_vehicle) is not None:
        return lane_change_base_time_s_v2(front_vehicle)
    enabled_obstacle_times = [
        obstacle.start_time_s
        for obstacle in list(params.obstacles.values()) + list(params.extra_obstacles)
        if obstacle.enabled
    ]
    if enabled_obstacle_times:
        return min(enabled_obstacle_times)
    return 5.0


def detect_review_tor_direction_v2(prompt_text: str) -> str | None:
    lane_pattern = lane_word_pattern_v2()
    patterns = (
        rf"(?:directional|direction|cue|guide|guidance|指向|方向|引導|引导)"
        rf"[^.;\n。；]{{0,80}}?(?P<lane>{lane_pattern})",
        rf"(?P<lane>{lane_pattern})[^.;\n。；]{{0,40}}?(?:directional|cue|guide|guidance|指向|方向|引導|引导)",
    )
    for pattern in patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL)
        if match:
            lane = lane_from_prompt_fragment_v2(match.group("lane"))
            if lane:
                return lane
    return None


def extract_review_display_message_v2(prompt_text: str) -> str | None:
    patterns = (
        r"(?:text\s+message|message|display(?:ed)?|stating|saying|shows?|showed)"
        r"[^\"“”'‘’\n]{0,64}[\"“'‘](?P<message>[^\"”'’\n]{1,80})[\"”'’]",
        r"(?:文字|訊息|信息|消息|顯示|显示)"
        r"[^\"“”'‘’\n]{0,64}[\"“'‘](?P<message>[^\"”'’\n]{1,80})[\"”'’]",
    )
    for pattern in patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL)
        if match:
            return re.sub(r"\s+", " ", match.group("message").strip())
    return None


def prompt_cue_reference_errors_v2(prompt_text: str) -> list[tuple[int, str]]:
    errors: list[tuple[int, str]] = []
    extension_pattern = r"(?:png|jpe?g|svg|bmp|gif|txt)"
    for line_number, raw_line in enumerate(normalize_cli_prompt_text_v2(prompt_text).splitlines(), start=1):
        line = raw_line.strip()
        if not line:
            continue
        if re.search(r"\.wav\b", line, flags=re.IGNORECASE) and re.search(
            r"\b(?:audio|auditory|sound|chime|beep|tor|alert|cue|warning|file)\b",
            line,
            flags=re.IGNORECASE,
        ):
            for match in re.finditer(r"(?:file\s+)?(?P<file>[A-Za-z0-9_.\-/]+\.wav)\b", line, flags=re.IGNORECASE):
                file_token = match.group("file").strip()
                try:
                    normalize_prompt_auditory_cue_filename_v2(file_token)
                except ValueError as exc:
                    errors.append((line_number, f"{file_token}: {exc}"))
        if re.search(rf"\.({extension_pattern})\b", line, flags=re.IGNORECASE) and re.search(
            r"\b(?:visual|screen|display|hmi|hud|icon|image|text|tor|alert|cue|warning|file)\b",
            line,
            flags=re.IGNORECASE,
        ):
            for match in re.finditer(rf"(?:file\s+)?(?P<file>[A-Za-z0-9_.\-/]+\.{extension_pattern})\b", line, flags=re.IGNORECASE):
                file_token = match.group("file").strip()
                try:
                    normalize_prompt_visual_cue_filename_v2(file_token)
                except ValueError as exc:
                    errors.append((line_number, f"{file_token}: {exc}"))
    return errors


def validate_prompt_cue_file_references_v2(prompt_text: str) -> None:
    errors = prompt_cue_reference_errors_v2(prompt_text)
    if not errors:
        return
    lines = [
        "Prompt cue files must be inside the dedicated cue folders.",
        "",
        "Missing or ambiguous:",
    ]
    lines.extend(f"- line {line_number}: {message}" for line_number, message in errors)
    lines.extend(
        (
            "",
            "Please add files here before selecting or typing them:",
            f"- auditory .wav: {PROMPT_AUDITORY_CUE_DIR_V2}",
            f"- visual cue files: {PROMPT_VISUAL_CUE_DIR_V2}",
        )
    )
    raise PromptClarificationError("\n".join(lines))


def extract_review_audio_events_v2(prompt_text: str) -> list[AudioEventV2]:
    events: list[AudioEventV2] = []
    seen: set[tuple[float, str]] = set()
    for raw_line in normalize_cli_prompt_text_v2(prompt_text).splitlines():
        line = raw_line.strip()
        if not line or not re.search(r"\.wav\b", line, flags=re.IGNORECASE):
            continue
        if not re.search(r"\b(?:audio|auditory|sound|chime|beep|tor|alert|cue|warning)\b|聲音|声音|警示|提示|接管", line, flags=re.IGNORECASE):
            continue
        time_s = prompt_line_sort_time_s_v2(line)
        if time_s is None:
            time_s = search_prompt_number_v2(
                line,
                (
                    r"(?:at|after|around|time|issued|triggered|在|於|于)\s*{n}{u}" + PROMPT_TIME_UNIT_PATTERN_V2,
                    r"{n}{u}" + PROMPT_TIME_UNIT_PATTERN_V2,
                ),
            )
        if time_s is None:
            time_s = 5.0
        for match in re.finditer(r"(?:file\s+)?(?P<file>[A-Za-z0-9_.\-/]+\.wav)\b", line, flags=re.IGNORECASE):
            try:
                file_name = normalize_prompt_auditory_cue_filename_v2(match.group("file").strip())
            except ValueError:
                continue
            key = (float(time_s), file_name)
            if key in seen:
                continue
            seen.add(key)
            events.append(AudioEventV2(time_s=float(time_s), file_name=file_name))
    return events


def extract_review_visual_cues_v2(prompt_text: str) -> list[tuple[float, str]]:
    cues: list[tuple[float, str]] = []
    seen: set[tuple[float, str]] = set()
    extension_pattern = r"(?:png|jpe?g|svg|bmp|gif|txt)"
    for raw_line in normalize_cli_prompt_text_v2(prompt_text).splitlines():
        line = raw_line.strip()
        if not line or not re.search(rf"\.({extension_pattern})\b", line, flags=re.IGNORECASE):
            continue
        if not re.search(r"\b(?:visual|screen|display|hmi|hud|icon|image|text|tor|alert|cue|warning)\b|視覺|视觉|螢幕|屏幕|圖示|图示|警示|提示|接管", line, flags=re.IGNORECASE):
            continue
        time_s = prompt_line_sort_time_s_v2(line)
        if time_s is None:
            time_s = search_prompt_number_v2(
                line,
                (
                    r"(?:at|after|around|time|issued|triggered|在|於|于)\s*{n}{u}" + PROMPT_TIME_UNIT_PATTERN_V2,
                    r"{n}{u}" + PROMPT_TIME_UNIT_PATTERN_V2,
                ),
            )
        if time_s is None:
            time_s = 5.0
        for match in re.finditer(rf"(?:file\s+)?(?P<file>[A-Za-z0-9_.\-/]+\.{extension_pattern})\b", line, flags=re.IGNORECASE):
            try:
                file_name = normalize_prompt_visual_cue_filename_v2(match.group("file").strip())
            except ValueError:
                continue
            key = (float(time_s), file_name)
            if key in seen:
                continue
            seen.add(key)
            cues.append((float(time_s), file_name))
    return cues


def apply_review_tor_prompt_factors_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    text = normalize_cli_prompt_text_v2(prompt_text)
    silent_failure = prompt_has_review_pattern_v2(
        text,
        r"\bsilent\s+failure\b|without\s+(?:a\s+)?(?:tor|takeover\s+request|warning|alert)|"
        r"\bno\s+(?:tor|takeover\s+request|warning|alert|cue)\b|"
        r"沒有(?:\s*)?(?:TOR|接管|提示|警示|警報)|無(?:\s*)?(?:TOR|接管|提示|警示|警報)|"
        r"无(?:\s*)?(?:TOR|接管|提示|警示|警报)",
    )
    if silent_failure:
        params.audio_events = []
        append_scene_note_v2(params, "review_takeover_request=absent_silent_failure")

    has_multimodal = prompt_has_review_pattern_v2(text, r"multi[-\s]?modal|audio[-\s]?visual|auditory[-\s]?visual|多模態|多模态")
    modalities: list[str] = []
    if prompt_has_review_pattern_v2(
        text,
        r"\b(?:auditory|audible|audio|sound|spoken|speech|voice|chime|beep)\b|"
        r"聲音|声音|聽覺|听觉|語音|语音|提示音|警示音|蜂鳴|蜂鸣",
    ):
        modalities.append("auditory")
    if prompt_has_review_pattern_v2(
        text,
        r"\b(?:visual|icon|symbol|hud|hmi|display|text\s+message|on[-\s]?screen|dashboard)\b|"
        r"視覺|视觉|圖示|图示|圖標|图标|螢幕|屏幕|顯示|显示|文字",
    ):
        modalities.append("visual")
    if has_multimodal:
        if "auditory" not in modalities:
            modalities.append("auditory")
        if "visual" not in modalities:
            modalities.append("visual")
        append_scene_note_v2(params, "review_tor_modality_group=multimodal")
    if modalities and not silent_failure:
        append_scene_note_v2(params, f"review_tor_modalities={'+'.join(dict.fromkeys(modalities))}")
    elif not silent_failure and prompt_has_review_pattern_v2(text, r"\b(?:tor|takeover\s+request|alert|warning|cue)\b|\u63a5\u7ba1|\u8b66\u793a|\u63d0\u793a"):
        cue_time_s = extract_review_prompt_cue_time_s_v2(params, text)
        append_scene_note_v2(params, f"review_tor_modality=text_metadata_default@{format_number(cue_time_s)}s")

    if prompt_has_review_pattern_v2(text, r"\b(?:directional|direction|guided|guide)\s+(?:tor|cue|alert)|方向|指向|引導|引导"):
        direction = detect_review_tor_direction_v2(text) or "unspecified"
        append_scene_note_v2(params, f"review_tor_directional_cue={direction}")
    if prompt_has_review_pattern_v2(text, r"\becological\b|environmental\s+cue|contextual\s+cue|情境提示|環境提示|环境提示"):
        append_scene_note_v2(params, "review_tor_style=ecological")
    if prompt_has_review_pattern_v2(text, r"\bgeneric\s+(?:tor|cue|alert|warning)|一般(?:提示|警示)|通用(?:提示|警示)"):
        append_scene_note_v2(params, "review_tor_style=generic")

    display_message = extract_review_display_message_v2(text)
    if display_message:
        append_scene_note_v2(params, f"review_visual_message={display_message}")

    explicit_audio_events = extract_review_audio_events_v2(text)
    if explicit_audio_events and not silent_failure:
        params.audio_events = explicit_audio_events
        append_scene_note_v2(
            params,
            "review_auditory_tor_files="
            + ",".join(f"{format_number(event.time_s)}s:{event.file_name}" for event in explicit_audio_events),
        )

    visual_cues = extract_review_visual_cues_v2(text)
    for cue_index, (time_s, file_name) in enumerate(visual_cues, start=1):
        append_scene_note_v2(params, f"review_visual_tor_file_{cue_index}={format_number(time_s)}s:{file_name}")
    if "visual" in modalities:
        append_scene_note_v2(params, "review_visual_tor=metadata_only")
    if "auditory" in modalities and not silent_failure and not params.audio_events:
        cue_time_s = extract_review_prompt_cue_time_s_v2(params, text)
        direction = detect_review_tor_direction_v2(text)
        file_name = "LCtoLeft_400.wav" if direction == "Left" else "NormalDriveTest_400.wav"
        params.audio_events = [AudioEventV2(time_s=cue_time_s, file_name=file_name)]
        append_scene_note_v2(params, f"review_auditory_tor_file={file_name}")


def apply_review_secondary_task_prompt_factors_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    text = normalize_cli_prompt_text_v2(prompt_text)
    ndrt_present = prompt_has_review_pattern_v2(
        text,
        r"\bndrt\b|non[-\s]?driving\s+related\s+task|secondary\s+task|"
        r"movie\s+clips?|videos?|tablet|smartphone|phone|reading|texting|email|game|sleeping|"
        r"watch(?:ing)?\s+(?:a\s+)?(?:movie|video)|副任務|副任务|非駕駛|非驾驶",
    )
    if not ndrt_present:
        return

    tasks: list[str] = []
    task_patterns = (
        ("n_back", r"\b(?:n[-\s]?back|[12]\s*[-]?\s*back|one[-\s]?back|two[-\s]?back)\b"),
        ("surt", r"\bsurt\b|surrogate\s+reference\s+task"),
        ("tqt", r"\btqt\b|twenty\s+questions?\s+task"),
        ("reading", r"\breading\b|read\s+(?:text|article|message)|閱讀|阅读"),
        ("movie_video", r"movie\s+clips?|videos?|watch(?:ing)?\s+(?:a\s+)?(?:movie|video)|影片|電影|视频|电影"),
        ("typing_texting_email", r"typing|texting|email|message\s+task|打字|簡訊|短信|郵件|邮件"),
        ("game", r"\bgame\b|gaming|遊戲|游戏"),
        ("sleeping", r"sleep(?:ing)?|drowsy\s+state|睡眠|睡覺|睡觉"),
        ("auditory_repeat", r"auditory\s+(?:task|oddball)|repeat(?:ing)?\s+(?:words?|numbers?)|聽覺任務|听觉任务"),
    )
    for key, pattern in task_patterns:
        if prompt_has_review_pattern_v2(text, pattern):
            tasks.append(key)
    append_scene_note_v2(params, "review_ndrt=present")
    if tasks:
        append_scene_note_v2(params, f"review_ndrt_tasks={'+'.join(dict.fromkeys(tasks))}")

    nback_levels: list[str] = []
    for match in re.finditer(r"\b(?P<digit>[12])\s*[-]?\s*back\b|\b(?P<word>one|two)\s*[-]?\s*back\b", text, flags=re.IGNORECASE):
        level = match.group("digit") or {"one": "1", "two": "2"}.get((match.group("word") or "").lower())
        if level and level not in nback_levels:
            nback_levels.append(level)
    if nback_levels:
        append_scene_note_v2(params, f"review_nback_levels={'+'.join(nback_levels)}")

    modalities: list[str] = []
    if any(task in tasks for task in ("surt", "reading", "movie_video", "typing_texting_email", "game")):
        modalities.append("visual")
    if any(task in tasks for task in ("n_back", "tqt")):
        modalities.append("cognitive")
    if any(task in tasks for task in ("surt", "typing_texting_email", "game")):
        modalities.append("motor")
    if "auditory_repeat" in tasks:
        modalities.append("auditory")
    if prompt_has_review_pattern_v2(
        text,
        r"(?:ndrt|secondary\s+task|non[-\s]?driving\s+related\s+task|副任務|副任务)"
        r"[^.;\n。；]{0,48}(?:visual|screen|display|視覺|视觉|螢幕|屏幕)|"
        r"(?:visual|視覺|视觉)[^.;\n。；]{0,24}(?:ndrt|secondary\s+task|副任務|副任务)",
    ):
        modalities.append("visual")
    if prompt_has_review_pattern_v2(
        text,
        r"(?:ndrt|secondary\s+task|non[-\s]?driving\s+related\s+task|副任務|副任务)"
        r"[^.;\n。；]{0,48}(?:cognitive|memory|mental|認知|认知|記憶|记忆)|"
        r"(?:cognitive|認知|认知)[^.;\n。；]{0,24}(?:ndrt|secondary\s+task|副任務|副任务)",
    ):
        modalities.append("cognitive")
    if prompt_has_review_pattern_v2(
        text,
        r"(?:ndrt|secondary\s+task|non[-\s]?driving\s+related\s+task|副任務|副任务)"
        r"[^.;\n。；]{0,48}(?:manual|motoric|typing|touchscreen|手動|手动)|"
        r"(?:manual|motoric|手動|手动)[^.;\n。；]{0,24}(?:ndrt|secondary\s+task|副任務|副任务)",
    ):
        modalities.append("motor")
    if prompt_has_review_pattern_v2(
        text,
        r"(?:ndrt|secondary\s+task|non[-\s]?driving\s+related\s+task|副任務|副任务)"
        r"[^.;\n。；]{0,48}(?:auditory|sound|spoken|聽覺|听觉|聲音|声音)|"
        r"(?:auditory|聽覺|听觉)[^.;\n。；]{0,24}(?:ndrt|secondary\s+task|副任務|副任务)",
    ):
        modalities.append("auditory")
    if modalities:
        append_scene_note_v2(params, f"review_ndrt_modalities={'+'.join(dict.fromkeys(modalities))}")

    if prompt_has_review_pattern_v2(text, r"handheld|held\s+in\s+hand|smartphone|phone|手機|手机|手持"):
        append_scene_note_v2(params, "review_ndrt_device=handheld")
    elif prompt_has_review_pattern_v2(text, r"mounted|tablet|right\s+side\s+of\s+the\s+driver|平板|固定"):
        append_scene_note_v2(params, "review_ndrt_device=mounted_tablet")

    duration_s = extract_review_duration_s_v2(
        text,
        r"(?:ndrt|non[-\s]?driving\s+related\s+task|secondary\s+task|movie\s+clips?|movie|video|task|副任務|副任务)",
    )
    if duration_s is not None:
        append_scene_note_v2(params, f"review_ndrt_duration_s={format_number(duration_s)}")
    if prompt_has_review_pattern_v2(text, r"before\s+(?:the\s+)?(?:tor|takeover)|prior\s+to\s+(?:tor|takeover)|TOR前|接管前"):
        append_scene_note_v2(params, "review_ndrt_timing=before_tor")


def extract_review_traffic_density_v2(prompt_text: str) -> str | None:
    pair_km = search_prompt_number_pair_v2(
        prompt_text,
        (
            rf"{{n1}}\s*(?:and|or|/|vs\.?|versus|或)\s*{{n2}}"
            rf"[^.;\n。；]{{0,32}}?(?:vehicles|cars|oncoming\s+vehicles|車輛|车辆)"
            rf"[^.;\n。；]{{0,24}}?(?:per|/)\s*(?:km|kilometers?|kilometres?|公里)",
        ),
    )
    if pair_km is not None:
        return f"{format_number(pair_km[0])}_or_{format_number(pair_km[1])}_vehicles_per_km"
    km_value = search_prompt_number_v2(
        prompt_text,
        (
            rf"{{n}}{{u}}(?:vehicles|cars|oncoming\s+vehicles|車輛|车辆)"
            rf"[^.;\n。；]{{0,24}}?(?:per|/)\s*(?:km|kilometers?|kilometres?|公里)",
            rf"(?:traffic\s+density|交通密度)[^.;\n。；]{{0,32}}?{{n}}{{u}}"
            rf"(?:vehicles|cars|車輛|车辆)[^.;\n。；]{{0,24}}?(?:per|/)\s*(?:km|kilometers?|kilometres?|公里)",
        ),
    )
    if km_value is not None:
        return f"{format_number(km_value)}_vehicles_per_km"
    mile_value = search_prompt_number_v2(
        prompt_text,
        (
            rf"{{n}}{{u}}(?:vehicles|cars|oncoming\s+vehicles)"
            rf"[^.;\n。；]{{0,24}}?(?:per|/)\s*(?:mile|miles|mi)",
        ),
    )
    if mile_value is not None:
        return f"{format_number(mile_value)}_vehicles_per_mile"
    if prompt_has_review_pattern_v2(prompt_text, r"\bno\s+traffic\b|0\s+(?:vehicles|cars)|無交通|无交通|沒有交通|没有交通"):
        return "none"
    if prompt_has_review_pattern_v2(prompt_text, r"\bheavy\s+traffic\b|dense\s+traffic|traffic\s+density\s+heavy|密集交通|高交通密度"):
        return "heavy"
    return None


def apply_review_environment_prompt_factors_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    text = normalize_cli_prompt_text_v2(prompt_text)
    if prompt_has_review_pattern_v2(text, r"heavy\s+rain|storm|大雨|暴雨"):
        params.rain_level = 0.85
        append_scene_note_v2(params, "review_weather=heavy_rain")
    elif prompt_has_review_pattern_v2(text, r"light\s+rain|drizzle|小雨|毛毛雨"):
        params.rain_level = 0.35
        append_scene_note_v2(params, "review_weather=light_rain")
    elif prompt_has_review_pattern_v2(text, r"\brain(?:y|ing)?\b|雨天|下雨|降雨"):
        params.rain_level = 0.65
        append_scene_note_v2(params, "review_weather=rain")
    elif prompt_has_review_pattern_v2(text, r"\bclear\s+(?:weather|conditions?|highway|road)|(?:weather|conditions?)\s+(?:is\s+)?clear|sunny|dry\s+condition|晴天|無雨|无雨"):
        params.rain_level = 0.0
        append_scene_note_v2(params, "review_weather=clear")
    if prompt_has_review_pattern_v2(text, r"\bfog(?:gy)?\b|霧|雾"):
        append_scene_note_v2(params, "review_weather_detail=fog_metadata_only")
    if prompt_has_review_pattern_v2(text, r"\bsnow(?:y|ing)?\b|冰雪|下雪|雪天"):
        append_scene_note_v2(params, "review_weather_detail=snow_metadata_only")

    road_features: list[str] = []
    road_patterns = (
        ("highway", r"\bhighway\b|freeway|motorway|高速"),
        ("urban", r"\burban\b|city|intersection|市區|市区|城市"),
        ("rural", r"\brural\b|country\s+road|郊區|郊区|鄉村|乡村"),
        ("curve", r"\bcurve\b|curved\s+road|彎道|弯道"),
        ("right_curve", r"right\s+curve|右彎|右弯"),
        ("left_curve", r"left\s+curve|左彎|左弯"),
        ("no_lane_markings", r"no\s+lane\s+markings|missing\s+lane\s+markings|無車道線|无车道线"),
        ("two_lane", r"two[-\s]?lane|2[-\s]?lane|兩車道|两车道"),
        ("three_lane", r"three[-\s]?lane|3[-\s]?lane|三車道|三车道"),
        ("construction_zone", r"construction\s+zone|road\s+construction|work\s+zone|施工區|施工区"),
    )
    for feature, pattern in road_patterns:
        if prompt_has_review_pattern_v2(text, pattern):
            road_features.append(feature)
    if road_features:
        append_scene_note_v2(params, f"review_road_features={'+'.join(dict.fromkeys(road_features))}")

    traffic_density = extract_review_traffic_density_v2(text)
    if traffic_density:
        append_scene_note_v2(params, f"review_traffic_density={traffic_density}")

    escape_paths: list[str] = []
    if prompt_has_review_pattern_v2(text, r"brake[-\s]?only|keep\s+(?:the\s+)?lane|lane[-\s]?keeping|煞車即可|刹车即可|保持車道|保持车道"):
        escape_paths.append("brake_or_lane_keeping")
    if prompt_has_review_pattern_v2(text, r"left\s+(?:lane|path)[^,.;\n。；]{0,32}(?:available|open|safe|most\s+available)|左(?:側)?車道[^，,。；\n]{0,16}(?:可用|安全|空)"):
        escape_paths.append("left_available")
    if prompt_has_review_pattern_v2(text, r"right\s+(?:lane|path)[^,.;\n。；]{0,32}(?:available|open|safe|most\s+available)|右(?:側)?車道[^，,。；\n]{0,16}(?:可用|安全|空)"):
        escape_paths.append("right_available")
    if prompt_has_review_pattern_v2(text, r"left\s+(?:lane|path)[^,.;\n。；]{0,32}(?:blocked|closed|occupied)|左(?:側)?車道[^，,。；\n]{0,16}(?:阻塞|封閉|佔用|占用)"):
        escape_paths.append("left_blocked")
    if prompt_has_review_pattern_v2(text, r"right\s+(?:lane|path)[^,.;\n。；]{0,32}(?:blocked|closed|occupied)|右(?:側)?車道[^，,。；\n]{0,16}(?:阻塞|封閉|佔用|占用)"):
        escape_paths.append("right_blocked")
    if escape_paths:
        append_scene_note_v2(params, f"review_escape_paths={'+'.join(dict.fromkeys(escape_paths))}")


def extract_review_obstacle_distance_m_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:obstacle|hazard|construction|event|障礙|障碍|施工)[^.;\n。；]{{0,80}}?"
            rf"{{n}}{{u}}{PROMPT_METERS_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:ahead|in\s+front|前方)",
            rf"{{n}}{{u}}{PROMPT_METERS_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:ahead|in\s+front|前方)"
            rf"[^.;\n。；]{{0,80}}?(?:obstacle|hazard|construction|event|障礙|障碍|施工)",
        ),
    )


def apply_review_time_budget_prompt_factors_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    text = normalize_cli_prompt_text_v2(prompt_text)
    lead_time_s = extract_takeover_lead_time_s_v2(text)
    if lead_time_s is not None:
        append_scene_note_v2(params, f"review_tor_lead_time_s={format_number(lead_time_s)}")
    ttc_s = search_prompt_number_v2(
        text,
        (
            rf"(?:\bttc\b|time\s+to\s+collision)[^.;\n。；]{{0,48}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:\bttc\b|time\s+to\s+collision)",
        ),
    )
    if ttc_s is not None:
        append_scene_note_v2(params, f"review_ttc_s={format_number(ttc_s)}")
    tlc_s = search_prompt_number_v2(
        text,
        (
            rf"(?:\btlc\b|time\s+to\s+lane\s+crossing)[^.;\n。；]{{0,48}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:\btlc\b|time\s+to\s+lane\s+crossing)",
        ),
    )
    if tlc_s is not None:
        append_scene_note_v2(params, f"review_tlc_s={format_number(tlc_s)}")
    time_headway_s = search_prompt_number_v2(
        text,
        (
            rf"(?:time\s+headway|headway)[^.;\n。；]{{0,40}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:time\s+headway|headway)",
        ),
    )
    if time_headway_s is not None:
        append_scene_note_v2(params, f"review_time_headway_s={format_number(time_headway_s)}")
    obstacle_distance_ft = extract_takeover_obstacle_distance_ft_v2(text)
    if obstacle_distance_ft is not None:
        append_scene_note_v2(params, f"review_obstacle_distance_ft={format_number(obstacle_distance_ft)}")
    obstacle_distance_m = extract_review_obstacle_distance_m_v2(text)
    if obstacle_distance_m is not None:
        append_scene_note_v2(params, f"review_obstacle_distance_m={format_number(obstacle_distance_m)}")
    if prompt_has_review_pattern_v2(text, r"critical\s+event\s+onset|event\s+onset|failure\s+onset|hazard\s+onset|事件開始|事件开始|失效開始|失效开始"):
        append_scene_note_v2(params, "review_event_timing=critical_event_onset_mentioned")


def apply_review_driver_state_prompt_factors_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    text = normalize_cli_prompt_text_v2(prompt_text)
    drive_count = search_prompt_number_v2(
        text,
        (
            r"(?:total\s+of\s+)?{n}{u}(?:drives?|trials?|sessions?)",
            r"(?:drive|trial|session)\s+count[^.;\n。；]{0,24}?{n}",
            r"{n}{u}(?:次|趟)(?:駕駛|驾驶|試驗|试验|實驗|实验)",
        ),
    )
    if drive_count is not None:
        append_scene_note_v2(params, f"review_repeated_exposure_count={format_number(drive_count)}")
    if prompt_has_review_pattern_v2(text, r"initial\s+exposure|reversed\s+exposure|within[-\s]?subjects?|between[-\s]?subjects?|mixed\s+design|counterbalanced|latin\s+square|重複量測|重复量测|拉丁方"):
        append_scene_note_v2(params, "review_experiment_design=mentioned")
    training_duration_s = extract_review_duration_s_v2(text, r"(?:training|practice|practice\s+drive|訓練|训练|練習|练习)")
    if training_duration_s is not None:
        append_scene_note_v2(params, f"review_training_duration_s={format_number(training_duration_s)}")
    elif prompt_has_review_pattern_v2(text, r"training|practice\s+drive|訓練|训练|練習|练习"):
        append_scene_note_v2(params, "review_training=present")

    driver_states: list[str] = []
    state_patterns = (
        ("fatigue_drowsiness", r"fatigue|fatigued|drowsy|sleepy|sleepiness|疲勞|疲劳|嗜睡|睏|困"),
        ("alcohol_bac", r"alcohol|blood\s+alcohol|BAC|酒精|酒駕|酒驾"),
        ("trust", r"\btrust\b|trust\s+level|system\s+trust|信任"),
        ("prior_automation_experience", r"prior\s+(?:automation|av)\s+experience|automation\s+experience|自動駕駛經驗|自动驾驶经验"),
        ("older_driver", r"older\s+(?:adult|driver)|elderly|senior\s+driver|高齡|高龄|年長|年长"),
        ("young_driver", r"young\s+(?:adult|driver)|younger\s+driver|年輕|年轻"),
    )
    for state, pattern in state_patterns:
        if prompt_has_review_pattern_v2(text, pattern):
            driver_states.append(state)
    if driver_states:
        append_scene_note_v2(params, f"review_driver_state={'+'.join(dict.fromkeys(driver_states))}")

    sensors: list[str] = []
    sensor_patterns = (
        ("eye_tracker", r"eye[-\s]?track|gaze|pupil|眼動|眼动|凝視|凝视"),
        ("gsr", r"\bgsr\b|skin\s+conductance|galvanic|皮膚電|皮肤电"),
        ("ppg", r"\bppg\b|photoplethysmography|pulse|脈搏|脉搏"),
        ("heart_rate", r"heart\s+rate|\bhr\b|心率|心跳"),
    )
    for sensor, pattern in sensor_patterns:
        if prompt_has_review_pattern_v2(text, pattern):
            sensors.append(sensor)
    if sensors:
        append_scene_note_v2(params, f"review_driver_sensors={'+'.join(dict.fromkeys(sensors))}")


def apply_review_measure_prompt_factors_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    text = normalize_cli_prompt_text_v2(prompt_text)
    measures: list[str] = []
    measure_patterns = (
        ("takeover_time", r"takeover\s+time|takeover\s+reaction\s+time|reaction\s+time|接管時間|接管时间"),
        ("automation_deactivation_time", r"deactivat(?:e|ion)|automation\s+off|brake\s+to\s+deactivate|解除自動|解除自动"),
        ("hands_on_wheel_time", r"hands?\s+on\s+(?:the\s+)?steering|steering\s+wheel\s+contact|手(?:放|回到).*方向盤|方向盘"),
        ("feet_on_pedal_time", r"feet?\s+on\s+(?:the\s+)?pedals?|pedal\s+contact|腳.*踏板|脚.*踏板"),
        ("gaze_reaction", r"gaze|eyes?\s+on\s+road|glance|mirror\s+gaze|speedometer\s+gaze|凝視|凝视|眼動|眼动"),
        ("ttc", r"\bttc\b|time\s+to\s+collision"),
        ("tlc", r"\btlc\b|time\s+to\s+lane\s+crossing"),
        ("time_headway", r"time\s+headway|headway"),
        ("distance_headway", r"distance\s+headway|following\s+distance|車距|车距"),
        ("lane_position", r"lane\s+position|lane\s+deviation|lane\s+keeping|lateral\s+deviation|車道偏移|车道偏移"),
        ("acceleration", r"acceleration|resulting\s+acceleration|加速度"),
        ("jerk", r"\bjerk\b|jerkiness|急動度|急动度"),
        ("steering_angle", r"steering\s+(?:wheel\s+)?angle|方向盤角度|方向盘角度"),
        ("speed_statistics", r"speed\s+(?:mean|maximum|min(?:imum)?|statistics|profile)|速度統計|速度统计"),
        ("crash_collision", r"crash(?:es)?|collision(?:s)?|accident(?:s)?|碰撞|事故"),
        ("lane_change_error", r"lane\s+change\s+error|wrong\s+lane|lane\s+selection\s+error|錯誤車道|错误车道"),
        ("takeover_quality", r"takeover\s+quality|接管品質|接管质量"),
    )
    for measure, pattern in measure_patterns:
        if prompt_has_review_pattern_v2(text, pattern):
            measures.append(measure)
    if measures:
        append_scene_note_v2(params, f"review_requested_measures={'+'.join(dict.fromkeys(measures))}")


def apply_review_prompt_factors_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    prompt_text = normalize_cli_prompt_text_v2(prompt_text)
    if not prompt_text:
        return
    apply_review_tor_prompt_factors_v2(params, prompt_text)
    apply_review_secondary_task_prompt_factors_v2(params, prompt_text)
    apply_review_environment_prompt_factors_v2(params, prompt_text)
    apply_review_time_budget_prompt_factors_v2(params, prompt_text)
    apply_review_driver_state_prompt_factors_v2(params, prompt_text)
    apply_review_measure_prompt_factors_v2(params, prompt_text)


def prompt_looks_like_takeover_study_v2(prompt_text: str) -> bool:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    signals = (
        r"\bsae\s*level\s*3\b",
        r"conditional\s+automated",
        r"automated\s+vehicle",
        r"takeover\s+(?:request|lead\s*time|study|task|model)",
        r"\btor\b",
        r"subject\s+vehicle",
        r"obstacle",
        r"three-lane|3-lane|三車道|三车道",
    )
    score = sum(1 for pattern in signals if re.search(pattern, text, flags=re.IGNORECASE))
    return score >= 3 and bool(re.search(r"takeover|tor|obstacle|接管|障礙|障碍", text, flags=re.IGNORECASE))


def prompt_contains_takeover_choice_v2(prompt_text: str, *patterns: str) -> bool:
    return any(re.search(pattern, prompt_text, flags=re.IGNORECASE) for pattern in patterns)


def extract_takeover_lead_time_s_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:takeover\s+lead\s+time|tor\s+lead\s+time|lead\s+time)[^.;\n。；]{{0,48}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:takeover\s+lead\s+time|tor\s+lead\s+time|lead\s+time)",
            rf"corresponding\s+to\s+a\s+{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?takeover\s+lead\s+time",
        ),
    )


def extract_takeover_obstacle_distance_ft_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:obstacle|obstacle\s+detection|障礙物|障碍物)[^.;\n。；]{{0,80}}?{{n}}{{u}}{PROMPT_FEET_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:ahead|in\s+front|前方)",
            rf"{{n}}{{u}}{PROMPT_FEET_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:ahead|in\s+front|前方)[^.;\n。；]{{0,80}}?(?:obstacle|obstacle\s+detection|障礙物|障碍物)",
        ),
    )


def extract_takeover_rear_gap_pair_ft_v2(prompt_text: str) -> tuple[float | None, float | None]:
    value = PROMPT_NUMBER_VALUE_PATTERN_V2
    pair_patterns = (
        rf"(?:changed|changes|change|shifted|reduced|closed|拉近|縮短|缩短)[^.;\n。；]{{0,48}}?"
        rf"(?:from|從|从)\s*(?P<initial>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}"
        rf"[^.;\n。；]{{0,32}}?(?:to|到)\s*(?P<closed>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}",
        rf"(?:from|從|从)\s*(?P<initial>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}"
        rf"[^.;\n。；]{{0,48}}?(?:to|到)\s*(?P<closed>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}",
    )
    for pattern in pair_patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL)
        if match:
            return parse_prompt_number_v2(match.group("initial")), parse_prompt_number_v2(match.group("closed"))

    initial = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:followed|following|trailing|separation|behind|後方|后方|跟車|跟车)[^.;\n。；]{{0,60}}?{{n}}{{u}}{PROMPT_FEET_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_FEET_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:separation|behind|trailing|following)",
        ),
    )
    closed = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:close|closes|closed|approach|approaches|changed|reduced|拉近|縮短|缩短)[^.;\n。；]{{0,60}}?{{n}}{{u}}{PROMPT_FEET_UNIT_PATTERN_V2}",
        ),
    )
    return initial, closed


def detect_takeover_rear_close_side_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"(?:generate|make|create|輸出|產生|生成).{0,24}(?:both|two|left\s+and\s+right|兩|两个|兩個)", text):
        return "generate_both"
    if re.search(r"(?:both\s+variants|left\s+and\s+right\s+variants|generate_both)", text):
        return "generate_both"
    if re.search(r"(?:takeover\s+)?variant\s+left|rear\s+close\s+side\s+left|left\s+closes", text):
        return "left"
    if re.search(r"(?:takeover\s+)?variant\s+right|rear\s+close\s+side\s+right|right\s+closes", text):
        return "right"
    if re.search(r"(?:random|randomly|alternating|left-\s*or\s+right|left\s+or\s+right|隨機|随机|交替)", text):
        return None
    left = re.search(r"(?:left(?:-|\s)*lane|left)\s+(?:vehicle\s+)?group[^.;\n。；]{0,60}(?:close|approach|change|拉近|縮短|缩短)", text)
    right = re.search(r"(?:right(?:-|\s)*lane|right)\s+(?:vehicle\s+)?group[^.;\n。；]{0,60}(?:close|approach|change|拉近|縮短|缩短)", text)
    if left and not right:
        return "left"
    if right and not left:
        return "right"
    if re.search(r"(?:left_rear_closes|left\s+rear\s+closes|左側後車|左侧后车)", text):
        return "left"
    if re.search(r"(?:right_rear_closes|right\s+rear\s+closes|右側後車|右侧后车)", text):
        return "right"
    return None


def detect_takeover_obstacle_type_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"disabled[_\s]+(?:vehicle|car)|stopped\s+(?:vehicle|car)|故障車|故障车", text):
        return "disabled_vehicle"
    if re.search(r"barrier|road\s+barrier|護欄|护栏|路障", text):
        return "barrier"
    if re.search(r"\bcone\b|cones|錐|锥", text):
        return "cone"
    if re.search(r"debris|barrel|碎片|雜物|杂物", text):
        return "debris"
    return None


def detect_takeover_cue_implementation_v2(prompt_text: str) -> tuple[str | None, str | None]:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    detected_source = None
    if re.search(r"(?:use|implement|implementation|as|with|cue).{0,24}(?:audio|sound)|audio\s+cue|sound\s+cue|聲音|声音", text):
        return "audio", detected_source
    if re.search(r"(?:visual|marker|hud|onscreen|on-screen|視覺|视觉|標記|标记)", text):
        return "marker", detected_source
    if re.search(r"(?:no\s+cue|none|without\s+(?:cue|tor)|不要提示|無提示|无提示)", text):
        return "none", detected_source
    return None, detected_source


def detect_takeover_ego_response_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"scripted|script\s+ego|auto(?:matic)?\s+lane\s+change|自動變道|自动变道|腳本|脚本", text):
        return "scripted_lane_change"
    if re.search(r"human[_\s]+takeover|manual(?:ly)?|participants?\s+were\s+required|driver\s+takeover|brake\s+to\s+deactivate|人工|手動|手动|駕駛員|驾驶员", text):
        return "human_takeover"
    return None


def detect_takeover_safest_lane_policy_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"infer(?:red)?|opposite\s+(?:of|to)\s+rear|infer_from_rear_close_side|根據後車|根据后车|自動推導|自动推导", text):
        return "infer_from_rear_close_side"
    if re.search(r"safest\s+lane[^.;\n。；]{0,24}left|move\s+into\s+left|change\s+to\s+left|安全車道[^.;\n。；]{0,24}左", text):
        return "left"
    if re.search(r"safest\s+lane[^.;\n。；]{0,24}right|move\s+into\s+right|change\s+to\s+right|安全車道[^.;\n。；]{0,24}右", text):
        return "right"
    if re.search(r"safest\s+lane[^.;\n。；]{0,24}center|return\s+to\s+center|安全車道[^.;\n。；]{0,24}中", text):
        return "middle"
    return None


def detect_takeover_rear_layout_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"(?:total\s+of\s+)?(?:4|four)\s+(?:rear\s+)?vehicles|two\s+pairs|2\s+pairs|四台|四輛|四辆", text):
        return "four_rear_vehicles"
    if re.search(r"(?:two|2)\s+groups|each\s+group\s+includes\s+(?:two|2)\s+vehicles|每組|每组", text):
        return None
    if re.search(r"(?:total\s+of\s+)?(?:2|two)\s+rear\s+vehicles|use\s+(?:2|two)\s+rear\s+vehicles|兩台後車|两台后车|兩輛後車|两辆后车", text):
        return "two_rear_vehicles"
    return None


def format_takeover_detected_value_v2(value: object) -> str:
    if value is None or value == "":
        return "not detected"
    if isinstance(value, float):
        return format_number(value)
    return str(value)


def build_takeover_study_clarification_message_v2(
    *,
    detected: dict[str, object],
    missing_items: list[str],
    implementation_ready: bool,
) -> str:
    detected_lines = "\n".join(
        f"- {label}: {format_takeover_detected_value_v2(value)}" for label, value in detected.items()
    )
    missing_lines = "\n".join(f"- {item}" for item in missing_items)
    example = (
        "Please add one clear instruction line, for example:\n"
        "takeover variant generate both; rear layout four vehicles; obstacle type disabled_vehicle; "
        "cue implementation audio; ego response human_takeover; safest lane infer_from_rear_close_side"
    )
    if not implementation_ready:
        return (
            "Prompt needs more detail before generating this takeover-study scenario.\n\n"
            "Detected:\n"
            f"{detected_lines}\n\n"
            "Missing or ambiguous:\n"
            f"{missing_lines}\n\n"
            f"{example}"
        )
    return (
        "This looks like a takeover-study scenario, not the current simple ego + vehicle 1 scene.\n\n"
        "Detected:\n"
        f"{detected_lines}\n\n"
        "The clarification fields are now clear, but this CLI does not yet implement the multi-actor "
        "takeover-study generator. Add a dedicated takeover preset/builder before generating this scene."
    )


def build_confidence_study_clarification_message_v2(
    *,
    detected: dict[str, object],
    missing_items: list[str],
) -> str:
    detected_lines = "\n".join(
        f"- {label}: {format_takeover_detected_value_v2(value)}" for label, value in detected.items()
    )
    missing_lines = "\n".join(f"- {item}" for item in missing_items)
    return (
        "Prompt needs more detail before generating this confidence-information study scenario.\n\n"
        "Detected:\n"
        f"{detected_lines}\n\n"
        "Missing or ambiguous:\n"
        f"{missing_lines}\n\n"
        "Please add one clear instruction line, for example:\n"
        "participant group both; confidence display metadata; av avoid scripted_lane_change; "
        "avoidance lane Left; road mapping current_3lane_middle; construction distance 400 ft; fixed seed 42"
    )


def validate_takeover_study_prompt_v2(prompt_text: str) -> None:
    prompt_text = normalize_cli_prompt_text_v2(prompt_text)
    if not prompt_looks_like_takeover_study_v2(prompt_text):
        return

    rear_initial_gap_ft, rear_closed_gap_ft = extract_takeover_rear_gap_pair_ft_v2(prompt_text)
    cue_implementation, cue_source = detect_takeover_cue_implementation_v2(prompt_text)
    ego_lane = extract_role_lane_from_prompt_v2(prompt_text, PROMPT_EGO_PATTERN_V2, "")
    ego_speed_kmh = extract_prompt_speed_kmh_v2(prompt_text, 0.0)
    detected = {
        "ego lane": ego_lane or "not detected",
        "ego speed": f"{format_number(ego_speed_kmh)} km/h" if ego_speed_kmh > 0 else "not detected",
        "obstacle distance ahead": (
            f"{format_number(extract_takeover_obstacle_distance_ft_v2(prompt_text))} ft"
            if extract_takeover_obstacle_distance_ft_v2(prompt_text) is not None
            else "not detected"
        ),
        "takeover lead time": (
            f"{format_number(extract_takeover_lead_time_s_v2(prompt_text))} s"
            if extract_takeover_lead_time_s_v2(prompt_text) is not None
            else "not detected"
        ),
        "rear initial gap": f"{format_number(rear_initial_gap_ft)} ft" if rear_initial_gap_ft is not None else "not detected",
        "rear closing gap": f"{format_number(rear_closed_gap_ft)} ft" if rear_closed_gap_ft is not None else "not detected",
        "rear close side / variant": detect_takeover_rear_close_side_v2(prompt_text) or "ambiguous",
        "rear vehicle layout": detect_takeover_rear_layout_v2(prompt_text) or "ambiguous",
        "obstacle type": detect_takeover_obstacle_type_v2(prompt_text) or "ambiguous",
        "takeover cue source": cue_source or "not detected",
        "takeover cue implementation": cue_implementation or "ambiguous",
        "ego response implementation": detect_takeover_ego_response_v2(prompt_text) or "ambiguous",
        "safest lane policy": detect_takeover_safest_lane_policy_v2(prompt_text) or "ambiguous",
    }

    missing_items: list[str] = []
    if not ego_lane:
        missing_items.append("ego lane: choose Left, Middle, or Right")
    if ego_speed_kmh <= 0:
        missing_items.append("ego speed: provide mph or km/h")
    if extract_takeover_obstacle_distance_ft_v2(prompt_text) is None:
        missing_items.append("obstacle distance ahead: provide feet or meters")
    if extract_takeover_lead_time_s_v2(prompt_text) is None:
        missing_items.append("takeover lead time: provide seconds")
    if rear_initial_gap_ft is None or rear_closed_gap_ft is None:
        missing_items.append("rear traffic gap change: provide initial and final gap, for example 150 ft to 40 ft")
    if detect_takeover_rear_close_side_v2(prompt_text) is None:
        missing_items.append("rear close side / variant policy: choose left, right, random, or generate both")
    if detect_takeover_rear_layout_v2(prompt_text) is None:
        missing_items.append("rear vehicle layout: confirm two rear vehicles or four rear vehicles")
    if detect_takeover_obstacle_type_v2(prompt_text) is None:
        missing_items.append("obstacle type: choose disabled_vehicle, barrier, cone, or debris")
    if cue_implementation is None:
        missing_items.append("takeover cue implementation in SCANeR: choose audio, visual marker, none, or custom")
    if detect_takeover_ego_response_v2(prompt_text) is None:
        missing_items.append("ego response implementation: choose human_takeover or scripted_lane_change")
    if detect_takeover_safest_lane_policy_v2(prompt_text) is None:
        missing_items.append("safest lane policy: choose left, right, or infer_from_rear_close_side")

    raise PromptClarificationError(
        build_takeover_study_clarification_message_v2(
            detected=detected,
            missing_items=missing_items or ["dedicated takeover-study generator is not implemented yet"],
            implementation_ready=not missing_items,
        )
    )


def prompt_is_construction_takeover_study_v2(prompt_text: str) -> bool:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    return prompt_looks_like_takeover_study_v2(prompt_text) and bool(
        re.search(r"construction\s+zone|road\s+construction|work\s+zone|施工區|施工区|道路施工", text)
    )


def find_number_options_near_v2(prompt_text: str, patterns: tuple[str, ...]) -> list[float]:
    values: list[float] = []
    for pattern in patterns:
        for match in re.finditer(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL):
            for group_name, value in match.groupdict().items():
                if group_name.startswith("n") and value:
                    try:
                        parsed = parse_prompt_number_v2(value)
                    except ValueError:
                        continue
                    if parsed not in values:
                        values.append(parsed)
    return values


def extract_takeover_lead_time_options_s_v2(prompt_text: str) -> list[float]:
    value = PROMPT_NUMBER_VALUE_PATTERN_V2
    patterns = (
        rf"(?:leading\s+vehicle|lead\s+vehicle|前車|前车)[^.;\n。；]{{0,120}}?(?P<n1>{value})\s*(?:or|/|或)\s*(?P<n2>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,30}}?(?:ahead|lead\s+time|前方)",
        rf"(?P<n1>{value})\s*(?:or|/|或)\s*(?P<n2>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,48}}?(?:lead\s+time|ahead|前方)",
        rf"(?P<n1>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,48}}?(?:lead\s+time|ahead|前方)",
    )
    return find_number_options_near_v2(prompt_text, patterns)


def extract_takeover_obstacle_distance_options_ft_v2(prompt_text: str) -> list[float]:
    value = PROMPT_NUMBER_VALUE_PATTERN_V2
    patterns = (
        rf"(?:obstacle|construction|road\s+construction|施工)[^.;\n。；]{{0,140}}?(?P<n1>{value})\s*(?:or|/|或)\s*(?P<n2>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}[^.;\n。；]{{0,30}}?(?:ahead|前方)",
        rf"(?P<n1>{value})\s*(?:or|/|或)\s*(?P<n2>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}[^.;\n。；]{{0,40}}?(?:ahead|前方)",
        rf"(?P<n1>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}[^.;\n。；]{{0,40}}?(?:ahead|前方)",
    )
    return find_number_options_near_v2(prompt_text, patterns)


def extract_takeover_rear_final_gap_options_ft_v2(prompt_text: str) -> list[float]:
    value = PROMPT_NUMBER_VALUE_PATTERN_V2
    patterns = (
        rf"(?:changed|changes|change|changed\s+from|from|從|从)[^.;\n。；]{{0,80}}?(?:to|到|either)\s*(?P<n1>{value})\s*(?:or|/|或)\s*(?P<n2>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}",
        rf"(?:to|到|either)\s*(?P<n1>{value})\s*(?:or|/|或)\s*(?P<n2>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}",
        rf"(?:to|到)\s*(?P<n1>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_FEET_UNIT_PATTERN_V2}",
    )
    values = find_number_options_near_v2(prompt_text, patterns)
    # Exclude the unchanged initial rear gap when a from X to Y/Z sentence is present.
    rear_initial, _ = extract_takeover_rear_gap_pair_ft_v2(prompt_text)
    return [value for value in values if rear_initial is None or not math.isclose(value, rear_initial, abs_tol=1e-6)]


def detect_takeover_fleet_size_per_side_v2(prompt_text: str) -> int | None:
    value = PROMPT_NUMBER_VALUE_PATTERN_V2
    patterns = (
        rf"(?:fleet\s+size|vehicles?\s+per\s+fleet|vehicles?\s+per\s+side|per\s+lane)\s*(?P<n1>{value})",
        rf"(?P<n1>{value})\s+vehicles?\s+(?:per\s+fleet|per\s+side|per\s+lane)",
        rf"每(?:個|个)?(?:fleet|車隊|车队|側|侧)\s*(?P<n1>{value})\s*(?:台|輛|辆|vehicles?)",
    )
    values = find_number_options_near_v2(prompt_text, patterns)
    return int(values[0]) if values else None


def detect_takeover_signal_selection_v2(prompt_text: str) -> list[int] | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"(?:tor\s+signals?|signal\s+types?|signals?)\s+(?:all|each)|(?:all|generate\s+all)\s+(?:tor\s+)?signals?", text):
        count_match = re.search(r"(?:one\s+of\s+)?(?P<count>[0-9]+|seven|七)\s+signal\s+types?", text)
        count = int(parse_prompt_number_v2(count_match.group("count"))) if count_match else 1
        return list(range(1, max(count, 1) + 1))
    match = re.search(r"(?:tor\s+)?signal(?:\s+type)?\s*(?P<number>[0-9]+|one|two|three|four|five|six|seven|一|二|三|四|五|六|七)", text)
    if match:
        return [int(parse_prompt_number_v2(match.group("number")))]
    return None


def detect_takeover_lead_time_selection_v2(prompt_text: str, options: list[float]) -> list[float] | None:
    if not options:
        return None
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if len(options) == 1 or re.search(r"(?:lead\s+times?|tor\s+lead\s+times?)\s+(?:all|both)|(?:all|both)\s+(?:lead\s+times?|tor\s+lead\s+times?)", text):
        return options
    explicit = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:use|choose|lead\s+time|tor\s+lead\s+time)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
        ),
    )
    if explicit is not None:
        return [min(options, key=lambda value: abs(value - explicit))]
    return options


def detect_takeover_rear_gap_assignment_v2(prompt_text: str, final_options_ft: list[float]) -> tuple[float, float] | None:
    if len(final_options_ft) == 1:
        return final_options_ft[0], final_options_ft[0]
    if len(final_options_ft) < 2:
        return None
    sorted_options = sorted(final_options_ft)
    return sorted_options[0], sorted_options[-1]


def choose_takeover_obstacle_distance_ft_v2(lead_time_s: float, distances_ft: list[float]) -> float:
    if not distances_ft:
        return lead_time_s * 60.0 * 1.4666666667
    return min(distances_ft, key=lambda value: abs(value - (lead_time_s * 60.0 * 1.4666666667)))


def configure_global_construction_takeover_params_v2(
    base_params: ScenarioParametersV2,
    *,
    output_name: str,
    ego_speed_kmh: float,
    lead_time_s: float,
    obstacle_distance_ft: float,
    rear_initial_gap_ft: float,
    blocked_gap_ft: float,
    open_gap_ft: float,
    rear_close_side: str,
    fleet_size_per_side: int,
    signal_id: int,
    cue_implementation: str,
    ego_response: str,
    safest_lane_policy: str,
) -> ScenarioParametersV2:
    params = clone_params_v2(base_params)
    params.output_filename = normalize_output_filename(output_name)
    tor_time_s = 5.0
    rear_transition_s = 1.0
    total_time_s = max(30.0, tor_time_s + lead_time_s + 14.0)
    params.total_experiment_time_s = total_time_s
    params.merge = MergeConfigV2(enabled=False)
    params.n_key_intervention.enabled = False
    params.audio_events = []
    params.extra_obstacles = []

    ego = params.vehicles["ego"]
    ego.enabled = True
    ego.initial_lane = "Middle"
    ego.initial_offset_m = 0.0
    ego.speed_kmh = ego_speed_kmh
    ego.lane_change_enabled = False
    ego.lane_change_target_lane = "Middle"
    ego.stop_enabled = False
    ego.gap_points = []

    lead = params.vehicles["front"]
    lead.enabled = True
    lead.initial_lane = "Middle"
    lead.initial_offset_m = kmh_to_mps_v2(ego_speed_kmh) * lead_time_s
    lead.speed_kmh = ego_speed_kmh
    lead.lane_change_enabled = False
    lead.lane_change_target_lane = "Middle"
    lead.stop_enabled = True
    lead.stop_time_s = tor_time_s
    lead.gap_points = []

    for key in ("rear", "left"):
        vehicle = params.vehicles[key]
        vehicle.enabled = False
        vehicle.stop_enabled = False
        vehicle.lane_change_enabled = False
        vehicle.gap_points = []

    lane_to_safe = {
        "left": "Right",
        "right": "Left",
    }
    if safest_lane_policy == "left":
        safe_lane = "Left"
    elif safest_lane_policy == "right":
        safe_lane = "Right"
    elif safest_lane_policy == "middle":
        safe_lane = "Middle"
    else:
        safe_lane = lane_to_safe.get(rear_close_side, "Left")
    if ego_response == "scripted_lane_change" and safe_lane != "Middle":
        ego.lane_change_enabled = True
        ego.lane_change_time_s = tor_time_s + 2.0
        ego.lane_change_duration_s = 5.0
        ego.lane_change_target_lane = safe_lane

    params.extra_vehicles = []
    base_id = 40
    stagger_m = 12.0
    rear_initial_m = rear_initial_gap_ft * FT_TO_M_V2
    blocked_gap_m = blocked_gap_ft * FT_TO_M_V2
    open_gap_m = open_gap_ft * FT_TO_M_V2
    for lane_name in ("Left", "Right"):
        is_blocked_side = rear_close_side == lane_name.lower()
        target_base_m = blocked_gap_m if is_blocked_side else open_gap_m
        for index in range(fleet_size_per_side):
            initial_offset = -(rear_initial_m + (index * stagger_m))
            target_offset = -(target_base_m + (index * stagger_m))
            vehicle_id = base_id + len(params.extra_vehicles)
            params.extra_vehicles.append(
                VehicleConfigV2(
                    key=f"fleet_{lane_name.lower()}_{index + 1}",
                    label=f"{lane_name} Fleet Vehicle {index + 1}",
                    name=f"{HF_ACTOR_PREFIX}FLEET_{lane_name.upper()}_{index + 1}",
                    vehicle_id=vehicle_id,
                    initial_offset_m=initial_offset,
                    initial_lane=lane_name,
                    speed_kmh=ego_speed_kmh,
                    lane_change_enabled=False,
                    lane_change_time_s=0.0,
                    lane_change_target_lane=lane_name,
                    stop_enabled=False,
                    stop_time_s=total_time_s,
                    gap_points=[
                        GapPointV2(time_s=tor_time_s, gap_m=initial_offset),
                        GapPointV2(time_s=tor_time_s + rear_transition_s, gap_m=target_offset),
                    ],
                    enabled=True,
                )
            )

    for pedestrian in params.pedestrians.values():
        pedestrian.enabled = False
    for obstacle in params.obstacles.values():
        obstacle.enabled = False
    obstacle = params.obstacles["obstacle_1"]
    obstacle.enabled = True
    obstacle.kind = "Barrier"
    obstacle.lane = "Middle"
    obstacle.gap_m = obstacle_distance_ft * FT_TO_M_V2
    obstacle.lateral_offset_m = 0.0
    obstacle.start_time_s = tor_time_s
    obstacle.end_time_s = total_time_s
    obstacle.model_name = OBSTACLE_MODEL_BY_KIND_V2["Barrier"]
    obstacle.world_locked = False
    obstacle.lock_time_s = 0.0

    if cue_implementation == "audio":
        audio_file = "LCtoLeft_400.wav" if signal_id % 2 else "NormalDriveTest_400.wav"
        params.audio_events = [AudioEventV2(time_s=tor_time_s, file_name=audio_file)]
    return params


def build_global_construction_takeover_scenarios_v2(
    base_params: ScenarioParametersV2,
    prompt_text: str,
    *,
    explicit_output: bool,
    requested_output: str,
) -> list[ScenarioParametersV2] | None:
    if not prompt_is_construction_takeover_study_v2(prompt_text):
        return None

    ego_lane = extract_role_lane_from_prompt_v2(prompt_text, PROMPT_EGO_PATTERN_V2, "")
    ego_speed_kmh = extract_prompt_speed_kmh_v2(prompt_text, 0.0)
    lead_time_options = extract_takeover_lead_time_options_s_v2(prompt_text)
    selected_lead_times = detect_takeover_lead_time_selection_v2(prompt_text, lead_time_options)
    obstacle_distances_ft = extract_takeover_obstacle_distance_options_ft_v2(prompt_text)
    rear_initial_gap_ft, _ = extract_takeover_rear_gap_pair_ft_v2(prompt_text)
    final_gap_options_ft = extract_takeover_rear_final_gap_options_ft_v2(prompt_text)
    final_gap_pair = detect_takeover_rear_gap_assignment_v2(prompt_text, final_gap_options_ft)
    rear_close_side = detect_takeover_rear_close_side_v2(prompt_text)
    fleet_size_per_side = detect_takeover_fleet_size_per_side_v2(prompt_text)
    cue_implementation, cue_source = detect_takeover_cue_implementation_v2(prompt_text)
    ego_response = detect_takeover_ego_response_v2(prompt_text)
    safest_lane_policy = detect_takeover_safest_lane_policy_v2(prompt_text)
    signal_selection = detect_takeover_signal_selection_v2(prompt_text)

    detected = {
        "scene route": "global construction-zone takeover",
        "ego lane": ego_lane or "not detected",
        "ego speed": f"{format_number(ego_speed_kmh)} km/h" if ego_speed_kmh > 0 else "not detected",
        "lead time options": ", ".join(format_number(value) + " s" for value in lead_time_options) or "not detected",
        "obstacle distance options": ", ".join(format_number(value) + " ft" for value in obstacle_distances_ft) or "not detected",
        "rear initial gap": f"{format_number(rear_initial_gap_ft)} ft" if rear_initial_gap_ft is not None else "not detected",
        "rear final gap options": ", ".join(format_number(value) + " ft" for value in final_gap_options_ft) or "not detected",
        "rear close side / variant": rear_close_side or "ambiguous",
        "fleet size per side": fleet_size_per_side or "ambiguous",
        "takeover cue source": cue_source or "not detected",
        "takeover cue implementation": cue_implementation or "ambiguous",
        "ego response implementation": ego_response or "ambiguous",
        "safest lane policy": safest_lane_policy or "ambiguous",
        "TOR signal selection": ",".join(str(value) for value in signal_selection) if signal_selection else "ambiguous",
    }
    missing_items: list[str] = []
    if ego_lane != "Middle":
        missing_items.append("ego lane must be detectable as Middle for this construction-zone takeover builder")
    if ego_speed_kmh <= 0:
        missing_items.append("ego speed: provide mph or km/h")
    if not selected_lead_times:
        missing_items.append("lead time variants: provide 4 s, 7 s, or both")
    if not obstacle_distances_ft:
        missing_items.append("obstacle distance options: provide feet ahead, for example 352 ft or 616 ft")
    if rear_initial_gap_ft is None:
        missing_items.append("rear initial fleet gap: provide feet, for example 176 ft")
    if final_gap_pair is None:
        missing_items.append("rear final gap options: provide the blocked/open distances, for example 88 ft and 264 ft")
    if rear_close_side not in {"left", "right", "generate_both"}:
        missing_items.append("rear close side / variant policy: choose left, right, or generate both")
    if fleet_size_per_side is None or fleet_size_per_side <= 0:
        missing_items.append("fleet size per side: provide a positive number, for example fleet size 2")
    if cue_implementation not in {"audio", "marker", "none"}:
        missing_items.append("takeover cue implementation in SCANeR: choose audio, marker, or none")
    if ego_response not in {"human_takeover", "scripted_lane_change"}:
        missing_items.append("ego response implementation: choose human_takeover or scripted_lane_change")
    if safest_lane_policy not in {"left", "right", "middle", "infer_from_rear_close_side"}:
        missing_items.append("safest lane policy: choose left, right, middle, or infer_from_rear_close_side")
    if not signal_selection:
        missing_items.append("TOR signal selection: choose signal 1, signal 2, etc., or TOR signals all")
    if missing_items:
        raise PromptClarificationError(
            build_takeover_study_clarification_message_v2(
                detected=detected,
                missing_items=missing_items,
                implementation_ready=False,
            )
        )

    blocked_gap_ft, open_gap_ft = final_gap_pair
    rear_sides = ("left", "right") if rear_close_side == "generate_both" else (rear_close_side,)
    params_list: list[ScenarioParametersV2] = []
    for lead_time_s in selected_lead_times:
        obstacle_distance_ft = choose_takeover_obstacle_distance_ft_v2(lead_time_s, obstacle_distances_ft)
        for side in rear_sides:
            for signal_id in signal_selection:
                output_base = Path(normalize_output_filename(requested_output)).stem if explicit_output else (
                    f"HF_GLOBAL_TOR_CONSTRUCTION_{filename_number_token_v2(lead_time_s)}S_"
                    f"{side.upper()}_CLOSES_SIGNAL_{signal_id}"
                )
                if explicit_output and (len(selected_lead_times) > 1 or len(rear_sides) > 1 or len(signal_selection) > 1):
                    output_base = (
                        f"{output_base}_{filename_number_token_v2(lead_time_s)}S_"
                        f"{side.upper()}_CLOSES_SIGNAL_{signal_id}"
                    )
                params_list.append(
                    configure_global_construction_takeover_params_v2(
                        base_params,
                        output_name=f"{output_base}.sce",
                        ego_speed_kmh=ego_speed_kmh,
                        lead_time_s=lead_time_s,
                        obstacle_distance_ft=obstacle_distance_ft,
                        rear_initial_gap_ft=rear_initial_gap_ft,
                        blocked_gap_ft=blocked_gap_ft,
                        open_gap_ft=open_gap_ft,
                        rear_close_side=side,
                        fleet_size_per_side=fleet_size_per_side,
                        signal_id=signal_id,
                        cue_implementation=cue_implementation,
                        ego_response=ego_response,
                        safest_lane_policy=safest_lane_policy,
                    )
                )
    return params_list


def prompt_is_confidence_takeover_study_v2(prompt_text: str) -> bool:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    return bool(
        re.search(r"\bconfidence\b|confidence\s+information|self-assessed|hmi\s+display|reliability|accurate\s+information|inaccurate\s+information", text)
        and re.search(r"construction\s+zone|obstacle|tor|takeover|sae\s*level\s*3|automated\s+vehicle", text)
    )


def extract_confidence_drive_count_v2(prompt_text: str) -> int | None:
    value = search_prompt_number_v2(
        prompt_text,
        (
            r"(?:total\s+of|experienced|comprised|included)[^.;\n。；]{0,24}?{n}\s+drives?",
            r"{n}\s+drives?",
        ),
    )
    return int(value) if value is not None else None


def extract_confidence_alert_time_s_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:initial|first)[^.;\n。；]{{0,24}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:after|following)[^.;\n。；]{{0,24}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:initial|autonomous|obstacle\s+detection|alert)",
        ),
    )


def extract_confidence_trend_duration_s_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:confidence\s+)?trend\s+duration[^.;\n。；]{{0,24}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:trend|confidence\s+display|exhibited)[^.;\n。；]{{0,48}}?(?:for|over)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:for|over)\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,48}}?(?:trend|confidence)",
        ),
    )


def extract_confidence_obstacle_distance_ft_v2(prompt_text: str) -> float | None:
    value = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:construction\s+distance|construction\s+zone\s+distance|obstacle\s+distance)[^.;\n。；]{{0,24}}?{{n}}{{u}}{PROMPT_FEET_UNIT_PATTERN_V2}",
            rf"(?:construction\s+zone|obstacle)[^.;\n。；]{{0,80}}?{{n}}{{u}}{PROMPT_FEET_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:ahead|前方)",
            rf"{{n}}{{u}}{PROMPT_FEET_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:ahead|前方)[^.;\n。；]{{0,80}}?(?:construction\s+zone|obstacle)",
        ),
    )
    return value


def detect_confidence_participant_groups_v2(prompt_text: str) -> tuple[str, ...] | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"participant\s+group\s+both|groups?\s+both|generate\s+both\s+groups|both\s+participant\s+groups|兩組|两组", text):
        return ("accurate", "inaccurate")
    if re.search(r"participant\s+group\s+accurate|accurate\s+information\s+group\s+only|group\s+accurate", text):
        return ("accurate",)
    if re.search(r"participant\s+group\s+inaccurate|inaccurate\s+information\s+group\s+only|group\s+inaccurate", text):
        return ("inaccurate",)
    return None


def detect_confidence_hmi_implementation_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"confidence\s+(?:display|hmi)\s+metadata|hmi\s+metadata|metadata_only|metadata-only|metadata\s+only", text):
        return "metadata_only"
    if re.search(r"confidence\s+(?:display|hmi)\s+standalone|hmi\s+script|standalone_python", text):
        return "standalone_python"
    if re.search(r"confidence\s+(?:display|hmi)|visual\s+hmi|middle\s+monitor", text):
        return None
    return None


def detect_confidence_av_behavior_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"av\s+avoid(?:ance)?\s+scripted_lane_change|can\s+avoid\s+scripted|scripted_lane_change|scripted\s+lane\s+change", text):
        return "scripted_lane_change"
    if re.search(r"av\s+avoid(?:ance)?\s+metadata|metadata\s+only", text):
        return "metadata_only"
    return None


def detect_confidence_avoidance_lane_v2(prompt_text: str) -> str | None:
    match = re.search(r"(?:avoidance\s+lane|av\s+avoid\s+lane|避讓車道|避让车道)\s*(?P<lane>left|right|middle|左|右|中)", prompt_text, flags=re.IGNORECASE)
    if not match:
        return None
    return lane_from_prompt_fragment_v2(match.group("lane"))


def detect_confidence_road_mapping_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"road\s+mapping\s+current_3lane_middle|current\s+3-lane|current\s+three-lane|use\s+current\s+map|use\s+middle\s+lane", text):
        return "current_3lane_middle"
    if re.search(r"road\s+mapping\s+two_lane|two-lane\s+native|two\s+lane\s+native", text):
        return "two_lane_native"
    return None


def detect_confidence_order_policy_v2(prompt_text: str) -> tuple[str, int | None]:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    seed_match = re.search(r"(?:fixed\s+seed|seed)\s*(?P<number>[0-9]+)", text)
    if seed_match:
        return "fixed_seed", int(seed_match.group("number"))
    if re.search(r"table_order|table\s+order|unrandomized|not\s+randomized", text):
        return "table_order", None
    if re.search(r"randomized|randomised|randomize|randomise", text):
        return "fixed_seed", 42
    return "table_order", None


def confidence_drive_plan_v2(group: str) -> list[dict[str, object]]:
    if group == "accurate":
        initial = [
            {"phase": "initial", "can_avoid": True, "trend": "increasing", "accuracy": "accurate"}
            for _ in range(5)
        ] + [{"phase": "initial", "can_avoid": False, "trend": "decreasing", "accuracy": "accurate"}]
        reversed_phase = [
            {"phase": "reversed", "can_avoid": True, "trend": "increasing", "accuracy": "accurate"}
            for _ in range(4)
        ] + [
            {"phase": "reversed", "can_avoid": True, "trend": "decreasing", "accuracy": "inaccurate"},
            {"phase": "reversed", "can_avoid": False, "trend": "increasing", "accuracy": "inaccurate"},
        ]
        return initial + reversed_phase
    initial = [
        {"phase": "initial", "can_avoid": True, "trend": "decreasing", "accuracy": "inaccurate"}
        for _ in range(5)
    ] + [{"phase": "initial", "can_avoid": False, "trend": "increasing", "accuracy": "inaccurate"}]
    reversed_phase = [
        {"phase": "reversed", "can_avoid": True, "trend": "decreasing", "accuracy": "inaccurate"}
        for _ in range(4)
    ] + [
        {"phase": "reversed", "can_avoid": True, "trend": "increasing", "accuracy": "accurate"},
        {"phase": "reversed", "can_avoid": False, "trend": "decreasing", "accuracy": "accurate"},
    ]
    return initial + reversed_phase


def ordered_confidence_drive_plan_v2(group: str, order_policy: str, seed: int | None) -> list[dict[str, object]]:
    plan = confidence_drive_plan_v2(group)
    if order_policy != "fixed_seed":
        for index, item in enumerate(plan, start=1):
            item["drive"] = index
        return plan
    rng = random.Random((seed or 42) + (0 if group == "accurate" else 1000))
    output: list[dict[str, object]] = []
    for phase_name, start_index in (("initial", 1), ("reversed", 7)):
        phase_items = [item for item in plan if item["phase"] == phase_name]
        rng.shuffle(phase_items)
        for offset, item in enumerate(phase_items):
            item["drive"] = start_index + offset
            output.append(item)
    return sorted(output, key=lambda item: int(item["drive"]))


def configure_global_confidence_takeover_params_v2(
    base_params: ScenarioParametersV2,
    *,
    output_name: str,
    ego_speed_kmh: float,
    alert_time_s: float,
    trend_duration_s: float,
    obstacle_distance_ft: float,
    group: str,
    drive_info: dict[str, object],
    hmi_implementation: str,
    av_behavior: str,
    avoidance_lane: str,
    road_mapping: str,
) -> ScenarioParametersV2:
    params = clone_params_v2(base_params)
    params.output_filename = normalize_output_filename(output_name)
    params.total_experiment_time_s = max(120.0, alert_time_s + trend_duration_s + 30.0)
    params.merge = MergeConfigV2(enabled=False)
    params.n_key_intervention.enabled = False
    params.extra_vehicles = []
    params.extra_obstacles = []
    params.rain_level = 0.65

    ego = params.vehicles["ego"]
    ego.enabled = True
    ego.initial_lane = "Middle"
    ego.initial_offset_m = 0.0
    ego.speed_kmh = ego_speed_kmh
    ego.lane_change_enabled = False
    ego.lane_change_target_lane = "Middle"
    ego.stop_enabled = False
    ego.gap_points = []
    if bool(drive_info["can_avoid"]) and av_behavior == "scripted_lane_change" and avoidance_lane != "Middle":
        ego.lane_change_enabled = True
        ego.lane_change_time_s = alert_time_s + 4.0
        ego.lane_change_duration_s = 5.0
        ego.lane_change_target_lane = avoidance_lane

    for key in ("front", "rear", "left"):
        vehicle = params.vehicles[key]
        vehicle.enabled = False
        vehicle.lane_change_enabled = False
        vehicle.stop_enabled = False
        vehicle.gap_points = []
    for pedestrian in params.pedestrians.values():
        pedestrian.enabled = False
    for obstacle in params.obstacles.values():
        obstacle.enabled = False

    obstacle = params.obstacles["obstacle_1"]
    obstacle.enabled = True
    obstacle.kind = "Barrier"
    obstacle.lane = "Middle"
    obstacle.gap_m = obstacle_distance_ft * FT_TO_M_V2
    obstacle.lateral_offset_m = 0.0
    obstacle.start_time_s = alert_time_s
    obstacle.end_time_s = params.total_experiment_time_s
    obstacle.model_name = OBSTACLE_MODEL_BY_KIND_V2["Barrier"]
    obstacle.world_locked = False
    obstacle.lock_time_s = 0.0

    params.audio_events = [AudioEventV2(time_s=alert_time_s, file_name="NormalDriveTest_400.wav")]
    params.scene_notes = [
        "global_route=confidence_takeover_study",
        f"participant_group={group}",
        f"drive={drive_info['drive']}",
        f"phase={drive_info['phase']}",
        f"av_reliability={'can_avoid' if drive_info['can_avoid'] else 'cannot_avoid'}",
        f"confidence_trend={drive_info['trend']}",
        f"information_accuracy={drive_info['accuracy']}",
        f"confidence_initial=85-90pct",
        f"confidence_post_alert={'60-85pct' if drive_info['trend'] == 'increasing' else '85-60pct'}",
        f"confidence_trend_duration_s={format_number(trend_duration_s)}",
        f"alert_text=obstacle detected",
        f"hmi_implementation={hmi_implementation}",
        f"av_behavior={av_behavior}",
        f"avoidance_lane={avoidance_lane}",
        f"road_mapping={road_mapping}",
    ]
    return params


def build_global_confidence_takeover_scenarios_v2(
    base_params: ScenarioParametersV2,
    prompt_text: str,
    *,
    explicit_output: bool,
    requested_output: str,
) -> list[ScenarioParametersV2] | None:
    if not prompt_is_confidence_takeover_study_v2(prompt_text):
        return None

    ego_speed_kmh = extract_prompt_speed_kmh_v2(prompt_text, 0.0)
    drive_count = extract_confidence_drive_count_v2(prompt_text)
    alert_time_s = extract_confidence_alert_time_s_v2(prompt_text)
    trend_duration_s = extract_confidence_trend_duration_s_v2(prompt_text)
    obstacle_distance_ft = extract_confidence_obstacle_distance_ft_v2(prompt_text)
    groups = detect_confidence_participant_groups_v2(prompt_text)
    hmi_implementation = detect_confidence_hmi_implementation_v2(prompt_text)
    av_behavior = detect_confidence_av_behavior_v2(prompt_text)
    avoidance_lane = detect_confidence_avoidance_lane_v2(prompt_text)
    road_mapping = detect_confidence_road_mapping_v2(prompt_text)
    order_policy, seed = detect_confidence_order_policy_v2(prompt_text)

    detected = {
        "scene route": "global confidence takeover study",
        "drive count": drive_count or "not detected",
        "ego speed": f"{format_number(ego_speed_kmh)} km/h" if ego_speed_kmh > 0 else "not detected",
        "weather": "rainy" if re.search(r"rainy|rain|雨", prompt_text, flags=re.IGNORECASE) else "not detected",
        "automation duration / alert time": f"{format_number(alert_time_s)} s" if alert_time_s is not None else "not detected",
        "confidence trend duration": f"{format_number(trend_duration_s)} s" if trend_duration_s is not None else "not detected",
        "construction distance ahead": f"{format_number(obstacle_distance_ft)} ft" if obstacle_distance_ft is not None else "ambiguous",
        "participant groups": ",".join(groups) if groups else "ambiguous",
        "HMI implementation": hmi_implementation or "ambiguous",
        "AV avoid behavior": av_behavior or "ambiguous",
        "avoidance lane": avoidance_lane or "ambiguous",
        "road mapping": road_mapping or "ambiguous",
        "drive order": f"{order_policy}{':' + str(seed) if seed is not None else ''}",
    }
    missing_items: list[str] = []
    if drive_count != 12:
        missing_items.append("drive count: confirm 12 drives")
    if ego_speed_kmh <= 0:
        missing_items.append("ego speed: provide mph or km/h")
    if alert_time_s is None:
        missing_items.append("automation duration / alert time: provide seconds, for example initial 60 s")
    if trend_duration_s is None:
        missing_items.append("confidence trend duration: provide seconds, for example 15 s")
    if obstacle_distance_ft is None:
        missing_items.append("construction zone distance ahead at alert: provide feet, for example construction distance 400 ft")
    if groups is None:
        missing_items.append("participant group selection: choose participant group accurate, inaccurate, or both")
    if hmi_implementation == "standalone_python":
        missing_items.append("confidence HMI implementation: standalone_python is not wired to SCANeR output yet; choose confidence display metadata")
    elif hmi_implementation != "metadata_only":
        missing_items.append("confidence HMI implementation: choose confidence display metadata")
    if av_behavior not in {"scripted_lane_change", "metadata_only"}:
        missing_items.append("AV can-avoid behavior: choose av avoid scripted_lane_change or metadata_only")
    if avoidance_lane not in LANE_NAMES_V2:
        missing_items.append("avoidance lane: choose Left, Middle, or Right")
    if road_mapping != "current_3lane_middle":
        missing_items.append("road mapping: use road mapping current_3lane_middle for the current SCANeR template")
    if missing_items:
        raise PromptClarificationError(
            build_confidence_study_clarification_message_v2(
                detected=detected,
                missing_items=missing_items,
            )
        )

    params_list: list[ScenarioParametersV2] = []
    for group in groups:
        for drive_info in ordered_confidence_drive_plan_v2(group, order_policy, seed):
            drive_number = int(drive_info["drive"])
            output_base = Path(normalize_output_filename(requested_output)).stem if explicit_output else (
                f"HF_GLOBAL_CONF_{group.upper()}_DRIVE_{drive_number:02d}_"
                f"{'CAN' if drive_info['can_avoid'] else 'CANNOT'}_"
                f"{str(drive_info['trend']).upper()}_{str(drive_info['accuracy']).upper()}"
            )
            if explicit_output and (len(groups) > 1 or drive_count > 1):
                output_base = f"{output_base}_{group.upper()}_DRIVE_{drive_number:02d}"
            params_list.append(
                configure_global_confidence_takeover_params_v2(
                    base_params,
                    output_name=f"{output_base}.sce",
                    ego_speed_kmh=ego_speed_kmh,
                    alert_time_s=alert_time_s,
                    trend_duration_s=trend_duration_s,
                    obstacle_distance_ft=obstacle_distance_ft,
                    group=group,
                    drive_info=drive_info,
                    hmi_implementation=hmi_implementation,
                    av_behavior=av_behavior,
                    avoidance_lane=avoidance_lane,
                    road_mapping=road_mapping,
                )
            )
    return params_list


EMOTION_TAKEOVER_EVENT_META_V2: dict[str, dict[str, str]] = {
    "construction_zone": {
        "label": "Construction Zone Ahead",
        "environment": "Urban",
        "asset_note": "barrier asset for construction zone",
    },
    "bicyclist": {
        "label": "Bicyclist In Lane Ahead",
        "environment": "Urban",
        "asset_note": "SCANeR digital vehicle Bicycle_Man01",
    },
    "police_vehicle": {
        "label": "Police Vehicle On Shoulder",
        "environment": "Rural",
        "asset_note": "SCANeR digital vehicle Renault_Megane3_Police on right shoulder",
    },
    "swerving_vehicle": {
        "label": "Swerving Vehicle Ahead",
        "environment": "Rural",
        "asset_note": "scripted lead vehicle lane change proxy",
    },
}
EMOTION_TAKEOVER_EVENT_ORDER_V2 = tuple(EMOTION_TAKEOVER_EVENT_META_V2)


def prompt_is_emotion_takeover_study_v2(prompt_text: str) -> bool:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    emotion_design = re.search(
        r"emotion\s+induction|valence|arousal|movie\s+clips?|self-assessment\s+manikin|\bsam\b|latin\s+square",
        text,
    )
    takeover_design = re.search(r"takeover\s+events?|takeover\s+request|\btor\b|takeover transitions?", text)
    event_terms = re.search(r"bicyclist|police\s+vehicle|swerving\s+vehicle|construction\s+zone", text)
    return bool(emotion_design and takeover_design and event_terms)


def extract_emotion_takeover_event_count_v2(prompt_text: str) -> int | None:
    number_token = (
        r"\d+(?:\.\d+)?|zero|one|two|three|four|five|six|seven|eight|nine|ten|"
        r"eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|"
        r"twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|"
        r"[零一二三四五六七八九十百千兩两]+"
    )
    patterns = (
        rf"\b(?P<number>{number_token})\s+takeover\s+events?",
        rf"(?:takeover\s+event\s+count|number\s+of\s+takeover\s+events?|total\s+takeover\s+events?)\s*(?P<number>{number_token})",
    )
    for pattern in patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL)
        if match:
            try:
                return int(parse_prompt_number_v2(match.group("number")))
            except ValueError:
                continue
    return None


def extract_emotion_movie_duration_s_v2(prompt_text: str) -> float | None:
    minute_unit = r"(?:min\b|mins\b|minute\b|minutes\b)"
    value = search_prompt_number_v2(
        prompt_text,
        (
            rf"{{n}}\s*(?:-|to\s+)?\s*{minute_unit}\s+movie\s+clips?",
            rf"movie\s+clips?[^.;\n。；]{{0,32}}?{{n}}\s*(?:-|to\s+)?\s*{minute_unit}",
            rf"emotion\s+induction[^.;\n。；]{{0,64}}?{{n}}\s*(?:-|to\s+)?\s*{minute_unit}",
        ),
    )
    return value * 60.0 if value is not None else None


def extract_emotion_tor_lead_time_s_v2(prompt_text: str) -> float | None:
    value = search_prompt_number_v2(
        prompt_text,
        (
            rf"\btor\b[^.;\n。；]{{0,96}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:away|before|lead\s+time)",
            rf"takeover\s+request[^.;\n。；]{{0,96}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:away|before|lead\s+time)",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:away\s+from|before)[^.;\n。；]{{0,96}}?(?:construction\s+zone|bicyclist|police\s+vehicle|swerving\s+vehicle)",
        ),
    )
    return value


def detect_emotion_av_lane_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    match = re.search(
        r"(?:av|automated\s+vehicle|vehicle|ego)[^.;\n。；]{0,96}?(?:drove|drives|travel(?:ed)?|was|is)[^.;\n。；]{0,48}?\b(?P<lane>left|middle|right)\s+lane",
        text,
    )
    if match:
        return lane_from_prompt_fragment_v2(match.group("lane"))
    return None


def detect_emotion_study_target_lane_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    match = re.search(
        r"(?:change|move|merge)[^.;\n。；]{0,48}?(?:to|into)\s+the\s+(?P<lane>left|middle|right)\s+lane",
        text,
    )
    if match:
        return lane_from_prompt_fragment_v2(match.group("lane"))
    match = re.search(r"(?:target|expected)\s+lane\s*(?P<lane>left|middle|right)", text)
    if match:
        return lane_from_prompt_fragment_v2(match.group("lane"))
    return None


def detect_emotion_takeover_events_v2(prompt_text: str) -> tuple[str, ...]:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    events: list[str] = []
    if re.search(r"construction\s+zone", text):
        events.append("construction_zone")
    if re.search(r"bicyclist|cyclist|bike|bicycle", text):
        events.append("bicyclist")
    if re.search(r"police\s+vehicle|police\s+car", text):
        events.append("police_vehicle")
    if re.search(r"swerving\s+vehicle|swerve", text):
        events.append("swerving_vehicle")
    if re.search(r"event\s+selection\s+all|takeover\s+events?\s+all|generate\s+all\s+events", text):
        return EMOTION_TAKEOVER_EVENT_ORDER_V2
    return tuple(event for event in EMOTION_TAKEOVER_EVENT_ORDER_V2 if event in events)


def detect_emotion_tor_cue_implementation_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"tor\s+cue\s+none|no\s+tor|without\s+tor", text):
        return "none"
    has_audio = bool(re.search(r"auditory|audible|spoken|sound|audio|phrase\s+['\"]?takeover|聲音|声音", text))
    has_visual = bool(re.search(r"visual|icon|red\s+hands?|steering\s+wheel|tor\s+symbol|hud|metadata", text))
    if has_audio and has_visual:
        return "audio_metadata"
    if has_audio:
        return "audio"
    if has_visual:
        return "metadata_only"
    return None


def detect_emotion_ego_response_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"scripted|script\s+ego|automatic\s+lane\s+change|ego\s+auto", text):
        return "scripted_lane_change"
    if re.search(r"participants?\s+(?:were\s+)?(?:expected|required|asked)|take\s+over|manually|manual|driver", text):
        return "human_takeover"
    return None


def emotion_scaner_target_lane_v2(ego_lane: str, study_target_lane: str) -> str:
    if ego_lane == "Right" and study_target_lane == "Left":
        return "Middle"
    if ego_lane == "Left" and study_target_lane == "Right":
        return "Middle"
    return study_target_lane


def build_emotion_takeover_clarification_message_v2(
    *,
    detected: dict[str, object],
    missing_items: list[str],
) -> str:
    detected_lines = "\n".join(
        f"- {label}: {format_takeover_detected_value_v2(value)}" for label, value in detected.items()
    )
    missing_lines = "\n".join(f"- {item}" for item in missing_items)
    return (
        "Prompt needs more detail before generating this emotion-induction takeover study scenario.\n\n"
        "Detected:\n"
        f"{detected_lines}\n\n"
        "Missing or ambiguous:\n"
        f"{missing_lines}\n\n"
        "Please add one clear instruction line, for example:\n"
        "event selection all; AV lane Right; target lane Left; TOR lead time 4 s; "
        "movie duration 4 min; speed 35 mph; TOR cue audio_metadata; ego response human_takeover"
    )


def configure_global_emotion_takeover_params_v2(
    base_params: ScenarioParametersV2,
    *,
    output_name: str,
    event_key: str,
    event_index: int,
    event_count: int,
    ego_speed_kmh: float,
    movie_duration_s: float,
    lead_time_s: float,
    ego_lane: str,
    study_target_lane: str,
    scaner_target_lane: str,
    cue_implementation: str,
    ego_response: str,
) -> ScenarioParametersV2:
    params = clone_params_v2(base_params)
    params.output_filename = normalize_output_filename(output_name)
    tor_time_s = max(5.0, movie_duration_s - lead_time_s)
    total_time_s = max(movie_duration_s + 30.0, tor_time_s + lead_time_s + 20.0)
    hazard_gap_m = kmh_to_mps_v2(ego_speed_kmh) * lead_time_s
    metadata = EMOTION_TAKEOVER_EVENT_META_V2[event_key]

    params.total_experiment_time_s = total_time_s
    params.merge = MergeConfigV2(enabled=False)
    params.n_key_intervention.enabled = False
    params.extra_vehicles = []
    params.extra_obstacles = []
    params.rain_level = None

    ego = params.vehicles["ego"]
    ego.enabled = True
    ego.initial_lane = ego_lane
    ego.initial_offset_m = 0.0
    ego.speed_kmh = ego_speed_kmh
    ego.lane_change_enabled = ego_response == "scripted_lane_change" and scaner_target_lane != ego_lane
    ego.lane_change_time_s = tor_time_s + 1.5
    ego.lane_change_duration_s = 3.5
    ego.lane_change_target_lane = scaner_target_lane
    ego.stop_enabled = False
    ego.gap_points = []

    for key in ("front", "rear", "left"):
        vehicle = params.vehicles[key]
        vehicle.enabled = False
        vehicle.lane_change_enabled = False
        vehicle.stop_enabled = False
        vehicle.gap_points = []

    for pedestrian in params.pedestrians.values():
        pedestrian.enabled = False
    for obstacle in params.obstacles.values():
        obstacle.enabled = False

    if event_key == "swerving_vehicle":
        swerving = params.vehicles["front"]
        swerving.enabled = True
        swerving.label = "Swerving Vehicle"
        swerving.initial_lane = ego_lane
        swerving.initial_offset_m = hazard_gap_m
        swerving.speed_kmh = ego_speed_kmh
        swerving.lane_change_enabled = True
        swerving.lane_change_time_s = tor_time_s
        swerving.lane_change_duration_s = 2.5
        swerving.lane_change_target_lane = scaner_target_lane
        swerving.stop_enabled = False
        swerving.gap_points = []
    else:
        obstacle = params.obstacles["obstacle_1"]
        obstacle.enabled = True
        obstacle.lane = ego_lane
        obstacle.gap_m = hazard_gap_m
        obstacle.start_time_s = tor_time_s
        obstacle.end_time_s = total_time_s
        obstacle.world_locked = False
        obstacle.lock_time_s = 0.0
        obstacle.lateral_offset_m = 0.0
        if event_key == "construction_zone":
            obstacle.kind = "Barrier"
            obstacle.model_name = OBSTACLE_MODEL_BY_KIND_V2["Barrier"]
        elif event_key == "bicyclist":
            obstacle.kind = "Disabled Vehicle"
            obstacle.model_name = SCANER_BICYCLE_MODEL_V2
        elif event_key == "police_vehicle":
            obstacle.kind = "Disabled Vehicle"
            obstacle.model_name = SCANER_POLICE_VEHICLE_MODEL_V2
            obstacle.lateral_offset_m = 3.5

    if cue_implementation in {"audio", "audio_metadata"}:
        params.audio_events = [AudioEventV2(time_s=tor_time_s, file_name="LCtoLeft_400.wav")]
    else:
        params.audio_events = []

    course_number = 1 + ((event_index - 1) // 2)
    event_in_course = 1 + ((event_index - 1) % 2)
    params.scene_notes = [
        "global_route=emotion_takeover_study",
        f"event_index={event_index}_of_{event_count}",
        f"course_number={course_number}",
        f"event_in_course={event_in_course}",
        f"environment={metadata['environment']}",
        f"event_key={event_key}",
        f"event_label={metadata['label']}",
        f"av_lane_study={ego_lane}",
        f"target_lane_study={study_target_lane}",
        f"target_lane_scaner={scaner_target_lane}",
        "road_mapping=current_3lane_right_to_middle_for_two_lane_study" if ego_lane == "Right" and study_target_lane == "Left" else "road_mapping=current_3lane_literal",
        f"movie_duration_s={format_number(movie_duration_s)}",
        f"tor_time_s={format_number(tor_time_s)}",
        f"tor_lead_time_s={format_number(lead_time_s)}",
        f"hazard_gap_m={format_number(hazard_gap_m)}",
        f"tor_cue={cue_implementation}",
        "tor_auditory_phrase=takeover",
        "tor_visual_metadata=red_hands_on_red_steering_wheel",
        "emotion_design=within_subjects_valence_arousal_movie_clips_latin_square",
        "measures=SAM_takeover_time_acceleration_jerk_TTC",
        f"asset_mapping={metadata['asset_note']}",
        f"ego_response={ego_response}",
    ]
    return params


def build_global_emotion_takeover_scenarios_v2(
    base_params: ScenarioParametersV2,
    prompt_text: str,
    *,
    explicit_output: bool,
    requested_output: str,
) -> list[ScenarioParametersV2] | None:
    if not prompt_is_emotion_takeover_study_v2(prompt_text):
        return None

    event_count = extract_emotion_takeover_event_count_v2(prompt_text)
    movie_duration_s = extract_emotion_movie_duration_s_v2(prompt_text)
    lead_time_s = extract_emotion_tor_lead_time_s_v2(prompt_text)
    ego_speed_kmh = extract_prompt_speed_kmh_v2(prompt_text, 0.0)
    ego_lane = detect_emotion_av_lane_v2(prompt_text)
    study_target_lane = detect_emotion_study_target_lane_v2(prompt_text)
    events = detect_emotion_takeover_events_v2(prompt_text)
    cue_implementation = detect_emotion_tor_cue_implementation_v2(prompt_text)
    ego_response = detect_emotion_ego_response_v2(prompt_text)

    scaner_target_lane = (
        emotion_scaner_target_lane_v2(ego_lane, study_target_lane)
        if ego_lane in LANE_NAMES_V2 and study_target_lane in LANE_NAMES_V2
        else None
    )
    detected = {
        "scene route": "global emotion-induction takeover study",
        "takeover event count": event_count or "not detected",
        "events": ", ".join(events) if events else "ambiguous",
        "ego speed": f"{format_number(ego_speed_kmh)} km/h" if ego_speed_kmh > 0 else "not detected",
        "movie duration": f"{format_number(movie_duration_s)} s" if movie_duration_s is not None else "not detected",
        "TOR lead time": f"{format_number(lead_time_s)} s" if lead_time_s is not None else "not detected",
        "AV lane": ego_lane or "ambiguous",
        "study target lane": study_target_lane or "ambiguous",
        "SCANeR target lane": scaner_target_lane or "ambiguous",
        "TOR cue": cue_implementation or "ambiguous",
        "ego response": ego_response or "ambiguous",
    }
    missing_items: list[str] = []
    if event_count != 4:
        missing_items.append("takeover event count: confirm four takeover events")
    if not events:
        missing_items.append("event selection: include construction_zone, bicyclist, police_vehicle, swerving_vehicle, or use event selection all")
    if ego_speed_kmh <= 0:
        missing_items.append("speed: provide mph or km/h, for example speed 35 mph")
    if movie_duration_s is None:
        missing_items.append("movie duration: provide minutes, for example movie duration 4 min")
    if lead_time_s is None:
        missing_items.append("TOR lead time: provide seconds, for example TOR lead time 4 s")
    if ego_lane not in LANE_NAMES_V2:
        missing_items.append("AV lane: provide Left, Middle, or Right")
    if study_target_lane not in LANE_NAMES_V2:
        missing_items.append("target lane: provide the expected takeover lane, for example target lane Left")
    if cue_implementation not in {"audio_metadata", "audio", "metadata_only", "none"}:
        missing_items.append("TOR cue implementation: choose audio_metadata, audio, metadata_only, or none")
    if ego_response not in {"human_takeover", "scripted_lane_change"}:
        missing_items.append("ego response: choose human_takeover or scripted_lane_change")
    if missing_items:
        raise PromptClarificationError(
            build_emotion_takeover_clarification_message_v2(
                detected=detected,
                missing_items=missing_items,
            )
        )

    params_list: list[ScenarioParametersV2] = []
    selected_events = events or EMOTION_TAKEOVER_EVENT_ORDER_V2
    for event_index, event_key in enumerate(selected_events, start=1):
        event_label = event_key.upper()
        output_base = Path(normalize_output_filename(requested_output)).stem if explicit_output else (
            f"HF_GLOBAL_EMOTION_TOR_{event_index:02d}_{event_label}"
        )
        if explicit_output and len(selected_events) > 1:
            output_base = f"{output_base}_{event_index:02d}_{event_label}"
        params_list.append(
            configure_global_emotion_takeover_params_v2(
                base_params,
                output_name=f"{output_base}.sce",
                event_key=event_key,
                event_index=event_index,
                event_count=len(selected_events),
                ego_speed_kmh=ego_speed_kmh,
                movie_duration_s=movie_duration_s,
                lead_time_s=lead_time_s,
                ego_lane=ego_lane,
                study_target_lane=study_target_lane,
                scaner_target_lane=scaner_target_lane,
                cue_implementation=cue_implementation,
                ego_response=ego_response,
            )
        )
    return params_list


