def prompt_has_explicit_nback_study_builder_intent_v2(prompt_text: str) -> bool:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    explicit_terms = (
        r"\bstudy\s*(?:1|2)\b",
        r"study\s+selection",
        r"both\s+studies",
        r"generate\s+(?:both\s+)?stud(?:y|ies)",
        r"n[-\s]*back\s+takeover\s+study",
        r"nback\s+takeover\s+study",
        r"psychophysiological\s+responses?.{0,80}n[-\s]*back",
    )
    return any(re.search(pattern, text, flags=re.IGNORECASE | re.DOTALL) for pattern in explicit_terms)


def prompt_is_nback_takeover_study_v2(prompt_text: str) -> bool:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if not prompt_has_explicit_nback_study_builder_intent_v2(prompt_text):
        return False
    design_terms = re.search(r"n-back|nback|ndrt|cognitive\s+load|traffic\s+density", text)
    takeover_terms = re.search(r"takeover\s+events?|\btor\b|takeover\s+request", text)
    event_terms = re.search(r"bicyclists?|construction\s+zone|sensor\s+error|swerving\s+vehicle|police\s+vehicle|lane\s+markings|stranded\s+vehicle", text)
    return bool(design_terms and takeover_terms and event_terms)


def detect_nback_study_selection_v2(prompt_text: str) -> tuple[str, ...] | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"study\s+selection\s+both|both\s+studies|generate\s+both\s+studies", text):
        return ("study1", "study2")
    if re.search(r"study\s+selection\s+study\s*1|study\s*1\s+only|generate\s+study\s*1", text):
        return ("study1",)
    if re.search(r"study\s+selection\s+study\s*2|study\s*2\s+only|generate\s+study\s*2", text):
        return ("study2",)
    has_study1 = bool(re.search(r"study\s*1", text))
    has_study2 = bool(re.search(r"study\s*2", text))
    if has_study1 and has_study2:
        return ("study1", "study2")
    if has_study1:
        return ("study1",)
    if has_study2:
        return ("study2",)
    return None


def extract_nback_event_count_v2(prompt_text: str, *, study: str) -> int | None:
    label = r"takeover\s+events?" if study == "study1" else r"scenarios?"
    patterns = (
        rf"\b(?P<number>{NBACK_SIMPLE_NUMBER_TOKEN_V2})\s+{label}",
        rf"(?:number\s+of\s+{label}|total\s+{label})\s*(?P<number>{NBACK_SIMPLE_NUMBER_TOKEN_V2})",
    )
    for pattern in patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL)
        if match:
            try:
                return int(parse_prompt_number_v2(match.group("number")))
            except ValueError:
                continue
    return None


def extract_nback_ndrt_duration_s_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:after\s+about|after|approximately|about)?\s*{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}\s+of\s+(?:the\s+)?ndrt",
            rf"ndrt[^.;\n。；]{{0,48}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
        ),
    )


def extract_nback_distance_m_v2(prompt_text: str) -> float | None:
    return search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:distance\s+between\s+obstacle|obstacle|entrance\s+of\s+the\s+curve)[^.;\n。；]{{0,96}}?{{n}}{{u}}{NBACK_METER_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{NBACK_METER_UNIT_PATTERN_V2}[^.;\n。；]{{0,96}}?(?:when\s+the\s+tor|tor\s+was\s+issued|obstacle|entrance\s+of\s+the\s+curve)",
        ),
    )


def extract_nback_speed_options_kmh_v2(prompt_text: str) -> tuple[float, ...]:
    values: list[float] = []
    pattern = rf"(?P<number>{NBACK_SIMPLE_NUMBER_TOKEN_V2})\s*(?:mph|miles\s+per\s+hour)"
    for match in re.finditer(pattern, normalize_cli_prompt_text_v2(prompt_text), flags=re.IGNORECASE):
        try:
            speed_kmh = parse_prompt_number_v2(match.group("number")) * MPH_TO_KMH_V2
        except ValueError:
            continue
        if not any(abs(existing - speed_kmh) < 0.01 for existing in values):
            values.append(speed_kmh)
    return tuple(values)


def detect_nback_cognitive_loads_v2(prompt_text: str) -> tuple[str, ...] | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"cognitive\s+load\s+both|low\s+and\s+high|high\s+and\s+low|1-back[^.;\n。；]+2-back|2-back[^.;\n。；]+1-back", text):
        return ("low", "high")
    if re.search(r"low\s+cognitive\s+load|1-back|low\s+only", text) and re.search(r"high\s+cognitive\s+load|2-back|high\s+only", text):
        return ("low", "high")
    if re.search(r"low\s+cognitive\s+load|1-back|low\s+only", text):
        return ("low",)
    if re.search(r"high\s+cognitive\s+load|2-back|high\s+only", text):
        return ("high",)
    return None


def detect_nback_traffic_densities_v2(prompt_text: str) -> tuple[str, ...] | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"traffic\s+density\s+both|heavy-\s*and\s+no-traffic|heavy\s+and\s+no\s+traffic|15\s+and\s+0\s+oncoming", text):
        return ("no_traffic", "heavy")
    if re.search(r"no-traffic|no\s+traffic|0\s+oncoming", text) and re.search(r"heavy\s+traffic|15\s+oncoming", text):
        return ("no_traffic", "heavy")
    if re.search(r"no-traffic|no\s+traffic|0\s+oncoming", text):
        return ("no_traffic",)
    if re.search(r"heavy\s+traffic|15\s+oncoming|traffic\s+consisted\s+of\s+15", text):
        return ("heavy",)
    return None


def detect_nback_tor_lead_options_s_v2(prompt_text: str) -> tuple[float, ...]:
    value = NBACK_SIMPLE_NUMBER_TOKEN_V2
    pair_patterns = (
        rf"(?:tor\s+lead\s+time|lead\s+time)[^.;\n。；]{{0,80}}?"
        rf"(?P<n1>{value})\s*(?:or|and|/|vs\.?|versus|或)\s*(?P<n2>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_TIME_UNIT_PATTERN_V2}",
        rf"(?P<n1>{value})\s*(?:or|and|/|vs\.?|versus|或)\s*(?P<n2>{value}){PROMPT_UNIT_SEPARATOR_PATTERN_V2}{PROMPT_TIME_UNIT_PATTERN_V2}"
        rf"[^.;\n。；]{{0,80}}?(?:tor\s+lead\s+time|lead\s+time)",
    )
    pair_values: list[float] = []
    for pattern in pair_patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL)
        if not match:
            continue
        for group_name in ("n1", "n2"):
            try:
                parsed = parse_prompt_number_v2(match.group(group_name))
            except ValueError:
                continue
            if not any(abs(existing - parsed) < 0.001 for existing in pair_values):
                pair_values.append(parsed)
        if pair_values:
            return tuple(pair_values)
    values = extract_takeover_lead_time_options_s_v2(prompt_text)
    if values:
        return tuple(values)
    single = extract_takeover_lead_time_s_v2(prompt_text)
    return (single,) if single is not None else ()


def detect_nback_study2_scenario_types_v2(prompt_text: str) -> tuple[str, ...] | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"scenario\s+type\s+both|lane\s+keeping\s+vs\.?\s+lane\s+changing|lane-keeping[^.;\n。；]+lane-changing", text):
        return ("lane_keeping", "lane_changing")
    has_keeping = bool(re.search(r"lane[-\s]+keeping|keep\s+in\s+the\s+current\s+lane", text))
    has_changing = bool(re.search(r"lane[-\s]+changing|change\s+to\s+the\s+neighboring\s+lane", text))
    if has_keeping and has_changing:
        return ("lane_keeping", "lane_changing")
    if has_keeping:
        return ("lane_keeping",)
    if has_changing:
        return ("lane_changing",)
    return None


def detect_nback_ego_lane_v2(prompt_text: str) -> str | None:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    match = re.search(r"(?:drivers\s+started|av\s+was|vehicle\s+was|subject\s+vehicle\s+was)[^.;\n。；]{0,64}?\b(?P<lane>left|middle|right)\s+lane", text)
    if match:
        return lane_from_prompt_fragment_v2(match.group("lane"))
    match = re.search(r"(?:av\s+lane|ego\s+lane)\s*(?P<lane>left|middle|right)", text)
    if match:
        return lane_from_prompt_fragment_v2(match.group("lane"))
    return None


def nback_event_lane_change_required_v2(event_key: str) -> bool:
    return NBACK_EVENT_META_V2[event_key]["scenario_type"] == "lane_changing"


def nback_scaner_target_lane_v2(ego_lane: str, event_key: str) -> str:
    if not nback_event_lane_change_required_v2(event_key):
        return ego_lane
    if ego_lane == "Right":
        return "Middle"
    if ego_lane == "Left":
        return "Middle"
    return "Left"


def build_nback_takeover_clarification_message_v2(
    *,
    detected: dict[str, object],
    missing_items: list[str],
) -> str:
    detected_lines = "\n".join(
        f"- {label}: {format_takeover_detected_value_v2(value)}" for label, value in detected.items()
    )
    missing_lines = "\n".join(f"- {item}" for item in missing_items)
    return (
        "Prompt needs more detail before generating this N-back / traffic-density takeover study scenario.\n\n"
        "Detected:\n"
        f"{detected_lines}\n\n"
        "Missing or ambiguous:\n"
        f"{missing_lines}\n\n"
        "Please add one clear instruction line, for example:\n"
        "study selection both; AV lane Right; NDRT duration 90 s; TOR cue audio_metadata; ego response human_takeover; "
        "Study 1 cognitive load both; traffic density both; TOR lead time 4 or 7 s; "
        "Study 2 scenario type both; speed 35 vs 60 mph; obstacle distance 100 m"
    )


def configure_global_nback_takeover_params_v2(
    base_params: ScenarioParametersV2,
    *,
    output_name: str,
    study: str,
    event_key: str,
    event_index: int,
    event_count: int,
    ego_speed_kmh: float,
    tor_time_s: float,
    hazard_gap_m: float,
    ego_lane: str,
    cue_implementation: str,
    ego_response: str,
    cognitive_load: str | None = None,
    traffic_density: str | None = None,
    lead_time_s: float | None = None,
    speed_label_mph: str | None = None,
    scenario_type: str | None = None,
) -> ScenarioParametersV2:
    params = clone_params_v2(base_params)
    params.output_filename = normalize_output_filename(output_name)
    total_time_s = max(tor_time_s + max(lead_time_s or 0.0, 0.0) + 30.0, tor_time_s + 35.0)
    metadata = NBACK_EVENT_META_V2[event_key]
    scaner_target_lane = nback_scaner_target_lane_v2(ego_lane, event_key)

    params.total_experiment_time_s = total_time_s
    params.merge = MergeConfigV2(enabled=False)
    params.n_key_intervention.enabled = False
    params.extra_vehicles = []
    params.extra_obstacles = []
    params.rain_level = None

    ego = params.vehicles["ego"]
    ego.enabled = True
    ego.initial_lane = ego_lane
    ego.initial_offset_m = 0.0
    ego.speed_kmh = ego_speed_kmh
    ego.lane_change_enabled = ego_response == "scripted_lane_change" and scaner_target_lane != ego_lane
    ego.lane_change_time_s = tor_time_s + 1.5
    ego.lane_change_duration_s = 3.5
    ego.lane_change_target_lane = scaner_target_lane
    ego.stop_enabled = False
    ego.gap_points = []

    for key in ("front", "rear", "left"):
        vehicle = params.vehicles[key]
        vehicle.enabled = False
        vehicle.lane_change_enabled = False
        vehicle.stop_enabled = False
        vehicle.gap_points = []

    for pedestrian in params.pedestrians.values():
        pedestrian.enabled = False
    for obstacle in params.obstacles.values():
        obstacle.enabled = False

    obstacle_lane = ego_lane
    obstacle_lateral_offset_m = 0.0
    if event_key == "construction_zone_left":
        obstacle_lane = scaner_target_lane if scaner_target_lane != ego_lane else "Middle"
    elif event_key == "police_vehicle_shoulder":
        obstacle_lateral_offset_m = 3.5

    if event_key == "swerving_vehicle_ahead":
        swerving = params.vehicles["front"]
        swerving.enabled = True
        swerving.label = "Swerving Vehicle"
        swerving.initial_lane = ego_lane
        swerving.initial_offset_m = hazard_gap_m
        swerving.speed_kmh = ego_speed_kmh
        swerving.lane_change_enabled = True
        swerving.lane_change_time_s = tor_time_s
        swerving.lane_change_duration_s = 2.5
        swerving.lane_change_target_lane = scaner_target_lane if scaner_target_lane != ego_lane else "Middle"
        swerving.stop_enabled = False
        swerving.gap_points = []
    elif event_key not in {"sensor_error_right_curve", "sensor_error_left_curve", "no_lane_markings_curve"}:
        obstacle = params.obstacles["obstacle_1"]
        obstacle.enabled = True
        obstacle.lane = obstacle_lane
        obstacle.gap_m = hazard_gap_m
        obstacle.start_time_s = tor_time_s
        obstacle.end_time_s = total_time_s
        obstacle.world_locked = False
        obstacle.lock_time_s = 0.0
        obstacle.lateral_offset_m = obstacle_lateral_offset_m
        if event_key == "police_vehicle_shoulder":
            obstacle.kind = "Disabled Vehicle"
            obstacle.model_name = SCANER_POLICE_VEHICLE_MODEL_V2
        elif event_key == "stranded_vehicle_ahead":
            obstacle.kind = "Disabled Vehicle"
            obstacle.model_name = OBSTACLE_MODEL_BY_KIND_V2[obstacle.kind]
        elif event_key == "bicyclists_ahead":
            obstacle.kind = "Disabled Vehicle"
            obstacle.model_name = SCANER_BICYCLE_MODEL_V2
            obstacle.lateral_offset_m = 0.8
            params.extra_obstacles.append(
                ObstacleConfigV2(
                    role="nback_bicycle_2",
                    label="Bicyclist 2",
                    vehicle_id=70,
                    enabled=True,
                    kind="Disabled Vehicle",
                    lane=obstacle_lane,
                    gap_m=hazard_gap_m + 4.0,
                    lateral_offset_m=-0.8,
                    start_time_s=tor_time_s,
                    end_time_s=total_time_s,
                    model_name=SCANER_BICYCLE_ALT_MODEL_V2,
                    world_locked=False,
                    lock_time_s=0.0,
                )
            )
        else:
            obstacle.kind = "Barrier"
            obstacle.model_name = OBSTACLE_MODEL_BY_KIND_V2[obstacle.kind]

    audio_events = [AudioEventV2(time_s=max(0.0, tor_time_s - 90.0), file_name="NormalDriveTest_400.wav")]
    if cue_implementation in {"audio", "audio_metadata"}:
        audio_events.append(AudioEventV2(time_s=tor_time_s, file_name="LCtoLeft_400.wav"))
    params.audio_events = audio_events

    study_label = "Study 1" if study == "study1" else "Study 2"
    params.scene_notes = [
        "global_route=nback_takeover_study",
        f"study={study_label}",
        f"event_index={event_index}_of_{event_count}",
        f"event_key={event_key}",
        f"event_label={metadata['label']}",
        f"environment={metadata['environment']}",
        f"scenario_type={scenario_type or metadata['scenario_type']}",
        f"av_lane_study={ego_lane}",
        f"target_lane_scaner={scaner_target_lane}",
        "road_mapping=current_3lane_right_to_middle_for_two_lane_adjacent_lane" if ego_lane == "Right" and scaner_target_lane == "Middle" else "road_mapping=current_3lane_literal",
        f"ego_speed_kmh={format_number(ego_speed_kmh)}",
        f"speed_label_mph={speed_label_mph or ''}",
        f"tor_time_s={format_number(tor_time_s)}",
        f"tor_lead_time_s={format_number(lead_time_s)}" if lead_time_s is not None else "tor_lead_time_s=distance_based",
        f"hazard_gap_m={format_number(hazard_gap_m)}",
        f"cognitive_load={cognitive_load or 'not_applicable'}",
        f"ndrt_task={'1-back' if cognitive_load == 'low' else '2-back' if cognitive_load == 'high' else 'not_applicable'}",
        f"traffic_density={traffic_density or 'heavy_15_oncoming_per_km'}",
        "traffic_density_implementation=metadata_only_current_template_has_no_reverse_oncoming_actor",
        f"tor_cue={cue_implementation}",
        "tor_auditory_phrase=takeover",
        "tor_visual_metadata=red_hands_on_red_steering_wheel",
        "ndrt_start_command_metadata=Please start the NDRT",
        "counterbalancing=balanced_latin_square_or_forward_reverse_order_metadata",
        f"asset_mapping={metadata['asset_note']}",
        f"ego_response={ego_response}",
    ]
    return params


def build_global_nback_takeover_scenarios_v2(
    base_params: ScenarioParametersV2,
    prompt_text: str,
    *,
    explicit_output: bool,
    requested_output: str,
) -> list[ScenarioParametersV2] | None:
    if not prompt_is_nback_takeover_study_v2(prompt_text):
        return None

    studies = detect_nback_study_selection_v2(prompt_text)
    ego_lane = detect_nback_ego_lane_v2(prompt_text)
    ndrt_duration_s = extract_nback_ndrt_duration_s_v2(prompt_text)
    cue_implementation = detect_emotion_tor_cue_implementation_v2(prompt_text)
    ego_response = detect_emotion_ego_response_v2(prompt_text)
    speed_options_kmh = extract_nback_speed_options_kmh_v2(prompt_text)
    study1_event_count = extract_nback_event_count_v2(prompt_text, study="study1")
    study2_event_count = extract_nback_event_count_v2(prompt_text, study="study2")
    cognitive_loads = detect_nback_cognitive_loads_v2(prompt_text)
    traffic_densities = detect_nback_traffic_densities_v2(prompt_text)
    lead_time_options = detect_nback_tor_lead_options_s_v2(prompt_text)
    study2_scenario_types = detect_nback_study2_scenario_types_v2(prompt_text)
    study2_distance_m = extract_nback_distance_m_v2(prompt_text)

    detected = {
        "scene route": "global N-back takeover study",
        "studies": ",".join(studies) if studies else "ambiguous",
        "AV lane": ego_lane or "ambiguous",
        "NDRT duration": f"{format_number(ndrt_duration_s)} s" if ndrt_duration_s is not None else "not detected",
        "TOR cue": cue_implementation or "ambiguous",
        "ego response": ego_response or "ambiguous",
        "speed options": ", ".join(f"{format_number(value)} km/h" for value in speed_options_kmh) or "not detected",
        "Study 1 event count": study1_event_count or "not detected",
        "Study 1 cognitive loads": ",".join(cognitive_loads) if cognitive_loads else "ambiguous",
        "Study 1 traffic densities": ",".join(traffic_densities) if traffic_densities else "ambiguous",
        "Study 1 TOR lead times": ", ".join(format_number(value) + " s" for value in lead_time_options) or "not detected",
        "Study 2 event count": study2_event_count or "not detected",
        "Study 2 scenario types": ",".join(study2_scenario_types) if study2_scenario_types else "ambiguous",
        "Study 2 obstacle/curve distance": f"{format_number(study2_distance_m)} m" if study2_distance_m is not None else "not detected",
    }
    missing_items: list[str] = []
    if not studies:
        missing_items.append("study selection: choose Study 1, Study 2, or both")
    if ego_lane not in LANE_NAMES_V2:
        missing_items.append("AV lane: provide Left, Middle, or Right")
    if ndrt_duration_s is None:
        missing_items.append("NDRT duration before TOR: provide seconds, for example NDRT duration 90 s")
    if cue_implementation not in {"audio_metadata", "audio", "metadata_only", "none"}:
        missing_items.append("TOR cue implementation: choose audio_metadata, audio, metadata_only, or none")
    if ego_response not in {"human_takeover", "scripted_lane_change"}:
        missing_items.append("ego response: choose human_takeover or scripted_lane_change")
    if not speed_options_kmh:
        missing_items.append("vehicle speed: provide mph options, for example 35 mph or 35 vs 60 mph")
    if studies and "study1" in studies:
        if study1_event_count not in {None, 8}:
            missing_items.append("Study 1 event count: confirm 8 takeover events")
        if cognitive_loads is None:
            missing_items.append("Study 1 cognitive load: choose low, high, or both")
        if traffic_densities is None:
            missing_items.append("Study 1 traffic density: choose no_traffic, heavy, or both")
        if not lead_time_options:
            missing_items.append("Study 1 TOR lead time: provide 4 s, 7 s, or both")
    if studies and "study2" in studies:
        if study2_event_count not in {None, 8}:
            missing_items.append("Study 2 scenario count: confirm 8 scenarios")
        if study2_scenario_types is None:
            missing_items.append("Study 2 scenario type: choose lane_keeping, lane_changing, or both")
        if len(speed_options_kmh) < 2:
            missing_items.append("Study 2 speed options: provide 35 vs 60 mph")
        if study2_distance_m is None:
            missing_items.append("Study 2 obstacle/curve distance: provide meters, for example obstacle distance 100 m")
    if missing_items:
        raise PromptClarificationError(
            build_nback_takeover_clarification_message_v2(
                detected=detected,
                missing_items=missing_items,
            )
        )

    params_list: list[ScenarioParametersV2] = []
    tor_time_s = 5.0 + ndrt_duration_s
    output_stem = Path(normalize_output_filename(requested_output)).stem if explicit_output else ""

    if "study1" in studies:
        study1_speed_kmh = next((value for value in speed_options_kmh if abs(value - 35.0 * MPH_TO_KMH_V2) < 0.5), speed_options_kmh[0])
        for cognitive_load in cognitive_loads:
            for traffic_density in traffic_densities:
                for lead_time_s in lead_time_options:
                    for event_index, event_key in enumerate(NBACK_STUDY1_EVENT_ORDER_V2, start=1):
                        output_base = output_stem if explicit_output else (
                            f"HF_GLOBAL_NBACK_S1_E{event_index:02d}_{event_key.upper()}_"
                            f"{cognitive_load.upper()}_{traffic_density.upper()}_TOR{filename_number_token_v2(lead_time_s)}S"
                        )
                        if explicit_output:
                            output_base = (
                                f"{output_base}_S1_E{event_index:02d}_{event_key.upper()}_"
                                f"{cognitive_load.upper()}_{traffic_density.upper()}_TOR{filename_number_token_v2(lead_time_s)}S"
                            )
                        params_list.append(
                            configure_global_nback_takeover_params_v2(
                                base_params,
                                output_name=f"{output_base}.sce",
                                study="study1",
                                event_key=event_key,
                                event_index=event_index,
                                event_count=len(NBACK_STUDY1_EVENT_ORDER_V2),
                                ego_speed_kmh=study1_speed_kmh,
                                tor_time_s=tor_time_s,
                                hazard_gap_m=kmh_to_mps_v2(study1_speed_kmh) * lead_time_s,
                                ego_lane=ego_lane,
                                cue_implementation=cue_implementation,
                                ego_response=ego_response,
                                cognitive_load=cognitive_load,
                                traffic_density=traffic_density,
                                lead_time_s=lead_time_s,
                                speed_label_mph="35",
                            )
                        )

    if "study2" in studies:
        events_by_type = {
            "lane_keeping": NBACK_STUDY2_LANE_KEEPING_EVENT_ORDER_V2,
            "lane_changing": NBACK_STUDY2_LANE_CHANGING_EVENT_ORDER_V2,
        }
        for scenario_type in study2_scenario_types:
            for speed_kmh in speed_options_kmh:
                speed_mph = speed_kmh / MPH_TO_KMH_V2
                for event_index, event_key in enumerate(events_by_type[scenario_type], start=1):
                    output_base = output_stem if explicit_output else (
                        f"HF_GLOBAL_NBACK_S2_{scenario_type.upper()}_E{event_index:02d}_"
                        f"{event_key.upper()}_{filename_number_token_v2(speed_mph)}MPH"
                    )
                    if explicit_output:
                        output_base = (
                            f"{output_base}_S2_{scenario_type.upper()}_E{event_index:02d}_"
                            f"{event_key.upper()}_{filename_number_token_v2(speed_mph)}MPH"
                        )
                    params_list.append(
                        configure_global_nback_takeover_params_v2(
                            base_params,
                            output_name=f"{output_base}.sce",
                            study="study2",
                            event_key=event_key,
                            event_index=event_index,
                            event_count=len(events_by_type[scenario_type]),
                            ego_speed_kmh=speed_kmh,
                            tor_time_s=tor_time_s,
                            hazard_gap_m=study2_distance_m,
                            ego_lane=ego_lane,
                            cue_implementation=cue_implementation,
                            ego_response=ego_response,
                            traffic_density="heavy_15_oncoming_per_km",
                            speed_label_mph=format_number(speed_mph),
                            scenario_type=scenario_type,
                        )
                    )

    return params_list


def filename_number_token_v2(value: float) -> str:
    return format_number(value).replace("-", "NEG").replace(".", "P")


def apply_extra_vehicle_prompt_scene_v2(
    params: ScenarioParametersV2,
    prompt_text: str,
    *,
    ego_speed_kmh: float,
) -> None:
    next_vehicle_id = max((config.vehicle_id for config in params.vehicles.values()), default=3) + 37
    latest_event_s = 0.0
    extra_configs: list[VehicleConfigV2] = []
    for vehicle_index in range(2, 7):
        role_pattern = prompt_vehicle_index_pattern_v2(vehicle_index)
        fragment = prompt_role_fragments_v2(prompt_text, role_pattern)
        if not fragment:
            continue

        lane_change_from, lane_change_to = extract_vehicle_lane_change_lanes_for_role_v2(fragment, role_pattern)
        initial_lane = lane_change_from or extract_role_lane_from_prompt_v2(fragment, role_pattern, "Middle")
        lane_change_events = extract_vehicle_lane_change_events_for_role_v2(
            prompt_text,
            role_pattern,
            default_initial_lane=initial_lane,
            default_duration_s=5.0,
        )
        if lane_change_events:
            initial_lane = lane_change_events[0].from_lane
        target_lane = lane_change_to or initial_lane
        gap_time_s = extract_prompt_gap_time_s_v2(fragment)
        relation_sign = prompt_gap_relation_sign_v2(fragment, default=1)
        if gap_time_s is not None:
            initial_offset_m = signed_gap_from_time_v2(
                gap_time_s,
                ego_speed_kmh,
                relation_sign,
            )
        else:
            initial_offset_m = kmh_to_mps_v2(ego_speed_kmh) * (7.0 + vehicle_index)
        if gap_time_s is None and prompt_vehicle_fragment_is_behind_v2(fragment):
            initial_offset_m = -abs(initial_offset_m)
        gap_points = extract_prompt_timed_gap_points_v2(fragment, ego_speed_kmh=ego_speed_kmh)
        vehicle_speed_kmh = extract_prompt_speed_kmh_v2(fragment, ego_speed_kmh)
        lane_change_enabled = target_lane != initial_lane
        lane_change_time_s = extract_prompt_lane_change_time_s_v2(fragment, 5.0 + vehicle_index)
        lane_change_duration_s = extract_prompt_lane_change_duration_s_v2(
            fragment,
            5.0 if lane_change_enabled else DEFAULT_NATIVE_LANE_CHANGE_DURATION_V2,
        )
        if lane_change_events:
            target_lane = lane_change_events[0].target_lane
            lane_change_enabled = True
            lane_change_time_s = lane_change_events[0].time_s
            lane_change_duration_s = lane_change_events[0].duration_s
            for event in lane_change_events:
                latest_event_s = max(latest_event_s, event.time_s + max(event.duration_s, 0.0))
        elif lane_change_enabled:
            latest_event_s = max(latest_event_s, lane_change_time_s + max(lane_change_duration_s, 0.0))
        for point in gap_points:
            latest_event_s = max(latest_event_s, point.time_s)
        extra_configs.append(
            VehicleConfigV2(
                key=f"prompt_vehicle_{vehicle_index}",
                label=f"Vehicle {vehicle_index}",
                name=f"{HF_ACTOR_PREFIX}PROMPT_VEHICLE_{vehicle_index}",
                vehicle_id=next_vehicle_id + len(extra_configs),
                initial_offset_m=initial_offset_m,
                initial_lane=initial_lane,
                speed_kmh=vehicle_speed_kmh,
                lane_change_enabled=lane_change_enabled,
                lane_change_time_s=lane_change_time_s,
                lane_change_target_lane=target_lane,
                stop_enabled=False,
                stop_time_s=params.total_experiment_time_s,
                lane_change_duration_s=lane_change_duration_s,
                lane_changes=lane_change_events,
                gap_points=gap_points,
                enabled=True,
            )
        )

    params.extra_vehicles = extra_configs
    if latest_event_s > 0:
        params.total_experiment_time_s = max(params.total_experiment_time_s, latest_event_s + 10.0)


def prompt_obstacle_index_pattern_v2(index: int) -> str:
    word_by_index = {1: "one", 2: "two", 3: "three", 4: "four", 5: "five", 6: "six"}
    word = word_by_index.get(index, str(index))
    return rf"(?:obstacle\s*(?:{index}|{word})|obstacle_{index}|障礙物\s*{index}|障碍物\s*{index}|路障\s*{index})"


def prompt_pedestrian_index_pattern_v2(index: int) -> str:
    word_by_index = {1: "one", 2: "two", 3: "three", 4: "four"}
    word = word_by_index.get(index, str(index))
    return rf"(?:pedestrian\s*(?:{index}|{word})|pedestrian_{index}|行人\s*{index})"


def detect_prompt_obstacle_kind_and_model_v2(prompt_text: str) -> tuple[str, str]:
    text = normalize_cli_prompt_text_v2(prompt_text).lower()
    if re.search(r"bicyclist|cyclist|bicycle|bike|腳踏車|自行車|單車|骑行者|自行车", text):
        return "Disabled Vehicle", SCANER_BICYCLE_MODEL_V2
    if re.search(r"disabled\s+vehicle|stranded\s+vehicle|stopped\s+vehicle|故障車|故障车", text):
        return "Disabled Vehicle", OBSTACLE_MODEL_BY_KIND_V2["Disabled Vehicle"]
    if re.search(r"construction\s+zone|road\s+construction|work\s+zone|barrier|施工|路障|護欄|护栏", text):
        return "Barrier", OBSTACLE_MODEL_BY_KIND_V2["Barrier"]
    if re.search(r"\bcone\b|cones|錐|锥", text):
        return "Cone", OBSTACLE_MODEL_BY_KIND_V2["Cone"]
    if re.search(r"debris|barrel|碎片|雜物|杂物", text):
        return "Debris", OBSTACLE_MODEL_BY_KIND_V2["Debris"]
    return "Barrier", OBSTACLE_MODEL_BY_KIND_V2["Barrier"]


def extract_prompt_distance_m_v2(prompt_text: str, default_m: float) -> float:
    meter_value = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:ahead|in\s+front|front|distance|gap|前方|距離|距离)[^.;\n。；]{{0,32}}?{{n}}{{u}}{PROMPT_METERS_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_METERS_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:ahead|in\s+front|front|前方)",
        ),
    )
    return meter_value if meter_value is not None else default_m


def extract_prompt_time_range_s_v2(prompt_text: str, default_start_s: float, default_end_s: float) -> tuple[float, float]:
    pair = search_prompt_number_pair_v2(
        prompt_text,
        (
            rf"(?:from|between|從|从|自)[^.;\n。；]{{0,16}}?{{n1}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}"
            rf"[^.;\n。；]{{0,24}}?(?:to|until|and|到|至)[^.;\n。；]{{0,16}}?{{n2}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n1}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:to|until|and|到|至)"
            rf"[^.;\n。；]{{0,16}}?{{n2}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
        ),
    )
    if pair is not None:
        start_s, end_s = pair
        if end_s < start_s:
            start_s, end_s = end_s, start_s
        return start_s, end_s
    start_s = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:start(?:ing)?|starts?|appear(?:s|ing)?|at|開始|开始|出現|出现|時間|时间)[^.;\n。；]{{0,32}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,32}}?(?:start(?:ing)?|starts?|appear(?:s|ing)?|開始|开始|出現|出现)",
        ),
    )
    end_s = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:end(?:ing)?|ends?|until|to|結束|结束|到|至)[^.;\n。；]{{0,32}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
        ),
    )
    return start_s if start_s is not None else default_start_s, end_s if end_s is not None else default_end_s


def extract_prompt_duration_s_v2(prompt_text: str, default_duration_s: float) -> float:
    value = search_prompt_number_v2(
        prompt_text,
        (
            rf"(?:duration|for|lasting|lasts|持續|持续|歷時|历时)[^.;\n。；]{{0,24}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?(?:duration|long|持續|持续)",
        ),
    )
    return value if value is not None else default_duration_s


def extract_prompt_total_experiment_time_s_v2(prompt_text: str) -> float | None:
    second_value = search_last_prompt_number_by_position_v2(
        prompt_text,
        (
            rf"(?:scenario|scene|experiment|trial|drive|simulation|timeline)[^.;\n。；]{{0,28}}?"
            rf"(?:duration|length|total\s*time|end\s*time|ends?|lasts?)[^.;\n。；]{{0,18}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:total\s*)?(?:scenario|scene|experiment|trial|drive|simulation|timeline)\s*"
            rf"(?:duration|length|time)[^.;\n。；]{{0,18}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:scenario\s*duration|timeline\s*length|total\s*time|scenario\s*end)[^.;\n。；]{{0,24}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:場景|场景|情境|實驗|实验|試驗|试验|模擬|模拟)[^.;\n。；]{{0,18}}?"
            rf"(?:總時長|总时长|總時間|总时间|時長|时长|結束時間|结束时间|結束|结束)[^.;\n。；]{{0,18}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"(?:總場景時長|总场景时长|場景總時長|场景总时长|整體時長|整体时长|總時長|总时长)[^.;\n。；]{{0,24}}?{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}",
            rf"{{n}}{{u}}{PROMPT_TIME_UNIT_PATTERN_V2}[^.;\n。；]{{0,24}}?"
            rf"(?:scenario\s*duration|timeline\s*length|total\s*time|場景總時長|场景总时长|總時長|总时长)",
        ),
    )
    if second_value is not None:
        return second_value

    minute_unit_pattern = r"(?:分鐘|分钟|min\b|mins\b|minute\b|minutes\b)"
    minute_value = search_last_prompt_number_by_position_v2(
        prompt_text,
        (
            rf"(?:scenario|scene|experiment|trial|drive|simulation|timeline)[^.;\n。；]{{0,28}}?"
            rf"(?:duration|length|total\s*time|end\s*time|ends?|lasts?)[^.;\n。；]{{0,18}}?{{n}}{{u}}{minute_unit_pattern}",
            rf"(?:scenario\s*duration|timeline\s*length|total\s*time|scenario\s*end)[^.;\n。；]{{0,24}}?{{n}}{{u}}{minute_unit_pattern}",
            rf"(?:場景|场景|情境|實驗|实验|試驗|试验|模擬|模拟)[^.;\n。；]{{0,18}}?"
            rf"(?:總時長|总时长|總時間|总时间|時長|时长|結束時間|结束时间|結束|结束)[^.;\n。；]{{0,18}}?{{n}}{{u}}{minute_unit_pattern}",
            rf"(?:總場景時長|总场景时长|場景總時長|场景总时长|整體時長|整体时长|總時長|总时长)[^.;\n。；]{{0,24}}?{{n}}{{u}}{minute_unit_pattern}",
        ),
    )
    return minute_value * 60.0 if minute_value is not None else None


def extract_prompt_crossing_sides_v2(prompt_text: str, default_start: str, default_end: str) -> tuple[str, str]:
    lane_pattern = lane_word_pattern_v2()
    patterns = (
        rf"(?:from|從|从)\s*(?P<start>{lane_pattern})[^.;\n。；]{{0,24}}(?:to|到|至)\s*(?P<end>{lane_pattern})",
        rf"(?P<start>{lane_pattern})[^.;\n。；]{{0,12}}(?:to|到|至)[^.;\n。；]{{0,12}}(?P<end>{lane_pattern})",
    )
    for pattern in patterns:
        match = re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL)
        if not match:
            continue
        start = lane_from_prompt_fragment_v2(match.group("start"), default_start)
        end = lane_from_prompt_fragment_v2(match.group("end"), default_end)
        return start or default_start, end or default_end
    return default_start, default_end


def apply_prompt_obstacle_pedestrian_scene_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    latest_event_s = 0.0
    for obstacle_index, role in enumerate(OBSTACLE_ROLE_ORDER_V2, start=1):
        role_pattern = prompt_obstacle_index_pattern_v2(obstacle_index)
        fragment = prompt_role_fragments_v2(prompt_text, role_pattern)
        if not fragment:
            continue
        config = params.obstacles[role]
        kind, model_name = detect_prompt_obstacle_kind_and_model_v2(fragment)
        lane = extract_role_lane_from_prompt_v2(fragment, role_pattern, "Middle")
        distance_m = extract_prompt_distance_m_v2(fragment, 100.0 + (obstacle_index - 1) * 20.0)
        start_s, end_s = extract_prompt_time_range_s_v2(fragment, 5.0, params.total_experiment_time_s)
        config.enabled = True
        config.kind = kind
        config.lane = lane
        config.gap_m = distance_m
        config.lateral_offset_m = 0.0
        config.start_time_s = start_s
        config.end_time_s = max(end_s, start_s + 1.0)
        config.model_name = model_name
        config.world_locked = False
        config.lock_time_s = 0.0
        latest_event_s = max(latest_event_s, config.end_time_s)

    for pedestrian_index, role in enumerate(PEDESTRIAN_ROLE_ORDER_V2, start=1):
        role_pattern = prompt_pedestrian_index_pattern_v2(pedestrian_index)
        fragment = prompt_role_fragments_v2(prompt_text, role_pattern)
        if not fragment:
            continue
        config = params.pedestrians[role]
        default_config = default_pedestrian_config_v2(role, pedestrian_index)
        start_side, end_side = extract_prompt_crossing_sides_v2(
            fragment,
            default_config.start_side,
            default_config.end_side,
        )
        start_s, _end_s = extract_prompt_time_range_s_v2(
            fragment,
            default_config.start_time_s,
            default_config.start_time_s + default_config.duration_s,
        )
        duration_s = extract_prompt_duration_s_v2(fragment, default_config.duration_s)
        config.enabled = True
        config.gap_m = extract_prompt_distance_m_v2(fragment, default_config.gap_m)
        config.start_side = start_side
        config.end_side = end_side
        config.start_time_s = start_s
        config.duration_s = duration_s
        config.model_name = default_config.model_name
        config.world_locked = False
        config.lock_time_s = 0.0
        latest_event_s = max(latest_event_s, start_s + duration_s)

    if latest_event_s > 0:
        params.total_experiment_time_s = max(params.total_experiment_time_s, latest_event_s + 5.0)


def apply_vehicle1_prompt_scene_v2(
    params: ScenarioParametersV2,
    prompt_text: str,
    *,
    explicit_output: bool,
) -> dict[str, float | str]:
    prompt_text = normalize_cli_prompt_text_v2(prompt_text)
    if not prompt_text:
        raise ValueError("Prompt text is empty.")

    ego = params.vehicles["ego"]
    vehicle1 = params.vehicles["front"]
    ego_speed_kmh = extract_prompt_speed_kmh_v2(prompt_text, ego.speed_kmh)
    explicit_total_time_s = extract_prompt_total_experiment_time_s_v2(prompt_text)
    if explicit_total_time_s is not None:
        params.total_experiment_time_s = max(explicit_total_time_s, 0.1)
    vehicle1_fragment = prompt_role_fragments_v2(prompt_text, PROMPT_VEHICLE1_PATTERN_V2)
    vehicle1_gap_source = vehicle1_fragment if extract_prompt_gap_time_s_v2(vehicle1_fragment) is not None else prompt_text
    gap_time_s = extract_prompt_gap_time_s_v2(vehicle1_gap_source)
    if gap_time_s is not None:
        initial_gap_m = signed_gap_from_time_v2(
            gap_time_s,
            ego_speed_kmh,
            prompt_gap_relation_sign_v2(vehicle1_gap_source, default=1),
        )
    else:
        initial_gap_m = vehicle1.initial_offset_m
        if vehicle1_fragment and prompt_vehicle_fragment_is_behind_v2(vehicle1_fragment):
            initial_gap_m = -abs(initial_gap_m)
    vehicle1_gap_points = extract_prompt_timed_gap_points_v2(vehicle1_fragment or prompt_text, ego_speed_kmh=ego_speed_kmh)

    lane_change_from, lane_change_to = extract_vehicle1_lane_change_lanes_v2(prompt_text)
    ego_lane = extract_role_lane_from_prompt_v2(prompt_text, PROMPT_EGO_PATTERN_V2, ego.initial_lane)
    vehicle1_initial_lane = lane_change_from or extract_role_lane_from_prompt_v2(
        prompt_text,
        PROMPT_VEHICLE1_PATTERN_V2,
        vehicle1.initial_lane,
    )
    lane_change_events = extract_vehicle_lane_change_events_for_role_v2(
        prompt_text,
        PROMPT_VEHICLE1_PATTERN_V2,
        default_initial_lane=vehicle1_initial_lane,
        default_duration_s=5.0,
    )
    if lane_change_events:
        vehicle1_initial_lane = lane_change_events[0].from_lane
        vehicle1_target_lane = lane_change_events[0].target_lane
        lane_change_enabled = True
        lane_change_time_s = lane_change_events[0].time_s
        lane_change_duration_s = lane_change_events[0].duration_s
    else:
        vehicle1_target_lane = lane_change_to or vehicle1_initial_lane
        lane_change_enabled = vehicle1_target_lane != vehicle1_initial_lane
        lane_change_time_s = extract_prompt_lane_change_time_s_v2(prompt_text, vehicle1.lane_change_time_s)
        lane_change_duration_s = extract_prompt_lane_change_duration_s_v2(
            prompt_text,
            5.0 if lane_change_enabled else DEFAULT_NATIVE_LANE_CHANGE_DURATION_V2,
        )

    ego.enabled = True
    ego.initial_offset_m = 0.0
    ego.initial_lane = ego_lane
    ego.speed_kmh = ego_speed_kmh
    ego.lane_change_enabled = False
    ego.lane_change_time_s = 0.0
    ego.lane_change_target_lane = ego_lane
    ego.lane_change_duration_s = DEFAULT_NATIVE_LANE_CHANGE_DURATION_V2
    ego.lane_changes = []
    ego.stop_enabled = False
    ego.gap_points = []

    vehicle1.enabled = True
    vehicle1.initial_offset_m = initial_gap_m
    vehicle1.initial_lane = vehicle1_initial_lane
    vehicle1.speed_kmh = ego_speed_kmh
    vehicle1.lane_change_enabled = lane_change_enabled
    vehicle1.lane_change_time_s = lane_change_time_s
    vehicle1.lane_change_duration_s = lane_change_duration_s
    vehicle1.lane_change_target_lane = vehicle1_target_lane
    vehicle1.lane_changes = lane_change_events
    vehicle1.stop_enabled = False
    vehicle1.gap_points = []
    apply_deceleration_prompt_v2(
        params,
        vehicle1,
        prompt_text,
        ego_speed_kmh=ego_speed_kmh,
        initial_gap_m=initial_gap_m,
        initial_gap_time_s=gap_time_s,
    )
    if vehicle1_gap_points:
        vehicle1.gap_points = vehicle1_gap_points

    for key in ("rear", "left"):
        params.vehicles[key].enabled = False
        params.vehicles[key].lane_change_enabled = False
        params.vehicles[key].lane_changes = []
        params.vehicles[key].stop_enabled = False
        params.vehicles[key].gap_points = []

    for pedestrian in params.pedestrians.values():
        pedestrian.enabled = False
    for obstacle in params.obstacles.values():
        obstacle.enabled = False
    params.extra_vehicles = []
    params.extra_obstacles = []
    apply_extra_vehicle_prompt_scene_v2(
        params,
        prompt_text,
        ego_speed_kmh=ego_speed_kmh,
    )
    apply_prompt_obstacle_pedestrian_scene_v2(params, prompt_text)

    params.audio_events = []
    params.merge = MergeConfigV2(enabled=False)
    params.n_key_intervention.enabled = False
    apply_n_key_intervention_prompt_v2(
        params,
        prompt_text,
        ego_speed_kmh=ego_speed_kmh,
    )
    minimum_total_time_s = explicit_total_time_s if explicit_total_time_s is not None else 30.0
    latest_lane_change_end_s = max(
        (event.time_s + max(event.duration_s, 0.0) for event in lane_change_events),
        default=lane_change_time_s + max(lane_change_duration_s, 0.0),
    )
    params.total_experiment_time_s = max(
        minimum_total_time_s,
        params.total_experiment_time_s,
        latest_lane_change_end_s + 10.0,
        max((point.time_s for point in vehicle1_gap_points), default=0.0) + 10.0,
    )
    if not explicit_output:
        gap_token = (
            f"GAP{filename_number_token_v2(gap_time_s)}S"
            if gap_time_s is not None
            else f"GAP{filename_number_token_v2(initial_gap_m)}M"
        )
        suffix = "CUTIN" if lane_change_enabled else "FOLLOW"
        params.output_filename = normalize_output_filename(
            f"HF_CLI_EGO_{ego_lane.upper()}_VEH1_{vehicle1_initial_lane.upper()}_{gap_token}_{suffix}.sce"
        )

    return {
        "ego_lane": ego_lane,
        "ego_speed_kmh": ego_speed_kmh,
        "vehicle1_initial_lane": vehicle1_initial_lane,
        "vehicle1_target_lane": vehicle1_target_lane,
        "gap_time_s": gap_time_s if gap_time_s is not None else "",
        "initial_gap_m": initial_gap_m,
        "lane_change_time_s": lane_change_time_s,
        "lane_change_duration_s": lane_change_duration_s,
    }


def read_cli_prompt_text_v2(args: argparse.Namespace) -> str:
    prompt_parts: list[str] = []
    if getattr(args, "prompt", None):
        prompt_parts.append(str(args.prompt))
    if getattr(args, "prompt_file", None):
        prompt_file = Path(args.prompt_file)
        if prompt_file.suffix.lower() == ".sce":
            prompt_parts.append(prompt_text_from_sce_v2(prompt_file, getattr(args, "template", None)))
        else:
            prompt_parts.append(prompt_file.read_text(encoding="utf-8"))
    if getattr(args, "stdin_prompt", False):
        prompt_parts.append(sys.stdin.read())
    return "\n".join(part for part in prompt_parts if part.strip())


def detach_ego_shared_driving_v2(output_path: Path) -> None:
    tree = ET.parse(output_path)
    scenario = tree.getroot().find("Scenario")
    if scenario is None:
        raise ValueError("Generated scenario is missing <Scenario>.")
    ego_driver = find_driver_by_id(scenario, 0)
    set_child_text_v2(ego_driver, "TrafficDriver/activateSharedDriving", "0")
    set_child_text_v2(ego_driver, "TrafficDriver/gasPedalThreashold", "0.99")
    set_child_text_v2(ego_driver, "TrafficDriver/steeringTorqueThreashold", "1000")
    tree.write(output_path, encoding="utf-8", xml_declaration=True, short_empty_elements=False)
    normalize_written_xml(output_path)


def summarize_prompt_params_v2(params: ScenarioParametersV2) -> list[str]:
    lines: list[str] = []
    lines.append(f"Scenario duration: {format_number(params.total_experiment_time_s)} s")
    ego = params.vehicles["ego"]
    lines.append(f"Ego: lane={ego.initial_lane}, speed={format_number(ego.speed_kmh)} km/h")
    ego_lane_events = lane_change_events_for_vehicle_v2(ego)
    if ego_lane_events:
        for event in ego_lane_events:
            lines.append(
                "Ego lane change: "
                f"{event.from_lane} -> {event.target_lane} "
                f"at {format_number(event.time_s)} s "
                f"over {format_number(event.duration_s)} s"
            )
    for config in iter_script_vehicle_configs_v2(params):
        if config.key == "ego" or not vehicle_enabled_v2(config):
            continue
        relation = "ahead" if config.initial_offset_m >= 0 else "behind"
        lines.append(
            f"{config.label}: lane={config.initial_lane}, {relation} {format_number(abs(config.initial_offset_m))} m, "
            f"speed={format_number(config.speed_kmh)} km/h"
        )
        lane_events = lane_change_events_for_vehicle_v2(config)
        for event_index, event in enumerate(lane_events, start=1):
            event_label = "lane change" if len(lane_events) == 1 else f"lane change {event_index}"
            lines.append(
                f"  {event_label}: {event.from_lane} -> {event.target_lane} "
                f"at {format_number(event.time_s)} s "
                f"over {format_number(event.duration_s)} s"
            )
        if config.gap_points:
            schedule = ", ".join(
                f"{format_number(point.time_s)} s -> {format_number(point.gap_m)} m"
                for point in config.gap_points
            )
            lines.append(f"  gap schedule: {schedule}")
        if config.stop_enabled:
            lines.append(f"  stop/decelerate at {format_number(config.stop_time_s)} s")
    for obstacle in iter_obstacle_configs_v2(params):
        if obstacle.enabled:
            lines.append(
                f"{obstacle.label}: {obstacle.kind}/{obstacle.model_name}, lane={obstacle.lane}, "
                f"gap={format_number(obstacle.gap_m)} m, active {format_number(obstacle.start_time_s)}-"
                f"{format_number(obstacle.end_time_s)} s"
            )
    if params.audio_events:
        lines.append(
            "Audio/TOR: "
            + "; ".join(f"{format_number(event.time_s)} s:{event.file_name}" for event in params.audio_events)
        )
    for note in params.scene_notes[:16]:
        lines.append(f"Note: {note}")
    if len(params.scene_notes) > 16:
        lines.append(f"Note: ... {len(params.scene_notes) - 16} more metadata notes")
    if params.terrain_override_name:
        lines.append(f"Terrain override: {params.terrain_override_name}")
    return lines


def prompt_block_header_v2(title: str) -> str:
    return f"=== {title} ==="


def prompt_preview_language_v2(prompt_text: str) -> str:
    return "zh" if re.search(r"[\u4e00-\u9fff]", prompt_text) else "en"


def prompt_text_v2(language: str, en_text: str, zh_text: str) -> str:
    return zh_text if language == "zh" else en_text


def prompt_lane_text_v2(lane: str, language: str) -> str:
    if language != "zh":
        return lane
    return {
        "Left": "左側車道",
        "Middle": "中間車道",
        "Right": "右側車道",
    }.get(lane, lane)


def prompt_relation_text_v2(relation: str, language: str) -> str:
    if language != "zh":
        return relation
    return {
        "ahead": "前方",
        "behind": "後方",
    }.get(relation, relation)


def prompt_actor_label_text_v2(label: str, language: str) -> str:
    if language != "zh":
        return label
    fixed_labels = {
        "Ego Vehicle": "Ego 車輛",
        "Front Vehicle": "前方車輛",
        "Rear Vehicle": "後方車輛",
        "Left Vehicle": "左側車輛",
        "Right Vehicle": "右側車輛",
    }
    if label in fixed_labels:
        return fixed_labels[label]
    match = re.fullmatch(r"Vehicle\s*(\d+)", label, flags=re.IGNORECASE)
    if match:
        return f"車輛 {match.group(1)}"
    match = re.fullmatch(r"Obstacle\s*(\d+)", label, flags=re.IGNORECASE)
    if match:
        return f"障礙物 {match.group(1)}"
    match = re.fullmatch(r"Pedestrian\s*(\d+)", label, flags=re.IGNORECASE)
    if match:
        return f"行人 {match.group(1)}"
    return label


def prompt_gap_summary_v2(gap_m: float, speed_kmh: float, language: str) -> str:
    if speed_kmh <= 0:
        return f"{format_number(abs(gap_m))} m"
    gap_s = abs(gap_m) / max(speed_kmh / 3.6, 0.001)
    return f"{format_number(abs(gap_m))} m / {format_number(gap_s)} s"


def prompt_dsl_lane_token_from_name_v2(lane: str) -> str:
    return str(lane or "middle").strip().lower()


def prompt_dsl_speed_token_v2(speed_kmh: float) -> str:
    speed_mph = speed_kmh / MPH_TO_KMH_V2
    rounded_mph = round(speed_mph)
    if abs(speed_mph - rounded_mph) < 0.05:
        return f"{format_number(float(rounded_mph))}mph"
    return f"{format_number(speed_kmh)}kmh"


def prompt_dsl_gap_time_token_v2(gap_m: float, ego_speed_kmh: float) -> str:
    ego_speed_mps = max(kmh_to_mps_v2(ego_speed_kmh), 0.001)
    return f"{format_number(abs(gap_m) / ego_speed_mps)}s"


def prompt_dsl_vehicle_token_v2(config: VehicleConfigV2, fallback_index: int, used_tokens: set[str]) -> str:
    label_match = re.fullmatch(r"Vehicle\s*(\d+)", str(config.label), flags=re.IGNORECASE)
    key_match = re.fullmatch(r"prompt_vehicle_(\d+)", str(config.key), flags=re.IGNORECASE)
    if label_match:
        candidate = f"v{int(label_match.group(1))}"
    elif key_match:
        candidate = f"v{int(key_match.group(1))}"
    elif config.key == "front":
        candidate = "v1"
    else:
        candidate = f"v{fallback_index}"
    while candidate in used_tokens:
        fallback_index += 1
        candidate = f"v{fallback_index}"
    used_tokens.add(candidate)
    return candidate


def build_timeline_sorted_prompt_for_params_v2(params: ScenarioParametersV2) -> list[str]:
    ego = params.vehicles["ego"]
    ego_speed_kmh = max(float(ego.speed_kmh), 0.0)
    lines: list[str] = [
        f"scenario duration={format_number(params.total_experiment_time_s)}s",
        f"ego: lane={prompt_dsl_lane_token_from_name_v2(ego.initial_lane)}, speed={prompt_dsl_speed_token_v2(ego.speed_kmh)}"
    ]
    events: list[tuple[float, str, int]] = []
    event_index = 0
    used_vehicle_tokens: set[str] = set()
    next_vehicle_index = 1

    def add_event(time_s: float, line: str) -> None:
        nonlocal event_index
        events.append((float(time_s), line, event_index))
        event_index += 1

    for config in iter_script_vehicle_configs_v2(params):
        if config.key == "ego" or not vehicle_enabled_v2(config):
            continue
        token = prompt_dsl_vehicle_token_v2(config, next_vehicle_index, used_vehicle_tokens)
        match = re.fullmatch(r"v(\d+)", token)
        if match:
            next_vehicle_index = max(next_vehicle_index, int(match.group(1)) + 1)
        relation = "ahead" if config.initial_offset_m >= 0 else "behind"
        gap_token = prompt_dsl_gap_time_token_v2(config.initial_offset_m, ego_speed_kmh)
        lines.append(
            f"{token}: lane={prompt_dsl_lane_token_from_name_v2(config.initial_lane)}, "
            f"{relation}={gap_token}, speed={prompt_dsl_speed_token_v2(config.speed_kmh)}"
        )
        for lane_event in lane_change_events_for_vehicle_v2(config):
            add_event(
                lane_event.time_s,
                (
                    f"t={format_number(lane_event.time_s)}s: {token} "
                    f"{prompt_dsl_lane_token_from_name_v2(lane_event.from_lane)} -> "
                    f"{prompt_dsl_lane_token_from_name_v2(lane_event.target_lane)}, "
                    f"duration={format_number(lane_event.duration_s)}s"
                ),
            )
        for point in config.gap_points:
            point_relation = "ahead" if point.gap_m >= 0 else "behind"
            point_gap = prompt_dsl_gap_time_token_v2(point.gap_m, ego_speed_kmh)
            add_event(point.time_s, f"t={format_number(point.time_s)}s: {token} {point_relation}={point_gap}")
        if config.stop_enabled:
            add_event(
                config.stop_time_s,
                f"t={format_number(config.stop_time_s)}s: source_event {token} halt_time={format_number(config.stop_time_s)}s",
            )

    obstacle_index = 1
    for obstacle in iter_obstacle_configs_v2(params):
        if not obstacle.enabled:
            continue
        add_event(
            obstacle.start_time_s,
            (
                f"t={format_number(obstacle.start_time_s)}s: obstacle{obstacle_index} {obstacle.kind}, "
                f"lane={prompt_dsl_lane_token_from_name_v2(obstacle.lane)}, "
                f"{format_number(obstacle.gap_m)}m, end={format_number(obstacle.end_time_s)}s"
            ),
        )
        obstacle_index += 1

    pedestrian_index = 1
    for role in PEDESTRIAN_ROLE_ORDER_V2:
        pedestrian = params.pedestrians.get(role)
        if pedestrian is None or not pedestrian.enabled:
            continue
        add_event(
            pedestrian.start_time_s,
            (
                f"t={format_number(pedestrian.start_time_s)}s: ped{pedestrian_index} "
                f"{prompt_dsl_lane_token_from_name_v2(pedestrian.start_side)} -> "
                f"{prompt_dsl_lane_token_from_name_v2(pedestrian.end_side)}, "
                f"{format_number(pedestrian.gap_m)}m, duration={format_number(pedestrian.duration_s)}s"
            ),
        )
        pedestrian_index += 1

    for event in params.audio_events:
        add_event(event.time_s, f"TOR at {format_number(event.time_s)}s with audio {event.file_name}")

    if n_key_intervention_enabled_v2(params):
        n_key = params.n_key_intervention
        lane_change_vehicle = params.vehicles.get(n_key.lane_change_vehicle_key)
        base_time_s = lane_change_base_time_s_v2(lane_change_vehicle) if lane_change_vehicle else 0.0
        window_start_s = base_time_s + n_key.window_start_offset_s
        window_end_s = base_time_s + n_key.window_end_offset_s
        add_event(
            window_start_s,
            (
                "N-key intervention: "
                f"valid from {format_number(window_start_s)}s to {format_number(window_end_s)}s, "
                f"ego slows {format_number(n_key.ego_speed_delta_mph)}mph, "
                f"return merge after press+{format_number(n_key.delayed_merge_offset_s)}s"
            ),
        )

    if events:
        lines.append("")
        lines.extend(line for _time_s, line, _index in sorted(events, key=lambda item: (item[0], item[2])))
    return lines


def build_timeline_sorted_prompt_v2(route: str, params_list: list[ScenarioParametersV2]) -> str:
    del route
    if len(params_list) <= 1:
        return "\n".join(build_timeline_sorted_prompt_for_params_v2(params_list[0])).strip() + "\n"
    blocks: list[str] = []
    for index, params in enumerate(params_list, start=1):
        blocks.append(f"Scenario {index}:")
        blocks.extend(build_timeline_sorted_prompt_for_params_v2(params))
        blocks.append("")
    return "\n".join(blocks).strip() + "\n"


def prompt_line_sort_time_s_v2(line: str) -> float | None:
    text = normalize_cli_prompt_text_v2(line)
    patterns = (
        rf"^(?:t|time)\s*=?\s*(?P<number>{PROMPT_NUMBER_VALUE_PATTERN_V2})\s*(?:{PROMPT_TIME_UNIT_PATTERN_V2})?\s*[:：]",
        rf"(?:^|\b)(?:at|after|around)\s+(?P<number>{PROMPT_NUMBER_VALUE_PATTERN_V2})\s*(?:{PROMPT_TIME_UNIT_PATTERN_V2})\b",
        rf"(?:第|在|於|于)\s*(?P<number>{PROMPT_NUMBER_VALUE_PATTERN_V2})\s*(?:{PROMPT_TIME_UNIT_PATTERN_V2})",
        rf"(?:啟動|启动|開始|开始|scenario\s+start\w*)[^.;\n。；]{{0,16}}?(?P<number>{PROMPT_NUMBER_VALUE_PATTERN_V2})\s*(?:{PROMPT_TIME_UNIT_PATTERN_V2})",
    )
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            try:
                return parse_prompt_number_v2(match.group("number"))
            except ValueError:
                return None
    return None


def sort_prompt_line_block_by_timeline_v2(prompt_text: str) -> str:
    prefix_lines: list[tuple[int, str]] = []
    timed_lines: list[tuple[float, int, str]] = []
    for index, raw_line in enumerate(prompt_text.splitlines()):
        line = raw_line.rstrip()
        if not line.strip():
            continue
        time_s = prompt_line_sort_time_s_v2(line)
        if time_s is None:
            prefix_lines.append((index, line))
        else:
            timed_lines.append((time_s, index, line))
    output_lines = [line for _index, line in prefix_lines]
    if output_lines and timed_lines:
        output_lines.append("")
    output_lines.extend(line for _time_s, _index, line in sorted(timed_lines, key=lambda item: (item[0], item[1])))
    return "\n".join(output_lines).strip() + ("\n" if output_lines else "")


def sort_prompt_lines_by_timeline_v2(prompt_text: str) -> str:
    lines = prompt_text.splitlines()
    sections: list[list[str]] = []
    current: list[str] = []
    scenario_header_re = re.compile(r"^\s*(?:scenario|scene|case|trial|drive|場景|情境)\s*\d+\s*[:：-]?", flags=re.IGNORECASE)
    for line in lines:
        if scenario_header_re.match(line) and current:
            sections.append(current)
            current = [line]
        else:
            current.append(line)
    if current:
        sections.append(current)
    if len(sections) <= 1:
        return sort_prompt_line_block_by_timeline_v2(prompt_text)
    sorted_sections = [sort_prompt_line_block_by_timeline_v2("\n".join(section)).strip() for section in sections]
    return "\n\n".join(section for section in sorted_sections if section).strip() + "\n"


def build_prompt_quick_edit_table_v2(params: ScenarioParametersV2, *, language: str = "en") -> list[str]:
    is_zh = language == "zh"
    if is_zh:
        lines = [
            "類型 | 名稱 | 車道/路徑 | 時間 | 速度/距離 | 動作",
            "--- | --- | --- | --- | --- | ---",
        ]
    else:
        lines = [
            "type | name | lane/path | timing | speed/gap | action",
            "--- | --- | --- | --- | --- | ---",
        ]
    none_text = "無" if is_zh else "none"
    hold_text = "維持" if is_zh else "hold"
    vehicle_type = "車輛" if is_zh else "vehicle"
    obstacle_type = "障礙物" if is_zh else "obstacle"
    pedestrian_type = "行人" if is_zh else "pedestrian"
    event_type = "事件" if is_zh else "event"
    crossing_text = "穿越" if is_zh else "crossing"
    lane_change_text = "變道" if is_zh else "LC"
    decel_text = "減速/停止" if is_zh else "decel/stop"
    ego_config = params.vehicles.get("ego")
    ego_speed_kmh = max(ego_config.speed_kmh if ego_config is not None else 0.0, 0.0)

    for config in iter_script_vehicle_configs_v2(params):
        if not vehicle_enabled_v2(config):
            continue
        label = prompt_actor_label_text_v2(config.label, language)
        lane = prompt_lane_text_v2(config.initial_lane, language)
        timing = "t=0 s"
        if config.key == "ego":
            gap_text = "-"
        else:
            relation = "ahead" if config.initial_offset_m >= 0 else "behind"
            relation_text = prompt_relation_text_v2(relation, language)
            gap_text = f"{relation_text} {prompt_gap_summary_v2(config.initial_offset_m, ego_speed_kmh, language)}"
        speed_gap = f"{format_number(config.speed_kmh)} km/h, {gap_text}"
        actions: list[str] = []
        for lane_event in lane_change_events_for_vehicle_v2(config):
            actions.append(
                f"{lane_change_text} {prompt_lane_text_v2(lane_event.from_lane, language)} -> "
                f"{prompt_lane_text_v2(lane_event.target_lane, language)} "
                f"@ {format_number(lane_event.time_s)} s / {format_number(lane_event.duration_s)} s"
            )
        if config.stop_enabled:
            actions.append(f"{decel_text} @ {format_number(config.stop_time_s)} s")
        if config.gap_points:
            actions.append(
                "gap "
                + ", ".join(
                    f"{format_number(point.time_s)} s={format_number(point.gap_m)} m"
                    for point in config.gap_points[:4]
                )
            )
        lines.append(f"{vehicle_type} | {label} | {lane} | {timing} | {speed_gap} | {'; '.join(actions) or hold_text}")

    obstacle_rows = 0
    for obstacle in iter_obstacle_configs_v2(params):
        if not obstacle.enabled:
            continue
        obstacle_rows += 1
        label = prompt_actor_label_text_v2(obstacle.label, language)
        lane = prompt_lane_text_v2(obstacle.lane, language)
        timing = f"{format_number(obstacle.start_time_s)}-{format_number(obstacle.end_time_s)} s"
        gap_text = f"{format_number(obstacle.gap_m)} m"
        lines.append(f"{obstacle_type} | {label} | {lane} | {timing} | {gap_text} | {obstacle.kind}/{obstacle.model_name}")

    pedestrian_rows = 0
    for role in PEDESTRIAN_ROLE_ORDER_V2:
        pedestrian = params.pedestrians.get(role)
        if pedestrian is None or not pedestrian.enabled:
            continue
        pedestrian_rows += 1
        label = prompt_actor_label_text_v2(pedestrian.label, language)
        path = f"{pedestrian.start_side} -> {pedestrian.end_side}"
        timing = f"{format_number(pedestrian.start_time_s)} s / {format_number(pedestrian.duration_s)} s"
        gap_text = f"{format_number(pedestrian.gap_m)} m"
        lines.append(f"{pedestrian_type} | {label} | {path} | {timing} | {gap_text} | {crossing_text}")

    if obstacle_rows == 0 and pedestrian_rows == 0:
        lines.append(f"{event_type} | {none_text} | - | - | - | -")
    return lines


def build_prompt_param_blocks_v2(
    route: str,
    params_list: list[ScenarioParametersV2],
    *,
    language: str = "en",
) -> list[str]:
    params = params_list[0]
    ego = params.vehicles["ego"]
    blocks: list[str] = []
    is_zh = language == "zh"
    lane_label = "車道" if is_zh else "lane"
    speed_label = "速度" if is_zh else "speed"
    none_text = "無" if is_zh else "none"

    blocks.extend(
        (
            prompt_block_header_v2(prompt_text_v2(language, "1. Scene Route", "1. 場景路由")),
            f"{prompt_text_v2(language, 'Route', '路由')}: {route}",
            f"{prompt_text_v2(language, 'Scenario count', '場景數量')}: {len(params_list)}",
            f"{prompt_text_v2(language, 'Showing', '目前預覽')}: {params.output_filename}",
            prompt_text_v2(
                language,
                "Edit this by changing study type / event description / output name in the prompt or Output field.",
                "要修改這段：請回左邊 prompt 調整 study type / event description / output name，或改上方 Output 欄位。",
            ),
            "",
        )
    )

    blocks.append(prompt_block_header_v2(prompt_text_v2(language, "2. Output Files", "2. 輸出檔案")))
    for name in [item.output_filename for item in params_list[:20]]:
        blocks.append(f"- {name}")
    if len(params_list) > 20:
        blocks.append(f"- ... {len(params_list) - 20} {prompt_text_v2(language, 'more', '個未顯示')}")
    blocks.extend(
        (
            prompt_text_v2(
                language,
                "Edit this by changing the Output field or variant selection words.",
                "要修改這段：請改上方 Output 欄位，或在 prompt 補充 variant / generate both / fixed seed 等字樣。",
            ),
            "",
        )
    )

    blocks.append(prompt_block_header_v2(prompt_text_v2(language, "2A. Quick Edit Table", "2A. 快速修改表")))
    blocks.extend(build_prompt_quick_edit_table_v2(params, language=language))
    blocks.extend(
        (
            prompt_text_v2(
                language,
                "Edit one row by changing the matching actor line in the prompt, for example 'v1: lane=left, behind=5s'.",
                "要修改某一列：請回到 prompt 改對應 actor，例如「v1: lane=left, behind=5s」。",
            ),
            "",
        )
    )

    blocks.extend(
        (
            prompt_block_header_v2(prompt_text_v2(language, "3. Ego Vehicle", "3. Ego 車輛")),
            f"{prompt_text_v2(language, 'Lane', '車道')}: {prompt_lane_text_v2(ego.initial_lane, language)}",
            f"{prompt_text_v2(language, 'Speed', '速度')}: {format_number(ego.speed_kmh)} km/h",
        )
    )
    ego_lane_events = lane_change_events_for_vehicle_v2(ego)
    if ego_lane_events:
        for event in ego_lane_events:
            blocks.append(
                f"{prompt_text_v2(language, 'Lane change', '變道')}: "
                f"{prompt_lane_text_v2(event.from_lane, language)} -> "
                f"{prompt_lane_text_v2(event.target_lane, language)} "
                f"{prompt_text_v2(language, 'at', '在')} {format_number(event.time_s)} s "
                f"{prompt_text_v2(language, 'over', '歷時')} {format_number(event.duration_s)} s"
            )
    else:
        blocks.append(f"{prompt_text_v2(language, 'Lane change', '變道')}: {none_text}")
    blocks.extend(
        (
            prompt_text_v2(
                language,
                "Edit this by changing ego/AV lane, speed, or ego takeover behavior.",
                "要修改這段：請調整 ego/AV 的車道、速度，或接管/自動駕駛反應。",
            ),
            "",
        )
    )

    blocks.append(prompt_block_header_v2(prompt_text_v2(language, "4. Other Vehicles", "4. 其他車輛")))
    other_vehicle_count = 0
    for config in iter_script_vehicle_configs_v2(params):
        if config.key == "ego" or not vehicle_enabled_v2(config):
            continue
        other_vehicle_count += 1
        relation = "ahead" if config.initial_offset_m >= 0 else "behind"
        blocks.append(
            f"- {prompt_actor_label_text_v2(config.label, language)}: {lane_label}={prompt_lane_text_v2(config.initial_lane, language)}, "
            f"{prompt_relation_text_v2(relation, language)} {format_number(abs(config.initial_offset_m))} m, "
            f"{speed_label}={format_number(config.speed_kmh)} km/h"
        )
        lane_events = lane_change_events_for_vehicle_v2(config)
        for event_index, event in enumerate(lane_events, start=1):
            event_name = prompt_text_v2(language, "lane change", "變道")
            if len(lane_events) > 1:
                event_name = f"{event_name} {event_index}"
            blocks.append(
                f"  {prompt_text_v2(language, 'action', '動作')}: "
                f"{event_name} "
                f"{prompt_lane_text_v2(event.from_lane, language)} -> "
                f"{prompt_lane_text_v2(event.target_lane, language)} "
                f"{prompt_text_v2(language, 'at', '在')} {format_number(event.time_s)} s "
                f"{prompt_text_v2(language, 'over', '歷時')} {format_number(event.duration_s)} s"
            )
        if config.gap_points:
            blocks.append(
                f"  {prompt_text_v2(language, 'gap schedule', '間距排程')}: "
                + ", ".join(
                    f"{format_number(point.time_s)} s -> {format_number(point.gap_m)} m"
                    for point in config.gap_points
                )
            )
        if config.stop_enabled:
            blocks.append(
                f"  {prompt_text_v2(language, 'action', '動作')}: "
                f"{prompt_text_v2(language, 'stop/decelerate at', '停止/減速時間')} "
                f"{format_number(config.stop_time_s)} s"
            )
    if other_vehicle_count == 0:
        blocks.append(f"- {none_text}")
    blocks.extend(
        (
            prompt_text_v2(
                language,
                "Edit this by changing vehicle 1 / lead vehicle / rear vehicle lane, gap, speed, or action wording.",
                "要修改這段：請調整 vehicle 1 / lead vehicle / rear vehicle 的車道、gap、速度或動作描述。",
            ),
            "",
        )
    )

    blocks.append(prompt_block_header_v2(prompt_text_v2(language, "5. Obstacles / Road Events", "5. 障礙物 / 道路事件")))
    obstacle_count = 0
    for obstacle in iter_obstacle_configs_v2(params):
        if not obstacle.enabled:
            continue
        obstacle_count += 1
        blocks.append(
            f"- {prompt_actor_label_text_v2(obstacle.label, language)}: {obstacle.kind}/{obstacle.model_name}, "
            f"{lane_label}={prompt_lane_text_v2(obstacle.lane, language)}, "
            f"gap={format_number(obstacle.gap_m)} m, "
            f"{prompt_text_v2(language, 'active', '出現時間')} {format_number(obstacle.start_time_s)}-"
            f"{format_number(obstacle.end_time_s)} s"
        )
    if obstacle_count == 0:
        blocks.append(f"- {none_text}")
    blocks.extend(
        (
            prompt_text_v2(
                language,
                "Edit this by changing obstacle, construction zone, bicyclist, police vehicle, or event wording.",
                "要修改這段：請調整 obstacle、construction zone、bicyclist、police vehicle 或事件描述。",
            ),
            "",
        )
    )

    blocks.append(prompt_block_header_v2(prompt_text_v2(language, "6. Alerts / Audio / TOR", "6. 警示 / 音效 / TOR")))
    if params.audio_events:
        for event in params.audio_events:
            blocks.append(f"- {format_number(event.time_s)} s: {event.file_name}")
    else:
        blocks.append(f"- {none_text}")
    blocks.extend(
        (
            prompt_text_v2(
                language,
                "Edit this by changing alert, TOR, chime, audio, cue, or takeover request wording.",
                "要修改這段：請調整 alert、TOR、chime、audio、cue 或 takeover request 的描述。",
            ),
            "",
        )
    )

    blocks.append(prompt_block_header_v2(prompt_text_v2(language, "7. N-Key Intervention", "7. N 鍵介入")))
    if n_key_intervention_enabled_v2(params):
        n_key = params.n_key_intervention
        lane_change_vehicle = params.vehicles[n_key.lane_change_vehicle_key]
        base_time_s = lane_change_base_time_s_v2(lane_change_vehicle)
        window_start_s = base_time_s + n_key.window_start_offset_s
        window_end_s = base_time_s + n_key.window_end_offset_s
        blocks.extend(
            (
                f"{prompt_text_v2(language, 'Key', '按鍵')}: {n_key.key_name}",
                (
                    f"{prompt_text_v2(language, 'Valid window', '有效按鍵時間')}: "
                    f"{format_number(window_start_s)}-{format_number(window_end_s)} s "
                    f"(LC+{format_number(n_key.window_start_offset_s)} to LC+{format_number(n_key.window_end_offset_s)})"
                ),
                (
                    f"{prompt_text_v2(language, 'Ego slowdown', 'Ego 減速目標')}: "
                    f"{format_number(n_key.ego_speed_delta_mph)} mph "
                    f"{prompt_text_v2(language, 'slower than', '慢於')} {n_key.reference_vehicle_key}"
                ),
                (
                    f"{prompt_text_v2(language, 'Return lane change', '回切動作')}: "
                    f"{n_key.merge_vehicle_key} -> {prompt_lane_text_v2(n_key.merge_target_lane, language)} "
                    f"@ {prompt_text_v2(language, 'press', '按鍵')}+{format_number(n_key.delayed_merge_offset_s)} s"
                ),
                (
                    f"{prompt_text_v2(language, 'Ego restore speed', 'Ego 恢復速度')}: "
                    f"{format_number(n_key.restore_ego_speed_kmh or params.vehicles['ego'].speed_kmh)} km/h"
                ),
            )
        )
    else:
        blocks.append(f"- {none_text}")
    blocks.extend(
        (
            prompt_text_v2(
                language,
                "Edit this by changing N key, press window, slower-than speed, return lane, or press+ delay wording.",
                "要修改這段：請調整 N 鍵、按鍵時間窗、慢幾 mph、回切車道或 press+ 延遲描述。",
            ),
            "",
        )
    )

    blocks.append(prompt_block_header_v2(prompt_text_v2(language, "8. Timeline", "8. 時間軸")))
    timeline_rows: list[tuple[float, str]] = [(0.0, prompt_text_v2(language, "scenario start", "場景開始"))]
    for config in iter_script_vehicle_configs_v2(params):
        if not vehicle_enabled_v2(config):
            continue
        lane_events = lane_change_events_for_vehicle_v2(config)
        for event_index, event in enumerate(lane_events, start=1):
            event_suffix = "" if len(lane_events) == 1 else f" {event_index}"
            timeline_rows.append(
                (
                    event.time_s,
                    f"{prompt_actor_label_text_v2(config.label, language)} "
                    f"{prompt_text_v2(language, 'lane change starts', '開始變道')}{event_suffix}",
                )
            )
            if event.duration_s > 0:
                timeline_rows.append(
                    (
                        event.time_s + event.duration_s,
                        f"{prompt_actor_label_text_v2(config.label, language)} "
                        f"{prompt_text_v2(language, 'lane change ends', '完成變道')}{event_suffix}",
                    )
                )
        if config.stop_enabled:
            timeline_rows.append(
                (
                    config.stop_time_s,
                    f"{prompt_actor_label_text_v2(config.label, language)} {prompt_text_v2(language, 'stop/decelerate', '停止/減速')}",
                )
            )
        for index, point in enumerate(config.gap_points, start=1):
            timeline_rows.append(
                (
                    point.time_s,
                    f"{prompt_actor_label_text_v2(config.label, language)} {prompt_text_v2(language, 'gap point', '間距控制點')} {index}",
                )
            )
    for obstacle in iter_obstacle_configs_v2(params):
        if obstacle.enabled:
            timeline_rows.append(
                (
                    obstacle.start_time_s,
                    f"{prompt_actor_label_text_v2(obstacle.label, language)} {prompt_text_v2(language, 'appears', '出現')}",
                )
            )
    for event in params.audio_events:
        timeline_rows.append((event.time_s, f"{prompt_text_v2(language, 'audio/TOR', '音效/TOR')} {event.file_name}"))
    if n_key_intervention_enabled_v2(params):
        n_key = params.n_key_intervention
        lane_change_vehicle = params.vehicles[n_key.lane_change_vehicle_key]
        base_time_s = lane_change_base_time_s_v2(lane_change_vehicle)
        timeline_rows.append(
            (
                base_time_s + n_key.window_start_offset_s,
                prompt_text_v2(language, "N-key valid window starts", "N 鍵有效時間開始"),
            )
        )
        timeline_rows.append(
            (
                base_time_s + n_key.window_end_offset_s,
                prompt_text_v2(language, "N-key valid window ends", "N 鍵有效時間結束"),
            )
        )
    timeline_rows.append((params.total_experiment_time_s, prompt_text_v2(language, "scenario end", "場景結束")))
    for time_s, label in sorted(timeline_rows, key=lambda item: item[0]):
        blocks.append(f"- t={format_number(time_s)} s: {label}")
    blocks.extend(
        (
            prompt_text_v2(
                language,
                "Edit this by changing time words such as 'at 5 seconds', lead time, or duration.",
                "要修改這段：請調整像「第 5 秒」、lead time、duration、initial 60 s 這類時間描述。",
            ),
            "",
        )
    )

    if params.scene_notes:
        blocks.append(prompt_block_header_v2(prompt_text_v2(language, "9. Study / Metadata Notes", "9. 研究 / Metadata 備註")))
        for note in params.scene_notes[:18]:
            blocks.append(f"- {note}")
        if len(params.scene_notes) > 18:
            blocks.append(f"- ... {len(params.scene_notes) - 18} {prompt_text_v2(language, 'more', '個未顯示')}")
        blocks.extend(
            (
                prompt_text_v2(
                    language,
                    "Edit this by changing study design, group, variant, or implementation lines.",
                    "要修改這段：請調整 study design、group、variant 或 implementation 相關描述。",
                ),
                "",
            )
        )

    return blocks


def summarize_prompt_params_list_v2(
    route: str,
    params_list: list[ScenarioParametersV2],
    *,
    language: str = "en",
) -> str:
    if not params_list:
        return prompt_text_v2(language, "No scenario parameters were produced.", "沒有產生任何場景參數。")
    lines = [
        prompt_text_v2(
            language,
            "Analysis complete. Review these blocks before generating.",
            "解析完成。生成前請先檢查以下區塊。",
        ),
        "",
    ]
    lines.extend(build_prompt_param_blocks_v2(route, params_list, language=language))
    return "\n".join(lines)


def split_scenario_batch_blocks_v2(prompt_text: str) -> list[tuple[int, str, str]]:
    header_pattern = re.compile(
        r"(?im)^\s*(?:scenario|scene|case|trial|drive|場景|情境)\s*(?P<number>\d+)"
        r"\s*(?:[:：\-–—]\s*(?P<title>[^\n\r]*))?\s*$"
    )
    matches = list(header_pattern.finditer(prompt_text))
    if len(matches) < 2:
        inline_pattern = re.compile(
            r"(?i)(?<!\w)(?:scenario|scene|case|trial|drive|場景|情境)\s*(?P<number>\d+)\s*[:：\-–—]\s*"
        )
        inline_matches = list(inline_pattern.finditer(prompt_text))
        if len(inline_matches) < 2:
            return []
        shared_text = prompt_text[: inline_matches[0].start()].strip()
        blocks: list[tuple[int, str, str]] = []
        for index, match in enumerate(inline_matches):
            next_start = inline_matches[index + 1].start() if index + 1 < len(inline_matches) else len(prompt_text)
            number = int(match.group("number"))
            body = prompt_text[match.end() : next_start].strip(" \t\r\n.;")
            parts = []
            if shared_text:
                parts.append(shared_text)
            parts.append(f"Scenario {number}")
            if body:
                parts.append(body)
            blocks.append((number, "", "\n\n".join(parts)))
        return blocks
    shared_text = prompt_text[: matches[0].start()].strip()
    blocks: list[tuple[int, str, str]] = []
    for index, match in enumerate(matches):
        next_start = matches[index + 1].start() if index + 1 < len(matches) else len(prompt_text)
        number = int(match.group("number"))
        title = (match.group("title") or "").strip()
        body = prompt_text[match.end() : next_start].strip()
        if title and not body:
            body = title
            title = ""
        parts = []
        if shared_text:
            parts.append(shared_text)
        header_text = f"Scenario {number}"
        if title:
            header_text += f": {title}"
        parts.append(header_text)
        if body:
            parts.append(body)
        blocks.append((number, title, "\n\n".join(parts)))
    return blocks


def batch_output_filename_v2(requested_output: str, block_number: int, *, explicit_output: bool) -> str:
    if explicit_output:
        base_stem = Path(normalize_output_filename(requested_output)).stem
    else:
        base_stem = "HF_PROMPT_BATCH"
    return normalize_output_filename(f"{base_stem}_S{block_number:02d}.sce")


def prompt_has_pattern_v2(prompt_text: str, pattern: str) -> bool:
    return re.search(pattern, prompt_text, flags=re.IGNORECASE | re.DOTALL) is not None


def prompt_has_explicit_speed_v2(prompt_text: str) -> bool:
    return prompt_has_pattern_v2(
        prompt_text,
        rf"{PROMPT_NUMBER_VALUE_PATTERN_V2}\s*(?:mph|miles?\s*(?:per|an)?\s*hour|miles?/h|mi/h|km/h|kmh|kph|"
        rf"kilometers?\s*per\s*hour|kilometres?\s*per\s*hour|\u82f1\u91cc|\u516c\u91cc)",
    )


def prompt_has_explicit_gap_or_distance_v2(prompt_text: str) -> bool:
    if extract_prompt_gap_time_s_v2(prompt_text) is not None:
        return True
    return prompt_has_pattern_v2(
        prompt_text,
        rf"{PROMPT_NUMBER_VALUE_PATTERN_V2}\s*(?:m|meter|meters|metre|metres|ft|feet|foot|\u516c\u5c3a|\u7c73)"
    )


def prompt_has_specific_lane_v2(prompt_text: str) -> bool:
    return lane_from_prompt_fragment_v2(prompt_text, None) is not None


def prompt_has_specific_time_v2(prompt_text: str) -> bool:
    return prompt_has_pattern_v2(prompt_text, rf"{PROMPT_NUMBER_VALUE_PATTERN_V2}\s*(?:{PROMPT_TIME_UNIT_PATTERN_V2})")


PROMPT_LANE_CHANGE_INTENT_PATTERN_V2 = (
    r"\b(?:change\s+lanes?|lane\s+change|switch\s+lanes?|moves?\s+over|"
    r"merge(?:s|d|ing)?|cut\s*in|cuts\s*in|cut-in)\b|"
    r"\u8b8a\u9053|\u53d8\u9053|\u63db\u9053|\u6362\u9053|\u5207\u9032|\u5207\u8fdb|"
    r"\u5207\u5230|\u5207\u63db|\u8b8a\u5230|\u53d8\u5230"
)


def prompt_vehicle_actor_pattern_v2() -> str:
    vehicle_patterns = "|".join(prompt_vehicle_index_pattern_v2(index) for index in range(1, 7))
    return rf"(?:{PROMPT_EGO_PATTERN_V2}|{vehicle_patterns})"


def prompt_lane_transition_pattern_v2() -> str:
    lane_pattern = lane_word_pattern_v2()
    return (
        rf"(?:{lane_pattern})\s*(?:->|=>|\bto\b|\binto\b|\u8b8a\u5230|\u53d8\u5230|"
        rf"\u63db\u5230|\u6362\u5230|\u5207\u5230|\u5230)\s*(?:{lane_pattern})"
    )


def prompt_fragment_has_timed_lane_target_v2(fragment: str) -> bool:
    if prompt_lane_change_fragment_time_s_v2(fragment) is None:
        return False
    if lane_from_prompt_fragment_v2(fragment) is None:
        return False
    return prompt_has_pattern_v2(
        fragment,
        r"\b(?:duration|dur|over|takes?|lasting|lasts?|within|for)\b|"
        r"\u8b8a\u9053\u6642\u9577|\u53d8\u9053\u65f6\u957f|\u8b8a\u9053\u6642\u9593|\u53d8\u9053\u65f6\u95f4",
    )


def prompt_lane_change_intent_fragments_v2(prompt_text: str) -> list[str]:
    text = normalize_cli_prompt_text_v2(prompt_text)
    actor_pattern = prompt_vehicle_actor_pattern_v2()
    lane_transition_pattern = prompt_lane_transition_pattern_v2()
    fragments: list[str] = []
    for fragment in re.split(r"[\n.;\u3002\uff1b]+", text):
        fragment = fragment.strip()
        if not fragment:
            continue
        has_vehicle_actor = re.search(actor_pattern, fragment, flags=re.IGNORECASE) is not None
        if prompt_has_pattern_v2(fragment, PROMPT_LANE_CHANGE_INTENT_PATTERN_V2):
            fragments.append(fragment)
            continue
        if has_vehicle_actor and re.search(lane_transition_pattern, fragment, flags=re.IGNORECASE | re.DOTALL):
            fragments.append(fragment)
            continue
        if has_vehicle_actor and prompt_fragment_has_timed_lane_target_v2(fragment):
            fragments.append(fragment)
    return fragments


def prompt_has_lane_change_intent_v2(prompt_text: str) -> bool:
    return bool(prompt_lane_change_intent_fragments_v2(prompt_text))


def params_lane_change_event_count_v2(params: ScenarioParametersV2) -> int:
    return sum(
        len(lane_change_events_for_vehicle_v2(config))
        for config in iter_script_vehicle_configs_v2(params)
        if vehicle_enabled_v2(config)
    )


def assert_prompt_lane_change_intent_resolved_v2(
    params: ScenarioParametersV2,
    prompt_text: str,
    language: str,
) -> None:
    fragments = prompt_lane_change_intent_fragments_v2(prompt_text)
    if not fragments or params_lane_change_event_count_v2(params) > 0:
        return
    fragment_lines = "\n".join(f"- {fragment}" for fragment in fragments[:3])
    message = prompt_text_v2(
        language,
        (
            "I detected lane-change intent, but no executable lane-change event was created. "
            "I will not generate a scenario that silently ignores the lane change.\n\n"
            "Please add the current lane, target lane, start time, and duration, for example:\n"
            "- v1: lane=left, ahead=7s\n"
            "- t=10s: v1 left -> middle, duration=2s\n"
            "- t=15s: v1 middle -> right, duration=2s\n\n"
            f"Detected lane-change text:\n{fragment_lines}"
        ),
        (
            "\u6211\u6709\u5075\u6e2c\u5230\u8b8a\u9053\u610f\u5716\uff0c"
            "\u4f46 parser \u6c92\u6709\u7522\u751f\u53ef\u57f7\u884c\u7684 lane-change event\uff1b"
            "\u70ba\u4e86\u907f\u514d\u5834\u666f\u8dd1\u8d77\u4f86\u537b\u6c92\u8b8a\u9053\uff0c\u6211\u5148\u4e0d\u751f\u6210\u3002\n\n"
            "\u8acb\u88dc\u4e0a\u76ee\u524d\u8eca\u9053\u3001\u76ee\u6a19\u8eca\u9053\u3001\u958b\u59cb\u6642\u9593\u548c\u8b8a\u9053\u6642\u9577\uff0c\u4f8b\u5982\uff1a\n"
            "- v1: lane=left, ahead=7s\n"
            "- t=10s: v1 left -> middle, duration=2s\n"
            "- t=15s: v1 middle -> right, duration=2s\n\n"
            f"\u6211\u5075\u6e2c\u5230\u7684\u8b8a\u9053\u6587\u5b57\uff1a\n{fragment_lines}"
        ),
    )
    raise PromptClarificationError(message)


def prompt_ambiguity_clarifications_v2(prompt_text: str, language: str) -> list[str]:
    text = normalize_cli_prompt_text_v2(prompt_text)
    missing: list[str] = []

    actor_or_event_intent = prompt_has_pattern_v2(
        text,
        r"\b(?:ego|vehicle|veh|car|obstacle|pedestrian|driver|tor|alert|warning|audio|visual|lane|gap)\b|"
        r"\u8eca|\u8f66|\u969c\u7919|\u969c\u788d|\u884c\u4eba|\u8b66\u793a|\u63d0\u793a|\u8eca\u9053|\u8f66\u9053|\u8ddd",
    )
    if not actor_or_event_intent and len(text.split()) <= 8:
        missing.append("actor/event: tell me what should exist or happen in the scenario")

    if prompt_has_pattern_v2(
        text,
        r"\b(?:something|object|hazards?|thing|vulnerable\s+road\s+users?|road\s+users?)\b|"
        r"\u6771\u897f|\u4e1c\u897f|\u969c\u7919|\u969c\u788d|\u8def\u969c",
    ):
        if not prompt_has_specific_lane_v2(text):
            missing.append("obstacle lane: left/middle/right")
        if not prompt_has_explicit_gap_or_distance_v2(text):
            missing.append("obstacle distance: meters/feet ahead of ego")
        if not prompt_has_specific_time_v2(text):
            missing.append("obstacle timing: when it appears and when it disappears")
        if not prompt_has_pattern_v2(text, r"\b(?:brake|lane change|avoid|manual|takeover|stop)\b|\u9583|\u95ea|\u8eb2|\u907f|\u715e|\u524e|\u5239|\u63a5\u7ba1"):
            missing.append("ego response: brake, lane-change, manual takeover, or metadata only")

    lane_change_intent = prompt_has_lane_change_intent_v2(text)
    ambiguous_lane_word = prompt_has_pattern_v2(
        text,
        r"\b(?:side lane|next lane|adjacent lane|neighbor(?:ing)? lane|nearby lane)\b|"
        r"\u65c1\u908a|\u65c1\u8fb9|\u9694\u58c1|\u53e6\u4e00\u689d|\u53e6\u4e00\u6761|\u90a3\u689d|\u90a3\u6761",
    )
    if lane_change_intent or ambiguous_lane_word:
        if not prompt_has_pattern_v2(text, r"\b(?:ego|vehicle\s*\d+|v\d+|car\s*\d+)\b|\u8eca\s*\d|\u8f66\s*\d"):
            missing.append("lane-change actor: ego or vehicle number")
        if not prompt_has_specific_lane_v2(text) or ambiguous_lane_word:
            missing.append("lane-change target lane: left/middle/right, not just 'side/next lane'")
        if not prompt_has_specific_time_v2(text):
            missing.append("lane-change start time and duration")
        if not prompt_has_explicit_speed_v2(text):
            missing.append("ego speed: needed to convert time gaps into SCANeR distances")
        if not prompt_has_explicit_gap_or_distance_v2(text):
            missing.append("vehicle initial gap/position relative to ego")

    decel_scan_text = prompt_text_without_cue_filenames_v2(text)
    if prompt_has_pattern_v2(decel_scan_text, PROMPT_DECELERATION_PATTERN_V2) or prompt_has_pattern_v2(decel_scan_text, r"\u6162\u4e00\u9ede|\u6162\u4e00\u70b9|\u8ffd\u4e0a|\u8b8a\u8fd1|\u53d8\u8fd1|\u62c9\u8fd1"):
        if not prompt_has_specific_time_v2(text):
            missing.append("deceleration timing: start time and target/recovery time")
        if not prompt_has_explicit_gap_or_distance_v2(text) and not prompt_has_explicit_speed_v2(text):
            missing.append("deceleration target: target gap seconds/meters or target speed")

    if prompt_has_pattern_v2(text, r"\b(?:rear|behind|trailing|following)\b|\u5f8c\u9762|\u540e\u9762|\u5f8c\u65b9|\u540e\u65b9|\u5f8c\u8eca|\u540e\u8f66"):
        if prompt_has_pattern_v2(text, r"\b(?:close(?:s|d|r|st|ing)?|catch(?:es|ing)?|approach(?:es|ing)?|shorten(?:s|ed|ing)?)\b|\u8ffd|\u8b8a\u8fd1|\u53d8\u8fd1|\u62c9\u8fd1"):
            if not prompt_has_explicit_gap_or_distance_v2(text):
                missing.append("rear traffic target gap: how close it becomes")
            if not prompt_has_specific_time_v2(text):
                missing.append("rear traffic timing: when the gap changes")

    if prompt_has_pattern_v2(text, r"\b(?:tor|alert|warning|cue|audio|visual|sound|play|show)\b|\u8b66\u793a|\u63d0\u793a|\u64ad\u653e|\u986f\u793a|\u663e\u793a"):
        cue_metadata_only = prompt_has_pattern_v2(
            text,
            r"\b(?:metadata\s*only|text\s*only|cue\s*note\s*only|no\s+(?:audio|visual)\s+file|"
            r"without\s+(?:audio|visual)\s+file|ignore\s+(?:the\s+)?(?:audio|visual|cue)|"
            r"do\s+not\s+implement\s+(?:audio|visual|cue))\b|"
            r"\u53ea\u505a\u6587\u5b57|\u53ea\u505a\u8a3b\u8a18|\u53ea\u505a\u6ce8\u8bb0|\u4e0d\u64ad\u653e|\u4e0d\u986f\u793a|\u4e0d\u663e\u793a",
        )
        if not prompt_has_specific_time_v2(text):
            missing.append("alert time")
        # Alert modality and missing cue assets are not geometric blockers.
        # Keep preview available; dry-run/final validation handles real cue files.

    if prompt_has_n_key_intervention_intent_v2(text):
        if not lane_change_intent and "->" not in text:
            missing.append("N-key reference lane change: which vehicle changes lane before the N window")
        if not prompt_has_specific_time_v2(text):
            missing.append("N-key timing window and delayed return time")
        if not prompt_has_explicit_speed_v2(text):
            missing.append("N-key ego speed delta in mph or km/h")

    takeover_design_intent = prompt_has_pattern_v2(
        text,
        r"\b(?:torlt|takeover\s+request\s+lead\s+time|tor\s+lead\s+time|lead\s+time|"
        r"traffic\s+conditions?|traffic\s+density|modality\s+of\s+(?:the\s+)?tor|modalities\s+of\s+tor|"
        r"experimental\s+route|experimental\s+design|within-subjects?\s+design)\b|"
        r"\u63a5\u7ba1\u9818\u5148\u6642\u9593|\u63a5\u7ba1\u9886\u5148\u65f6\u95f4|\u4ea4\u901a\u5bc6\u5ea6|\u5be6\u9a57\u8a2d\u8a08|\u5b9e\u9a8c\u8bbe\u8ba1",
    )
    if takeover_design_intent:
        if not prompt_has_pattern_v2(
            text,
            r"\b(?:obstacle|construction|barrier|accident|bicyclist|cyclist|pedestrian|police|swerving|stopped\s+vehicle|"
            r"disabled\s+vehicle|cow|animal|lane\s+marking|sensor\s+error)\b|"
            r"\u969c\u7919|\u969c\u788d|\u65bd\u5de5|\u8def\u969c|\u4e8b\u6545|\u884c\u4eba|\u8b66\u8eca|\u8b66\u8f66|\u52d5\u7269|\u52a8\u7269",
        ):
            missing.append("takeover event type: obstacle, construction, pedestrian, police vehicle, sensor error, etc.")
        if not prompt_has_explicit_gap_or_distance_v2(text):
            missing.append("takeover event distance: meters/feet ahead, or enough speed plus lead time to infer it")
        if not prompt_has_specific_lane_v2(text):
            missing.append("takeover event lane: left/middle/right")

    cooperative_merge_intent = prompt_has_pattern_v2(
        text,
        r"\b(?:motorway\s+access|highway\s+access|on[-\s]?ramp|entry\s+ramp|"
        r"enter(?:ing)?\s+(?:the\s+)?(?:motorway|highway|freeway)|"
        r"cooperat(?:e|es|ed|ing|ion|ive)|letting\s+(?:someone|another\s+vehicle)\s+enter|"
        r"randomi[sz]ed\s+speed|speed\s+changed\s+in\s+a\s+randomi[sz]ed\s+pattern)\b|"
        r"\u532f\u5165|\u6c47\u5165|\u532f\u6d41|\u6c47\u6d41|\u5408\u6d41|\u4e0a\u9ad8\u901f|\u8b93\u8eca|\u8ba9\u8f66|\u5354\u4f5c|\u534f\u4f5c",
    )
    if cooperative_merge_intent:
        if not prompt_has_pattern_v2(text, r"\b(?:ego|vehicle\s*\d+|v\d+|car\s*\d+)\b|\u8eca\s*\d|\u8f66\s*\d"):
            missing.append("cooperative merge actor: which vehicle enters/merges")
        if not prompt_has_specific_lane_v2(text):
            missing.append("cooperative merge lanes: ramp/current lane and target lane")
        if not prompt_has_specific_time_v2(text):
            missing.append("cooperative merge timing: start/commit/end time")
        if not prompt_has_explicit_speed_v2(text) or prompt_has_pattern_v2(text, r"\brandomi[sz]ed\s+speed\b"):
            missing.append("cooperative merge speed schedule: exact time and target speed changes")

    seen: set[str] = set()
    unique_missing: list[str] = []
    for item in missing:
        if item not in seen:
            seen.add(item)
            unique_missing.append(item)
    return unique_missing


def prompt_ambiguity_message_v2(missing: list[str], language: str) -> str:
    if language == "zh":
        lines = [
            "這段 prompt 有場景意圖，但資訊太曖昧；為了避免亂套預設場景，我先不生成。",
            "",
            "請補清楚：",
        ]
        lines.extend(f"- {item}" for item in missing)
        lines.extend(
            (
                "",
                "可以直接補一行，例如：",
                "- ego: lane=left, speed=50mph",
                "- v1: lane=middle, ahead=7s",
                "- t=5s: v1 -> left, duration=5s",
                "- obstacle 1: type=construction, lane=middle, ahead=80m, start=8s, end=30s",
            )
        )
        return "\n".join(lines)
    lines = [
        "This prompt has scenario intent, but it is too ambiguous. I will not silently generate a default scene.",
        "",
        "Please clarify:",
    ]
    lines.extend(f"- {item}" for item in missing)
    lines.extend(
        (
            "",
            "Example lines you can add:",
            "- ego: lane=left, speed=50mph",
            "- v1: lane=middle, ahead=7s",
            "- t=5s: v1 -> left, duration=5s",
            "- obstacle 1: type=construction, lane=middle, ahead=80m, start=8s, end=30s",
        )
    )
    return "\n".join(lines)


def prompt_vehicle_config_for_token_v2(params: ScenarioParametersV2, token: str) -> VehicleConfigV2 | None:
    normalized = str(token or "").strip().lower().replace("_", " ")
    if normalized in {"ego", "ego vehicle"}:
        return params.vehicles.get("ego")
    if normalized in {"front", "front vehicle", "vehicle one", "vehicle 1", "v1"}:
        return params.vehicles.get("front")
    match = re.fullmatch(r"(?:v|veh|vehicle|car)\s*(\d+)", normalized)
    if not match:
        return None
    number = int(match.group(1))
    if number == 1:
        return params.vehicles.get("front")
    label = f"Vehicle {number}".lower()
    key = f"prompt_vehicle_{number}".lower()
    for config in extra_vehicles_v2(params):
        if config.key.lower() == key or config.label.lower() == label:
            return config
    return None


def apply_imported_source_events_prompt_v2(params: ScenarioParametersV2, prompt_text: str) -> None:
    for match in re.finditer(
        rf"\bsource_event\s+(?P<actor>ego|v\s*\d+|veh\s*\d+|vehicle\s*\d+|car\s*\d+)\s+halt_time\s*=\s*(?P<time>{PROMPT_NUMBER_VALUE_PATTERN_V2})\s*(?:s|sec|secs|second|seconds)?",
        prompt_text,
        flags=re.IGNORECASE,
    ):
        config = prompt_vehicle_config_for_token_v2(params, match.group("actor"))
        if config is None:
            continue
        config.stop_enabled = True
        config.stop_time_s = parse_prompt_number_v2(match.group("time"))


def build_prompt_preview_v2(
    *,
    template_path: Path,
    prompt_text: str,
    requested_output: str = DEFAULT_OUTPUT_FILENAME,
) -> PromptPreviewResultV2:
    raw_prompt_text = normalize_cli_prompt_text_v2(prompt_text)
    language = prompt_preview_language_v2(raw_prompt_text)
    if not raw_prompt_text.strip():
        return PromptPreviewResultV2(
            False,
            "empty",
            prompt_text_v2(language, "Enter a natural-language scenario description first.", "請先輸入自然語言場景描述。"),
            language=language,
        )
    defaults = load_template_defaults_v2(template_path)
    base_params = clone_params_v2(defaults.default_params)
    prompt_output = extract_prompt_output_filename_v2(raw_prompt_text)
    effective_requested_output = (
        prompt_output
        if requested_output == DEFAULT_OUTPUT_FILENAME and prompt_output is not None
        else requested_output
    )
    explicit_output = effective_requested_output != DEFAULT_OUTPUT_FILENAME
    base_params.output_filename = normalize_output_filename(effective_requested_output)
    batch_blocks = split_scenario_batch_blocks_v2(raw_prompt_text)
    if batch_blocks:
        params_list: list[ScenarioParametersV2] = []
        output_names: list[str] = []
        block_routes: list[str] = []
        block_errors: list[str] = []
        for block_number, title, block_prompt in batch_blocks:
            block_output = batch_output_filename_v2(effective_requested_output, block_number, explicit_output=explicit_output)
            block_preview = build_prompt_preview_v2(
                template_path=template_path,
                prompt_text=block_prompt,
                requested_output=block_output,
            )
            block_label = f"Scenario {block_number}" + (f" ({title})" if title else "")
            if not block_preview.ok:
                block_errors.append(f"{block_label}:\n{block_preview.message}")
                continue
            block_routes.append(f"{block_label}: {block_preview.route}")
            params_list.extend(block_preview.params_list)
            output_names.extend(block_preview.output_names)
        if block_errors:
            message = (
                "Batch prompt needs fixes before generating.\n\n"
                + "\n\n".join(block_errors)
            )
            return PromptPreviewResultV2(False, "scenario_batch_needs_clarification", message, language=language)
        message = summarize_prompt_params_list_v2("scenario_batch", params_list, language=language)
        if block_routes:
            message += "\n\n=== Batch Blocks ===\n" + "\n".join(f"- {line}" for line in block_routes)
        return PromptPreviewResultV2(
            True,
            "scenario_batch",
            message,
            params_list=params_list,
            output_names=output_names,
            language=language,
        )
    prompt_text = expand_prompt_shorthand_v2(raw_prompt_text)
    try:
        validate_prompt_cue_file_references_v2(prompt_text)
    except PromptClarificationError as exc:
        return PromptPreviewResultV2(False, "needs_clarification", str(exc), language=language)
    route_builders: tuple[tuple[str, Any], ...] = (
        ("confidence_takeover_study", build_global_confidence_takeover_scenarios_v2),
        ("emotion_takeover_study", build_global_emotion_takeover_scenarios_v2),
        ("nback_takeover_study", build_global_nback_takeover_scenarios_v2),
        ("construction_takeover_study", build_global_construction_takeover_scenarios_v2),
    )
    try:
        for route, builder in route_builders:
            params_list = builder(
                clone_params_v2(base_params),
                prompt_text,
                explicit_output=explicit_output,
                requested_output=effective_requested_output,
            )
            if params_list is not None:
                for params in params_list:
                    apply_review_prompt_factors_v2(params, prompt_text)
                    validate_parameters_v2(params)
                message = summarize_prompt_params_list_v2(route, params_list, language=language)
                return PromptPreviewResultV2(
                    True,
                    route,
                    message,
                    params_list=params_list,
                    output_names=[params.output_filename for params in params_list],
                    language=language,
                )

        validate_takeover_study_prompt_v2(prompt_text)
        ambiguity_missing = prompt_ambiguity_clarifications_v2(prompt_text, language)
        if ambiguity_missing:
            return PromptPreviewResultV2(
                False,
                "needs_clarification",
                prompt_ambiguity_message_v2(ambiguity_missing, language),
                language=language,
            )
        simple_params = clone_params_v2(base_params)
        apply_vehicle1_prompt_scene_v2(simple_params, prompt_text, explicit_output=explicit_output)
        apply_imported_source_events_prompt_v2(simple_params, prompt_text)
        assert_prompt_lane_change_intent_resolved_v2(simple_params, prompt_text, language)
        apply_review_prompt_factors_v2(simple_params, prompt_text)
        validate_parameters_v2(simple_params)
        message = summarize_prompt_params_list_v2("simple_vehicle_prompt", [simple_params], language=language)
        return PromptPreviewResultV2(
            True,
            "simple_vehicle_prompt",
            message,
            params_list=[simple_params],
            output_names=[simple_params.output_filename],
            language=language,
        )
    except PromptClarificationError as exc:
        return PromptPreviewResultV2(False, "needs_clarification", str(exc), language=language)
    except Exception as exc:  # noqa: BLE001
        message = prompt_text_v2(language, f"Could not parse or generate preview: {exc}", f"無法解析或生成預覽：{exc}")
        return PromptPreviewResultV2(False, "error", message, language=language)


def generate_prompt_preview_v2(
    *,
    template_path: Path,
    preview: PromptPreviewResultV2,
    output_dir: str | Path | None = None,
) -> list[Path]:
    if not preview.ok or not preview.params_list:
        raise ValueError("Preview is not ready for generation.")
    if output_dir is not None:
        register_prompt_output_dir_for_runner_v2(output_dir, template_path)
    defaults = load_template_defaults_v2(template_path)
    output_paths: list[Path] = []
    for params in preview.params_list:
        output_path = prompt_scenario_output_path_v2(params.output_filename, template_path, output_dir)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        generated_path = generate_scenario_v2(
            template_path=template_path,
            output_path=output_path,
            params=params,
            defaults=defaults,
        )
        detach_ego_shared_driving_v2(generated_path)
        output_paths.append(generated_path)
    return output_paths


