    def _update_storage_status(self) -> None:
        output_name = self.output_var.get().strip() or DEFAULT_OUTPUT_FILENAME
        try:
            output_filename = normalize_output_filename(output_name)
            self.storage_status_var.set(f"Draft: {shorten_name(output_filename, max_length=16)}")
        except ValueError as exc:
            self.storage_status_var.set(f"Output error: {exc}")

    def _storage_detail_text(self) -> str:
        output_name = self.output_var.get().strip() or DEFAULT_OUTPUT_FILENAME
        output_dir = self._selected_output_dir()
        try:
            output_filename = normalize_output_filename(output_name)
            output_line = f"Output: {output_filename}"
        except ValueError as exc:
            output_line = f"Output error: {exc}"
        return "\n".join(
            (
                output_line,
                f"Target folder: {output_dir}",
                f"Template: {self.template_path.name}",
                "Status: draft, not generated",
            )
        )

    def _selected_output_dir(self) -> Path:
        return normalize_prompt_output_dir_v2(self.output_dir_var.get(), self.template_path)

    def _browse_output_dir(self) -> None:
        initial_dir = self._selected_output_dir()
        path_text = filedialog.askdirectory(
            title="Select generated scenario folder",
            initialdir=str(initial_dir if initial_dir.exists() else prompt_scenario_output_dir_v2(self.template_path)),
        )
        if not path_text:
            return
        self.output_dir_var.set(str(Path(path_text)))
        registered = register_prompt_output_dir_for_runner_v2(path_text, self.template_path)
        suffix = " Runner will also scan it." if registered else ""
        self.status_var.set(f"Output folder updated. Generate will write to the selected folder.{suffix}")

    def _on_output_changed(self) -> None:
        self._preview_cache_signature = None
        self._preview_cache_result = None
        self._last_preview = None
        self._last_live_analyze_text = ""
        self._update_storage_status()
        if self.insight_tab_var.get() == "Files":
            self._set_insight_tab("Files")
        self._schedule_live_analyze(delay_ms=150)

    def _on_output_dir_changed(self) -> None:
        self._update_storage_status()
        self._set_insight_tab(self.insight_tab_var.get())

    def _refresh_workspace_chrome(self) -> None:
        active_mode = self.workspace_mode_var.get()
        for mode_name, button in getattr(self, "_mode_buttons", {}).items():
            selected = mode_name == active_mode
            try:
                button.configure(
                    bg=self.PALETTE["accent_soft"] if selected else self.PALETTE["panel"],
                    fg=self.PALETTE["text"] if selected else self.PALETTE["muted"],
                    highlightbackground=self.PALETTE["accent"] if selected else self.PALETTE["line"],
                )
            except tk.TclError:
                continue
        active_tab = self.insight_tab_var.get()
        for tab_name, button in getattr(self, "_insight_tab_buttons", {}).items():
            selected = tab_name == active_tab
            try:
                button.configure(
                    bg=self.PALETTE["accent_soft"] if selected else self.PALETTE["rail"],
                    fg=self.PALETTE["text"] if selected else self.PALETTE["muted"],
                    highlightbackground=self.PALETTE["accent"] if selected else self.PALETTE["line"],
                )
            except tk.TclError:
                continue

    def _set_workspace_mode(self, mode: str) -> None:
        self.workspace_mode_var.set(mode)
        self._refresh_workspace_chrome()

    def _focus_write_mode(self) -> None:
        self._set_workspace_mode("Write")
        self._ensure_prompt_editor_editable(focus=True)
        self.status_var.set("Write mode: editing the scenario source prompt.")

    def _ensure_prompt_editor_editable(self, *, focus: bool = False) -> None:
        prompt_text = getattr(self, "prompt_text", None)
        if prompt_text is None:
            return
        try:
            prompt_text.configure(state=tk.NORMAL)
            if focus:
                prompt_text.focus_set()
        except tk.TclError:
            return

    def _focus_prompt_editor_from_click(self, _event: tk.Event | None = None) -> None:
        self._ensure_prompt_editor_editable(focus=True)

    def _ensure_prompt_editor_visible(self) -> None:
        prompt_text = getattr(self, "prompt_text", None)
        guide_collapsed = getattr(self, "guide_collapsed_var", None)
        if prompt_text is None or guide_collapsed is None:
            return
        try:
            hidden_or_tiny = not prompt_text.winfo_ismapped() or prompt_text.winfo_height() < 80
            if hidden_or_tiny and not guide_collapsed.get():
                self._apply_guide_collapsed_state(True, update_status=False)
                self.status_var.set("Start Wizard collapsed to keep the prompt editor editable.")
        except tk.TclError:
            return

    def _set_plain_insight_text(self, title: str, text: str) -> None:
        self.insight_title_var.set(title)
        snapshot = ("plain", title, text)
        if self._result_render_snapshot == snapshot:
            return
        self._result_render_snapshot = snapshot
        self.result_text.configure(state=tk.NORMAL)
        self.result_text.delete("1.0", tk.END)
        self.result_text.insert("1.0", text)
        if text.strip():
            self.result_text.tag_add("section_title", "1.0", "1.end")
        self._highlight_result_text_if_small(text)
        self.result_text.configure(state=tk.DISABLED)

    def _preview_insight_text(self) -> str:
        preview = self._last_preview
        if preview is None or not preview.params_list:
            return "No valid preview yet.\n\nRun Analyze first, then open Preview for the map and timeline player."
        params = preview.params_list[0]
        vehicle_count = sum(1 for config in iter_script_vehicle_configs_v2(params) if vehicle_enabled_v2(config))
        obstacle_count = sum(1 for obstacle in iter_obstacle_configs_v2(params) if obstacle.enabled)
        pedestrian_count = sum(1 for pedestrian in params.pedestrians.values() if pedestrian.enabled)
        lines = [
            "Preview Context",
            "",
            f"Route: {preview.route}",
            f"Variants: {len(preview.params_list)}",
            f"Timeline length: {format_number(params.total_experiment_time_s)} s",
            f"Actors: {vehicle_count} vehicle(s), {obstacle_count} obstacle(s), {pedestrian_count} pedestrian(s)",
            "",
            "First scenario summary:",
        ]
        summary_lines = summarize_prompt_params_v2(params)
        lines.extend(f"- {line}" for line in summary_lines[:14])
        if len(summary_lines) > 14:
            lines.append("- ... more items available in the generated parser summary")
        return "\n".join(lines)

    def _files_insight_text(self) -> str:
        preview = self._last_preview
        lines = ["Local Output", "", self._storage_detail_text()]
        if preview is not None and preview.output_names:
            lines.extend(("", "Ready files:"))
            lines.extend(f"- {name}" for name in preview.output_names[:16])
            if len(preview.output_names) > 16:
                lines.append(f"- ... {len(preview.output_names) - 16} more")
        else:
            lines.extend(("", "No generated file list yet. Run Analyze after editing the prompt."))
        recent = load_prompt_recent_state_v2()
        if recent["prompt_files"] or recent["outputs"]:
            lines.extend(("", "Recent"))
            for item in recent["prompt_files"][:5]:
                lines.append(f"- prompt: {item}")
            for item in recent["outputs"][:5]:
                lines.append(f"- output: {item}")
        return "\n".join(lines)

    def _set_insight_tab(self, tab_name: str) -> None:
        self.insight_tab_var.set(tab_name)
        self._refresh_workspace_chrome()
        if tab_name == "Parser":
            self.insight_title_var.set("Parser Check")
            if self._last_result_text.strip():
                self._set_result_text(self._last_result_text, ok=self._last_result_ok, language=self._last_result_language)
            else:
                self._set_plain_insight_text("Parser Check", "Run Analyze to see missing fields, interpreted blocks, and the quick edit table.")
            self.status_var.set("Insight rail is showing parser checks.")
        elif tab_name == "Preview":
            self._set_plain_insight_text("Preview Context", self._preview_insight_text())
            self.status_var.set("Insight rail preview context is active. Use Preview to open map/timeline.")
        else:
            self._set_plain_insight_text("Files", self._files_insight_text())
            self.status_var.set(self.storage_status_var.get().replace("\n", " | "))

    def _command_palette_items(self) -> list[dict[str, Any]]:
        def set_validation_profile(value: str) -> None:
            self.validation_profile_var.set(value)
            self.status_var.set(f"Validation profile set to {value}.")

        def set_generate_profile(value: str) -> None:
            self.generate_profile_var.set(value)
            self.status_var.set(f"Generate profile set to {value}.")

        def group_for_label(label: str) -> str:
            lower = label.lower()
            if lower.startswith("insert "):
                return "Insert"
            if any(word in lower for word in ("wizard", "recipe", "cheatsheet", "rewrite", "load prompt", "clear prompt")):
                return "Prompt"
            if any(word in lower for word in ("analyze", "format", "fix", "why", "dry run", "linter", "defaults", "clarification", "paper", "regression")):
                return "Check"
            if any(word in lower for word in ("variant", "matrix", "batch", "diff", "summary")):
                return "Batch"
            if "profile" in lower:
                return "Settings"
            if any(word in lower for word in ("save", "export", "manifest", "dataset", "generate", "cli", "project")):
                return "Output"
            if any(word in lower for word in ("asset", "tor", "audio", "visual", "preview")):
                return "Assets"
            return "Prompt"

        items = [
            {"label": "Start prompt wizard", "meta": "Focus the inline two-column wizard", "command": self._open_prompt_wizard},
            {"label": "Analyze prompt", "meta": "Parser check current prompt", "command": self._request_analyze_prompt},
            {"label": "Format prompt by timeline", "meta": "Organize messy prompt into initial state + timed events", "command": self._format_prompt_by_timeline},
            {"label": "Make variants", "meta": "Turn the current scene into a small batch", "command": self._make_variants_from_current_prompt},
            {"label": "Open variant table", "meta": "Edit batch variants in a compact table", "command": self._open_variant_table_editor},
            {"label": "Show scenario diff", "meta": "Compare variants against Scenario 1", "command": self._show_variant_diff},
            {"label": "Open clarification form", "meta": "Fill missing parser fields as form rows", "command": self._open_clarification_form},
            {"label": "Show paper method mode", "meta": "Split method text into detected/missing scenario blocks", "command": self._show_method_import_mode},
            {"label": "Use safe defaults", "meta": "Append explicit assumed defaults for missing fields", "command": self._apply_safe_defaults_from_current_prompt},
            {"label": "Show prompt linter", "meta": "List line-level warnings and errors", "command": self._show_prompt_linter},
            {"label": "Apply first quick fix", "meta": "Use the top parser/linter fix", "command": self._apply_first_quick_fix},
            {"label": "Open variant matrix", "meta": "Generate batch variants from speed/gap/lead-time lists", "command": self._open_variant_matrix_builder},
            {"label": "Show scenario summary", "meta": "Plain-language interpretation of current prompt", "command": self._show_scenario_summary},
            {"label": "Restore previous prompt", "meta": "Undo the last transform/rebuild", "command": self._restore_previous_prompt},
            {"label": "Open TOR asset picker", "meta": "Preview audio and visual cue files", "command": self._open_asset_picker_preview},
            {"label": "Open recipe library", "meta": "Insert a common scenario template", "command": self._open_recipe_library},
            {"label": "Open prompt cheatsheet", "meta": "Search DSL commands and examples", "command": self._open_prompt_cheatsheet},
            {"label": "Rewrite natural language to DSL", "meta": "Normalize messy prompt text", "command": self._rewrite_prompt_to_dsl},
            {"label": "Generate dry run", "meta": "Validate files, timings, assets, and output manifest", "command": self._show_generate_dry_run},
            {"label": "Explain current error", "meta": "Plain-language why for parser/validation issues", "command": self._explain_current_error},
            {"label": "Save prompt project", "meta": "Save editor, output, and profiles as .scenario.json", "command": self._save_prompt_project},
            {"label": "Load prompt project", "meta": "Restore a saved .scenario.json project", "command": self._load_prompt_project},
            {"label": "Export manifest", "meta": "Write CSV/JSON scenario manifest for the current prompt", "command": self._export_manifest},
            {"label": "Export test dataset", "meta": "Write prompt + manifest + parsed parameters as JSON", "command": self._export_test_dataset},
            {"label": "Run parser regression tests", "meta": "Smoke-test core prompt patterns", "command": self._run_prompt_regression_tests},
            {"label": "Set validation profile: Relaxed", "meta": "Parser accepts more ambiguity", "command": lambda: set_validation_profile("Relaxed")},
            {"label": "Set validation profile: Study-ready", "meta": "Balanced study prompt validation", "command": lambda: set_validation_profile("Study-ready")},
            {"label": "Set validation profile: Strict SCANeR", "meta": "Require executable SCANeR details", "command": lambda: set_validation_profile("Strict SCANeR")},
            {"label": "Set generate profile: Preview only", "meta": "Do not assume final generation settings", "command": lambda: set_generate_profile("Preview only")},
            {"label": "Set generate profile: Research batch", "meta": "Batch-oriented generation defaults", "command": lambda: set_generate_profile("Research batch")},
            {"label": "Set generate profile: SCANeR final", "meta": "Final SCANeR output profile", "command": lambda: set_generate_profile("SCANeR final")},
            {"label": "Open scenario preview", "meta": "Map and timeline player", "command": self._open_scenario_preview},
            {"label": "Generate .sce", "meta": "Write generated scenario file(s)", "command": self._generate_from_preview},
            {"label": "Insert wizard prompt", "meta": "Wizard -> editor", "command": self._guide_build_prompt},
            {"label": "Insert wizard prompt and analyze", "meta": "Wizard -> editor -> parser check", "command": self._guide_build_and_analyze},
            {"label": "Load prompt file", "meta": "Import text prompt", "command": self._load_prompt_file},
            {"label": "Clear prompt", "meta": "Reset editor", "command": self._clear_prompt},
            {"label": "Insert ego lane/speed", "meta": "Snippet", "command": lambda: self._insert_snippet_chip("ego lane/speed")},
            {"label": "Insert vehicle gap", "meta": "Snippet", "command": lambda: self._insert_snippet_chip("v1 lane + gap")},
            {"label": "Insert lane change", "meta": "Snippet", "command": lambda: self._insert_snippet_chip("lane change")},
            {"label": "Insert obstacle", "meta": "Snippet", "command": lambda: self._insert_snippet_chip("obstacle barrier")},
            {"label": "Insert batch variants", "meta": "Snippet", "command": lambda: self._insert_snippet_chip("batch variants")},
            {"label": "Copy CLI command", "meta": "Put current prompt command on clipboard", "command": self._copy_cli_command},
        ]
        for item in items:
            item.setdefault("group", group_for_label(str(item["label"])))
        return items

    def _copy_cli_command(self) -> None:
        prompt = self.prompt_text.get("1.0", "end-1c").strip()
        command = [
            sys.executable,
            str(SCRIPT_DIR / "prompt_scenario_gui.py"),
            "--prompt",
            prompt,
            "--output",
            self.output_var.get().strip() or DEFAULT_OUTPUT_FILENAME,
            "--output-dir",
            str(self._selected_output_dir()),
            "--template",
            str(self.template_path),
            "--analyze-only",
        ]
        command_text = subprocess.list2cmdline(command)
        try:
            self.clipboard_clear()
            self.clipboard_append(command_text)
            self.status_var.set("CLI command copied to clipboard.")
        except tk.TclError:
            self.status_var.set(command_text)

    def _open_prompt_wizard(self) -> None:
        if getattr(self, "guide_collapsed_var", None) is not None and self.guide_collapsed_var.get():
            self._toggle_guide_collapsed()
        self._guide_set_step(max(0, min(4, self._guide_step_index)))
        self._refresh_inline_wizard_preview()
        try:
            self.guide_fields_shell.focus_set()
        except tk.TclError:
            pass
        self.status_var.set("Start Wizard is open inline above the editor. Use the live prompt column, then Insert Prompt or Insert + Analyze.")

    def _open_prompt_wizard_popup(self) -> None:
        if self._wizard_popup is not None and self._wizard_popup.winfo_exists():
            self._wizard_popup.lift(self)
            self._wizard_popup.focus_force()
            return

        popup = tk.Toplevel(self)
        popup.title("Prompt Wizard")
        popup.transient(self)
        popup.configure(bg=self.PALETTE["bg"])
        popup.geometry("+{}+{}".format(self.winfo_rootx() + 86, self.winfo_rooty() + 58))
        popup.minsize(900, 600)
        popup.resizable(True, True)
        self._wizard_popup = popup

        shell = tk.Frame(popup, bg=self.PALETTE["line"])
        shell.pack(fill=tk.BOTH, expand=True, padx=16, pady=16)
        root = tk.Frame(shell, bg=self.PALETTE["panel"], padx=16, pady=16)
        root.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        root.grid_columnconfigure(0, weight=1)
        root.grid_rowconfigure(2, weight=1)

        header = tk.Frame(root, bg=self.PALETTE["panel"])
        header.grid(row=0, column=0, sticky="ew")
        header.columnconfigure(0, weight=1)
        tk.Label(
            header,
            text="Start Wizard",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["text"],
            font=(BODY_FONT_FAMILY, 18, "bold"),
            anchor="w",
        ).grid(row=0, column=0, sticky="ew")
        tk.Label(
            header,
            text="Answer a few scene questions, review the generated prompt, then insert it into the editor.",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["muted"],
            font=(BODY_FONT_FAMILY, 10),
            anchor="w",
        ).grid(row=1, column=0, sticky="ew", pady=(2, 0))
        ttk.Button(header, text="Close", style="Soft.TButton", command=lambda: close()).grid(row=0, column=1, rowspan=2, sticky="ne")

        step_names = ("Basics", "Vehicles", "Actors", "Alerts", "N-key")
        step_index_var = tk.IntVar(value=max(0, min(4, self._guide_step_index)))
        stepper = tk.Frame(root, bg=self.PALETTE["panel"])
        stepper.grid(row=1, column=0, sticky="ew", pady=(12, 10))
        step_buttons: list[tk.Button] = []

        body = tk.Frame(root, bg=self.PALETTE["panel"])
        body.grid(row=2, column=0, sticky="nsew")
        body.grid_columnconfigure(0, weight=5, uniform="wizard")
        body.grid_columnconfigure(1, weight=4, uniform="wizard")
        body.grid_rowconfigure(0, weight=1)

        form_shell = tk.Frame(body, bg=self.PALETTE["line"])
        form_shell.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        form = tk.Frame(form_shell, bg=self.PALETTE["panel_soft"], padx=12, pady=12)
        form.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        form.columnconfigure(1, weight=1)
        form.columnconfigure(3, weight=1)

        preview_shell = tk.Frame(body, bg=self.PALETTE["line"])
        preview_shell.grid(row=0, column=1, sticky="nsew")
        preview_panel = tk.Frame(preview_shell, bg=self.PALETTE["field"], padx=10, pady=10)
        preview_panel.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        preview_panel.grid_columnconfigure(0, weight=1)
        preview_panel.grid_rowconfigure(1, weight=1)
        tk.Label(
            preview_panel,
            text="Live prompt",
            bg=self.PALETTE["field"],
            fg=self.PALETTE["accent_dark"],
            font=(BODY_FONT_FAMILY, 10, "bold"),
            anchor="w",
        ).grid(row=0, column=0, sticky="ew", pady=(0, 8))
        prompt_preview = tk.Text(
            preview_panel,
            wrap=tk.WORD,
            height=18,
            borderwidth=0,
            relief=tk.FLAT,
            padx=10,
            pady=10,
            bg="#0b1220",
            fg=self.PALETTE["text"],
            insertbackground=self.PALETTE["accent"],
            selectbackground="#2f4778",
            selectforeground="#ffffff",
            font=(MONO_FONT_FAMILY, 11),
        )
        prompt_preview_scroll = ttk.Scrollbar(preview_panel, orient=tk.VERTICAL, command=prompt_preview.yview)
        prompt_preview.configure(yscrollcommand=prompt_preview_scroll.set)
        prompt_preview.grid(row=1, column=0, sticky="nsew")
        prompt_preview_scroll.grid(row=1, column=1, sticky="ns")
        prompt_preview.configure(state=tk.DISABLED)

        footer = tk.Frame(root, bg=self.PALETTE["panel"])
        footer.grid(row=3, column=0, sticky="ew", pady=(12, 0))
        footer.columnconfigure(0, weight=1)
        wizard_status_var = tk.StringVar(value="Step 1 of 5")
        tk.Label(
            footer,
            textvariable=wizard_status_var,
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["muted"],
            font=(BODY_FONT_FAMILY, 10),
            anchor="w",
        ).grid(row=0, column=0, sticky="ew")

        trace_tokens: list[tuple[tk.Variable, str]] = []

        def tracked_vars() -> list[tk.Variable]:
            values: list[tk.Variable] = [
                self.guide_prompt_language_var,
                self.guide_scene_type_var,
                self.guide_ego_lane_var,
                self.guide_ego_speed_var,
                self.guide_total_time_var,
                self.guide_road_var,
                self.guide_weather_var,
                self.guide_vehicle_count_var,
                self.guide_keep_gap_var,
                self.guide_tor_modality_var,
                self.guide_tor_time_var,
                self.guide_obstacle_count_var,
                self.guide_pedestrian_count_var,
                self.guide_audio_count_var,
                self.guide_visual_count_var,
                self.guide_ndrt_task_var,
                self.guide_ndrt_duration_var,
                self.guide_nkey_enabled_var,
                self.guide_nkey_start_offset_var,
                self.guide_nkey_end_offset_var,
                self.guide_nkey_slow_delta_var,
                self.guide_nkey_delay_var,
                self.guide_nkey_return_lane_var,
                self.guide_restore_speed_var,
            ]
            for mapping in (
                self.guide_vehicle_lane_vars,
                self.guide_vehicle_target_lane_vars,
                self.guide_vehicle_gap_vars,
                self.guide_vehicle_relative_vars,
                self.guide_vehicle_lc_time_vars,
                self.guide_vehicle_lc_duration_vars,
                self.guide_obstacle_kind_vars,
                self.guide_obstacle_lane_vars,
                self.guide_obstacle_distance_vars,
                self.guide_obstacle_start_vars,
                self.guide_obstacle_end_vars,
                self.guide_pedestrian_start_side_vars,
                self.guide_pedestrian_end_side_vars,
                self.guide_pedestrian_distance_vars,
                self.guide_pedestrian_start_time_vars,
                self.guide_pedestrian_duration_vars,
                self.guide_audio_time_vars,
                self.guide_audio_file_vars,
                self.guide_visual_time_vars,
                self.guide_visual_file_vars,
            ):
                values.extend(mapping.values())
            unique: list[tk.Variable] = []
            seen: set[int] = set()
            for variable in values:
                key = id(variable)
                if key in seen:
                    continue
                unique.append(variable)
                seen.add(key)
            return unique

        def refresh_preview(*_args: object) -> None:
            try:
                lines = self._guide_prompt_lines()
                prompt_preview.configure(state=tk.NORMAL)
                prompt_preview.delete("1.0", tk.END)
                prompt_preview.insert("1.0", "\n".join(lines).strip() + "\n")
                prompt_preview.yview_moveto(0)
                prompt_preview.configure(state=tk.DISABLED)
            except tk.TclError:
                return

        def set_step(index: int) -> None:
            step_index_var.set(max(0, min(4, index)))
            render_step()

        def refresh_counts_and_render() -> None:
            refresh_preview()
            render_step()

        def label(row: int, column: int, text: str, *, bold: bool = False) -> tk.Label:
            widget = tk.Label(
                form,
                text=text,
                bg=self.PALETTE["panel_soft"],
                fg=self.PALETTE["text"] if bold else self.PALETTE["muted"],
                font=(BODY_FONT_FAMILY, 10, "bold" if bold else "normal"),
                anchor="w",
            )
            widget.grid(row=row, column=column, sticky="w", padx=(0, 8), pady=5)
            return widget

        def field(row: int, column: int, text: str, widget: tk.Widget) -> None:
            label(row, column, text)
            widget.grid(row=row, column=column + 1, sticky="ew", padx=(0, 12), pady=5)

        def combo(variable: tk.StringVar, values: tuple[str, ...] | list[str], width: int = 15) -> ttk.Combobox:
            return ttk.Combobox(form, textvariable=variable, values=tuple(values), state="readonly", width=width)

        def entry(variable: tk.StringVar, width: int = 8) -> ttk.Entry:
            return ttk.Entry(form, textvariable=variable, width=width)

        def dark_check(text: str, variable: tk.BooleanVar) -> tk.Checkbutton:
            return tk.Checkbutton(
                form,
                text=text,
                variable=variable,
                bg=self.PALETTE["panel_soft"],
                fg=self.PALETTE["text"],
                activebackground=self.PALETTE["panel_soft"],
                activeforeground=self.PALETTE["text"],
                selectcolor=self.PALETTE["field"],
                highlightthickness=0,
                font=(BODY_FONT_FAMILY, 10),
            )

        def render_stepper() -> None:
            if not step_buttons:
                for index, step_name in enumerate(step_names):
                    button = tk.Button(
                        stepper,
                        text=f"{index + 1}. {step_name}",
                        command=lambda selected=index: set_step(selected),
                        relief=tk.FLAT,
                        padx=12,
                        pady=6,
                        font=(BODY_FONT_FAMILY, 10, "bold"),
                        cursor="hand2",
                        highlightthickness=1,
                    )
                    button.pack(side=tk.LEFT, padx=(0, 6))
                    step_buttons.append(button)
            current = step_index_var.get()
            for index, button in enumerate(step_buttons):
                active = index == current
                complete = index < current
                button.configure(
                    bg="#22345d" if active else "#1a2740" if complete else "#111827",
                    fg="#dbe7ff" if active else "#b8c7de" if complete else self.PALETTE["muted"],
                    activebackground="#2d4372",
                    activeforeground="#eaf1ff",
                    highlightbackground="#4f6fb3" if active else "#2f3e56",
                )

        def render_step() -> None:
            for child in form.winfo_children():
                child.destroy()
            render_stepper()
            step = step_index_var.get()
            wizard_status_var.set(f"Step {step + 1} of 5 - {step_names[step]}")

            if step == 0:
                field(0, 0, "Prompt language", combo(self.guide_prompt_language_var, ("中文", "English"), width=14))
                field(
                    0,
                    2,
                    "Scene type",
                    combo(
                        self.guide_scene_type_var,
                        ("Simple vehicle cut-in", "N-key intervention", "Takeover obstacle metadata", "Confidence study metadata"),
                        width=25,
                    ),
                )
                field(1, 0, "Ego lane", combo(self.guide_ego_lane_var, ("Left", "Middle", "Right"), width=14))
                field(1, 2, "Ego speed mph", entry(self.guide_ego_speed_var))
                field(2, 0, "Road", combo(self.guide_road_var, ("highway", "urban", "rural", "curve"), width=14))
                field(2, 2, "Weather", combo(self.guide_weather_var, ("clear", "rain", "fog", "snow"), width=14))
                field(3, 0, "Scenario duration s", entry(self.guide_total_time_var))
                label(4, 0, "Tip", bold=True)
                tk.Label(
                    form,
                    text="Use this first step to set the base world. Later steps add vehicles, actors, alerts, and interventions.",
                    bg=self.PALETTE["panel_soft"],
                    fg=self.PALETTE["muted"],
                    font=(BODY_FONT_FAMILY, 10),
                    wraplength=620,
                    justify=tk.LEFT,
                    anchor="w",
                ).grid(row=4, column=1, columnspan=3, sticky="ew", padx=(0, 12), pady=4)

            elif step == 1:
                count_combo = combo(self.guide_vehicle_count_var, ("1", "2", "3", "4", "5", "6"), width=8)
                count_combo.bind("<<ComboboxSelected>>", lambda _event: refresh_counts_and_render())
                field(0, 0, "Vehicle count", count_combo)
                dark_check("Keep the listed gaps initially", self.guide_keep_gap_var).grid(
                    row=0, column=2, columnspan=2, sticky="w", padx=(0, 12), pady=4
                )
                headers = ("Actor", "Lane", "Gap / pos", "Target / LC")
                for column, header_text in enumerate(headers):
                    label(2, column, header_text, bold=True)
                for vehicle_index in range(1, self._guide_vehicle_count() + 1):
                    row = vehicle_index + 2
                    label(row, 0, f"Vehicle {vehicle_index}", bold=True)
                    combo(self.guide_vehicle_lane_vars[vehicle_index], ("Left", "Middle", "Right"), width=10).grid(
                        row=row, column=1, sticky="ew", padx=(0, 8), pady=4
                    )
                    gap_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    gap_box.grid(row=row, column=2, sticky="ew", padx=(0, 8), pady=4)
                    ttk.Entry(gap_box, textvariable=self.guide_vehicle_gap_vars[vehicle_index], width=6).pack(side=tk.LEFT)
                    tk.Label(gap_box, text="s", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT, padx=(3, 5))
                    ttk.Combobox(
                        gap_box,
                        textvariable=self.guide_vehicle_relative_vars[vehicle_index],
                        values=("ahead", "behind"),
                        state="readonly",
                        width=8,
                    ).pack(side=tk.LEFT)
                    lc_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    lc_box.grid(row=row, column=3, sticky="ew", pady=4)
                    ttk.Combobox(
                        lc_box,
                        textvariable=self.guide_vehicle_target_lane_vars[vehicle_index],
                        values=("Left", "Middle", "Right"),
                        state="readonly",
                        width=10,
                    ).pack(side=tk.LEFT)
                    tk.Label(lc_box, text=" at ", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT)
                    ttk.Entry(lc_box, textvariable=self.guide_vehicle_lc_time_vars[vehicle_index], width=5).pack(side=tk.LEFT)
                    tk.Label(lc_box, text="s / ", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT)
                    ttk.Entry(lc_box, textvariable=self.guide_vehicle_lc_duration_vars[vehicle_index], width=5).pack(side=tk.LEFT)
                    tk.Label(lc_box, text="s", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT, padx=(3, 0))

            elif step == 2:
                obstacle_count = combo(self.guide_obstacle_count_var, ("0", "1", "2", "3", "4", "5", "6"), width=8)
                obstacle_count.bind("<<ComboboxSelected>>", lambda _event: refresh_counts_and_render())
                field(0, 0, "Obstacle count", obstacle_count)
                pedestrian_count = combo(self.guide_pedestrian_count_var, ("0", "1", "2", "3", "4"), width=8)
                pedestrian_count.bind("<<ComboboxSelected>>", lambda _event: refresh_counts_and_render())
                field(0, 2, "Pedestrian count", pedestrian_count)
                headers = ("Obstacle", "Kind", "Lane / distance", "Start / end")
                for column, header_text in enumerate(headers):
                    label(2, column, header_text, bold=True)
                row = 3
                for obstacle_index in range(1, self._guide_obstacle_count() + 1):
                    label(row, 0, f"Obstacle {obstacle_index}", bold=True)
                    combo(
                        self.guide_obstacle_kind_vars[obstacle_index],
                        ("construction zone", "barrier", "cone", "debris", "disabled vehicle", "bicyclist"),
                        width=18,
                    ).grid(row=row, column=1, sticky="ew", padx=(0, 8), pady=4)
                    pos_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    pos_box.grid(row=row, column=2, sticky="ew", padx=(0, 8), pady=4)
                    ttk.Combobox(
                        pos_box,
                        textvariable=self.guide_obstacle_lane_vars[obstacle_index],
                        values=("Left", "Middle", "Right"),
                        state="readonly",
                        width=9,
                    ).pack(side=tk.LEFT)
                    tk.Label(pos_box, text=" / ", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT)
                    ttk.Entry(pos_box, textvariable=self.guide_obstacle_distance_vars[obstacle_index], width=6).pack(side=tk.LEFT)
                    tk.Label(pos_box, text="m", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT, padx=(3, 0))
                    time_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    time_box.grid(row=row, column=3, sticky="ew", pady=4)
                    ttk.Entry(time_box, textvariable=self.guide_obstacle_start_vars[obstacle_index], width=5).pack(side=tk.LEFT)
                    tk.Label(time_box, text="s to ", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT)
                    ttk.Entry(time_box, textvariable=self.guide_obstacle_end_vars[obstacle_index], width=5).pack(side=tk.LEFT)
                    tk.Label(time_box, text="s", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT, padx=(3, 0))
                    row += 1

                row += 1
                headers = ("Pedestrian", "Crossing", "Distance", "Start / duration")
                for column, header_text in enumerate(headers):
                    label(row, column, header_text, bold=True)
                row += 1
                for pedestrian_index in range(1, self._guide_pedestrian_count() + 1):
                    label(row, 0, f"Pedestrian {pedestrian_index}", bold=True)
                    cross_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    cross_box.grid(row=row, column=1, sticky="ew", padx=(0, 8), pady=4)
                    ttk.Combobox(
                        cross_box,
                        textvariable=self.guide_pedestrian_start_side_vars[pedestrian_index],
                        values=("Left", "Right"),
                        state="readonly",
                        width=8,
                    ).pack(side=tk.LEFT)
                    tk.Label(cross_box, text=" to ", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT)
                    ttk.Combobox(
                        cross_box,
                        textvariable=self.guide_pedestrian_end_side_vars[pedestrian_index],
                        values=("Left", "Right"),
                        state="readonly",
                        width=8,
                    ).pack(side=tk.LEFT)
                    dist_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    dist_box.grid(row=row, column=2, sticky="ew", padx=(0, 8), pady=4)
                    ttk.Entry(dist_box, textvariable=self.guide_pedestrian_distance_vars[pedestrian_index], width=6).pack(side=tk.LEFT)
                    tk.Label(dist_box, text="m ahead", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT, padx=(3, 0))
                    time_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    time_box.grid(row=row, column=3, sticky="ew", pady=4)
                    ttk.Entry(time_box, textvariable=self.guide_pedestrian_start_time_vars[pedestrian_index], width=5).pack(side=tk.LEFT)
                    tk.Label(time_box, text="s / ", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT)
                    ttk.Entry(time_box, textvariable=self.guide_pedestrian_duration_vars[pedestrian_index], width=5).pack(side=tk.LEFT)
                    tk.Label(time_box, text="s", bg=self.PALETTE["panel_soft"], fg=self.PALETTE["muted"]).pack(side=tk.LEFT, padx=(3, 0))
                    row += 1

            elif step == 3:
                field(
                    0,
                    0,
                    "TOR / alert",
                    combo(self.guide_tor_modality_var, ("none", "audio", "visual", "audio visual", "silent failure no TOR"), width=24),
                )
                field(0, 2, "TOR time s", entry(self.guide_tor_time_var))
                tk.Label(
                    form,
                    text=f"Audio files must live in: {PROMPT_AUDITORY_CUE_DIR_V2}\nVisual files must live in: {PROMPT_VISUAL_CUE_DIR_V2}",
                    bg=self.PALETTE["panel_soft"],
                    fg=self.PALETTE["muted"],
                    font=(BODY_FONT_FAMILY, 10),
                    justify=tk.LEFT,
                    anchor="w",
                ).grid(row=1, column=0, columnspan=4, sticky="ew", pady=(0, 8))

                audio_count = combo(self.guide_audio_count_var, ("0", "1", "2", "3", "4"), width=8)
                audio_count.bind("<<ComboboxSelected>>", lambda _event: refresh_counts_and_render())
                field(2, 0, "Audio cues", audio_count)
                visual_count = combo(self.guide_visual_count_var, ("0", "1", "2", "3", "4"), width=8)
                visual_count.bind("<<ComboboxSelected>>", lambda _event: refresh_counts_and_render())
                field(2, 2, "Visual cues", visual_count)
                row = 4
                for cue_index in range(1, self._guide_audio_count() + 1):
                    label(row, 0, f"Audio {cue_index}", bold=True)
                    ttk.Entry(form, textvariable=self.guide_audio_time_vars[cue_index], width=6).grid(
                        row=row, column=1, sticky="w", padx=(0, 8), pady=4
                    )
                    cue_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    cue_box.grid(row=row, column=2, columnspan=2, sticky="ew", pady=4)
                    ttk.Combobox(
                        cue_box,
                        textvariable=self.guide_audio_file_vars[cue_index],
                        values=self.guide_audio_file_options,
                        state="readonly",
                        width=28,
                    ).pack(side=tk.LEFT, fill=tk.X, expand=True)
                    ttk.Button(
                        cue_box,
                        text="Browse",
                        style="Soft.TButton",
                        command=lambda index=cue_index: (self._browse_guide_audio_file(index), refresh_preview()),
                    ).pack(side=tk.LEFT, padx=(6, 0))
                    row += 1
                if self._guide_audio_count() > 0 and not self.guide_audio_file_options:
                    tk.Label(
                        form,
                        text="No audio files found. Put .wav files in the prompt_auditory_cues folder.",
                        bg=self.PALETTE["panel_soft"],
                        fg=self.PALETTE["warning"],
                        font=(BODY_FONT_FAMILY, 10, "bold"),
                        anchor="w",
                    ).grid(row=row, column=0, columnspan=4, sticky="ew", pady=(0, 5))
                    row += 1
                row += 1
                for cue_index in range(1, self._guide_visual_count() + 1):
                    label(row, 0, f"Visual {cue_index}", bold=True)
                    ttk.Entry(form, textvariable=self.guide_visual_time_vars[cue_index], width=6).grid(
                        row=row, column=1, sticky="w", padx=(0, 8), pady=4
                    )
                    cue_box = ttk.Frame(form, style="PanelSoft.TFrame")
                    cue_box.grid(row=row, column=2, columnspan=2, sticky="ew", pady=4)
                    ttk.Combobox(
                        cue_box,
                        textvariable=self.guide_visual_file_vars[cue_index],
                        values=self.guide_visual_file_options,
                        state="readonly",
                        width=28,
                    ).pack(side=tk.LEFT, fill=tk.X, expand=True)
                    ttk.Button(
                        cue_box,
                        text="Browse",
                        style="Soft.TButton",
                        command=lambda index=cue_index: (self._browse_guide_visual_file(index), refresh_preview()),
                    ).pack(side=tk.LEFT, padx=(6, 0))
                    row += 1
                if self._guide_visual_count() > 0 and not self.guide_visual_file_options:
                    tk.Label(
                        form,
                        text="No visual files found. Put png/jpg/svg/bmp/gif/txt files in the prompt_visual_cues folder.",
                        bg=self.PALETTE["panel_soft"],
                        fg=self.PALETTE["warning"],
                        font=(BODY_FONT_FAMILY, 10, "bold"),
                        anchor="w",
                    ).grid(row=row, column=0, columnspan=4, sticky="ew", pady=(0, 5))
                    row += 1
                field(row + 1, 0, "NDRT", combo(self.guide_ndrt_task_var, ("none", "movie/video", "1-back", "2-back", "SuRT", "reading", "texting"), width=14))
                field(row + 1, 2, "NDRT duration s", entry(self.guide_ndrt_duration_var))

            else:
                dark_check("Enable N-key intervention", self.guide_nkey_enabled_var).grid(
                    row=0, column=0, columnspan=4, sticky="w", pady=(0, 8)
                )
                field(1, 0, "Window start offset s", entry(self.guide_nkey_start_offset_var))
                field(1, 2, "Window end offset s", entry(self.guide_nkey_end_offset_var))
                field(2, 0, "Ego slower by mph", entry(self.guide_nkey_slow_delta_var))
                field(2, 2, "Vehicle return after s", entry(self.guide_nkey_delay_var))
                field(3, 0, "Vehicle return lane", combo(self.guide_nkey_return_lane_var, ("Left", "Middle", "Right"), width=14))
                field(3, 2, "Restore ego mph", entry(self.guide_restore_speed_var))
                tk.Label(
                    form,
                    text="This maps directly to the N-key parser: valid key window, ego slowdown, delayed return lane change, and speed restore.",
                    bg=self.PALETTE["panel_soft"],
                    fg=self.PALETTE["muted"],
                    font=(BODY_FONT_FAMILY, 10),
                    wraplength=620,
                    justify=tk.LEFT,
                    anchor="w",
                ).grid(row=5, column=0, columnspan=4, sticky="ew", pady=(10, 0))

            back_button.configure(state=tk.NORMAL if step > 0 else tk.DISABLED)
            next_button.configure(state=tk.NORMAL if step < 4 else tk.DISABLED)
            refresh_preview()

        def close() -> None:
            for variable, token in trace_tokens:
                try:
                    variable.trace_remove("write", token)
                except tk.TclError:
                    pass
            self._wizard_popup = None
            try:
                popup.destroy()
            except tk.TclError:
                pass

        def insert_prompt(*, analyze: bool) -> None:
            self._guide_step_index = step_index_var.get()
            self._replace_prompt_with_lines(self._guide_prompt_lines())
            try:
                self._render_guide_step()
            except tk.TclError:
                pass
            close()
            self.status_var.set("Wizard inserted the prompt. Running Analyze..." if analyze else "Wizard inserted the prompt into the editor.")
            if analyze:
                self.after(40, self._analyze_prompt)

        def append_step() -> None:
            step_lines = self._guide_prompt_lines_for_step(step_index_var.get())
            if not step_lines:
                wizard_status_var.set("This step does not add prompt text unless the option is enabled.")
                return
            self._append_prompt_lines(step_lines)
            wizard_status_var.set(f"Appended Step {step_index_var.get() + 1} to the editor.")

        nav = tk.Frame(footer, bg=self.PALETTE["panel"])
        nav.grid(row=0, column=1, sticky="e")
        back_button = ttk.Button(nav, text="Back", style="Soft.TButton", command=lambda: set_step(step_index_var.get() - 1))
        back_button.pack(side=tk.LEFT)
        next_button = ttk.Button(nav, text="Next", style="Soft.TButton", command=lambda: set_step(step_index_var.get() + 1))
        next_button.pack(side=tk.LEFT, padx=(6, 0))
        ttk.Button(nav, text="Append Step", style="Soft.TButton", command=append_step).pack(side=tk.LEFT, padx=(12, 0))
        ttk.Button(nav, text="Insert Prompt", style="Accent.TButton", command=lambda: insert_prompt(analyze=False)).pack(side=tk.LEFT, padx=(6, 0))
        ttk.Button(nav, text="Insert + Analyze", style="Success.TButton", command=lambda: insert_prompt(analyze=True)).pack(side=tk.LEFT, padx=(6, 0))

        for variable in tracked_vars():
            try:
                trace_tokens.append((variable, variable.trace_add("write", refresh_preview)))
            except tk.TclError:
                pass
        popup.protocol("WM_DELETE_WINDOW", close)
        render_step()
        popup.focus_force()

    def _open_command_palette(self, event: tk.Event | None = None) -> str:
        if self._command_palette_popup is not None and self._command_palette_popup.winfo_exists():
            self._command_palette_popup.lift(self)
            try:
                self._command_palette_popup.focus_force()
            except tk.TclError:
                pass
            return "break"

        groups = ("Prompt", "Check", "Batch", "Output", "Assets", "Settings", "Insert")
        all_items = self._command_palette_items()
        active_group = tk.StringVar(value="Prompt")
        query_var = tk.StringVar()
        selected_index = [0]
        category_buttons: dict[str, tk.Button] = {}
        card_rows: list[dict[str, Any]] = []
        placeholder = "Search tools, actions, exports..."
        normal_geometry: list[str] = []
        is_maximized = [False]
        drag_start = [0, 0, 0, 0]

        popup = tk.Toplevel(self)
        popup.overrideredirect(True)
        popup.transient(self)
        popup.configure(bg=self.PALETTE["line"])
        popup.resizable(True, True)
        width = min(760, max(620, self.winfo_width() - 96))
        height = min(560, max(460, self.winfo_height() - 120))
        x = self.winfo_rootx() + max(28, (self.winfo_width() - width) // 2)
        y = self.winfo_rooty() + max(42, (self.winfo_height() - height) // 2)
        normal_geometry.append(f"{width}x{height}+{x}+{y}")
        popup.geometry(normal_geometry[0])

        def close_drawer() -> None:
            self._command_palette_popup = None
            self._command_palette_listbox = None
            self._command_palette_matches = []
            try:
                popup.destroy()
            except tk.TclError:
                pass
            try:
                self.prompt_text.focus_set()
            except tk.TclError:
                pass

        def toggle_drawer_maximize() -> None:
            if is_maximized[0]:
                popup.geometry(normal_geometry[0])
                is_maximized[0] = False
                max_button.configure(text="Max")
                return
            normal_geometry[0] = popup.geometry()
            screen_w = popup.winfo_screenwidth()
            screen_h = popup.winfo_screenheight()
            popup.geometry(f"{screen_w}x{screen_h}+0+0")
            is_maximized[0] = True
            max_button.configure(text="Restore")

        def start_drag(event: tk.Event) -> None:
            if is_maximized[0]:
                return
            drag_start[:] = [event.x_root, event.y_root, popup.winfo_x(), popup.winfo_y()]

        def drag_drawer(event: tk.Event) -> None:
            if is_maximized[0]:
                return
            dx = event.x_root - drag_start[0]
            dy = event.y_root - drag_start[1]
            popup.geometry(f"+{drag_start[2] + dx}+{drag_start[3] + dy}")

        shell = tk.Frame(popup, bg=self.PALETTE["line"], highlightthickness=1, highlightbackground="#334155")
        shell.pack(fill=tk.BOTH, expand=True)
        frame = tk.Frame(shell, bg=self.PALETTE["panel"], padx=16, pady=14)
        frame.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        frame.grid_columnconfigure(0, weight=0)
        frame.grid_columnconfigure(1, weight=1)
        frame.grid_rowconfigure(2, weight=1)

        header = tk.Frame(frame, bg=self.PALETTE["panel"])
        header.grid(row=0, column=0, columnspan=2, sticky="ew")
        header.columnconfigure(0, weight=1)
        header.bind("<ButtonPress-1>", start_drag)
        header.bind("<B1-Motion>", drag_drawer)
        title_stack = tk.Frame(header, bg=self.PALETTE["panel"])
        title_stack.grid(row=0, column=0, sticky="w")
        title_stack.bind("<ButtonPress-1>", start_drag)
        title_stack.bind("<B1-Motion>", drag_drawer)
        tk.Label(
            title_stack,
            text="More Tools",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["text"],
            font=(BODY_FONT_FAMILY, 18, "bold"),
            anchor="w",
        ).pack(anchor=tk.W)
        tk.Label(
            title_stack,
            text="Search or pick a group. Click a card to run. Esc closes this drawer.",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["muted"],
            font=(BODY_FONT_FAMILY, 10),
            anchor="w",
        ).pack(anchor=tk.W, pady=(2, 0))
        max_button = tk.Button(
            header,
            text="Max",
            command=toggle_drawer_maximize,
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["muted"],
            activebackground=self.PALETTE["surface_strong"],
            activeforeground=self.PALETTE["text"],
            relief=tk.FLAT,
            font=(BODY_FONT_FAMILY, 10, "bold"),
            padx=10,
            pady=5,
            cursor="hand2",
        )
        max_button.grid(row=0, column=1, sticky="ne", padx=(0, 6))
        tk.Button(
            header,
            text="Close",
            command=close_drawer,
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["muted"],
            activebackground=self.PALETTE["surface_strong"],
            activeforeground=self.PALETTE["text"],
            relief=tk.FLAT,
            font=(BODY_FONT_FAMILY, 10, "bold"),
            padx=10,
            pady=5,
            cursor="hand2",
        ).grid(row=0, column=2, sticky="ne")

        search_shell = tk.Frame(frame, bg=self.PALETTE["field"], highlightthickness=1, highlightbackground=self.PALETTE["line"])
        search_shell.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(14, 12))
        search_shell.columnconfigure(0, weight=1)
        entry = tk.Entry(
            search_shell,
            textvariable=query_var,
            bg=self.PALETTE["field"],
            fg=self.PALETTE["text"],
            insertbackground=self.PALETTE["accent"],
            relief=tk.FLAT,
            font=(BODY_FONT_FAMILY, 13),
            borderwidth=0,
        )
        entry.grid(row=0, column=0, sticky="ew", padx=12, pady=10)
        hint_label = tk.Label(
            search_shell,
            text=placeholder,
            bg=self.PALETTE["field"],
            fg=self.PALETTE["quiet"],
            font=(BODY_FONT_FAMILY, 10),
            anchor="e",
        )
        hint_label.grid(row=0, column=1, sticky="e", padx=(0, 12))

        category_panel = tk.Frame(frame, bg=self.PALETTE["panel"])
        category_panel.grid(row=2, column=0, sticky="nsw", padx=(0, 14))
        tk.Label(
            category_panel,
            text="Groups",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["quiet"],
            font=(BODY_FONT_FAMILY, 10, "bold"),
            anchor="w",
        ).pack(fill=tk.X, pady=(0, 8))

        result_shell = tk.Frame(frame, bg=self.PALETTE["line"], highlightthickness=0)
        result_shell.grid(row=2, column=1, sticky="nsew")
        result_shell.grid_rowconfigure(0, weight=1)
        result_shell.grid_columnconfigure(0, weight=1)
        result_canvas = tk.Canvas(result_shell, bg=self.PALETTE["field"], highlightthickness=0, borderwidth=0)
        result_canvas.grid(row=0, column=0, sticky="nsew", padx=1, pady=1)
        result_scroll = ttk.Scrollbar(result_shell, orient=tk.VERTICAL, command=result_canvas.yview)
        result_scroll.grid(row=0, column=1, sticky="ns")
        result_canvas.configure(yscrollcommand=result_scroll.set)
        cards_frame = tk.Frame(result_canvas, bg=self.PALETTE["field"])
        cards_window = result_canvas.create_window((0, 0), window=cards_frame, anchor="nw")
        self._command_palette_popup = popup
        self._command_palette_listbox = None

        def sync_canvas(_event: tk.Event | None = None) -> None:
            result_canvas.configure(scrollregion=result_canvas.bbox("all"))
            result_canvas.itemconfigure(cards_window, width=max(1, result_canvas.winfo_width()))

        def set_card_selected(index: int) -> None:
            if not card_rows:
                selected_index[0] = 0
                return
            selected_index[0] = max(0, min(index, len(card_rows) - 1))
            for row_index, row in enumerate(card_rows):
                selected = row_index == selected_index[0]
                bg = "#1e3358" if selected else self.PALETTE["field"]
                border = self.PALETTE["accent"] if selected else "#263244"
                row["frame"].configure(bg=bg, highlightbackground=border)
                row["title"].configure(bg=bg, fg="#f8fbff" if selected else self.PALETTE["text"])
                row["meta"].configure(bg=bg, fg="#cbd5e1" if selected else self.PALETTE["muted"])
                row["group"].configure(bg=bg, fg=self.PALETTE["accent"] if selected else self.PALETTE["quiet"])

        def update_category_buttons() -> None:
            query_active = bool(query_var.get().strip())
            for group, button in category_buttons.items():
                selected = active_group.get() == group and not query_active
                button.configure(
                    bg=self.PALETTE["accent_soft"] if selected else self.PALETTE["panel"],
                    fg=self.PALETTE["text"] if selected else self.PALETTE["muted"],
                )

        def filtered_items() -> list[dict[str, Any]]:
            query = query_var.get().strip().lower()
            if query:
                return [
                    item
                    for item in all_items
                    if query in str(item["label"]).lower()
                    or query in str(item["meta"]).lower()
                    or query in str(item.get("group", "")).lower()
                ]
            return [item for item in all_items if item.get("group") == active_group.get()]

        def refresh(*_args: object) -> None:
            matches = filtered_items()
            self._command_palette_matches = matches
            card_rows.clear()
            for child in cards_frame.winfo_children():
                child.destroy()
            if not matches:
                empty = tk.Frame(cards_frame, bg=self.PALETTE["field"])
                empty.pack(fill=tk.BOTH, expand=True, padx=18, pady=26)
                tk.Label(
                    empty,
                    text="No matching tools",
                    bg=self.PALETTE["field"],
                    fg=self.PALETTE["text"],
                    font=(BODY_FONT_FAMILY, 14, "bold"),
                ).pack(anchor=tk.W)
                tk.Label(
                    empty,
                    text="Try a shorter word, or switch groups on the left.",
                    bg=self.PALETTE["field"],
                    fg=self.PALETTE["muted"],
                    font=(BODY_FONT_FAMILY, 11),
                ).pack(anchor=tk.W, pady=(4, 0))
                selected_index[0] = 0
                update_category_buttons()
                sync_canvas()
                return
            for item_index, item in enumerate(matches):
                card = tk.Frame(
                    cards_frame,
                    bg=self.PALETTE["field"],
                    highlightthickness=1,
                    highlightbackground="#263244",
                    padx=12,
                    pady=9,
                    cursor="hand2",
                )
                card.pack(fill=tk.X, padx=10, pady=(10 if item_index == 0 else 6, 0))
                card.grid_columnconfigure(0, weight=1)
                title = tk.Label(
                    card,
                    text=str(item["label"]),
                    bg=self.PALETTE["field"],
                    fg=self.PALETTE["text"],
                    font=(BODY_FONT_FAMILY, 12, "bold"),
                    anchor="w",
                )
                title.grid(row=0, column=0, sticky="ew")
                group_label = tk.Label(
                    card,
                    text=str(item.get("group", "")),
                    bg=self.PALETTE["field"],
                    fg=self.PALETTE["quiet"],
                    font=(BODY_FONT_FAMILY, 9, "bold"),
                    anchor="e",
                )
                group_label.grid(row=0, column=1, sticky="e", padx=(10, 0))
                meta = tk.Label(
                    card,
                    text=str(item["meta"]),
                    bg=self.PALETTE["field"],
                    fg=self.PALETTE["muted"],
                    font=(BODY_FONT_FAMILY, 10),
                    wraplength=max(360, width - 300),
                    justify=tk.LEFT,
                    anchor="w",
                )
                meta.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(3, 0))
                row = {"frame": card, "title": title, "meta": meta, "group": group_label, "item": item}
                card_rows.append(row)
                for widget in (card, title, meta, group_label):
                    widget.bind("<Button-1>", lambda _event, idx=item_index: (set_card_selected(idx), "break")[-1])
                    widget.bind("<ButtonRelease-1>", lambda _event, idx=item_index: run_selected_index(idx))
                    widget.bind("<Enter>", lambda _event, idx=item_index: set_card_selected(idx))
            update_category_buttons()
            set_card_selected(0)
            sync_canvas()

        def close() -> None:
            close_drawer()

        def run_selected_index(index: int) -> str:
            if not self._command_palette_matches:
                return "break"
            item = self._command_palette_matches[max(0, min(index, len(self._command_palette_matches) - 1))]
            close()
            item["command"]()
            return "break"

        def run_selected(_event: tk.Event | None = None) -> str:
            return run_selected_index(selected_index[0])

        def move_selection(delta: int) -> str:
            if not self._command_palette_matches:
                return "break"
            next_index = max(0, min(len(self._command_palette_matches) - 1, selected_index[0] + delta))
            set_card_selected(next_index)
            return "break"

        def set_group(group: str) -> None:
            active_group.set(group)
            query_var.set("")
            refresh()

        for group in groups:
            button = tk.Button(
                category_panel,
                text=group,
                command=lambda group_name=group: set_group(group_name),
                bg=self.PALETTE["panel"],
                fg=self.PALETTE["muted"],
                activebackground=self.PALETTE["surface_strong"],
                activeforeground=self.PALETTE["text"],
                relief=tk.FLAT,
                padx=14,
                pady=8,
                font=(BODY_FONT_FAMILY, 10, "bold"),
                highlightthickness=1,
                highlightbackground=self.PALETTE["line"],
                cursor="hand2",
                anchor="w",
                width=12,
            )
            button.pack(fill=tk.X, pady=(0, 6))
            category_buttons[group] = button

        query_var.trace_add("write", refresh)
        entry.bind("<Return>", run_selected)
        entry.bind("<Down>", lambda _event: move_selection(1))
        entry.bind("<Up>", lambda _event: move_selection(-1))
        entry.bind("<Escape>", lambda _event: (close(), "break")[-1])
        popup.bind("<Escape>", lambda _event: (close(), "break")[-1])
        popup.bind("<Return>", run_selected)
        popup.bind("<Down>", lambda _event: move_selection(1))
        popup.bind("<Up>", lambda _event: move_selection(-1))
        result_canvas.bind("<Configure>", sync_canvas)
        cards_frame.bind("<Configure>", sync_canvas)
        popup.protocol("WM_DELETE_WINDOW", close)
        refresh()
        popup.focus_force()
        entry.focus_set()
        return "break"

    def _build_guided_builder(self, parent: ttk.Frame) -> None:
        guide_shell = tk.Frame(parent, bg=self.PALETTE["panel"], highlightthickness=1, highlightbackground=self.PALETTE["line"])
        guide_shell.pack(fill=tk.X, pady=(0, 12))
        guide = ttk.Frame(guide_shell, padding=(14, 12), style="Panel.TFrame")
        guide.pack(fill=tk.X)
        guide.columnconfigure(0, weight=1)

        self.guide_progress_var = tk.StringVar()
        self.guide_hint_var = tk.StringVar()
        guide_title_row = ttk.Frame(guide, style="Panel.TFrame")
        guide_title_row.grid(row=0, column=0, sticky="ew")
        guide_title_row.columnconfigure(0, weight=1)
        ttk.Label(guide_title_row, text="Start Wizard", style="PanelSection.TLabel").grid(row=0, column=0, sticky="w")
        ttk.Label(guide_title_row, textvariable=self.guide_progress_var, style="PanelMuted.TLabel").grid(row=0, column=1, sticky="e")
        self.guide_collapse_button = ttk.Button(guide_title_row, text="Collapse", style="Soft.TButton", command=self._toggle_guide_collapsed)
        self.guide_collapse_button.grid(row=0, column=2, sticky="e", padx=(8, 0))

        self.guide_stepper_frame = tk.Frame(guide, bg=self.PALETTE["panel"])
        self.guide_stepper_frame.grid(row=1, column=0, sticky="ew", pady=(8, 6))

        self.guide_hint_label = ttk.Label(guide, textvariable=self.guide_hint_var, style="PanelMuted.TLabel", wraplength=540)
        self.guide_hint_label.grid(
            row=2,
            column=0,
            sticky="ew",
            pady=(0, 8),
        )

        self.guide_wizard_body = tk.Frame(guide, bg=self.PALETTE["panel"])
        self.guide_wizard_body.grid(row=3, column=0, sticky="ew")
        self.guide_wizard_body.columnconfigure(0, weight=5, uniform="inline_wizard")
        self.guide_wizard_body.columnconfigure(1, weight=4, uniform="inline_wizard")
        self.guide_wizard_body.rowconfigure(0, weight=1)
        self.guide_wizard_body.configure(height=330)
        self.guide_wizard_body.grid_propagate(False)

        self.guide_fields_shell = tk.Frame(
            self.guide_wizard_body,
            bg=self.PALETTE["panel_soft"],
            highlightthickness=1,
            highlightbackground="#263244",
        )
        self.guide_fields_shell.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        self.guide_fields_shell.columnconfigure(0, weight=1)
        self.guide_fields_shell.rowconfigure(0, weight=1)
        self.guide_fields_canvas = tk.Canvas(
            self.guide_fields_shell,
            bg=self.PALETTE["panel_soft"],
            highlightthickness=0,
            borderwidth=0,
        )
        self.guide_fields_canvas.grid(row=0, column=0, sticky="nsew")
        self.guide_fields_scrollbar = ttk.Scrollbar(
            self.guide_fields_shell,
            orient=tk.VERTICAL,
            command=self.guide_fields_canvas.yview,
        )
        self.guide_fields_scrollbar.grid(row=0, column=1, sticky="ns")
        self.guide_fields_canvas.configure(yscrollcommand=self.guide_fields_scrollbar.set)
        self.guide_fields_container = ttk.Frame(self.guide_fields_canvas, padding=(10, 8), style="PanelSoft.TFrame")
        self._guide_fields_canvas_window = self.guide_fields_canvas.create_window(
            (0, 0),
            window=self.guide_fields_container,
            anchor="nw",
        )
        self.guide_fields_canvas.bind("<Configure>", self._on_guide_fields_canvas_configure)
        self.guide_fields_container.bind("<Configure>", self._on_guide_fields_container_configure)
        self.guide_fields_canvas.bind("<Enter>", self._bind_guide_fields_mousewheel)
        self.guide_fields_canvas.bind("<Leave>", self._unbind_guide_fields_mousewheel)
        self.guide_fields_container.columnconfigure(0, weight=1)
        self.guide_fields_frame = self.guide_fields_container
        self._guide_step_frames: dict[int, ttk.Frame] = {}
        self._guide_dirty_steps: set[int] = set(range(5))
        self._guide_stepper_chips: list[tk.Label] = []

        self.guide_preview_shell = tk.Frame(
            self.guide_wizard_body,
            bg=self.PALETTE["line"],
            highlightthickness=0,
        )
        self.guide_preview_shell.grid(row=0, column=1, sticky="nsew")
        guide_preview_panel = tk.Frame(self.guide_preview_shell, bg=self.PALETTE["field"], padx=10, pady=10)
        guide_preview_panel.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        guide_preview_panel.grid_columnconfigure(0, weight=1)
        guide_preview_panel.grid_rowconfigure(1, weight=1)
        tk.Label(
            guide_preview_panel,
            text="Live prompt",
            bg=self.PALETTE["field"],
            fg=self.PALETTE["accent_dark"],
            font=(BODY_FONT_FAMILY, 10, "bold"),
            anchor="w",
        ).grid(row=0, column=0, sticky="ew", pady=(0, 8))
        self.guide_prompt_preview_text = tk.Text(
            guide_preview_panel,
            wrap=tk.WORD,
            height=9,
            borderwidth=0,
            relief=tk.FLAT,
            padx=10,
            pady=10,
            bg="#0b1220",
            fg=self.PALETTE["text"],
            insertbackground=self.PALETTE["accent"],
            selectbackground="#2f4778",
            selectforeground="#ffffff",
            font=(MONO_FONT_FAMILY, 11),
        )
        guide_prompt_preview_scroll = ttk.Scrollbar(
            guide_preview_panel,
            orient=tk.VERTICAL,
            command=self.guide_prompt_preview_text.yview,
        )
        self.guide_prompt_preview_text.configure(yscrollcommand=guide_prompt_preview_scroll.set)
        self.guide_prompt_preview_text.grid(row=1, column=0, sticky="nsew")
        guide_prompt_preview_scroll.grid(row=1, column=1, sticky="ns")
        self.guide_prompt_preview_text.configure(state=tk.DISABLED)

        self.guide_actions_frame = ttk.Frame(guide, style="Panel.TFrame")
        self.guide_actions_frame.grid(row=4, column=0, sticky="ew", pady=(9, 0))
        self.guide_back_button = ttk.Button(self.guide_actions_frame, text="Back", style="Soft.TButton", command=self._guide_previous_step)
        self.guide_back_button.pack(side=tk.LEFT)
        self.guide_next_button = ttk.Button(self.guide_actions_frame, text="Next", style="Soft.TButton", command=self._guide_next_step)
        self.guide_next_button.pack(side=tk.LEFT, padx=(6, 0))
        ttk.Button(self.guide_actions_frame, text="Append Step", style="Soft.TButton", command=self._guide_append_current_step).pack(side=tk.LEFT, padx=(12, 0))
        ttk.Button(self.guide_actions_frame, text="Insert Prompt", style="Accent.TButton", command=self._guide_build_prompt).pack(side=tk.LEFT, padx=(6, 0))
        ttk.Button(self.guide_actions_frame, text="Insert + Analyze", style="Success.TButton", command=self._guide_build_and_analyze).pack(side=tk.LEFT, padx=(6, 0))

        if self.guide_collapsed_var.get():
            self.guide_progress_var.set("Collapsed")
            self.guide_hint_var.set("Expand to build a prompt step by step.")
            self._render_guide_stepper()
            self._apply_guide_collapsed_state(True, update_status=False)
        else:
            self._render_guide_step()
            self._install_guide_live_preview_traces()
            self._refresh_inline_wizard_preview()

    def _warm_guide_step_frames(self) -> None:
        original_step = self._guide_step_index
        try:
            for step_index in range(5):
                if step_index == original_step:
                    continue
                self._guide_step_index = step_index
                self._render_guide_step()
        finally:
            self._guide_step_index = original_step
            self._render_guide_step()

    def _on_guide_fields_canvas_configure(self, event: tk.Event) -> None:
        canvas = getattr(self, "guide_fields_canvas", None)
        window_id = getattr(self, "_guide_fields_canvas_window", None)
        if canvas is None or window_id is None:
            return
        try:
            canvas.itemconfigure(window_id, width=max(1, int(event.width)))
        except tk.TclError:
            pass

    def _on_guide_fields_container_configure(self, _event: tk.Event) -> None:
        canvas = getattr(self, "guide_fields_canvas", None)
        if canvas is None:
            return
        try:
            canvas.configure(scrollregion=canvas.bbox("all"))
        except tk.TclError:
            pass

    def _bind_guide_fields_mousewheel(self, _event: tk.Event) -> None:
        canvas = getattr(self, "guide_fields_canvas", None)
        if canvas is None:
            return
        try:
            canvas.bind_all("<MouseWheel>", self._on_guide_fields_mousewheel)
        except tk.TclError:
            pass

    def _unbind_guide_fields_mousewheel(self, _event: tk.Event) -> None:
        canvas = getattr(self, "guide_fields_canvas", None)
        if canvas is None:
            return
        try:
            canvas.unbind_all("<MouseWheel>")
        except tk.TclError:
            pass

    def _on_guide_fields_mousewheel(self, event: tk.Event) -> str:
        canvas = getattr(self, "guide_fields_canvas", None)
        if canvas is None:
            return "break"
        delta = -1 if int(getattr(event, "delta", 0)) > 0 else 1
        try:
            canvas.yview_scroll(delta * 3, "units")
        except tk.TclError:
            pass
        return "break"

    def _reset_guide_fields_scroll(self) -> None:
        canvas = getattr(self, "guide_fields_canvas", None)
        if canvas is None:
            return
        try:
            canvas.yview_moveto(0)
        except tk.TclError:
            pass

    def _apply_guide_collapsed_state(self, collapsed: bool, *, update_status: bool = True) -> None:
        self.guide_collapsed_var.set(collapsed)
        widgets = (
            getattr(self, "guide_stepper_frame", None),
            getattr(self, "guide_hint_label", None),
            getattr(self, "guide_wizard_body", None),
            getattr(self, "guide_actions_frame", None),
        )
        for widget in widgets:
            if widget is None:
                continue
            if collapsed:
                widget.grid_remove()
            else:
                widget.grid()
        self.guide_collapse_button.configure(text="Expand" if collapsed else "Collapse")
        if not collapsed:
            if not self._guide_step_frames:
                self._render_guide_step()
            if not self._guide_var_trace_tokens:
                self._install_guide_live_preview_traces()
            self._refresh_inline_wizard_preview()
        if update_status:
            self.status_var.set("Start Wizard collapsed." if collapsed else "Start Wizard expanded.")
        self.after_idle(self._ensure_prompt_editor_visible)

    def _toggle_guide_collapsed(self) -> None:
        self._apply_guide_collapsed_state(not self.guide_collapsed_var.get())

    def _guide_tracked_vars(self) -> list[tk.Variable]:
        values: list[tk.Variable] = [
            self.guide_prompt_language_var,
            self.guide_scene_type_var,
            self.guide_ego_lane_var,
            self.guide_ego_speed_var,
            self.guide_total_time_var,
            self.guide_road_var,
            self.guide_weather_var,
            self.guide_vehicle_count_var,
            self.guide_keep_gap_var,
            self.guide_tor_modality_var,
            self.guide_tor_time_var,
            self.guide_obstacle_count_var,
            self.guide_pedestrian_count_var,
            self.guide_audio_count_var,
            self.guide_visual_count_var,
            self.guide_ndrt_task_var,
            self.guide_ndrt_duration_var,
            self.guide_nkey_enabled_var,
            self.guide_nkey_start_offset_var,
            self.guide_nkey_end_offset_var,
            self.guide_nkey_slow_delta_var,
            self.guide_nkey_delay_var,
            self.guide_nkey_return_lane_var,
            self.guide_restore_speed_var,
        ]
        for mapping in (
            self.guide_vehicle_lane_vars,
            self.guide_vehicle_target_lane_vars,
            self.guide_vehicle_gap_vars,
            self.guide_vehicle_relative_vars,
            self.guide_vehicle_lc_time_vars,
            self.guide_vehicle_lc_duration_vars,
            self.guide_obstacle_kind_vars,
            self.guide_obstacle_lane_vars,
            self.guide_obstacle_distance_vars,
            self.guide_obstacle_start_vars,
            self.guide_obstacle_end_vars,
            self.guide_pedestrian_start_side_vars,
            self.guide_pedestrian_end_side_vars,
            self.guide_pedestrian_distance_vars,
            self.guide_pedestrian_start_time_vars,
            self.guide_pedestrian_duration_vars,
            self.guide_audio_time_vars,
            self.guide_audio_file_vars,
            self.guide_visual_time_vars,
            self.guide_visual_file_vars,
        ):
            values.extend(mapping.values())

        unique: list[tk.Variable] = []
        seen: set[int] = set()
        for variable in values:
            key = id(variable)
            if key in seen:
                continue
            unique.append(variable)
            seen.add(key)
        return unique

    def _install_guide_live_preview_traces(self) -> None:
        for variable, token in self._guide_var_trace_tokens:
            try:
                variable.trace_remove("write", token)
            except tk.TclError:
                pass
        self._guide_var_trace_tokens = []
        for variable in self._guide_tracked_vars():
            try:
                token = variable.trace_add("write", self._schedule_inline_wizard_preview_refresh)
            except tk.TclError:
                continue
            self._guide_var_trace_tokens.append((variable, token))

    def _schedule_inline_wizard_preview_refresh(self, *_args: object) -> None:
        if not hasattr(self, "guide_prompt_preview_text"):
            return
        if getattr(self, "guide_collapsed_var", None) is not None and self.guide_collapsed_var.get():
            return
        if self._inline_wizard_preview_refresh_job is not None:
            try:
                self.after_cancel(self._inline_wizard_preview_refresh_job)
            except tk.TclError:
                pass
        self._inline_wizard_preview_refresh_job = self.after(60, self._refresh_inline_wizard_preview)

    def _refresh_inline_wizard_preview(self) -> None:
        self._inline_wizard_preview_refresh_job = None
        preview_text = getattr(self, "guide_prompt_preview_text", None)
        if preview_text is None:
            return
        if getattr(self, "guide_collapsed_var", None) is not None and self.guide_collapsed_var.get():
            return
        try:
            lines = self._guide_prompt_lines()
            preview_text.configure(state=tk.NORMAL)
            preview_text.delete("1.0", tk.END)
            preview_text.insert("1.0", "\n".join(lines).strip() + "\n")
            preview_text.yview_moveto(0)
            preview_text.configure(state=tk.DISABLED)
        except tk.TclError:
            return

    def _render_guide_stepper(self) -> None:
        step_labels = ("Basics", "Vehicles", "Actors", "Alerts", "N-key")
        if len(getattr(self, "_guide_stepper_chips", [])) != len(step_labels):
            for child in self.guide_stepper_frame.winfo_children():
                child.destroy()
            self._guide_stepper_chips = []
            for index, label in enumerate(step_labels):
                chip = tk.Label(
                    self.guide_stepper_frame,
                    text=f"{index + 1}. {label}",
                    padx=12,
                    pady=5,
                    font=(BODY_FONT_FAMILY, 10, "bold"),
                    cursor="hand2",
                    highlightthickness=1,
                )
                chip.pack(side=tk.LEFT, padx=(0, 6))
                chip.bind("<Button-1>", lambda _event, step=index: self._guide_set_step(step))
                self._guide_stepper_chips.append(chip)
        for index, label in enumerate(step_labels):
            active = index == self._guide_step_index
            complete = index < self._guide_step_index
            bg = "#22345d" if active else "#1a2740" if complete else "#111827"
            fg = "#dbe7ff" if active else "#b8c7de" if complete else self.PALETTE["muted"]
            border = "#4f6fb3" if active else "#2f3e56"
            self._guide_stepper_chips[index].configure(
                text=f"{index + 1}. {label}",
                bg=bg,
                fg=fg,
                highlightbackground=border,
            )

    def _guide_set_step(self, step_index: int) -> None:
        next_step = max(0, min(4, step_index))
        if next_step == self._guide_step_index:
            return
        self._guide_step_index = next_step
        self._render_guide_step()

    def _guide_refresh_current_step(self) -> None:
        self._guide_dirty_steps.add(self._guide_step_index)
        self._render_guide_step()

    def _guide_vehicle_count(self) -> int:
        try:
            return max(1, min(6, int(self.guide_vehicle_count_var.get())))
        except ValueError:
            return 1

    def _guide_add_vehicle(self) -> None:
        self.guide_vehicle_count_var.set(str(min(6, self._guide_vehicle_count() + 1)))
        self._guide_refresh_current_step()

    def _guide_remove_vehicle(self) -> None:
        self.guide_vehicle_count_var.set(str(max(1, self._guide_vehicle_count() - 1)))
        self._guide_refresh_current_step()

