    def _browse_guide_audio_file(self, cue_index: int) -> None:
        ensure_prompt_cue_asset_dirs_v2()
        path = filedialog.askopenfilename(
            title="Select TOR audio cue",
            initialdir=str(PROMPT_AUDITORY_CUE_DIR_V2),
            filetypes=[("Prompt auditory cue files", "*.wav")],
        )
        if not path:
            return
        try:
            selected = selected_prompt_auditory_cue_name_v2(path)
        except ValueError as exc:
            messagebox.showerror("Invalid Audio File", str(exc))
            return
        self.guide_audio_file_options = discover_prompt_auditory_cue_files_v2()
        self.guide_audio_file_vars[cue_index].set(selected)
        self._guide_refresh_current_step()

    def _browse_guide_visual_file(self, cue_index: int) -> None:
        ensure_prompt_cue_asset_dirs_v2()
        path = filedialog.askopenfilename(
            title="Select TOR visual cue",
            initialdir=str(PROMPT_VISUAL_CUE_DIR_V2),
            filetypes=[
                ("Prompt visual cue files", "*.png *.jpg *.jpeg *.svg *.bmp *.gif *.txt"),
            ],
        )
        if not path:
            return
        try:
            selected = selected_prompt_visual_cue_name_v2(path)
        except ValueError as exc:
            messagebox.showerror("Invalid Visual Cue File", str(exc))
            return
        self.guide_visual_file_options = discover_prompt_visual_cue_files_v2()
        self.guide_visual_file_vars[cue_index].set(selected)
        self._guide_refresh_current_step()

