    def _guide_next_step(self) -> None:
        self._guide_set_step(self._guide_step_index + 1)

    def _guide_previous_step(self) -> None:
        self._guide_set_step(self._guide_step_index - 1)

    def _guide_lane_label(self, lane: str, *, zh: bool) -> str:
        if not zh:
            return lane.lower()
        return {"Left": "左側", "Middle": "中間", "Right": "右側"}.get(lane, lane)

    def _guide_weather_label(self, weather: str, *, zh: bool) -> str:
        if not zh:
            return weather
        return {"clear": "晴天", "rain": "雨天", "fog": "霧天", "snow": "雪天"}.get(weather, weather)

    def _guide_obstacle_kind_label(self, kind: str, *, zh: bool) -> str:
        return kind

    def _guide_prompt_lines_for_step(self, step_index: int) -> list[str]:
        zh = self.guide_prompt_language_var.get() in {"中文", "Chinese", "zh", "中文"}
        ego_lane = self._guide_lane_label(self.guide_ego_lane_var.get(), zh=zh)
        vehicle_lane = self._guide_lane_label(self.guide_vehicle_lane_var.get(), zh=zh)
        target_lane = self._guide_lane_label(self.guide_vehicle_target_lane_var.get(), zh=zh)
        return_lane = self._guide_lane_label(self.guide_nkey_return_lane_var.get(), zh=zh)
        speed = self.guide_ego_speed_var.get().strip() or "50"
        total_time = self.guide_total_time_var.get().strip() or "30"
        gap = self.guide_gap_var.get().strip() or "7"
        lc_start = self.guide_lane_change_start_var.get().strip() or "5"
        lc_duration = self.guide_lane_change_duration_var.get().strip() or "5"

        if step_index == 0:
            if zh:
                return [
                    "# Step 1 基本場景",
                    f"道路是 {self.guide_road_var.get()}，天氣是 {self._guide_weather_label(self.guide_weather_var.get(), zh=True)}。",
                    f"場景總時長 {total_time} 秒。",
                    f"ego vehicle 在{ego_lane}車道，速度恆定 {speed} mph。",
                ]
            return [
                "# Step 1 Basics",
                f"The road is a {self.guide_road_var.get()} and the weather is {self.guide_weather_var.get()}.",
                f"Scenario duration is {total_time} seconds.",
                f"The ego vehicle starts in the {ego_lane} lane at a constant speed of {speed} mph.",
            ]
        if step_index == 1:
            keep_gap_text = "保持這個距離" if zh else "keep this distance"
            lines = ["# Step 2 車輛與距離"] if zh else ["# Step 2 Vehicles and gaps"]
            for vehicle_index in range(1, self._guide_vehicle_count() + 1):
                lane = self._guide_lane_label(self.guide_vehicle_lane_vars[vehicle_index].get(), zh=zh)
                target = self._guide_lane_label(self.guide_vehicle_target_lane_vars[vehicle_index].get(), zh=zh)
                gap_value = self.guide_vehicle_gap_vars[vehicle_index].get().strip() or "7"
                relative = self.guide_vehicle_relative_vars[vehicle_index].get()
                lc_time = self.guide_vehicle_lc_time_vars[vehicle_index].get().strip()
                lc_duration_value = self.guide_vehicle_lc_duration_vars[vehicle_index].get().strip() or "5"
                relative_zh = "前方" if relative == "ahead" else "後方"
                if zh:
                    lines.append(f"vehicle {vehicle_index} 在{lane}車道，位於 ego {relative_zh}，初始 gap {gap_value} 秒，{keep_gap_text}。")
                    if target != lane and lc_time:
                        lines.append(
                            f"場景啟動 {lc_time} 秒時，vehicle {vehicle_index} 從{lane}變到{target}車道，變道時長 {lc_duration_value} 秒。"
                        )
                    else:
                        lines.append(f"vehicle {vehicle_index} 保持{lane}車道。")
                else:
                    lines.append(
                        f"Vehicle {vehicle_index} starts in the {lane} lane, {relative} of ego, with initial gap {gap_value} seconds, and should {keep_gap_text}."
                    )
                    if target != lane and lc_time:
                        lines.append(
                            f"At {lc_time} seconds, vehicle {vehicle_index} changes from the {lane} lane to the {target} lane, with lane-change duration {lc_duration_value} seconds."
                        )
                    else:
                        lines.append(f"Vehicle {vehicle_index} keeps the {lane} lane.")
            return lines
        if step_index == 2:
            lines = ["# Step 3 Obstacle / Pedestrian"] if zh else ["# Step 3 Obstacles and pedestrians"]
            for obstacle_index in range(1, self._guide_obstacle_count() + 1):
                kind = self._guide_obstacle_kind_label(self.guide_obstacle_kind_vars[obstacle_index].get(), zh=zh)
                lane = self._guide_lane_label(self.guide_obstacle_lane_vars[obstacle_index].get(), zh=zh)
                distance = self.guide_obstacle_distance_vars[obstacle_index].get().strip() or "100"
                start_s = self.guide_obstacle_start_vars[obstacle_index].get().strip() or "5"
                end_s = self.guide_obstacle_end_vars[obstacle_index].get().strip() or "30"
                if zh:
                    lines.append(
                        f"obstacle {obstacle_index} 是 {kind}，在{lane}車道，位於 ego 前方 {distance} m，從 {start_s} 秒到 {end_s} 秒出現。"
                    )
                else:
                    lines.append(
                        f"Obstacle {obstacle_index} is a {kind} in the {lane} lane, {distance} m ahead of ego, appearing from {start_s} seconds to {end_s} seconds."
                    )
            for pedestrian_index in range(1, self._guide_pedestrian_count() + 1):
                start_side = self._guide_lane_label(self.guide_pedestrian_start_side_vars[pedestrian_index].get(), zh=zh)
                end_side = self._guide_lane_label(self.guide_pedestrian_end_side_vars[pedestrian_index].get(), zh=zh)
                distance = self.guide_pedestrian_distance_vars[pedestrian_index].get().strip() or "35"
                start_s = self.guide_pedestrian_start_time_vars[pedestrian_index].get().strip() or "8"
                duration_s = self.guide_pedestrian_duration_vars[pedestrian_index].get().strip() or "4"
                if zh:
                    lines.append(
                        f"pedestrian {pedestrian_index} 從{start_side}到{end_side}穿越，位於 ego 前方 {distance} m，開始時間 {start_s} 秒，持續 {duration_s} 秒。"
                    )
                else:
                    lines.append(
                        f"Pedestrian {pedestrian_index} crosses from {start_side} to {end_side}, {distance} m ahead of ego, starting at {start_s} seconds for {duration_s} seconds."
                    )
            if len(lines) == 1:
                lines.append("沒有額外 obstacle 或 pedestrian。" if zh else "No extra obstacle or pedestrian.")
            return lines

        if step_index == 3:
            lines = ["# Step 4 警示與 NDRT"] if zh else ["# Step 4 Alerts and NDRT"]
            tor = self.guide_tor_modality_var.get()
            if tor == "silent failure no TOR":
                lines.append("這是 silent failure，沒有 TOR、警示或提示。" if zh else "This is a silent failure with no TOR, warning, or alert.")
            elif tor != "none":
                tor_time = self.guide_tor_time_var.get().strip() or lc_start
                if zh:
                    lines.append(f"在 {tor_time} 秒發出 {tor} TOR，文字訊息 \"takeover\"。")
                else:
                    lines.append(f"At {tor_time} seconds, issue {tor} TOR with text message \"takeover\".")
            for cue_index in range(1, self._guide_audio_count() + 1):
                cue_time = self.guide_audio_time_vars[cue_index].get().strip() or self.guide_tor_time_var.get().strip() or lc_start
                file_name = self.guide_audio_file_vars[cue_index].get().strip()
                if not file_name:
                    continue
                if zh:
                    lines.append(f"在 {cue_time} 秒播放 TOR audio file {file_name}。")
                else:
                    lines.append(f"At {cue_time} seconds, play TOR audio file {file_name}.")
            for cue_index in range(1, self._guide_visual_count() + 1):
                cue_time = self.guide_visual_time_vars[cue_index].get().strip() or self.guide_tor_time_var.get().strip() or lc_start
                file_name = self.guide_visual_file_vars[cue_index].get().strip()
                if not file_name:
                    continue
                if zh:
                    lines.append(f"在 {cue_time} 秒顯示 TOR visual file {file_name}。")
                else:
                    lines.append(f"At {cue_time} seconds, show TOR visual file {file_name}.")
            ndrt = self.guide_ndrt_task_var.get()
            if ndrt != "none":
                duration = self.guide_ndrt_duration_var.get().strip() or "90"
                lines.append(
                    f"駕駛在 TOR 前執行 {ndrt} NDRT，持續 {duration} 秒。"
                    if zh
                    else f"Before the TOR, the driver performs a {ndrt} NDRT for {duration} seconds."
                )
            if len(lines) == 1:
                lines.append("沒有額外警示或 NDRT。" if zh else "No extra alert or NDRT.")
            return lines

        nkey_on = self.guide_nkey_enabled_var.get() or self.guide_scene_type_var.get() == "N-key intervention"
        lines = ["# Step 5 N-key 介入"] if zh else ["# Step 5 N-key intervention"]
        if not nkey_on:
            return []
        start_offset = self.guide_nkey_start_offset_var.get().strip() or "1"
        end_offset = self.guide_nkey_end_offset_var.get().strip() or "9"
        slow_delta = self.guide_nkey_slow_delta_var.get().strip() or "10"
        delay = self.guide_nkey_delay_var.get().strip() or "10"
        restore = self.guide_restore_speed_var.get().strip() or speed
        if zh:
            return lines + [
                f"變道時長控制在準確的 {lc_duration} 秒。",
                f"變道期間減速，在變道完成後車速以及後車距離實現 ego 的間隔距離為 {gap} 秒。",
                f"變道開始後 {start_offset} 秒到 {end_offset} 秒內，可以透過按鍵 N 減速到比 vehicle 1 慢 {slow_delta} mile/h。",
                f"在 {end_offset} 秒內成功按鍵的情況下，以按鍵後 {delay} 秒為節點，原本 merge 進{target_lane}車道的 vehicle 加速向{return_lane}車道變道；變道完成後，ego 恢復原來的駕駛速度 {restore} mile/h。",
            ]
        return lines + [
            f"Control the lane-change duration to exactly {lc_duration} s.",
            f"During the lane change, decelerate, and after the lane change is complete restore the ego gap to {gap} s.",
            f"From {start_offset} s after lane-change start until {end_offset} s, pressing N slows the ego to {slow_delta} mph slower than vehicle 1.",
            f"If N is pressed within {end_offset} s, {delay} s after the key press the vehicle that merged into the {target_lane} lane accelerates and changes to the {return_lane} lane. After completion, ego restores its original driving speed {restore} mph.",
        ]

    def _guide_prompt_lines(self, *, through_step: int | None = None) -> list[str]:
        final_step = 4 if through_step is None else through_step
        lines: list[str] = []
        for index in range(final_step + 1):
            step_lines = self._guide_prompt_lines_for_step(index)
            if not step_lines:
                continue
            if lines:
                lines.append("")
            lines.extend(step_lines)
        return lines

    def _push_prompt_history(self, label: str) -> None:
        if self._prompt_history_suspended or not hasattr(self, "prompt_text"):
            return
        prompt = self.prompt_text.get("1.0", "end-1c")
        output_name = self.output_var.get().strip() if hasattr(self, "output_var") else ""
        output_dir = self.output_dir_var.get().strip() if hasattr(self, "output_dir_var") else ""
        if self._prompt_history_stack and self._prompt_history_stack[-1].get("prompt") == prompt:
            return
        self._prompt_history_stack.append({"label": label, "prompt": prompt, "output": output_name, "output_dir": output_dir})
        if len(self._prompt_history_stack) > self._prompt_history_limit:
            self._prompt_history_stack = self._prompt_history_stack[-self._prompt_history_limit :]

    def _restore_previous_prompt(self) -> None:
        if not self._prompt_history_stack:
            self.status_var.set("No previous prompt transform to restore.")
            return
        snapshot = self._prompt_history_stack.pop()
        self._prompt_history_suspended = True
        try:
            self._replace_editor_prompt(snapshot.get("prompt", ""))
            if snapshot.get("output"):
                self.output_var.set(snapshot["output"])
            if snapshot.get("output_dir"):
                self.output_dir_var.set(snapshot["output_dir"])
        finally:
            self._prompt_history_suspended = False
        self._analyze_prompt()
        self.status_var.set(f"Restored prompt before: {snapshot.get('label', 'last transform')}.")

    def _replace_prompt_with_lines(self, lines: list[str]) -> None:
        self._push_prompt_history("wizard build")
        self._invalidate_prompt_editor_caches()
        self.prompt_text.delete("1.0", tk.END)
        self.prompt_text.insert("1.0", "\n".join(lines).strip() + "\n")
        self._highlight_prompt(force=True)
        self._refresh_prompt_diagnostics()
        self._update_prompt_editor_visuals()
        self._schedule_live_analyze(delay_ms=300)

    def _append_prompt_lines(self, lines: list[str]) -> None:
        self._push_prompt_history("append wizard step")
        existing = self.prompt_text.get("1.0", "end-1c")
        if existing.strip():
            self.prompt_text.insert(tk.END, "\n\n")
        self.prompt_text.insert(tk.END, "\n".join(lines).strip() + "\n")
        self._highlight_prompt(force=True)
        self._refresh_prompt_diagnostics()
        self._update_prompt_editor_visuals()

    def _replace_editor_prompt(self, text: str) -> None:
        normalized_text = text.strip() + ("\n" if text.strip() else "")
        if self.prompt_text.get("1.0", "end-1c") != normalized_text.rstrip("\n"):
            self._push_prompt_history("prompt rewrite")
        self._invalidate_prompt_editor_caches()
        self.prompt_text.edit_separator()
        self.prompt_text.delete("1.0", tk.END)
        self.prompt_text.insert("1.0", normalized_text)
        self.prompt_text.edit_separator()
        self._highlight_prompt(force=True)
        self._refresh_prompt_diagnostics()
        self._update_prompt_editor_visuals()

    def _apply_preview_to_insight(self, preview: PromptPreviewResultV2) -> None:
        self._last_preview = preview if preview.ok else None
        self._set_result_text(self._analysis_display_text(preview), ok=preview.ok, language=preview.language)
        self._refresh_prompt_diagnostics(preview)
        self._refresh_quick_fix_buttons(preview)
        if preview.ok:
            self.preview_button.configure(state=tk.NORMAL)
            self.generate_button.configure(state=tk.NORMAL)
        else:
            self.preview_button.configure(state=tk.DISABLED)
            self.generate_button.configure(state=tk.DISABLED)
        self.insight_tab_var.set("Parser")
        self._refresh_workspace_chrome()

    def _cancel_live_analyze_job(self) -> None:
        if self._live_analyze_job is None:
            return
        try:
            self.after_cancel(self._live_analyze_job)
        except tk.TclError:
            pass
        self._live_analyze_job = None

    def _request_analyze_prompt(self) -> None:
        self._cancel_live_analyze_job()
        if self._analysis_request_job is not None:
            try:
                self.after_cancel(self._analysis_request_job)
            except tk.TclError:
                pass
        self.status_var.set("Analyzing prompt...")
        self._set_workspace_mode("Check")
        self.insight_tab_var.set("Parser")
        self._refresh_workspace_chrome()
        self._analysis_request_job = self.after(10, self._run_requested_analyze_prompt)

    def _run_requested_analyze_prompt(self) -> None:
        self._analysis_request_job = None
        self._analyze_prompt()

    def _request_scenario_preview(self) -> None:
        if self._preview_request_job is not None:
            try:
                self.after_cancel(self._preview_request_job)
            except tk.TclError:
                pass
        self.status_var.set("Opening preview...")
        self._set_workspace_mode("Preview")
        self._set_insight_tab("Preview")
        self._preview_request_job = self.after(10, self._run_requested_scenario_preview)

    def _run_requested_scenario_preview(self) -> None:
        self._preview_request_job = None
        self._open_scenario_preview()

    def _toggle_live_analyze(self) -> None:
        if self.live_analyze_var.get():
            self.status_var.set("Live Analyze is on. Parser checks update after you pause typing.")
            self._schedule_live_analyze(delay_ms=120)
        else:
            self._cancel_live_analyze_job()
            self.status_var.set("Live Analyze is off. Use Analyze when you want to check the prompt.")

    def _on_validation_profile_changed(self) -> None:
        if not hasattr(self, "prompt_text"):
            return
        if self.prompt_text.get("1.0", "end-1c").strip():
            self._last_live_analyze_text = ""
            self._schedule_live_analyze(delay_ms=120)
        self.status_var.set(f"Validation profile: {self.validation_profile_var.get()}")

    def _schedule_live_analyze(self, delay_ms: int = 650) -> None:
        if not getattr(self, "live_analyze_var", None) or not self.live_analyze_var.get():
            return
        if self._live_analyze_job is not None:
            try:
                self.after_cancel(self._live_analyze_job)
            except tk.TclError:
                pass
        self._live_analyze_job = self.after(delay_ms, self._run_live_analyze)

    def _run_live_analyze(self) -> None:
        self._live_analyze_job = None
        if self._resize_light_mode:
            self._schedule_live_analyze(delay_ms=350)
            return
        prompt = self.prompt_text.get("1.0", "end-1c")
        if not prompt.strip() or prompt == self._last_live_analyze_text:
            return
        self._last_live_analyze_text = prompt
        preview = self._build_preview_from_editor()
        self._last_preview = preview if preview.ok else None
        self._set_result_text(self._analysis_display_text(preview), ok=preview.ok, language=preview.language)
        self._refresh_prompt_diagnostics(preview)
        self._refresh_quick_fix_buttons(preview)
        self.preview_button.configure(state=tk.NORMAL if preview.ok else tk.DISABLED)
        self.generate_button.configure(state=tk.NORMAL if preview.ok else tk.DISABLED)
        self.insight_tab_var.set("Parser")
        self._refresh_workspace_chrome()
        self.status_var.set(
            f"Live Analyze: {len(preview.output_names)} scenario(s) ready."
            if preview.ok
            else "Live Analyze: more detail is needed."
        )

    def _preview_signature_from_editor(self) -> tuple[str, str, str]:
        prompt = self.prompt_text.get("1.0", "end-1c")
        requested_output = self.output_var.get().strip() or DEFAULT_OUTPUT_FILENAME
        return (prompt, requested_output, str(Path(self.template_path).resolve()).lower())

    def _build_preview_from_editor(self) -> PromptPreviewResultV2:
        signature = self._preview_signature_from_editor()
        if self._preview_cache_signature == signature and self._preview_cache_result is not None:
            return self._preview_cache_result
        preview = build_prompt_preview_v2(
            template_path=self.template_path,
            prompt_text=signature[0],
            requested_output=signature[1],
        )
        self._preview_cache_signature = signature
        self._preview_cache_result = preview
        return preview

    def _missing_item_line_matches(self, missing_items: list[str], line: str) -> list[str]:
        lowered = line.lower()
        matches: list[str] = []
        for item in missing_items:
            item_lower = item.lower()
            if (
                ("ego" in item_lower and "ego" in lowered)
                or ("vehicle" in item_lower and re.search(r"\b(?:v\d+|vehicle|veh|car)\b|\u8eca|\u车", lowered))
                or ("obstacle" in item_lower and re.search(r"\b(?:obs|obstacle|barrier|construction)\b|\u969c|\u65bd\u5de5", lowered))
                or ("pedestrian" in item_lower and re.search(r"\b(?:ped|pedestrian|walker)\b|\u884c\u4eba", lowered))
                or ("tor" in item_lower and re.search(r"\b(?:tor|alert|cue|warning)\b|\u8b66|\u63d0\u793a", lowered))
                or ("audio" in item_lower and re.search(r"\b(?:audio|sound|wav)\b|\u8072|\u58f0", lowered))
                or ("visual" in item_lower and re.search(r"\b(?:visual|image|png|jpg)\b|\u8996|\u89c6|\u5716|\u56fe", lowered))
                or ("lane" in item_lower and re.search(r"\b(?:lane|left|middle|right)\b|\u5de6|\u53f3|\u4e2d", lowered))
                or ("speed" in item_lower and re.search(r"\b(?:speed|mph|kmh|kph|mile)\b|\u901f", lowered))
                or ("gap" in item_lower and re.search(r"\b(?:gap|headway|ahead|behind|front|rear)\b|\u9593|\u95f4|\u524d|\u5f8c|\u540e", lowered))
            ):
                matches.append(item)
        return matches

    def _error_location_lines(self, preview: PromptPreviewResultV2) -> list[str]:
        if preview.ok:
            return []
        missing_items = self._extract_missing_items(preview.message)
        if not missing_items:
            return []
        lines = [prompt_block_header_v2("Error Location")]
        content_lines = self.prompt_text.get("1.0", "end-1c").splitlines()
        located = False
        for line_number, line in enumerate(content_lines, start=1):
            matches = self._missing_item_line_matches(missing_items, line)
            if not matches:
                continue
            located = True
            shown = "; ".join(matches[:3])
            lines.append(f"- Line {line_number}: add or clarify {shown}.")
        if not located:
            lines.append("- No single line owns the missing field. Add a new explicit line near the related actor or timed event.")
        return lines

    def _scenario_qa_lines(self, preview: PromptPreviewResultV2) -> list[str]:
        lines = [prompt_block_header_v2("Mini Simulator QA")]
        if not preview.ok or not preview.params_list:
            lines.append("- Parser must pass before motion QA can run.")
            return lines
        try:
            defaults = self._prompt_template_defaults()
        except Exception as exc:  # noqa: BLE001
            lines.append(f"- QA skipped: could not read template defaults ({exc}).")
            return lines
        warnings: list[str] = []
        errors: list[str] = []
        for scenario_index, params in enumerate(preview.params_list, start=1):
            ego = params.vehicles.get("ego")
            if ego is None:
                errors.append(f"Scenario {scenario_index}: ego vehicle is missing.")
                continue
            latest_event = self._latest_event_time_for_params(params)
            if latest_event > params.total_experiment_time_s + 0.01:
                errors.append(
                    f"Scenario {scenario_index}: latest event {format_number(latest_event)}s is after scenario end "
                    f"{format_number(params.total_experiment_time_s)}s."
                )
            if params.total_experiment_time_s - latest_event < 3.0 and latest_event > 0.0:
                warnings.append(f"Scenario {scenario_index}: add 3+ seconds after the last event for recovery.")
            vehicles = [config for config in iter_script_vehicle_configs_v2(params) if vehicle_enabled_v2(config)]
            check_times = {0.0, max(params.total_experiment_time_s, 0.0)}
            for config in vehicles:
                for event in lane_change_events_for_vehicle_v2(config):
                    check_times.add(max(event.time_s, 0.0))
                    check_times.add(max(event.time_s + event.duration_s, 0.0))
                for point in config.gap_points:
                    check_times.add(max(point.time_s, 0.0))
            for time_s in sorted(check_times):
                if time_s > params.total_experiment_time_s + 0.01:
                    continue
                lane_groups: dict[str, list[tuple[VehicleConfigV2, float]]] = {}
                for config in vehicles:
                    lane_groups.setdefault(self._lane_for_vehicle_at_time(config, time_s), []).append(
                        (config, project_vehicle_abscissa_v2(params, defaults, config, time_s))
                    )
                for lane_name, lane_vehicles in lane_groups.items():
                    lane_vehicles.sort(key=lambda item: item[1])
                    for first, second in zip(lane_vehicles, lane_vehicles[1:]):
                        gap_m = abs(second[1] - first[1])
                        if gap_m < 8.0:
                            errors.append(
                                f"Scenario {scenario_index}: {first[0].label} and {second[0].label} are only "
                                f"{format_number(gap_m)}m apart in {lane_name} lane at {format_number(time_s)}s."
                            )
                        elif gap_m < 18.0:
                            warnings.append(
                                f"Scenario {scenario_index}: tight {lane_name} lane gap "
                                f"({format_number(gap_m)}m) at {format_number(time_s)}s."
                            )
            for obstacle in iter_obstacle_configs_v2(params):
                if not obstacle.enabled:
                    continue
                if obstacle.end_time_s < obstacle.start_time_s:
                    errors.append(f"Scenario {scenario_index}: {obstacle.label} ends before it starts.")
                if obstacle.start_time_s > params.total_experiment_time_s:
                    errors.append(f"Scenario {scenario_index}: {obstacle.label} appears after the scenario ends.")
            for pedestrian in params.pedestrians.values():
                if pedestrian.enabled and pedestrian.start_time_s + pedestrian.duration_s > params.total_experiment_time_s + 0.01:
                    warnings.append(f"Scenario {scenario_index}: {pedestrian.label} crossing continues past scenario end.")
            if n_key_intervention_enabled_v2(params):
                n_key = params.n_key_intervention
                lane_change_vehicle = params.vehicles.get(n_key.lane_change_vehicle_key)
                if lane_change_vehicle is None:
                    errors.append(f"Scenario {scenario_index}: N-key references a missing lane-change vehicle.")
                else:
                    base_time_s = lane_change_base_time_s_v2(lane_change_vehicle)
                    window_start = base_time_s + n_key.window_start_offset_s
                    window_end = base_time_s + n_key.window_end_offset_s
                    if window_start < base_time_s:
                        warnings.append(f"Scenario {scenario_index}: N-key window starts before lane change.")
                    if window_end > params.total_experiment_time_s:
                        errors.append(f"Scenario {scenario_index}: N-key window ends after scenario duration.")
        for message in errors[:8]:
            lines.append(f"- ERROR: {message}")
        for message in warnings[:10]:
            lines.append(f"- WARN: {message}")
        if not errors and not warnings:
            lines.append("- No obvious timing, lane, or spacing conflicts detected.")
        return lines

    def _analysis_display_text(self, preview: PromptPreviewResultV2) -> str:
        sections: list[str] = []
        sections.extend(self._scenario_completeness_lines(preview))
        sections.extend(self._scenario_health_lines(preview))
        method_lines = self._method_block_lines(preview)
        if method_lines:
            sections.extend(("", *method_lines))
        location_lines = self._error_location_lines(preview)
        if location_lines:
            sections.extend(("", *location_lines))
        validation_lines = self._validation_profile_lines(preview)
        if validation_lines:
            sections.extend(("", *validation_lines))
        qa_lines = self._scenario_qa_lines(preview)
        if qa_lines:
            sections.extend(("", *qa_lines))
        diff_lines = self._variant_diff_lines(preview)
        if diff_lines:
            sections.extend(("", *diff_lines))
        change_diff_lines = self._prompt_change_diff_lines(preview)
        if change_diff_lines:
            sections.extend(("", *change_diff_lines))
        if preview.message.strip():
            sections.extend(("", preview.message.strip()))
        return "\n".join(sections).strip()

    def _asset_visual_names_for_params(self, params: ScenarioParametersV2) -> list[str]:
        visual_names: list[str] = []
        for note in params.scene_notes:
            match = re.search(r"review_visual_tor_file_\d+\s*=\s*[^:]+:(?P<name>.+)$", note)
            if match:
                visual_names.append(match.group("name").strip())
        return visual_names

    def _validation_profile_lines(self, preview: PromptPreviewResultV2) -> list[str]:
        profile = self.validation_profile_var.get() or "Study-ready"
        lines = [prompt_block_header_v2(f"Validation Profile: {profile}")]
        if not preview.ok:
            missing_count = len(self._extract_missing_items(preview.message))
            lines.append(f"- Parser must be fixed first ({missing_count} missing/ambiguous item(s)).")
            return lines
        if not preview.params_list:
            lines.append("- No scenario parameters found.")
            return lines
        warnings: list[str] = []
        errors: list[str] = []
        output_seen: set[str] = set()
        for index, params in enumerate(preview.params_list, start=1):
            vehicle_count, obstacle_count, pedestrian_count = self._scenario_actor_counts(params)
            latest_event = self._latest_event_time_for_params(params)
            if latest_event > params.total_experiment_time_s + 0.01:
                errors.append(f"Scenario {index}: latest event exceeds scenario duration.")
            if params.output_filename in output_seen:
                errors.append(f"Scenario {index}: duplicate output filename {params.output_filename}.")
            output_seen.add(params.output_filename)
            if not params.output_filename.lower().endswith(".sce"):
                errors.append(f"Scenario {index}: output filename should end with .sce.")
            if profile in {"Study-ready", "Strict SCANeR"}:
                if params.total_experiment_time_s <= 0:
                    errors.append(f"Scenario {index}: scenario duration is missing.")
                if vehicle_count == 0 and obstacle_count == 0 and pedestrian_count == 0:
                    warnings.append(f"Scenario {index}: no non-ego actor is active.")
                has_dynamic_event = any(
                    lane_change_events_for_vehicle_v2(config) or config.stop_enabled or config.gap_points
                    for config in iter_script_vehicle_configs_v2(params)
                    if vehicle_enabled_v2(config)
                )
                if not has_dynamic_event and obstacle_count == 0 and pedestrian_count == 0:
                    warnings.append(f"Scenario {index}: no timed vehicle/obstacle/pedestrian event detected.")
                if obstacle_count == 0 and pedestrian_count == 0:
                    warnings.append(f"Scenario {index}: no obstacle or pedestrian hazard.")
                if not params.audio_events and not self._asset_visual_names_for_params(params):
                    warnings.append(f"Scenario {index}: no TOR audio/visual cue.")
            if profile == "Strict SCANeR":
                output_path = prompt_scenario_output_path_v2(
                    params.output_filename,
                    self.template_path,
                    self._selected_output_dir(),
                )
                if output_path.exists():
                    warnings.append(f"Scenario {index}: output file already exists and would be overwritten.")
                for event in params.audio_events:
                    audio_path = PROMPT_AUDITORY_CUE_DIR_V2 / event.file_name
                    if not audio_path.exists():
                        errors.append(f"Scenario {index}: missing audio asset {event.file_name}.")
                for visual_name in self._asset_visual_names_for_params(params):
                    visual_path = PROMPT_VISUAL_CUE_DIR_V2 / visual_name
                    if not visual_path.exists():
                        errors.append(f"Scenario {index}: missing visual asset {visual_name}.")
        if errors:
            lines.append("- Errors:")
            lines.extend(f"  - {message}" for message in errors[:8])
        if warnings and profile != "Relaxed":
            lines.append("- Warnings:")
            lines.extend(f"  - {message}" for message in warnings[:10])
        if not errors and (not warnings or profile == "Relaxed"):
            lines.append("- Passed for this profile.")
        return lines

    def _latest_event_time_for_params(self, params: ScenarioParametersV2) -> float:
        latest = 0.0
        for config in iter_script_vehicle_configs_v2(params):
            if not vehicle_enabled_v2(config):
                continue
            for event in lane_change_events_for_vehicle_v2(config):
                latest = max(latest, event.time_s + max(event.duration_s, 0.0))
            if config.stop_enabled:
                latest = max(latest, config.stop_time_s)
            for point in config.gap_points:
                latest = max(latest, point.time_s)
        for obstacle in iter_obstacle_configs_v2(params):
            if obstacle.enabled:
                latest = max(latest, obstacle.end_time_s)
        for pedestrian in params.pedestrians.values():
            if pedestrian.enabled:
                latest = max(latest, pedestrian.start_time_s + max(pedestrian.duration_s, 0.0))
        for event in params.audio_events:
            latest = max(latest, event.time_s)
        if n_key_intervention_enabled_v2(params):
            n_key = params.n_key_intervention
            lane_change_vehicle = params.vehicles.get(n_key.lane_change_vehicle_key)
            base_time = lane_change_base_time_s_v2(lane_change_vehicle) if lane_change_vehicle else 0.0
            latest = max(latest, base_time + n_key.window_end_offset_s + n_key.delayed_merge_offset_s)
        return latest

    def _scenario_actor_counts(self, params: ScenarioParametersV2) -> tuple[int, int, int]:
        vehicle_count = sum(
            1
            for config in iter_script_vehicle_configs_v2(params)
            if config.key != "ego" and vehicle_enabled_v2(config)
        )
        obstacle_count = sum(1 for obstacle in iter_obstacle_configs_v2(params) if obstacle.enabled)
        pedestrian_count = sum(1 for pedestrian in params.pedestrians.values() if pedestrian.enabled)
        return vehicle_count, obstacle_count, pedestrian_count

    def _assumption_lines_from_prompt(self) -> list[str]:
        lines: list[str] = []
        for raw_line in self.prompt_text.get("1.0", "end-1c").splitlines():
            stripped = raw_line.strip()
            if re.search(r"\[?\s*assumed\s+default\s*\]?|safe\s+default|\u5047\u8a2d|\u5047\u8bbe", stripped, flags=re.IGNORECASE):
                lines.append(stripped)
        return lines

    def _scenario_completeness_lines(self, preview: PromptPreviewResultV2) -> list[str]:
        lines = [prompt_block_header_v2("Scenario Completeness")]
        assumptions = self._assumption_lines_from_prompt()
        if not preview.ok:
            missing_items = self._extract_missing_items(preview.message)
            critical_keywords = (
                "lane",
                "speed",
                "time",
                "duration",
                "distance",
                "gap",
                "actor",
                "obstacle",
                "event",
                "response",
                "tor",
                "alert",
                "cue",
            )
            critical = [item for item in missing_items if any(keyword in item.lower() for keyword in critical_keywords)]
            optional = [item for item in missing_items if item not in critical]
            score = max(5, 80 - len(critical) * 12 - len(optional) * 5)
            if not self.prompt_text.get("1.0", "end-1c").strip():
                score = 0
            lines.append(f"Completeness: {score}/100")
            lines.append(f"- Critical missing: {len(critical)}")
            lines.append(f"- Optional/metadata missing: {len(optional)}")
            if critical:
                lines.extend(f"  - {item}" for item in critical[:8])
            if assumptions:
                lines.append("- Explicit assumptions already in prompt:")
                lines.extend(f"  - {line}" for line in assumptions[:5])
            return lines

        if not preview.params_list:
            lines.append("Completeness: 0/100")
            lines.append("- Parser succeeded but produced no scenarios.")
            return lines

        optional_notes: list[str] = []
        errors: list[str] = []
        score = 100
        for index, params in enumerate(preview.params_list, start=1):
            vehicle_count, obstacle_count, pedestrian_count = self._scenario_actor_counts(params)
            if params.total_experiment_time_s <= 0:
                errors.append(f"Scenario {index}: missing total duration.")
            if vehicle_count == 0:
                optional_notes.append(f"Scenario {index}: no non-ego vehicle actor.")
            if obstacle_count == 0 and pedestrian_count == 0:
                optional_notes.append(f"Scenario {index}: no obstacle or pedestrian hazard.")
            if not params.audio_events and not self._asset_visual_names_for_params(params):
                optional_notes.append(f"Scenario {index}: no file-based TOR cue.")
            if self._latest_event_time_for_params(params) <= 0:
                optional_notes.append(f"Scenario {index}: no timed event detected.")
        score = max(0, score - len(errors) * 25 - len(optional_notes) * 5)
        lines.append(f"Completeness: {score}/100")
        lines.append("- Critical fields: passed" if not errors else "- Critical fields need fixes:")
        lines.extend(f"  - {item}" for item in errors[:6])
        if optional_notes:
            lines.append("- Optional/research fidelity notes:")
            lines.extend(f"  - {item}" for item in optional_notes[:8])
        if assumptions:
            lines.append("- Explicit assumptions:")
            lines.extend(f"  - {line}" for line in assumptions[:5])
        if not errors and not optional_notes:
            lines.append("- No obvious missing scenario fields.")
        return lines

    def _method_block_lines(self, preview: PromptPreviewResultV2 | None = None) -> list[str]:
        preview = preview or self._build_preview_from_editor()
        prompt = self.prompt_text.get("1.0", "end-1c")
        missing_items = self._extract_missing_items(preview.message)
        lower_missing = " | ".join(item.lower() for item in missing_items)

        def has(pattern: str) -> bool:
            return re.search(pattern, prompt, flags=re.IGNORECASE | re.DOTALL) is not None

        def block_status(pattern: str, missing_keywords: tuple[str, ...]) -> str:
            if any(keyword in lower_missing for keyword in missing_keywords):
                return "ambiguous"
            return "detected" if has(pattern) else "missing"

        blocks = [
            (
                "Road / environment",
                block_status(r"\b(?:road|lane|highway|motorway|urban|rural|rain|weather)\b|\u8eca\u9053|\u8f66\u9053|\u96e8|\u9ad8\u901f", ("road", "lane", "weather")),
                "Road type, lane count, weather, and terrain mapping.",
            ),
            (
                "Ego / AV",
                block_status(r"\b(?:ego|subject|automated\s+vehicle|av)\b|\u81ea\u8eca|\u81ea\u8f66|\u4e3b\u8eca|\u4e3b\u8f66", ("ego", "av lane", "speed")),
                "Starting lane, speed, automation mode, and driver response.",
            ),
            (
                "Traffic / vehicles",
                block_status(r"\b(?:vehicle|fleet|traffic|rear|lead|following|oncoming)\b|\u8eca|\u8f66|\u8eca\u968a|\u8f66\u961f", ("vehicle", "rear", "gap", "fleet")),
                "Other vehicles, lane positions, gaps, and scripted maneuvers.",
            ),
            (
                "Obstacle / hazard",
                block_status(r"\b(?:obstacle|construction|barrier|accident|hazard|bicyclist|pedestrian|cow|police)\b|\u969c|\u65bd\u5de5|\u4e8b\u6545|\u884c\u4eba", ("obstacle", "hazard", "event type", "distance")),
                "Obstacle type, lane, distance, active time, and disappearance.",
            ),
            (
                "TOR / HMI cue",
                block_status(r"\b(?:tor|takeover|alert|warning|cue|audio|visual|hmi|display)\b|\u63a5\u7ba1|\u8b66\u793a|\u63d0\u793a", ("tor", "alert", "cue", "audio", "visual")),
                "Cue time, cue modality, and cue asset or metadata-only policy.",
            ),
            (
                "Driver / ego response",
                block_status(r"\b(?:brake|take over|takeover|lane change|change lanes|manual|avoid|steer)\b|\u715e|\u5239|\u63a5\u7ba1|\u8b8a\u9053|\u53d8\u9053", ("response", "avoidance", "target lane")),
                "Brake, lane change, manual takeover, or metadata-only response.",
            ),
            (
                "Variants / batch factors",
                block_status(r"\b(?:variant|variants|condition|lead time|traffic density|random|counterbalance|scenario\s+\d+)\b|\u8b8a\u9ad4|\u53d8\u4f53|\u689d\u4ef6|\u6761\u4ef6", ("variant", "selection", "lead time")),
                "Lead-time, traffic, cue, speed, or scenario matrices.",
            ),
        ]

        lines = [prompt_block_header_v2("Paper Method Import Mode")]
        lines.append("Block status: detected / ambiguous / missing")
        for name, status, description in blocks:
            marker = {"detected": "OK", "ambiguous": "ASK", "missing": "--"}[status]
            lines.append(f"- {marker} {name}: {status}")
            lines.append(f"  {description}")
        if missing_items:
            lines.append("")
            lines.append("Fields to clarify before generation:")
            lines.extend(f"- {item}" for item in missing_items[:10])
        return lines

    def _show_method_import_mode(self) -> None:
        preview = self._build_preview_from_editor()
        self._apply_preview_to_insight(preview)
        self._set_plain_insight_text("Paper Method Mode", "\n".join(self._method_block_lines(preview)))
        self.status_var.set("Paper Method Mode split the prompt into scenario blocks.")

    def _scenario_health_lines(self, preview: PromptPreviewResultV2) -> list[str]:
        lines = [prompt_block_header_v2("Scenario Health")]
        if not preview.ok:
            missing_items = self._extract_missing_items(preview.message)
            score = 35 if self.prompt_text.get("1.0", "end-1c").strip() else 10
            lines.append(f"Score: {score}/100 | Needs clarification")
            lines.append("- Generate is disabled until required fields are clear.")
            if missing_items:
                lines.append(f"- Missing fields: {len(missing_items)}")
            return lines
        if not preview.params_list:
            lines.append("Score: 0/100 | No scenario parsed")
            return lines

        warnings: list[str] = []
        errors: list[str] = []
        output_names: set[str] = set()
        for index, params in enumerate(preview.params_list, start=1):
            total_time = max(float(params.total_experiment_time_s), 0.0)
            latest_event = self._latest_event_time_for_params(params)
            vehicle_count, obstacle_count, pedestrian_count = self._scenario_actor_counts(params)
            if params.output_filename in output_names:
                warnings.append(f"Scenario {index}: output filename duplicates another variant.")
            output_names.add(params.output_filename)
            if total_time < 10.0:
                warnings.append(f"Scenario {index}: total duration is very short ({format_number(total_time)} s).")
            if latest_event > total_time + 0.01:
                errors.append(
                    f"Scenario {index}: latest event at {format_number(latest_event)} s exceeds "
                    f"duration {format_number(total_time)} s."
                )
            elif total_time - latest_event < 2.0 and latest_event > 0.0:
                warnings.append(f"Scenario {index}: less than 2 s remains after the last event.")
            if vehicle_count == 0 and obstacle_count == 0 and pedestrian_count == 0 and not params.audio_events:
                warnings.append(f"Scenario {index}: only ego is active; add a vehicle, obstacle, pedestrian, or cue.")
            if n_key_intervention_enabled_v2(params):
                n_key = params.n_key_intervention
                lane_change_vehicle = params.vehicles.get(n_key.lane_change_vehicle_key)
                if lane_change_vehicle is None or first_lane_change_event_v2(lane_change_vehicle) is None:
                    errors.append(f"Scenario {index}: N-key intervention has no lane-change vehicle.")

        score = max(0, 100 - len(errors) * 30 - len(warnings) * 7)
        label = "Ready" if not errors and not warnings else "Review warnings" if not errors else "Needs fixes"
        if len(preview.params_list) > 1 and not errors:
            label = "Batch ready" if not warnings else "Batch review"
        lines.append(f"Score: {score}/100 | {label}")
        lines.append(f"- Variants: {len(preview.params_list)}")
        lines.append(f"- Outputs: {len(preview.output_names)} file(s)")
        if errors:
            lines.append("- Errors:")
            lines.extend(f"  - {message}" for message in errors[:6])
        if warnings:
            lines.append("- Warnings:")
            lines.extend(f"  - {message}" for message in warnings[:8])
        if not errors and not warnings:
            lines.append("- No timing or structure issues detected.")
        return lines

    def _first_variant_vehicle(self, params: ScenarioParametersV2) -> VehicleConfigV2 | None:
        for config in iter_script_vehicle_configs_v2(params):
            if config.key != "ego" and vehicle_enabled_v2(config):
                return config
        return None

    def _variant_signature(self, params: ScenarioParametersV2) -> dict[str, str]:
        ego = params.vehicles["ego"]
        vehicle = self._first_variant_vehicle(params)
        vehicle_count, obstacle_count, pedestrian_count = self._scenario_actor_counts(params)
        signature = {
            "duration": f"{format_number(params.total_experiment_time_s)}s",
            "ego lane": ego.initial_lane,
            "ego speed": prompt_dsl_speed_token_v2(ego.speed_kmh),
            "vehicles": str(vehicle_count),
            "obstacles": str(obstacle_count),
            "pedestrians": str(pedestrian_count),
            "audio cues": str(len(params.audio_events)),
            "N-key": "on" if n_key_intervention_enabled_v2(params) else "off",
            "output": params.output_filename,
        }
        if vehicle is None:
            signature.update(
                {
                    "v1 lane": "none",
                    "v1 gap": "none",
                    "v1 target": "none",
                    "v1 event": "none",
                }
            )
            return signature
        relation = "ahead" if vehicle.initial_offset_m >= 0 else "behind"
        lane_events = lane_change_events_for_vehicle_v2(vehicle)
        signature["v1 lane"] = vehicle.initial_lane
        signature["v1 gap"] = f"{relation} {prompt_dsl_gap_time_token_v2(vehicle.initial_offset_m, ego.speed_kmh)}"
        signature["v1 target"] = " -> ".join(event.target_lane for event in lane_events) if lane_events else "none"
        signature["v1 event"] = (
            ", ".join(f"{format_number(event.time_s)}s/{format_number(event.duration_s)}s" for event in lane_events)
            if lane_events
            else "none"
        )
        return signature

    def _variant_diff_lines(self, preview: PromptPreviewResultV2) -> list[str]:
        if not preview.ok or len(preview.params_list) <= 1:
            return []
        base = self._variant_signature(preview.params_list[0])
        lines = [prompt_block_header_v2("Scenario Diff"), "Compared with Scenario 1:"]
        for index, params in enumerate(preview.params_list[1:9], start=2):
            signature = self._variant_signature(params)
            changes = [
                f"{key}: {base[key]} -> {value}"
                for key, value in signature.items()
                if value != base.get(key)
            ]
            lines.append(f"- Scenario {index}: " + ("; ".join(changes[:8]) if changes else "same core parameters"))
        if len(preview.params_list) > 9:
            lines.append(f"- ... {len(preview.params_list) - 9} more variants")
        return lines

    def _prompt_change_diff_lines(self, preview: PromptPreviewResultV2) -> list[str]:
        reference = self._diff_reference_preview
        if (
            reference is None
            or not reference.ok
            or not preview.ok
            or not reference.params_list
            or not preview.params_list
        ):
            return []
        before = self._variant_signature(reference.params_list[0])
        after = self._variant_signature(preview.params_list[0])
        changes = [
            f"- {key}: {before_value} -> {after_value}"
            for key, before_value in before.items()
            if after.get(key) != before_value
            for after_value in [after.get(key, "")]
        ]
        if len(reference.params_list) != len(preview.params_list):
            changes.insert(0, f"- variants: {len(reference.params_list)} -> {len(preview.params_list)}")
        if not changes:
            return []
        lines = [prompt_block_header_v2("Prompt Change Diff"), "Compared with the previous successful Analyze:"]
        lines.extend(changes[:10])
        if len(changes) > 10:
            lines.append(f"- ... {len(changes) - 10} more changes")
        return lines

    def _show_variant_diff(self) -> None:
        previous_preview = self._last_preview
        preview = self._build_preview_from_editor()
        self._diff_reference_preview = previous_preview if preview.ok and previous_preview is not None else None
        self._apply_preview_to_insight(preview)
        diff_lines = self._prompt_change_diff_lines(preview)
        variant_lines = self._variant_diff_lines(preview)
        if diff_lines and variant_lines:
            diff_lines.extend(("", *variant_lines))
        elif variant_lines:
            diff_lines = variant_lines
        if not diff_lines:
            diff_lines = [
                prompt_block_header_v2("Scenario Diff"),
                "No previous successful analysis or batch variants are available to compare.",
            ]
        self._set_plain_insight_text("Scenario Diff", "\n".join(diff_lines))
        self.status_var.set("Scenario diff is showing in the insight rail.")

    def _show_prompt_linter(self) -> None:
        preview = self._build_preview_from_editor()
        self._refresh_prompt_diagnostics(preview)
        lines = [prompt_block_header_v2("Prompt Linter")]
        if not self._prompt_lint_lines:
            lines.append("No line-level issues detected.")
        else:
            for line_number in sorted(self._prompt_lint_lines):
                status = self._prompt_lint_lines[line_number]
                message = self._prompt_lint_messages.get(line_number, "Check this line.")
                lines.append(f"- Line {line_number}: {status.upper()} - {message}")
        self._set_plain_insight_text("Prompt Linter", "\n".join(lines))
        self.status_var.set("Prompt linter is showing line-level checks.")

    def _line_index_range(self, line_number: int) -> tuple[str, str]:
        return f"{line_number}.0", f"{line_number}.end"

    def _replace_prompt_line(self, line_number: int, replacement: str, label: str) -> None:
        self._push_prompt_history(label)
        start, end = self._line_index_range(line_number)
        self.prompt_text.delete(start, end)
        self.prompt_text.insert(start, replacement)
        self._highlight_prompt(force=True)
        self._analyze_prompt()
        self.status_var.set(f"Quick Fix applied: {label}")

    def _prepend_prompt_line(self, line: str, label: str) -> None:
        self._push_prompt_history(label)
        self.prompt_text.insert("1.0", line.rstrip() + "\n")
        self._highlight_prompt(force=True)
        self._analyze_prompt()
        self.status_var.set(f"Quick Fix applied: {label}")

    def _append_prompt_line(self, line: str, label: str) -> None:
        self._push_prompt_history(label)
        existing = self.prompt_text.get("1.0", "end-1c")
        separator = "" if not existing.strip() else "\n"
        self.prompt_text.insert(tk.END, separator + line.rstrip() + "\n")
        self._highlight_prompt(force=True)
        self._analyze_prompt()
        self.status_var.set(f"Quick Fix applied: {label}")

    def _prompt_has_duration_line(self, prompt: str) -> bool:
        return bool(
            re.search(
                r"\bscenario\s+duration\b|\btotal\s+(?:scenario\s+)?(?:time|duration)\b|\btimeline\s+length\b|\u5834\u666f.*\u6642|\u603b\u65f6|\u7e3d\u6642",
                prompt,
                flags=re.IGNORECASE,
            )
        )

    def _quick_fix_actions(self, preview: PromptPreviewResultV2 | None = None) -> list[dict[str, Any]]:
        prompt = self.prompt_text.get("1.0", "end-1c")
        actions: list[dict[str, Any]] = []
        if not prompt.strip():
            actions.append(
                {
                    "label": "Insert Starter",
                    "description": "Add a basic ego + vehicle prompt.",
                    "command": lambda: self._replace_editor_prompt(
                        "scenario duration=45s\n"
                        "ego: lane=left, speed=50mph\n"
                        "v1: lane=middle, ahead=7s\n"
                        "t=5s: v1 -> left, duration=5s\n"
                    ),
                }
            )
            return actions

        if not self._prompt_has_duration_line(prompt):
            actions.append(
                {
                    "label": "Add Duration",
                    "description": "Insert scenario duration=45s at the top.",
                    "command": lambda: self._prepend_prompt_line("scenario duration=45s", "add scenario duration"),
                }
            )

        if preview is not None and not preview.ok and self._safe_default_entries_for_preview(preview):
            actions.append(
                {
                    "label": "Clarify Form",
                    "description": "Open editable rows for the missing scenario fields.",
                    "command": self._open_clarification_form,
                }
            )
            actions.append(
                {
                    "label": "Use Defaults",
                    "description": "Append explicit assumed defaults for missing fields.",
                    "command": self._apply_safe_defaults_from_current_prompt,
                }
            )

        slash_commands = {str(item["label"]).lower() for item in self.PROMPT_COMPLETIONS if str(item["label"]).startswith("/")}
        for line_number, raw_line in enumerate(prompt.splitlines(), start=1):
            stripped = raw_line.strip()
            if len(actions) >= 5:
                break
            if not stripped:
                continue
            if stripped.startswith("/") and stripped.split()[0].lower() not in slash_commands:
                replacement = "v1: lane=middle, ahead=7s" if stripped.lower().startswith("/v") else "obstacle1: barrier, lane=middle, 100m, t=10s, end=30s"
                actions.append(
                    {
                        "label": f"Fix / line {line_number}",
                        "description": f"Replace unknown slash command with '{replacement}'.",
                        "command": lambda n=line_number, text=replacement: self._replace_prompt_line(n, text, "fix slash command"),
                    }
                )
                continue
            actor_match = re.match(r"^(?:v|veh|vehicle|car)\s*(?P<num>\d+)\s+(?P<body>.+)$", stripped, flags=re.IGNORECASE)
            if actor_match and ":" not in stripped:
                body = actor_match.group("body")
                lane = lane_from_prompt_fragment_v2(body, "Middle") or "Middle"
                relation = "behind" if re.search(r"\bbehind|rear|back\b|\u5f8c|\u540e", body, flags=re.IGNORECASE) else "ahead"
                gap_match = re.search(r"(?P<gap>\d+(?:\.\d+)?)\s*(?:s|sec|secs|second|seconds)\b", body, flags=re.IGNORECASE)
                gap_s = gap_match.group("gap") if gap_match else "7"
                replacement = f"v{actor_match.group('num')}: lane={prompt_dsl_lane_token_from_name_v2(lane)}, {relation}={gap_s}s"
                actions.append(
                    {
                        "label": f"Normalize v{actor_match.group('num')}",
                        "description": f"Rewrite line {line_number} as DSL.",
                        "command": lambda n=line_number, text=replacement: self._replace_prompt_line(n, text, "normalize vehicle line"),
                    }
                )
                continue
            time_match = re.match(r"^(?:t|time|at|\u7b2c)\s*=?\s*(?P<time>\d+(?:\.\d+)?)\s*(?:s|sec|seconds?)?$", stripped, flags=re.IGNORECASE)
            if time_match:
                replacement = f"t={time_match.group('time')}s: v1 -> left, duration=5s"
                actions.append(
                    {
                        "label": f"Complete t={time_match.group('time')}s",
                        "description": "Add a lane-change action to this timed event.",
                        "command": lambda n=line_number, text=replacement: self._replace_prompt_line(n, text, "complete timed event"),
                    }
                )
                continue
            if re.search(PROMPT_DECELERATION_PATTERN_V2, stripped, flags=re.IGNORECASE) and "N-key" not in stripped:
                replacement = stripped + "; target gap=7s or ego slows 10mph"
                actions.append(
                    {
                        "label": f"Clarify slow line {line_number}",
                        "description": "Add a concrete gap/speed target to deceleration wording.",
                        "command": lambda n=line_number, text=replacement: self._replace_prompt_line(n, text, "clarify deceleration"),
                    }
                )

        if preview is not None and not preview.ok:
            missing_items = self._extract_missing_items(preview.message)
            suggested = self._suggested_completion_line(missing_items, language=preview.language).strip()
            if suggested and "<value>" not in suggested:
                actions.append(
                    {
                        "label": "Append Parser Hint",
                        "description": suggested,
                        "command": lambda text=suggested: self._append_prompt_line(text, "append parser suggestion"),
                    }
                )

        if self.guide_audio_file_options and not re.search(r"\bTOR\b.*\.wav|\.wav", prompt, flags=re.IGNORECASE):
            first_audio = self.guide_audio_file_options[0]
            actions.append(
                {
                    "label": "Add Audio Cue",
                    "description": f"Insert TOR audio using {first_audio}.",
                    "command": lambda file_name=first_audio: self._append_prompt_line(f"TOR at 7s with audio {file_name}", "add audio cue"),
                }
            )
        if self.guide_visual_file_options and not re.search(r"\bvisual\b.*\.(?:png|jpg|jpeg|gif|bmp)|\.(?:png|jpg|jpeg|gif|bmp)", prompt, flags=re.IGNORECASE):
            first_visual = self.guide_visual_file_options[0]
            actions.append(
                {
                    "label": "Add Visual Cue",
                    "description": f"Insert TOR visual using {first_visual}.",
                    "command": lambda file_name=first_visual: self._append_prompt_line(f"TOR at 7s with visual {file_name}", "add visual cue"),
                }
            )
        if not actions:
            actions.extend(
                (
                    {"label": "Format Timeline", "description": "Sort prompt by initial state and timed events.", "command": self._format_prompt_by_timeline},
                    {"label": "Make Variants", "description": "Create a small editable batch.", "command": self._make_variants_from_current_prompt},
                )
            )
        return actions[:5]

    def _refresh_quick_fix_buttons(self, preview: PromptPreviewResultV2 | None = None) -> None:
        frame = self._quick_fix_frame
        if frame is None or not frame.winfo_exists():
            return
        for child in frame.winfo_children():
            child.destroy()
        actions = self._quick_fix_actions(preview)
        self._quick_fix_actions_cache = actions
        for index, action in enumerate(actions[:3]):
            tk.Button(
                frame,
                text=str(action["label"]),
                command=action["command"],
                bg="#18243a",
                fg=self.PALETTE["text"],
                activebackground="#263a61",
                activeforeground="#ffffff",
                relief=tk.FLAT,
                padx=8,
                pady=4,
                font=(BODY_FONT_FAMILY, 10, "bold"),
                highlightthickness=1,
                highlightbackground=self.PALETTE["line"],
                cursor="hand2",
            ).pack(side=tk.LEFT, padx=(0 if index == 0 else 6, 0), pady=(0, 2))

    def _apply_first_quick_fix(self) -> None:
        preview = self._build_preview_from_editor()
        self._refresh_prompt_diagnostics(preview)
        actions = self._quick_fix_actions(preview)
        self._refresh_quick_fix_buttons(preview)
        if not actions:
            self.status_var.set("No quick fix is available for the current prompt.")
            return
        actions[0]["command"]()

    def _make_variants_from_current_prompt(self) -> None:
        preview = self._build_preview_from_editor()
        if not preview.ok or not preview.params_list:
            self._apply_preview_to_insight(preview)
            self.status_var.set("Make Variants needs one valid base scenario first.")
            return

        base = preview.params_list[0]
        variants = [copy.deepcopy(base) for _ in range(4)]
        variants[1].total_experiment_time_s = max(variants[1].total_experiment_time_s, self._latest_event_time_for_params(variants[1]) + 8.0)
        closer_vehicle = self._first_variant_vehicle(variants[1])
        if closer_vehicle is not None:
            ego_speed_mps = max(kmh_to_mps_v2(variants[1].vehicles["ego"].speed_kmh), 0.001)
            sign = 1.0 if closer_vehicle.initial_offset_m >= 0 else -1.0
            current_gap_s = abs(closer_vehicle.initial_offset_m) / ego_speed_mps
            closer_vehicle.initial_offset_m = sign * max(1.0, current_gap_s - 2.0) * ego_speed_mps

        variants[2].total_experiment_time_s = max(variants[2].total_experiment_time_s + 15.0, self._latest_event_time_for_params(variants[2]) + 15.0)
        for config in iter_script_vehicle_configs_v2(variants[2]):
            if config.lane_change_enabled:
                config.lane_change_time_s += 3.0
            for event in getattr(config, "lane_changes", []) or []:
                event.time_s += 3.0
            for point in config.gap_points:
                point.time_s += 3.0

        ego_speed_delta_kmh = 5.0 * MPH_TO_KMH_V2
        variants[3].vehicles["ego"].speed_kmh += ego_speed_delta_kmh
        for config in iter_script_vehicle_configs_v2(variants[3]):
            if config.key != "ego" and vehicle_enabled_v2(config):
                config.speed_kmh = variants[3].vehicles["ego"].speed_kmh

        formatted_prompt = build_timeline_sorted_prompt_v2(preview.route, variants)
        self._replace_editor_prompt(formatted_prompt)
        self._analyze_prompt()
        self.status_var.set("Made four editable variants from the first valid scenario.")

    def _variant_table_row_from_params(self, params: ScenarioParametersV2, index: int) -> dict[str, str]:
        ego = params.vehicles["ego"]
        vehicle = self._first_variant_vehicle(params)
        row = {
            "scenario": str(index),
            "duration_s": format_number(params.total_experiment_time_s),
            "ego_lane": ego.initial_lane,
            "ego_speed_mph": format_number(ego.speed_kmh / MPH_TO_KMH_V2),
            "vehicle_lane": "",
            "relation": "",
            "gap_s": "",
            "event_time_s": "",
            "target_lane": "",
            "event_duration_s": "",
            "output": params.output_filename,
        }
        if vehicle is None:
            return row
        ego_speed_mps = max(kmh_to_mps_v2(ego.speed_kmh), 0.001)
        relation = "ahead" if vehicle.initial_offset_m >= 0 else "behind"
        row.update(
            {
                "vehicle_lane": vehicle.initial_lane,
                "relation": relation,
                "gap_s": format_number(abs(vehicle.initial_offset_m) / ego_speed_mps),
                "event_time_s": format_number(vehicle.lane_change_time_s) if vehicle.lane_change_enabled else "",
                "target_lane": vehicle.lane_change_target_lane if vehicle.lane_change_enabled else "",
                "event_duration_s": format_number(vehicle.lane_change_duration_s) if vehicle.lane_change_enabled else "",
            }
        )
        return row

    def _safe_variant_float(self, raw_value: str, fallback: float, *, minimum: float | None = None) -> float:
        try:
            value = float(str(raw_value).strip())
        except (TypeError, ValueError):
            value = fallback
        if minimum is not None:
            value = max(minimum, value)
        return value

    def _apply_variant_table_row_to_params(self, row_index: int) -> None:
        if row_index < 0 or row_index >= len(self._variant_table_params):
            return
        params = self._variant_table_params[row_index]
        row = self._variant_table_rows[row_index]
        ego = params.vehicles["ego"]
        ego.initial_lane = lane_from_prompt_fragment_v2(row.get("ego_lane", ""), ego.initial_lane) or ego.initial_lane
        ego.speed_kmh = self._safe_variant_float(row.get("ego_speed_mph", ""), ego.speed_kmh / MPH_TO_KMH_V2, minimum=1.0) * MPH_TO_KMH_V2
        params.total_experiment_time_s = self._safe_variant_float(
            row.get("duration_s", ""),
            params.total_experiment_time_s,
            minimum=max(1.0, self._latest_event_time_for_params(params)),
        )

        vehicle = self._first_variant_vehicle(params)
        if vehicle is None:
            return
        vehicle.initial_lane = lane_from_prompt_fragment_v2(row.get("vehicle_lane", ""), vehicle.initial_lane) or vehicle.initial_lane
        vehicle.speed_kmh = ego.speed_kmh
        relation = str(row.get("relation", "")).strip().lower()
        if relation not in {"ahead", "behind"}:
            relation = "ahead" if vehicle.initial_offset_m >= 0 else "behind"
        gap_s = self._safe_variant_float(row.get("gap_s", ""), abs(vehicle.initial_offset_m) / max(kmh_to_mps_v2(ego.speed_kmh), 0.001), minimum=0.1)
        sign = 1.0 if relation == "ahead" else -1.0
        vehicle.initial_offset_m = sign * gap_s * max(kmh_to_mps_v2(ego.speed_kmh), 0.001)
        target_lane = lane_from_prompt_fragment_v2(row.get("target_lane", ""), "")
        event_time_raw = str(row.get("event_time_s", "")).strip()
        if target_lane and event_time_raw:
            vehicle.lane_change_enabled = target_lane != vehicle.initial_lane
            vehicle.lane_change_target_lane = target_lane
            vehicle.lane_change_time_s = self._safe_variant_float(event_time_raw, vehicle.lane_change_time_s, minimum=0.0)
            vehicle.lane_change_duration_s = self._safe_variant_float(row.get("event_duration_s", ""), vehicle.lane_change_duration_s, minimum=0.0)
            vehicle.lane_changes = []
        else:
            vehicle.lane_change_enabled = False
            vehicle.lane_changes = []
        params.total_experiment_time_s = max(params.total_experiment_time_s, self._latest_event_time_for_params(params))

    def _refresh_variant_table_tree(self) -> None:
        tree = self._variant_table_tree
        if tree is None or not tree.winfo_exists():
            return
        for item_id in tree.get_children():
            tree.delete(item_id)
        for row_index, row in enumerate(self._variant_table_rows):
            tree.insert(
                "",
                tk.END,
                iid=str(row_index),
                values=(
                    row["scenario"],
                    row["duration_s"],
                    row["ego_lane"],
                    row["ego_speed_mph"],
                    row["vehicle_lane"],
                    row["relation"],
                    row["gap_s"],
                    row["event_time_s"],
                    row["target_lane"],
                    row["event_duration_s"],
                    row["output"],
                ),
            )

    def _open_variant_table_editor(self) -> None:
        preview = self._build_preview_from_editor()
        if not preview.ok or not preview.params_list:
            self._apply_preview_to_insight(preview)
            messagebox.showinfo("Variant Table", "Analyze a valid prompt first, then open the variant table.")
            return

        self._apply_preview_to_insight(preview)
        self._variant_table_params = [copy.deepcopy(params) for params in preview.params_list]
        self._variant_table_rows = [
            self._variant_table_row_from_params(params, index)
            for index, params in enumerate(self._variant_table_params, start=1)
        ]

        if self._variant_table_popup is not None and self._variant_table_popup.winfo_exists():
            self._refresh_variant_table_tree()
            self._variant_table_popup.lift(self)
            self._variant_table_popup.focus_force()
            return

        popup = tk.Toplevel(self)
        popup.title("Variant Table")
        popup.geometry("1120x560")
        popup.minsize(920, 500)
        popup.configure(bg=self.PALETTE["bg"])
        popup.transient(self)
        self._variant_table_popup = popup

        shell = tk.Frame(popup, bg=self.PALETTE["line"])
        shell.pack(fill=tk.BOTH, expand=True, padx=14, pady=14)
        root = tk.Frame(shell, bg=self.PALETTE["panel"], padx=14, pady=14)
        root.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        root.grid_columnconfigure(0, weight=3)
        root.grid_columnconfigure(1, weight=2)
        root.grid_rowconfigure(1, weight=1)

        tk.Label(
            root,
            text="Variant Table",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["text"],
            font=(BODY_FONT_FAMILY, 16, "bold"),
            anchor="w",
        ).grid(row=0, column=0, sticky="ew", columnspan=2)

        columns = (
            "scenario",
            "duration_s",
            "ego_lane",
            "ego_speed_mph",
            "vehicle_lane",
            "relation",
            "gap_s",
            "event_time_s",
            "target_lane",
            "event_duration_s",
            "output",
        )
        table_frame = tk.Frame(root, bg=self.PALETTE["field"], highlightthickness=1, highlightbackground=self.PALETTE["line"])
        table_frame.grid(row=1, column=0, sticky="nsew", pady=(12, 0), padx=(0, 12))
        tree = ttk.Treeview(table_frame, columns=columns, show="headings", height=14)
        self._variant_table_tree = tree
        widths = {
            "scenario": 72,
            "duration_s": 88,
            "ego_lane": 92,
            "ego_speed_mph": 96,
            "vehicle_lane": 92,
            "relation": 82,
            "gap_s": 72,
            "event_time_s": 82,
            "target_lane": 92,
            "event_duration_s": 96,
            "output": 180,
        }
        headings = {
            "scenario": "Scenario",
            "duration_s": "Duration",
            "ego_lane": "Ego lane",
            "ego_speed_mph": "Ego mph",
            "vehicle_lane": "V1 lane",
            "relation": "Relation",
            "gap_s": "Gap s",
            "event_time_s": "Event s",
            "target_lane": "Target",
            "event_duration_s": "LC dur",
            "output": "Output",
        }
        for column in columns:
            tree.heading(column, text=headings[column])
            tree.column(column, width=widths[column], minwidth=60, stretch=column == "output")
        tree_scroll = ttk.Scrollbar(table_frame, orient=tk.VERTICAL, command=tree.yview)
        tree.configure(yscrollcommand=tree_scroll.set)
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        tree_scroll.pack(side=tk.RIGHT, fill=tk.Y)

        edit = tk.Frame(root, bg=self.PALETTE["panel_soft"], highlightthickness=1, highlightbackground=self.PALETTE["line"], padx=12, pady=12)
        edit.grid(row=1, column=1, sticky="nsew", pady=(12, 0))
        edit.columnconfigure(1, weight=1)
        tk.Label(
            edit,
            text="Edit selected row",
            bg=self.PALETTE["panel_soft"],
            fg=self.PALETTE["text"],
            font=(BODY_FONT_FAMILY, 10, "bold"),
            anchor="w",
        ).grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 8))

        self._variant_table_edit_vars = {
            key: tk.StringVar()
            for key in (
                "duration_s",
                "ego_lane",
                "ego_speed_mph",
                "vehicle_lane",
                "relation",
                "gap_s",
                "event_time_s",
                "target_lane",
                "event_duration_s",
            )
        }

        def add_editor_row(row_number: int, label: str, key: str, values: tuple[str, ...] | None = None) -> None:
            tk.Label(
                edit,
                text=label,
                bg=self.PALETTE["panel_soft"],
                fg=self.PALETTE["muted"],
                font=(BODY_FONT_FAMILY, 10, "bold"),
                anchor="w",
            ).grid(row=row_number, column=0, sticky="w", pady=4, padx=(0, 8))
            if values is None:
                ttk.Entry(edit, textvariable=self._variant_table_edit_vars[key]).grid(row=row_number, column=1, sticky="ew", pady=4)
            else:
                ttk.Combobox(edit, textvariable=self._variant_table_edit_vars[key], values=values, state="readonly").grid(row=row_number, column=1, sticky="ew", pady=4)

        add_editor_row(1, "Duration s", "duration_s")
        add_editor_row(2, "Ego lane", "ego_lane", LANE_NAMES_V2)
        add_editor_row(3, "Ego mph", "ego_speed_mph")
        add_editor_row(4, "V1 lane", "vehicle_lane", LANE_NAMES_V2)
        add_editor_row(5, "Relation", "relation", ("ahead", "behind"))
        add_editor_row(6, "Gap s", "gap_s")
        add_editor_row(7, "Event time s", "event_time_s")
        add_editor_row(8, "Target lane", "target_lane", ("", *LANE_NAMES_V2))
        add_editor_row(9, "LC duration s", "event_duration_s")

        def selected_row_index() -> int | None:
            selected = tree.selection()
            if not selected:
                return None
            try:
                return int(selected[0])
            except ValueError:
                return None

        def load_selected_row(_event: tk.Event | None = None) -> None:
            row_index = selected_row_index()
            if row_index is None:
                return
            row = self._variant_table_rows[row_index]
            for key, variable in self._variant_table_edit_vars.items():
                variable.set(row.get(key, ""))

        def apply_selected_row() -> None:
            row_index = selected_row_index()
            if row_index is None:
                self.status_var.set("Select a variant row first.")
                return
            row = self._variant_table_rows[row_index]
            for key, variable in self._variant_table_edit_vars.items():
                row[key] = variable.get().strip()
            self._apply_variant_table_row_to_params(row_index)
            self._variant_table_rows[row_index] = self._variant_table_row_from_params(self._variant_table_params[row_index], row_index + 1)
            self._refresh_variant_table_tree()
            tree.selection_set(str(row_index))
            load_selected_row()
            self.status_var.set(f"Variant table row {row_index + 1} applied.")

        def rebuild_prompt_from_table() -> None:
            for row_index in range(len(self._variant_table_rows)):
                self._apply_variant_table_row_to_params(row_index)
            prompt_text = build_timeline_sorted_prompt_v2(preview.route, self._variant_table_params)
            self._replace_editor_prompt(prompt_text)
            self.status_var.set("Prompt rebuilt from variant table. Run Analyze to verify.")

        button_row = tk.Frame(edit, bg=self.PALETTE["panel_soft"])
        button_row.grid(row=10, column=0, columnspan=2, sticky="ew", pady=(14, 0))
        button_row.columnconfigure((0, 1, 2), weight=1)
        ttk.Button(button_row, text="Apply Row", style="Soft.TButton", command=apply_selected_row).grid(row=0, column=0, sticky="ew", padx=(0, 6))
        ttk.Button(button_row, text="Rebuild Prompt", style="Accent.TButton", command=rebuild_prompt_from_table).grid(row=0, column=1, sticky="ew", padx=3)
        ttk.Button(button_row, text="Analyze", style="Success.TButton", command=lambda: (rebuild_prompt_from_table(), self._analyze_prompt())).grid(row=0, column=2, sticky="ew", padx=(6, 0))

        tree.bind("<<TreeviewSelect>>", load_selected_row)
        self._refresh_variant_table_tree()
        if self._variant_table_rows:
            tree.selection_set("0")
            load_selected_row()
        popup.protocol("WM_DELETE_WINDOW", lambda: (setattr(self, "_variant_table_popup", None), popup.destroy()))
        self.status_var.set(f"Variant table opened with {len(self._variant_table_rows)} row(s).")

    def _parse_matrix_number_list(self, raw_value: str, fallback: list[float]) -> list[float]:
        values: list[float] = []
        for token in re.split(r"[,;\s]+", str(raw_value).strip()):
            if not token:
                continue
            try:
                value = float(token)
            except ValueError:
                continue
            if value > 0 and value not in values:
                values.append(value)
        return values or fallback

    def _open_variant_matrix_builder(self) -> None:
        preview = self._build_preview_from_editor()
        if not preview.ok or not preview.params_list:
            self._apply_preview_to_insight(preview)
            messagebox.showinfo("Variant Matrix", "Analyze one valid base scenario first, then create a matrix.")
            return
        base = copy.deepcopy(preview.params_list[0])
        ego = base.vehicles["ego"]
        vehicle = self._first_variant_vehicle(base)
        base_speed_mph = max(1.0, ego.speed_kmh / MPH_TO_KMH_V2)
        base_gap_s = 7.0
        if vehicle is not None:
            base_gap_s = abs(vehicle.initial_offset_m) / max(kmh_to_mps_v2(ego.speed_kmh), 0.001)
        base_lead_s = vehicle.lane_change_time_s if vehicle is not None and vehicle.lane_change_enabled else 5.0
        base_duration_s = vehicle.lane_change_duration_s if vehicle is not None and vehicle.lane_change_enabled else 5.0

        if self._matrix_popup is not None and self._matrix_popup.winfo_exists():
            self._matrix_popup.lift(self)
            self._matrix_popup.focus_force()
            return

        popup = tk.Toplevel(self)
        popup.title("Variant Matrix Builder")
        popup.geometry("620x430")
        popup.minsize(560, 390)
        popup.configure(bg=self.PALETTE["bg"])
        popup.transient(self)
        self._matrix_popup = popup

        shell = tk.Frame(popup, bg=self.PALETTE["line"])
        shell.pack(fill=tk.BOTH, expand=True, padx=14, pady=14)
        root = tk.Frame(shell, bg=self.PALETTE["panel"], padx=16, pady=16)
        root.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        root.columnconfigure(1, weight=1)

        tk.Label(
            root,
            text="Variant Matrix",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["text"],
            font=(BODY_FONT_FAMILY, 16, "bold"),
            anchor="w",
        ).grid(row=0, column=0, columnspan=2, sticky="ew")
        tk.Label(
            root,
            text="Enter comma-separated values. The builder creates every speed x gap x lead-time combination.",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["muted"],
            font=(BODY_FONT_FAMILY, 10),
            anchor="w",
        ).grid(row=1, column=0, columnspan=2, sticky="ew", pady=(2, 14))

        speed_var = tk.StringVar(value=f"{format_number(base_speed_mph)}, {format_number(base_speed_mph + 5)}")
        gap_var = tk.StringVar(value=f"{format_number(base_gap_s)}, {format_number(max(1.0, base_gap_s - 2.0))}")
        lead_var = tk.StringVar(value=f"{format_number(base_lead_s)}, {format_number(base_lead_s + 2.0)}")
        lc_duration_var = tk.StringVar(value=format_number(base_duration_s))
        target_lane_var = tk.StringVar(value=(vehicle.lane_change_target_lane if vehicle is not None and vehicle.lane_change_enabled else "Left"))
        count_var = tk.StringVar(value="")

        def add_row(row: int, label: str, widget: tk.Widget) -> None:
            tk.Label(
                root,
                text=label,
                bg=self.PALETTE["panel"],
                fg=self.PALETTE["muted"],
                font=(BODY_FONT_FAMILY, 10, "bold"),
                anchor="w",
            ).grid(row=row, column=0, sticky="w", pady=6, padx=(0, 10))
            widget.grid(row=row, column=1, sticky="ew", pady=6)

        add_row(2, "Speed mph", ttk.Entry(root, textvariable=speed_var))
        add_row(3, "Gap seconds", ttk.Entry(root, textvariable=gap_var))
        add_row(4, "Lead / event time s", ttk.Entry(root, textvariable=lead_var))
        add_row(5, "LC duration s", ttk.Entry(root, textvariable=lc_duration_var))
        add_row(6, "Target lane", ttk.Combobox(root, textvariable=target_lane_var, values=LANE_NAMES_V2, state="readonly"))
        tk.Label(root, textvariable=count_var, bg=self.PALETTE["panel"], fg=self.PALETTE["accent_dark"], font=(BODY_FONT_FAMILY, 10, "bold"), anchor="w").grid(
            row=7, column=0, columnspan=2, sticky="ew", pady=(10, 0)
        )

        def update_count() -> int:
            speeds = self._parse_matrix_number_list(speed_var.get(), [base_speed_mph])
            gaps = self._parse_matrix_number_list(gap_var.get(), [base_gap_s])
            leads = self._parse_matrix_number_list(lead_var.get(), [base_lead_s])
            count = len(speeds) * len(gaps) * len(leads)
            count_var.set(f"{count} scenario(s) will be created.")
            return count

        def build_matrix() -> None:
            speeds = self._parse_matrix_number_list(speed_var.get(), [base_speed_mph])
            gaps = self._parse_matrix_number_list(gap_var.get(), [base_gap_s])
            leads = self._parse_matrix_number_list(lead_var.get(), [base_lead_s])
            count = len(speeds) * len(gaps) * len(leads)
            if count > 96:
                messagebox.showwarning("Variant Matrix", "This would create more than 96 scenarios. Please narrow the lists first.")
                return
            variants: list[ScenarioParametersV2] = []
            for speed_mph in speeds:
                for gap_s in gaps:
                    for lead_s in leads:
                        params = copy.deepcopy(base)
                        params.vehicles["ego"].speed_kmh = speed_mph * MPH_TO_KMH_V2
                        first_vehicle = self._first_variant_vehicle(params)
                        if first_vehicle is not None:
                            first_vehicle.speed_kmh = params.vehicles["ego"].speed_kmh
                            sign = 1.0 if first_vehicle.initial_offset_m >= 0 else -1.0
                            first_vehicle.initial_offset_m = sign * gap_s * max(kmh_to_mps_v2(params.vehicles["ego"].speed_kmh), 0.001)
                            target_lane = lane_from_prompt_fragment_v2(target_lane_var.get(), first_vehicle.lane_change_target_lane) or first_vehicle.lane_change_target_lane
                            if target_lane:
                                first_vehicle.lane_change_enabled = target_lane != first_vehicle.initial_lane
                                first_vehicle.lane_change_target_lane = target_lane
                                first_vehicle.lane_change_time_s = max(0.0, lead_s)
                                first_vehicle.lane_change_duration_s = self._safe_variant_float(lc_duration_var.get(), base_duration_s, minimum=0.0)
                                first_vehicle.lane_changes = []
                        params.total_experiment_time_s = max(params.total_experiment_time_s, self._latest_event_time_for_params(params) + 5.0)
                        variants.append(params)
            self._replace_editor_prompt(build_timeline_sorted_prompt_v2(preview.route, variants))
            self._analyze_prompt()
            popup.destroy()
            self._matrix_popup = None
            self.status_var.set(f"Variant matrix created {len(variants)} scenario(s).")

        for variable in (speed_var, gap_var, lead_var):
            variable.trace_add("write", lambda *_args: update_count())
        update_count()
        buttons = tk.Frame(root, bg=self.PALETTE["panel"])
        buttons.grid(row=8, column=0, columnspan=2, sticky="ew", pady=(18, 0))
        buttons.columnconfigure((0, 1), weight=1)
        ttk.Button(buttons, text="Build Matrix", style="Accent.TButton", command=build_matrix).grid(row=0, column=0, sticky="ew", padx=(0, 6))
        ttk.Button(buttons, text="Close", style="Soft.TButton", command=popup.destroy).grid(row=0, column=1, sticky="ew", padx=(6, 0))
        popup.protocol("WM_DELETE_WINDOW", lambda: (setattr(self, "_matrix_popup", None), popup.destroy()))

    def _scenario_summary_lines(self, preview: PromptPreviewResultV2) -> list[str]:
        if not preview.ok or not preview.params_list:
            return [prompt_block_header_v2("Scenario Summary"), "No valid scenario yet. Run Analyze and fix the required fields first."]
        zh = preview.language == "zh"
        lines = [prompt_block_header_v2("Scenario Summary")]
        for index, params in enumerate(preview.params_list[:8], start=1):
            ego = params.vehicles["ego"]
            title = f"Scenario {index}: {params.output_filename}" if len(preview.params_list) > 1 else params.output_filename
            lines.extend(("", title))
            lines.append(
                (
                    f"- Ego 在 {prompt_lane_text_v2(ego.initial_lane, 'zh')}，速度 {format_number(ego.speed_kmh / MPH_TO_KMH_V2)} mph，總時長 {format_number(params.total_experiment_time_s)} 秒。"
                    if zh
                    else f"- Ego starts in {ego.initial_lane} at {format_number(ego.speed_kmh / MPH_TO_KMH_V2)} mph for {format_number(params.total_experiment_time_s)} s."
                )
            )
            for vehicle_index, config in enumerate(iter_script_vehicle_configs_v2(params), start=1):
                if config.key == "ego" or not vehicle_enabled_v2(config):
                    continue
                relation = "ahead" if config.initial_offset_m >= 0 else "behind"
                gap_s = abs(config.initial_offset_m) / max(kmh_to_mps_v2(ego.speed_kmh), 0.001)
                actor = prompt_actor_label_text_v2(config.label, "zh" if zh else "en")
                lines.append(
                    (
                        f"- {actor} 在 {prompt_lane_text_v2(config.initial_lane, 'zh')}，{prompt_relation_text_v2(relation, 'zh')} ego {format_number(gap_s)} 秒。"
                        if zh
                        else f"- {actor} starts in {config.initial_lane}, {relation} ego by {format_number(gap_s)} s."
                    )
                )
                for event in lane_change_events_for_vehicle_v2(config):
                    lines.append(
                        (
                            f"  在 {format_number(event.time_s)} 秒從 {prompt_lane_text_v2(event.from_lane, 'zh')} 切到 {prompt_lane_text_v2(event.target_lane, 'zh')}，變道 {format_number(event.duration_s)} 秒。"
                            if zh
                            else f"  At {format_number(event.time_s)} s it changes from {event.from_lane} to {event.target_lane} over {format_number(event.duration_s)} s."
                        )
                    )
                if vehicle_index >= 7:
                    break
            for obstacle in iter_obstacle_configs_v2(params):
                if obstacle.enabled:
                    lines.append(
                        (
                            f"- 障礙物 {obstacle.kind} 在 {prompt_lane_text_v2(obstacle.lane, 'zh')}，{format_number(obstacle.start_time_s)} 到 {format_number(obstacle.end_time_s)} 秒出現。"
                            if zh
                            else f"- Obstacle {obstacle.kind} appears in {obstacle.lane} from {format_number(obstacle.start_time_s)} to {format_number(obstacle.end_time_s)} s."
                        )
                    )
            for pedestrian in params.pedestrians.values():
                if pedestrian.enabled:
                    lines.append(
                        (
                            f"- 行人從 {prompt_lane_text_v2(pedestrian.start_side, 'zh')} 到 {prompt_lane_text_v2(pedestrian.end_side, 'zh')}，{format_number(pedestrian.start_time_s)} 秒開始。"
                            if zh
                            else f"- Pedestrian crosses {pedestrian.start_side} -> {pedestrian.end_side} starting at {format_number(pedestrian.start_time_s)} s."
                        )
                    )
            if params.audio_events:
                lines.append("- TOR audio: " + ", ".join(f"{format_number(event.time_s)}s {event.file_name}" for event in params.audio_events))
            if n_key_intervention_enabled_v2(params):
                lines.append("- N-key intervention is enabled.")
        if len(preview.params_list) > 8:
            lines.append(f"\n... {len(preview.params_list) - 8} more scenario(s).")
        return lines

    def _show_scenario_summary(self) -> None:
        preview = self._build_preview_from_editor()
        self._apply_preview_to_insight(preview)
        self._set_plain_insight_text("Scenario Summary", "\n".join(self._scenario_summary_lines(preview)))
        self.status_var.set("Scenario summary is showing in the insight rail.")

    def _open_asset_picker_preview(self) -> None:
        ensure_prompt_cue_asset_dirs_v2()
        self.guide_audio_file_options = discover_prompt_auditory_cue_files_v2()
        self.guide_visual_file_options = discover_prompt_visual_cue_files_v2()
        if self._asset_picker_popup is not None and self._asset_picker_popup.winfo_exists():
            self._asset_picker_popup.lift(self)
            self._asset_picker_popup.focus_force()
            return

        popup = tk.Toplevel(self)
        popup.title("TOR Asset Picker")
        popup.geometry("840x520")
        popup.minsize(720, 460)
        popup.configure(bg=self.PALETTE["bg"])
        popup.transient(self)
        self._asset_picker_popup = popup

        shell = tk.Frame(popup, bg=self.PALETTE["line"])
        shell.pack(fill=tk.BOTH, expand=True, padx=14, pady=14)
        root = tk.Frame(shell, bg=self.PALETTE["panel"], padx=14, pady=14)
        root.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        root.grid_columnconfigure((0, 1, 2), weight=1)
        root.grid_rowconfigure(2, weight=1)

        tk.Label(root, text="TOR Asset Picker", bg=self.PALETTE["panel"], fg=self.PALETTE["text"], font=(BODY_FONT_FAMILY, 16, "bold")).grid(
            row=0, column=0, columnspan=3, sticky="w"
        )
        tk.Label(
            root,
            text=f"Audio: {PROMPT_AUDITORY_CUE_DIR_V2}   |   Visual: {PROMPT_VISUAL_CUE_DIR_V2}",
            bg=self.PALETTE["panel"],
            fg=self.PALETTE["muted"],
            font=(BODY_FONT_FAMILY, 10),
            anchor="w",
        ).grid(row=1, column=0, columnspan=3, sticky="ew", pady=(2, 10))

        audio_list = tk.Listbox(root, bg=self.PALETTE["field"], fg=self.PALETTE["text"], selectbackground="#22345d", selectforeground="#ffffff", height=12)
        visual_list = tk.Listbox(root, bg=self.PALETTE["field"], fg=self.PALETTE["text"], selectbackground="#22345d", selectforeground="#ffffff", height=12)
        preview_canvas = tk.Canvas(root, bg=self.PALETTE["field"], highlightthickness=1, highlightbackground=self.PALETTE["line"], height=220)
        audio_list.grid(row=2, column=0, sticky="nsew", padx=(0, 8))
        visual_list.grid(row=2, column=1, sticky="nsew", padx=8)
        preview_canvas.grid(row=2, column=2, sticky="nsew", padx=(8, 0))

        def populate_lists() -> None:
            self.guide_audio_file_options = discover_prompt_auditory_cue_files_v2()
            self.guide_visual_file_options = discover_prompt_visual_cue_files_v2()
            audio_list.delete(0, tk.END)
            visual_list.delete(0, tk.END)
            for name in self.guide_audio_file_options:
                audio_list.insert(tk.END, name)
            for name in self.guide_visual_file_options:
                visual_list.insert(tk.END, name)
            if self.guide_audio_file_options:
                audio_list.selection_set(0)
            if self.guide_visual_file_options:
                visual_list.selection_set(0)
                preview_visual()

        def selected_audio() -> str:
            selected = audio_list.curselection()
            return audio_list.get(selected[0]) if selected else ""

        def selected_visual() -> str:
            selected = visual_list.curselection()
            return visual_list.get(selected[0]) if selected else ""

        def play_audio() -> None:
            name = selected_audio()
            if not name:
                self.status_var.set("No audio cue selected.")
                return
            path = PROMPT_AUDITORY_CUE_DIR_V2 / name
            try:
                import winsound

                winsound.PlaySound(str(path), winsound.SND_FILENAME | winsound.SND_ASYNC)
                self.status_var.set(f"Playing audio cue: {name}")
            except Exception as exc:  # noqa: BLE001
                messagebox.showwarning("Audio Preview", f"Could not play {name}: {exc}")

        def preview_visual(_event: tk.Event | None = None) -> None:
            name = selected_visual()
            preview_canvas.delete("all")
            if not name:
                preview_canvas.create_text(20, 24, text="No visual cue selected.", anchor=tk.W, fill=self.PALETTE["muted"])
                return
            path = PROMPT_VISUAL_CUE_DIR_V2 / name
            try:
                image = tk.PhotoImage(file=str(path))
                max_w = max(preview_canvas.winfo_width() - 28, 180)
                max_h = max(preview_canvas.winfo_height() - 48, 160)
                subsample = max(1, math.ceil(max(image.width() / max_w, image.height() / max_h)))
                if subsample > 1:
                    image = image.subsample(subsample, subsample)
                self._asset_picker_visual_photo = image
                preview_canvas.create_image(max(preview_canvas.winfo_width() / 2, 120), 112, image=image, anchor=tk.CENTER)
                preview_canvas.create_text(14, 18, text=name, anchor=tk.W, fill=self.PALETTE["text"], font=(BODY_FONT_FAMILY, 10, "bold"))
            except tk.TclError:
                preview_canvas.create_text(16, 26, text=name, anchor=tk.W, fill=self.PALETTE["text"], font=(BODY_FONT_FAMILY, 10, "bold"))
                preview_canvas.create_text(16, 52, text="Preview unavailable for this image type.", anchor=tk.W, fill=self.PALETTE["muted"])

        def insert_audio() -> None:
            name = selected_audio()
            if name:
                self._append_prompt_line(f"TOR at 7s with audio {name}", "insert audio asset")

        def insert_visual() -> None:
            name = selected_visual()
            if name:
                self._append_prompt_line(f"TOR at 7s with visual {name}", "insert visual asset")

        audio_buttons = tk.Frame(root, bg=self.PALETTE["panel"])
        audio_buttons.grid(row=3, column=0, sticky="ew", padx=(0, 8), pady=(10, 0))
        visual_buttons = tk.Frame(root, bg=self.PALETTE["panel"])
        visual_buttons.grid(row=3, column=1, sticky="ew", padx=8, pady=(10, 0))
        misc_buttons = tk.Frame(root, bg=self.PALETTE["panel"])
        misc_buttons.grid(row=3, column=2, sticky="ew", padx=(8, 0), pady=(10, 0))
        audio_buttons.columnconfigure((0, 1), weight=1)
        visual_buttons.columnconfigure(0, weight=1)
        misc_buttons.columnconfigure((0, 1), weight=1)
        ttk.Button(audio_buttons, text="Play", style="Soft.TButton", command=play_audio).grid(row=0, column=0, sticky="ew", padx=(0, 4))
        ttk.Button(audio_buttons, text="Insert", style="Accent.TButton", command=insert_audio).grid(row=0, column=1, sticky="ew", padx=(4, 0))
        ttk.Button(visual_buttons, text="Insert Visual", style="Accent.TButton", command=insert_visual).grid(row=0, column=0, sticky="ew")
        ttk.Button(misc_buttons, text="Refresh", style="Soft.TButton", command=populate_lists).grid(row=0, column=0, sticky="ew", padx=(0, 4))
        ttk.Button(misc_buttons, text="Close", style="Soft.TButton", command=popup.destroy).grid(row=0, column=1, sticky="ew", padx=(4, 0))
        visual_list.bind("<<ListboxSelect>>", preview_visual)
        preview_canvas.bind("<Configure>", lambda _event: preview_visual())
        populate_lists()
        popup.protocol("WM_DELETE_WINDOW", lambda: (setattr(self, "_asset_picker_popup", None), popup.destroy()))

