    def _open_recipe_library(self) -> None:
        if self._recipe_library_popup is not None and self._recipe_library_popup.winfo_exists():
            self._recipe_library_popup.lift(self)
            self._recipe_library_popup.focus_force()
            return
        recipes = self._scenario_recipe_items()
        popup = tk.Toplevel(self)
        popup.title("Scenario Recipe Library")
        popup.geometry("980x600")
        popup.minsize(820, 520)
        popup.configure(bg=self.PALETTE["bg"])
        popup.transient(self)
        self._recipe_library_popup = popup

        shell = tk.Frame(popup, bg=self.PALETTE["line"])
        shell.pack(fill=tk.BOTH, expand=True, padx=14, pady=14)
        root = tk.Frame(shell, bg=self.PALETTE["panel"], padx=14, pady=14)
        root.pack(fill=tk.BOTH, expand=True, padx=1, pady=1)
        root.grid_columnconfigure(0, weight=1)
        root.grid_columnconfigure(1, weight=2)
        root.grid_rowconfigure(1, weight=1)
        tk.Label(root, text="Scenario Recipe Library", bg=self.PALETTE["panel"], fg=self.PALETTE["text"], font=(BODY_FONT_FAMILY, 16, "bold")).grid(
            row=0, column=0, columnspan=2, sticky="w"
        )
        listbox = tk.Listbox(root, bg=self.PALETTE["field"], fg=self.PALETTE["text"], selectbackground="#22345d", selectforeground="#ffffff", exportselection=False)
        listbox.grid(row=1, column=0, sticky="nsew", pady=(12, 0), padx=(0, 10))
        preview = tk.Text(root, bg=self.PALETTE["field"], fg=self.PALETTE["text"], insertbackground=self.PALETTE["accent"], font=(MONO_FONT_FAMILY, 12), wrap=tk.WORD)
        preview.grid(row=1, column=1, sticky="nsew", pady=(12, 0))
        for recipe in recipes:
            listbox.insert(tk.END, recipe["name"])

        def selected_recipe() -> dict[str, str]:
            selected = listbox.curselection()
            return recipes[selected[0] if selected else 0]

        def render_recipe(_event: tk.Event | None = None) -> None:
            recipe = selected_recipe()
            preview.configure(state=tk.NORMAL)
            preview.delete("1.0", tk.END)
            preview.insert("1.0", f"{recipe['name']}\n{recipe['description']}\n\n{recipe['prompt']}")
            preview.configure(state=tk.DISABLED)

        def insert_recipe(*, replace: bool) -> None:
            recipe = selected_recipe()
            if replace:
                self._replace_editor_prompt(recipe["prompt"])
            else:
                self._append_prompt_lines([recipe["prompt"].rstrip()])
            self._analyze_prompt()
            self.status_var.set(f"Recipe inserted: {recipe['name']}")

        buttons = tk.Frame(root, bg=self.PALETTE["panel"])
        buttons.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(12, 0))
        buttons.columnconfigure((0, 1, 2), weight=1)
        ttk.Button(buttons, text="Replace Prompt", style="Accent.TButton", command=lambda: insert_recipe(replace=True)).grid(row=0, column=0, sticky="ew", padx=(0, 6))
        ttk.Button(buttons, text="Append Recipe", style="Soft.TButton", command=lambda: insert_recipe(replace=False)).grid(row=0, column=1, sticky="ew", padx=3)
        ttk.Button(buttons, text="Close", style="Soft.TButton", command=popup.destroy).grid(row=0, column=2, sticky="ew", padx=(6, 0))
        listbox.bind("<<ListboxSelect>>", render_recipe)
        listbox.selection_set(0)
        render_recipe()
        popup.protocol("WM_DELETE_WINDOW", lambda: (setattr(self, "_recipe_library_popup", None), popup.destroy()))

